def _bounded_prostudio_worker_concurrency(value) -> int:
    try:
        raw = str("20" if value is None else value).strip() or "20"
        parsed = int(raw)
    except (TypeError, ValueError):
        parsed = 20
    return max(1, min(20, parsed))


