def shop_item(pack_id: str):
    return SHOP_ITEMS.get((pack_id or "").strip())


def shop_payload(provider: str, telegram_id: int, pack_id: str, item: dict) -> str:
    if item["kind"] == "subscription":
        return f"sylvex_{provider}_sub:{telegram_id}:{item['plan_key']}:{item['usd']:.2f}"
    return f"sylvex_{provider}_credits:{telegram_id}:{item['credits']}:{item['usd']:.2f}"


def bot_stars_payload(telegram_id: int, item: dict, charge_id: str = None) -> str:
    if item["kind"] == "subscription":
        payload = f"sylvex_sub:{telegram_id}:{item['plan_key']}:{item['stars']}"
    else:
        payload = f"sylvex_stars:{telegram_id}:{item['credits']}:{item['stars']}"
    if charge_id:
        payload = f"{payload}:{charge_id}"
    return payload


def parse_shop_payload(payload: str) -> dict:
    if not payload or not isinstance(payload, str):
        return {}

    parts = payload.split(":")
    if not parts:
        return {}

    result = {
        "kind": None,
        "provider": None,
        "telegram_id": 0,
        "plan_key": None,
        "credits": 0,
        "charge_id": None,
    }

    key = parts[0] or ""
    if key.startswith("sylvex_") and key.endswith("_sub"):
        result["kind"] = "subscription"
        result["provider"] = key[len("sylvex_"):-len("_sub")]
    elif key.startswith("sylvex_") and key.endswith("_credits"):
        result["kind"] = "credits"
        result["provider"] = key[len("sylvex_"):-len("_credits")]
    elif key == "sylvex_sub":
        result["kind"] = "subscription"
    elif key == "sylvex_stars":
        result["kind"] = "credits"
    else:
        return {}

    if len(parts) >= 2:
        try:
            result["telegram_id"] = int(parts[1] or 0)
        except Exception:
            result["telegram_id"] = 0

    if result["kind"] == "subscription":
        if len(parts) >= 3:
            result["plan_key"] = parts[2]
        if len(parts) >= 5:
            result["charge_id"] = parts[4]
    else:
        if len(parts) >= 3:
            try:
                result["credits"] = int(parts[2] or 0)
            except Exception:
                result["credits"] = 0
        if len(parts) >= 5:
            result["charge_id"] = parts[4]

    return result


def _has_subscription_purchase(telegram_id: int) -> bool:
    if not DATABASE_URL or not telegram_id:
        return False

    ensure_payment_tables()
    conn = db_connect(DATABASE_URL)
    cursor = conn.cursor()
    try:
        cursor.execute("""
            SELECT 1
            FROM purchases
            WHERE telegram_id = %s
              AND payload LIKE 'sylvex_%%sub:%%'
            LIMIT 1
        """, (telegram_id,))
        return cursor.fetchone() is not None
    finally:
        cursor.close()
        conn.close()


def _restore_active_subscription(telegram_id: int) -> bool:
    if not DATABASE_URL or not telegram_id:
        return False

    ensure_payment_tables()
    conn = db_connect(DATABASE_URL)
    cursor = conn.cursor()
    try:
        cursor.execute("""
            SELECT provider, payload, amount, currency, charge_id, created_at
            FROM purchases
            WHERE telegram_id = %s
              AND payload LIKE 'sylvex_%%sub:%%'
            ORDER BY created_at DESC
            LIMIT 1
        """, (telegram_id,))
        row = cursor.fetchone()
    finally:
        cursor.close()
        conn.close()

    item = SHOP_ITEMS.get("sub_month")
    charge_id = None
    provider = "recovery"
    amount = 0
    currency = "REC"
    payload = None

    if row:
        payload_str = row[1] or ""
        parsed = parse_shop_payload(payload_str)
        plan_key = parsed.get("plan_key") or "month"
        item = SHOP_ITEMS.get(f"sub_{plan_key}") or SHOP_ITEMS.get("sub_month")
        charge_id = row[4] or f"recovery_sub_{telegram_id}_{int(row[5].timestamp()) if row[5] else 0}"
        provider = row[0] or "telegram_stars"
        amount = row[2] or 0
        currency = row[3] or "USD"
        payload = payload_str
    else:
        item = SHOP_ITEMS.get("sub_month")
        charge_id = f"recovery_sub_month_{telegram_id}"
        payload = bot_stars_payload(telegram_id, item, charge_id)

    if not item or not charge_id:
        return False

    inserted = activate_subscription(
        telegram_id=telegram_id,
        item=item,
        provider=provider,
        amount=amount,
        currency=currency,
        payload=payload,
        charge_id=charge_id,
    )

    if inserted and item.get("bonus_credits"):
        add_user_balance(telegram_id, int(item["bonus_credits"]))
        log_user_event(
            telegram_id=telegram_id,
            source="system",
            event_type="subscription_restored",
            event_name=f"restore_{item.get('plan_key')}",
            payload={
                "subscription_type": item.get("plan_key"),
                "charge_id": charge_id,
            },
        )
        log_user_event(
            telegram_id=telegram_id,
            source="system",
            event_type="credits_added",
            event_name="subscription_bonus_restored",
            payload={
                "credits": int(item["bonus_credits"]),
                "charge_id": charge_id,
            },
        )
    return inserted










_USER_EVENTS_SCHEMA_LOCK = threading.Lock()
_USER_EVENTS_SCHEMA_READY = False
def ensure_user_events_table():
    # SQL-4: this used to re-run its full DDL batch on every call (every
    # call is on the get_user_state() hot path) - guarded the same way
    # ensure_prostudio_table() already is, with the ready flag only ever
    # set after a successful commit, so a failed migration leaves the
    # next call free to retry rather than wrongly caching the failure.
    global _USER_EVENTS_SCHEMA_READY
    if _USER_EVENTS_SCHEMA_READY or not DATABASE_URL:
        return
    with _USER_EVENTS_SCHEMA_LOCK:
        if _USER_EVENTS_SCHEMA_READY:
            return
        conn = db_connect(DATABASE_URL)
        cursor = conn.cursor()
        try:
            cursor.execute("""
            CREATE TABLE IF NOT EXISTS user_events (
                id SERIAL PRIMARY KEY,
                telegram_id BIGINT NOT NULL,
                source TEXT NOT NULL,
                event_type TEXT NOT NULL,
                event_name TEXT,
                payload JSONB DEFAULT '{}'::jsonb,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
            """)
            # get_user_state()'s "SELECT ... FROM user_events WHERE telegram_id
            # = %s ORDER BY created_at DESC LIMIT 20" had nothing to use but a
            # full table scan - telegram_id wasn't indexed here at all.
            cursor.execute("""
            CREATE INDEX IF NOT EXISTS idx_user_events_user_created
            ON user_events (telegram_id, created_at DESC)
            """)
            conn.commit()
            _USER_EVENTS_SCHEMA_READY = True
        except Exception:
            conn.rollback()
            raise
        finally:
            cursor.close()
            conn.close()


_PAYMENT_SCHEMA_LOCK = threading.Lock()
_PAYMENT_SCHEMA_READY = False
def ensure_payment_tables():
    # SQL-4: webhook retry storms (PayPal retries, concurrent Stars
    # purchases) called this on every webhook delivery; guard it the same
    # way ensure_prostudio_table() already is.
    global _PAYMENT_SCHEMA_READY
    if _PAYMENT_SCHEMA_READY or not DATABASE_URL:
        return
    with _PAYMENT_SCHEMA_LOCK:
        if _PAYMENT_SCHEMA_READY:
            return
        conn = db_connect(DATABASE_URL)
        cursor = conn.cursor()
        try:
            cursor.execute("""
            CREATE TABLE IF NOT EXISTS purchases (
                id SERIAL PRIMARY KEY,
                telegram_id BIGINT NOT NULL,
                provider TEXT NOT NULL,
                credits INTEGER DEFAULT 0,
                amount INTEGER DEFAULT 0,
                currency TEXT DEFAULT 'USD',
                payload TEXT,
                charge_id TEXT UNIQUE,
                status TEXT DEFAULT 'completed',
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
            """)
            # get_user_state()'s "SELECT ... FROM purchases WHERE telegram_id = %s
            # ORDER BY created_at DESC LIMIT 10" had no index to use at all -
            # telegram_id was neither the PK nor covered by any other index, so
            # every call was a full table scan followed by a sort.
            cursor.execute("""
            CREATE INDEX IF NOT EXISTS idx_purchases_user_created
            ON purchases (telegram_id, created_at DESC)
            """)
            cursor.execute("""
            CREATE TABLE IF NOT EXISTS subscriptions (
                id SERIAL PRIMARY KEY,
                telegram_id BIGINT NOT NULL,
                subscription_type TEXT,
                payment_method TEXT,
                amount INTEGER DEFAULT 0,
                currency TEXT DEFAULT 'USD',
                starts_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                expires_at TIMESTAMP,
                status TEXT DEFAULT 'active',
                charge_id TEXT UNIQUE,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
            """)
            # get_user_state() runs two queries against this table for every
            # session/me and generation call: the active subscription (telegram_id
            # + status='active' + expires_at > NOW(), ORDER BY expires_at DESC
            # LIMIT 1) and the latest one regardless of status (telegram_id,
            # ORDER BY expires_at DESC NULLS LAST LIMIT 1), plus the UPDATE that
            # expires stale rows the same way. None of that was indexed - every
            # call scanned the whole subscriptions table. NULLS LAST matches the
            # latest-subscription query's own ORDER BY exactly so that one can be
            # served by a pure index scan with no extra sort step; the
            # active-subscription query still benefits from the telegram_id
            # prefix narrowing the scan before its status/expires_at filter runs.
            cursor.execute("""
            CREATE INDEX IF NOT EXISTS idx_subscriptions_user_expires
            ON subscriptions (telegram_id, expires_at DESC NULLS LAST)
            """)
            cursor.execute("""
            CREATE TABLE IF NOT EXISTS paypal_orders (
                id SERIAL PRIMARY KEY,
                telegram_id BIGINT NOT NULL,
                pack_id TEXT NOT NULL,
                purchase_type TEXT NOT NULL,
                paypal_order_id TEXT UNIQUE NOT NULL,
                paypal_capture_id TEXT UNIQUE,
                amount INTEGER NOT NULL,
                currency TEXT DEFAULT 'USD',
                status TEXT DEFAULT 'created',
                checkout_url TEXT,
                payload TEXT,
                raw_event JSONB DEFAULT '{}'::jsonb,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
            """)
            cursor.execute("""
            CREATE TABLE IF NOT EXISTS paypal_subscriptions (
                id SERIAL PRIMARY KEY,
                telegram_id BIGINT NOT NULL,
                pack_id TEXT NOT NULL DEFAULT 'sub_month',
                plan_id TEXT NOT NULL,
                paypal_subscription_id TEXT UNIQUE NOT NULL,
                amount INTEGER NOT NULL DEFAULT 500,
                currency TEXT DEFAULT 'USD',
                status TEXT DEFAULT 'pending',
                payload TEXT,
                raw_event JSONB DEFAULT '{}'::jsonb,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
            """)
            cursor.execute("""
            CREATE TABLE IF NOT EXISTS subscription_reminders (
                id SERIAL PRIMARY KEY,
                subscription_id INTEGER NOT NULL,
                telegram_id BIGINT NOT NULL,
                days_before INTEGER NOT NULL,
                status TEXT NOT NULL DEFAULT 'sending',
                sent_at TIMESTAMP,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                UNIQUE(subscription_id, days_before)
            )
            """)
            conn.commit()
            _PAYMENT_SCHEMA_READY = True
        except Exception:
            conn.rollback()
            raise
        finally:
            cursor.close()
            conn.close()


def ensure_generations_index():
    """get_user_state() runs two queries against `generations` on every
    call - a COUNT(*) and a "SELECT ... ORDER BY created_at DESC LIMIT 10" -
    both filtered by telegram_id. That table isn't created anywhere in this
    codebase (it predates this webapp and is shared with the Telegram bot),
    so its schema is only known through how it's already queried - and none
    of those queries had a supporting index, making both of them full table
    scans on what is likely the single largest table in the whole database.
    Guarded by to_regclass() rather than assuming the table exists, since
    this process doesn't own its schema; cached like ensure_prostudio_table()
    so this check runs once per process, not on every request.
    """
    global _GENERATIONS_INDEX_READY
    if _GENERATIONS_INDEX_READY or not DATABASE_URL:
        return
    with GENERATIONS_INDEX_LOCK:
        if _GENERATIONS_INDEX_READY:
            return
        conn = db_connect(DATABASE_URL)
        cursor = conn.cursor()
        try:
            cursor.execute("SELECT to_regclass('public.generations')")
            if cursor.fetchone()[0]:
                cursor.execute("""
                    CREATE INDEX IF NOT EXISTS idx_generations_user_created
                    ON generations (telegram_id, created_at DESC)
                """)
                conn.commit()
            _GENERATIONS_INDEX_READY = True
        finally:
            cursor.close()
            conn.close()


def _sanitize_event_payload(value, max_text=512, max_items=20, depth=3):
    if depth <= 0:
        return None
    if isinstance(value, dict):
        sanitized = {}
        for i, (k, v) in enumerate(value.items()):
            if i >= max_items:
                break
            sanitized[str(k)] = _sanitize_event_payload(v, max_text, max_items, depth - 1)
        return sanitized
    if isinstance(value, list):
        return [_sanitize_event_payload(v, max_text, max_items, depth - 1) for v in value[:max_items]]
    if isinstance(value, str):
        return value if len(value) <= max_text else value[:max_text] + '…'
    if isinstance(value, (int, float, bool)) or value is None:
        return value
    return str(value)[:max_text]


def log_user_event(
    telegram_id: int,
    source: str,
    event_type: str,
    event_name: str = "",
    payload: Optional[dict] = None,
):
    if not DATABASE_URL or not telegram_id or not source or not event_type:
        return

    ensure_user_events_table()
    try:
        payload = payload or {}
        sanitized = _sanitize_event_payload(payload)
        payload_str = json.dumps(sanitized, ensure_ascii=False)

        conn = db_connect(DATABASE_URL)
        cursor = conn.cursor()
        try:
            cursor.execute(
                """
                INSERT INTO user_events (telegram_id, source, event_type, event_name, payload)
                VALUES (%s, %s, %s, %s, %s::jsonb)
                """,
                (telegram_id, source, event_type, event_name or None, payload_str),
            )
            conn.commit()
        finally:
            cursor.close()
            conn.close()
    except Exception as exc:
        print("LOG EVENT FAILED:", exc)
    try:
        track_referral_activity(telegram_id, event_type, event_name)
    except Exception as exc:
        print("REFERRAL ACTIVITY TRACKING FAILED:", exc)


def _to_iso(v):
    if v is None:
        return None
    try:
        return v.isoformat()
    except Exception:
        try:
            return str(v)
        except Exception:
            return None


