def referral_code_for(telegram_id: int) -> str:
    digest = hashlib.sha1(f"sylvex:{telegram_id}".encode("utf-8")).hexdigest()[:10]
    return f"sylvex_{digest}"


def get_referral_state(telegram_id: int, activate: bool = False) -> dict:
    if not telegram_id:
        return {}

    code = referral_code_for(telegram_id)
    bot_username = (os.getenv("TELEGRAM_BOT_USERNAME") or "sylvexai_bot").strip().lstrip("@")
    link = f"https://t.me/{bot_username}?startapp=ref_{code}_shop"

    if not DATABASE_URL:
        return {
            "ok": True,
            "telegram_id": telegram_id,
            "code": code,
            "link": link,
            "referrals_count": 0,
            "generation_events": 0,
            "subscription_events": 0,
            "activated_at": None,
        }

    ensure_user_exists(telegram_id)
    ensure_user_referrals_table()
    conn = db_connect(DATABASE_URL)
    cursor = conn.cursor()
    try:
        cursor.execute("""
            INSERT INTO user_referrals (telegram_id, code, activated_at)
            VALUES (%s, %s, CASE WHEN %s THEN NOW() ELSE NULL END)
            ON CONFLICT (telegram_id) DO UPDATE
            SET activated_at = CASE
                WHEN %s AND user_referrals.activated_at IS NULL THEN NOW()
                ELSE user_referrals.activated_at
            END
            RETURNING activated_at
        """, (telegram_id, code, activate, activate))
        row = cursor.fetchone()
        cursor.execute("""
            SELECT COUNT(*), COALESCE(SUM(generation_count), 0),
                   COALESCE(SUM(subscription_count), 0)
            FROM referral_attributions
            WHERE inviter_telegram_id = %s
        """, (telegram_id,))
        referral_totals = cursor.fetchone() or (0, 0, 0)
        conn.commit()
    finally:
        cursor.close()
        conn.close()

    return {
        "ok": True,
        "telegram_id": telegram_id,
        "code": code,
        "link": link,
        "referrals_count": int(referral_totals[0] or 0),
        "generation_events": int(referral_totals[1] or 0),
        "subscription_events": int(referral_totals[2] or 0),
        "activated_at": _to_iso(row[0]) if row and row[0] else None,
    }


def claim_referral(invited_telegram_id: int, referral_code: str) -> dict:
    """Permanently attributes a user to the first valid referrer."""
    if not DATABASE_URL or not invited_telegram_id or not referral_code:
        return {"ok": False, "error": "referral_unavailable"}

    ensure_user_referrals_table()
    conn = db_connect(DATABASE_URL)
    cursor = conn.cursor()
    try:
        cursor.execute(
            "SELECT telegram_id FROM user_referrals WHERE code = %s",
            (referral_code,),
        )
        owner = cursor.fetchone()
        if not owner:
            return {"ok": False, "error": "referral_not_found"}
        inviter_telegram_id = int(owner[0])
        if inviter_telegram_id == int(invited_telegram_id):
            return {"ok": False, "error": "self_referral"}
        cursor.execute("""
            INSERT INTO referral_attributions
                (invited_telegram_id, inviter_telegram_id, referral_code)
            VALUES (%s, %s, %s)
            ON CONFLICT (invited_telegram_id) DO NOTHING
            RETURNING invited_telegram_id
        """, (invited_telegram_id, inviter_telegram_id, referral_code))
        created = bool(cursor.fetchone())
        conn.commit()
    finally:
        cursor.close()
        conn.close()
    return {"ok": True, "claimed": created, "shop": True}


def track_referral_activity(telegram_id: int, event_type: str, event_name: str):
    """Records activity for manual referral reward review by administrators."""
    is_generation = event_name == "generation_completed"
    is_subscription = event_type == "subscription_activated" or event_name == "subscription_activated"
    if not DATABASE_URL or not telegram_id or not (is_generation or is_subscription):
        return
    ensure_user_referrals_table()
    conn = db_connect(DATABASE_URL)
    cursor = conn.cursor()
    try:
        cursor.execute("""
            UPDATE referral_attributions
            SET last_activity_at = NOW(),
                generation_count = generation_count + %s,
                subscription_count = subscription_count + %s,
                last_event_name = %s
            WHERE invited_telegram_id = %s
            RETURNING inviter_telegram_id
        """, (1 if is_generation else 0, 1 if is_subscription else 0, event_name, telegram_id))
        owner = cursor.fetchone()
        if owner:
            cursor.execute("""
                INSERT INTO user_events (telegram_id, source, event_type, event_name, payload)
                VALUES (%s, 'referral_system', 'referral_activity', %s, %s::jsonb)
            """, (int(owner[0]), event_name, json.dumps({"invited_telegram_id": telegram_id})))
        conn.commit()
    finally:
        cursor.close()
        conn.close()


def get_user_state(telegram_id: int, username: str = None, first_name: str = None) -> dict:
    if not DATABASE_URL or not telegram_id:
        return {}

    state_started = time.monotonic()

    def _mark(stage):
        print("USER_STATE_TIMING:", {"stage": stage, "ms": round((time.monotonic() - state_started) * 1000), "telegram_id": telegram_id})

    ensure_start = time.monotonic()
    ensure_user_exists(telegram_id)
    print("USER_STATE_TIMING:", {"stage": "ensure_user_exists", "ms": round((time.monotonic() - ensure_start) * 1000), "telegram_id": telegram_id})
    ensure_start = time.monotonic()
    ensure_generations_index()
    print("USER_STATE_TIMING:", {"stage": "ensure_generations_index", "ms": round((time.monotonic() - ensure_start) * 1000), "telegram_id": telegram_id})
    if username or first_name:
        conn = db_connect(DATABASE_URL)
        cursor = conn.cursor()
        try:
            q_start = time.monotonic()
            cursor.execute("""
                UPDATE users
                SET username = COALESCE(%s, username),
                    first_name = COALESCE(%s, first_name)
                WHERE telegram_id = %s
            """, (username, first_name, telegram_id))
            conn.commit()
            print("USER_STATE_TIMING:", {"stage": "update_username", "ms": round((time.monotonic() - q_start) * 1000), "telegram_id": telegram_id})
        finally:
            cursor.close()
            conn.close()

    conn = db_connect(DATABASE_URL)
    cursor = conn.cursor()
    try:
        q_start = time.monotonic()
        cursor.execute("""
            SELECT telegram_id, username, first_name, balance, subscription, created_at
            FROM users
            WHERE telegram_id = %s
        """, (telegram_id,))
        user_row = cursor.fetchone()
        print("USER_STATE_TIMING:", {"stage": "select_users", "ms": round((time.monotonic() - q_start) * 1000), "telegram_id": telegram_id})
        if not user_row:
            return {}

        q_start = time.monotonic()
        cursor.execute("""
            SELECT s.subscription_type, s.expires_at::timestamp
            FROM subscriptions s
            WHERE s.telegram_id = %s AND """ + shop_orders.VALID_ENTITLEMENT_SQL + """
            ORDER BY """ + shop_orders.EFFECTIVE_ORDER_SQL + """
            LIMIT 1
        """, (telegram_id,))
        active_sub = cursor.fetchone()
        cursor.execute("""
            SELECT subscription_type, expires_at::timestamp
            FROM subscriptions
            WHERE telegram_id = %s
            ORDER BY expires_at::timestamp DESC NULLS LAST, id DESC
            LIMIT 1
        """, (telegram_id,))
        latest_sub = cursor.fetchone()
        print("USER_STATE_TIMING:", {"stage": "select_subscriptions", "ms": round((time.monotonic() - q_start) * 1000), "telegram_id": telegram_id})

        q_start = time.monotonic()
        if active_sub:
            cursor.execute("""
                UPDATE users
                SET subscription = COALESCE(%s, 'active')
                WHERE telegram_id = %s
            """, (active_sub[0], telegram_id))
            conn.commit()
        else:
            cursor.execute("""
                UPDATE subscriptions
                SET status = 'expired'
                WHERE telegram_id = %s
                  AND status = 'active'
                  AND expires_at::timestamp <= NOW()
            """, (telegram_id,))
            cursor.execute("""
                UPDATE users
                SET subscription = NULL
                WHERE telegram_id = %s
                  AND subscription IS NOT NULL
            """, (telegram_id,))
            conn.commit()
        print("USER_STATE_TIMING:", {"stage": "update_subscription_status", "ms": round((time.monotonic() - q_start) * 1000), "telegram_id": telegram_id})

        q_start = time.monotonic()
        cursor.execute("""
            SELECT COUNT(*)
            FROM generations
            WHERE telegram_id = %s
        """, (telegram_id,))
        total_generations = cursor.fetchone()[0] or 0
        print("USER_STATE_TIMING:", {"stage": "select_generations_count", "ms": round((time.monotonic() - q_start) * 1000), "telegram_id": telegram_id})

        q_start = time.monotonic()
        try:
            cursor.execute("""
                SELECT COALESCE(SUM(credits), 0)
                FROM generation_charges
                WHERE telegram_id = %s
            """, (telegram_id,))
            tokens_spent = max(0, int(cursor.fetchone()[0] or 0))
        except Exception:
            tokens_spent = 0
        print("USER_STATE_TIMING:", {"stage": "select_generation_charges", "ms": round((time.monotonic() - q_start) * 1000), "telegram_id": telegram_id})

        q_start = time.monotonic()
        referrals_count = 0
        community_posts_count = 0
        community_likes_count = 0
        cursor.execute("SELECT to_regclass('public.referral_attributions')")
        if cursor.fetchone()[0]:
            cursor.execute("SELECT COUNT(*) FROM referral_attributions WHERE inviter_telegram_id = %s", (telegram_id,))
            referrals_count = int(cursor.fetchone()[0] or 0)
        cursor.execute("SELECT to_regclass('public.community_posts'), to_regclass('public.community_likes')")
        community_tables = cursor.fetchone() or (None, None)
        if community_tables[0]:
            cursor.execute("SELECT COUNT(*) FROM community_posts WHERE telegram_id = %s", (telegram_id,))
            community_posts_count = int(cursor.fetchone()[0] or 0)
        if community_tables[0] and community_tables[1]:
            cursor.execute("""
                SELECT COUNT(*)
                FROM community_likes likes
                JOIN community_posts posts ON posts.id = likes.post_id
                WHERE posts.telegram_id = %s
            """, (telegram_id,))
            community_likes_count = int(cursor.fetchone()[0] or 0)
        print("USER_STATE_TIMING:", {"stage": "referrals_and_community_counts", "ms": round((time.monotonic() - q_start) * 1000), "telegram_id": telegram_id})

        q_start = time.monotonic()
        cursor.execute("""
            SELECT event_type, event_name, source, payload, created_at
            FROM user_events
            WHERE telegram_id = %s
            ORDER BY created_at DESC
            LIMIT 20
        """, (telegram_id,))
        events = cursor.fetchall()
        print("USER_STATE_TIMING:", {"stage": "select_user_events", "ms": round((time.monotonic() - q_start) * 1000), "telegram_id": telegram_id})

        q_start = time.monotonic()
        cursor.execute("""
            SELECT provider, credits, amount, currency, payload, charge_id, status, created_at
            FROM purchases
            WHERE telegram_id = %s
            ORDER BY created_at DESC
            LIMIT 10
        """, (telegram_id,))
        purchases = cursor.fetchall()
        print("USER_STATE_TIMING:", {"stage": "select_purchases", "ms": round((time.monotonic() - q_start) * 1000), "telegram_id": telegram_id})

        q_start = time.monotonic()
        cursor.execute("""
            SELECT generation_type, prompt, status, created_at
            FROM generations
            WHERE telegram_id = %s
            ORDER BY created_at DESC
            LIMIT 10
        """, (telegram_id,))
        generations = cursor.fetchall()
        conn.commit()
        print("USER_STATE_TIMING:", {"stage": "select_generations_and_commit", "ms": round((time.monotonic() - q_start) * 1000), "telegram_id": telegram_id})
    finally:
        release_start = time.monotonic()
        cursor.close()
        conn.close()
        print("USER_STATE_TIMING:", {"stage": "release", "ms": round((time.monotonic() - release_start) * 1000), "telegram_id": telegram_id})
    _mark("total")

    profile = get_user_profile(telegram_id)
    subscription_status = "active" if active_sub else "free"
    subscription_details = None
    if latest_sub:  # only users who ever had a plan; keeps the hot path cheap
        try:
            ensure_shop_orders()
            subscription_details = _subscription_public(shop_orders.subscription_summary(shop_db, telegram_id))
        except Exception as exc:
            prostudio_error("USER_STATE_SUBSCRIPTION_DETAILS_FAILED", exc, telegram_id=telegram_id)
    last_subscription_expires_at = _to_iso(latest_sub[1]) if latest_sub and latest_sub[1] else None
    subscription_expired = bool(latest_sub and latest_sub[1] and not active_sub and latest_sub[1].timestamp() <= time.time())
    result = {
        "telegram_id": user_row[0],
        "username": user_row[1],
        "first_name": user_row[2],
        "balance": user_row[3] or 0,
        "status": "active" if active_sub else (user_row[4] or "free"),
        "subscription_status": subscription_status,
        "subscription_plan": active_sub[0] if active_sub else None,
        "subscription_expires_at": _to_iso(active_sub[1]) if active_sub and active_sub[1] else None,
        "last_subscription_expires_at": last_subscription_expires_at,
        "subscription_expired": subscription_expired,
        "subscription_details": subscription_details,
        "display_name": profile.get("display_name"),
        "custom_avatar_url": profile.get("custom_avatar_url"),
        "theme_preference": profile.get("theme_preference") or {},
        "created_at": user_row[5],
        "total_generations": total_generations,
        "generations_count": total_generations,
        "tokens_spent": tokens_spent,
        "referrals_count": referrals_count,
        "community_posts_count": community_posts_count,
        "community_likes_count": community_likes_count,
        "last_actions": [
            {
                "event_type": row[0],
                "event_name": row[1],
                "source": row[2],
                "payload": row[3],
                "created_at": _to_iso(row[4]) if row[4] else None,
            }
            for row in events
        ],
        "last_purchases": [
            {
                "provider": row[0],
                "credits": row[1],
                "amount": row[2],
                "currency": row[3],
                "payload": row[4],
                "charge_id": row[5],
                "status": row[6],
                "created_at": _to_iso(row[7]) if row[7] else None,
            }
            for row in purchases
        ],
        "last_generations": [
            {
                "generation_type": row[0],
                "prompt": row[1],
                "status": row[2],
                "created_at": _to_iso(row[3]) if row[3] else None,
            }
            for row in generations
        ],
    }
    return result


def get_fast_user_state(telegram_id: int) -> dict:
    if not telegram_id:
        return {
            "balance": 0,
            "subscription": None,
            "subscription_until": None,
            "status": "free",
        }
    if not DATABASE_URL:
        return {
            "balance": 0,
            "subscription": None,
            "subscription_until": None,
            "status": "free",
        }

    ensure_user_exists(telegram_id)
    conn = db_connect(DATABASE_URL)
    cursor = conn.cursor()
    try:
        cursor.execute("""
            SELECT COALESCE(balance, 0)
            FROM users
            WHERE telegram_id = %s
        """, (telegram_id,))
        user_row = cursor.fetchone()

        cursor.execute("""
            SELECT s.subscription_type, s.expires_at::timestamp
            FROM subscriptions s
            WHERE s.telegram_id = %s AND """ + shop_orders.VALID_ENTITLEMENT_SQL + """
            ORDER BY """ + shop_orders.EFFECTIVE_ORDER_SQL + """
            LIMIT 1
        """, (telegram_id,))
        active_sub = cursor.fetchone()
        cursor.execute("""
            SELECT subscription_type, expires_at::timestamp
            FROM subscriptions
            WHERE telegram_id = %s
            ORDER BY expires_at::timestamp DESC NULLS LAST, id DESC
            LIMIT 1
        """, (telegram_id,))
        latest_sub = cursor.fetchone()
    finally:
        cursor.close()
        conn.close()

    balance = user_row[0] if user_row else 0
    subscription = active_sub[0] if active_sub else None
    subscription_until = _to_iso(active_sub[1]) if active_sub and active_sub[1] else None
    status = "pro" if active_sub else "free"
    last_subscription_expires_at = _to_iso(latest_sub[1]) if latest_sub and latest_sub[1] else None
    subscription_expired = bool(latest_sub and latest_sub[1] and not active_sub and latest_sub[1].timestamp() <= time.time())
    profile = get_user_profile(telegram_id)

    return {
        "telegram_id": telegram_id,
        "balance": balance or 0,
        "subscription": subscription,
        "subscription_until": subscription_until,
        "status": status,
        "subscription_status": "active" if active_sub else "free",
        "subscription_plan": subscription,
        "subscription_expires_at": subscription_until,
        "last_subscription_expires_at": last_subscription_expires_at,
        "subscription_expired": subscription_expired,
        "display_name": profile.get("display_name"),
        "custom_avatar_url": profile.get("custom_avatar_url"),
        "theme_preference": profile.get("theme_preference") or {},
    }


def create_purchase_once(telegram_id: int, provider: str, credits: int, amount: int, currency: str, payload: str, charge_id: str) -> bool:
    if not DATABASE_URL:
        return False

    ensure_payment_tables()
    conn = db_connect(DATABASE_URL)
    cursor = conn.cursor()
    try:
        cursor.execute("""
            INSERT INTO purchases (telegram_id, provider, credits, amount, currency, payload, charge_id, status)
            VALUES (%s, %s, %s, %s, %s, %s, %s, 'completed')
            ON CONFLICT (charge_id) DO NOTHING
        """, (telegram_id, provider, credits, amount, currency, payload, charge_id))
        created = cursor.rowcount > 0
        conn.commit()
        return created
    finally:
        cursor.close()
        conn.close()


def activate_subscription(telegram_id: int, item: dict, provider: str, amount: int, currency: str, payload: str, charge_id: str) -> bool:
    if not DATABASE_URL:
        return False

    ensure_user_exists(telegram_id)
    ensure_payment_tables()
    conn = db_connect(DATABASE_URL)
    cursor = conn.cursor()
    try:
        # Serialize subscription changes for this user so two confirmations
        # cannot overwrite one another or lose already-paid remaining time.
        cursor.execute("SELECT telegram_id FROM users WHERE telegram_id = %s FOR UPDATE", (telegram_id,))
        cursor.execute("""
            DELETE FROM subscription_reminders
            WHERE status = 'sending'
              AND created_at < NOW() - INTERVAL '1 hour'
        """)
        cursor.execute("""
            INSERT INTO subscriptions (
                telegram_id, subscription_type, payment_method, amount, currency, expires_at, status, charge_id
            )
            VALUES (
                %s, %s, %s, %s, %s,
                (
                    SELECT GREATEST(
                        CURRENT_TIMESTAMP,
                        COALESCE(MAX(expires_at::timestamp), CURRENT_TIMESTAMP)
                    ) + (%s || ' days')::interval
                    FROM subscriptions
                    WHERE telegram_id = %s
                      AND status = 'active'
                      AND expires_at::timestamp > CURRENT_TIMESTAMP
                ),
                'active', %s
            )
            ON CONFLICT (charge_id) DO NOTHING
            RETURNING id
        """, (telegram_id, item["plan_key"], provider, amount, currency, item["days"], telegram_id, charge_id))
        inserted_row = cursor.fetchone()
        inserted = bool(inserted_row)
        if inserted:
            cursor.execute("""
                UPDATE subscriptions
                SET status = 'cancelled'
                WHERE telegram_id = %s
                  AND status = 'active'
                  AND id <> %s
            """, (telegram_id, inserted_row[0]))
            cursor.execute("UPDATE users SET subscription = %s WHERE telegram_id = %s", (item.get("plan_key") or "active", telegram_id))
        conn.commit()
        return inserted
    finally:
        cursor.close()
        conn.close()




def ensure_user_exists(telegram_id: int):
    if not DATABASE_URL or not telegram_id:
        return

    conn = db_connect(DATABASE_URL)
    cursor = conn.cursor()
    try:
        cursor.execute("""
            INSERT INTO users (telegram_id, first_name, balance, subscription)
            VALUES (%s, 'Developer', 0, 'free')
            ON CONFLICT (telegram_id) DO NOTHING
        """, (telegram_id,))
        conn.commit()
    finally:
        cursor.close()
        conn.close()

# =====================================================
# БАЛАНС И СТОИМОСТЬ: add_user_balance
# Рассчитывает стоимость генерации, проверяет токены пользователя или фиксирует списание после успешного результата.
# =====================================================
def add_user_balance(telegram_id: int, credits: int):
    if not DATABASE_URL or not telegram_id or not credits:
        return

    ensure_user_exists(telegram_id)
    conn = db_connect(DATABASE_URL)
    cursor = conn.cursor()
    try:
        cursor.execute(
            "UPDATE users SET balance = COALESCE(balance, 0) + %s WHERE telegram_id = %s",
            (credits, telegram_id),
        )
        conn.commit()
    finally:
        cursor.close()
        conn.close()


# =====================================================
# БАЛАНС И СТОИМОСТЬ: charge_generation_balance
# Рассчитывает стоимость генерации, проверяет токены пользователя или фиксирует списание после успешного результата.
# =====================================================
def charge_generation_balance(telegram_id: int, generation_id: str, result: dict, payload: dict) -> dict:
    snapshot = payload.get("price_snapshot") if isinstance(payload.get("price_snapshot"), dict) else {}
    credits = int(snapshot.get("final_credits") or result.get("cost_credits") or result.get("cost") or result.get("price") or 0)
    if not DATABASE_URL or not telegram_id or not generation_id:
        return {"charged": False, "credits": max(0, credits), "balance_after": None, "error": "billing_unavailable"}
    ensure_user_exists(telegram_id)
    ensure_prostudio_table()
    ensure_reservations(lambda: db_connect(DATABASE_URL))
    try:
        return settle_generation(lambda: db_connect(DATABASE_URL), telegram_id, generation_id, credits, payload, result)
    except SecurityError as exc:
        return {"charged": False, "credits": max(0, credits), "balance_after": None, "error": exc.code, "insufficient_balance": exc.status == 402}


def finalize_shop_payment(telegram_id: int, provider: str, item: dict, amount: int, currency: str, payload: str, charge_id: str):
    if not DATABASE_URL:
        raise RuntimeError("database_not_configured")
    credits = int(item.get("credits") or 0)
    bonus_credits = int(item.get("bonus_credits") or 0)
    ensure_user_exists(telegram_id)
    ensure_payment_tables()
    created = apply_payment(lambda: db_connect(DATABASE_URL), telegram_id, provider, item, amount, currency, payload, charge_id)
    if not created:
        return False
    # Preserve referral/reporting events after the atomic financial commit.
    try:
        log_user_event(
            telegram_id=telegram_id,
            source="payment",
            event_type="payment_success",
            event_name="payment_success",
            payload={
                "provider": provider,
                "pack_id": item.get("plan_key") or f"credits_{credits}",
                "amount": amount,
                "currency": currency,
                "charge_id": charge_id,
                "payload": payload,
            },
        )

        if item["kind"] == "subscription":
            activated = True
            if activated:
                log_user_event(
                    telegram_id=telegram_id,
                    source="payment",
                    event_type="subscription_activated",
                    event_name=f"activate_{item.get('plan_key')}",
                    payload={
                        "subscription_type": item.get("plan_key"),
                        "expires_in_days": item.get("days"),
                        "charge_id": charge_id,
                    },
                )
            if bonus_credits:
                log_user_event(
                    telegram_id=telegram_id,
                    source="payment",
                    event_type="credits_added",
                    event_name="subscription_bonus_credits",
                    payload={
                        "credits": bonus_credits,
                        "charge_id": charge_id,
                    },
                )
            if activated:
                send_subscription_congratulations(telegram_id, item, provider)
        else:
            log_user_event(
                telegram_id=telegram_id,
                source="payment",
                event_type="credits_added",
                event_name="credits_purchase",
                payload={
                    "credits": credits,
                    "charge_id": charge_id,
                },
            )

    except Exception as exc:
        print("PAYMENT POST-COMMIT NOTIFICATION FAILED:", type(exc).__name__)
    return True


def send_subscription_congratulations(telegram_id: int, item: dict, provider: str = "") -> bool:
    if not BOT_TOKEN or not telegram_id:
        return False
    name = "Пользователь"
    username = ""
    expires_at = None
    balance = 0
    try:
        conn = db_connect(DATABASE_URL)
        cursor = conn.cursor()
        try:
            cursor.execute("SELECT first_name, username, COALESCE(balance, 0) FROM users WHERE telegram_id = %s", (telegram_id,))
            user_row = cursor.fetchone()
            if user_row:
                name = user_row[0] or user_row[1] or name
                username = user_row[1] or ""
                balance = int(user_row[2] or 0)
            cursor.execute("""
                SELECT expires_at::timestamp
                FROM subscriptions
                WHERE telegram_id = %s AND status = 'active'
                ORDER BY expires_at::timestamp DESC LIMIT 1
            """, (telegram_id,))
            sub_row = cursor.fetchone()
            expires_at = sub_row[0] if sub_row else None
        finally:
            cursor.close()
            conn.close()
    except Exception as exc:
        prostudio_error("SUBSCRIPTION_CONGRATULATION_PROFILE_FAILED", exc, telegram_id=telegram_id)

    plan_label = shop_catalog.plan_label(item.get("plan_key"))
    handle = f"@{html.escape(username)}" if username else "без username"
    expiry_label = expires_at.strftime("%d.%m.%Y %H:%M") if expires_at else "активна"
    text = (
        f"🎉 <b>Поздравляем с подпиской {html.escape(shop_catalog.plan_product_name(item.get('plan_key')))}!</b>\n\n"
        f"👤 <b>{html.escape(str(name))}</b> · {handle}\n"
        f"🆔 <code>{int(telegram_id)}</code>\n"
        f"💎 План: <b>{plan_label}</b>\n"
        f"📅 Действует до: <b>{expiry_label}</b>\n"
        f"⚡️ Баланс: <b>{balance}</b>\n"
        f"💳 Оплата: <b>{html.escape(str(provider or 'payment'))}</b>\n\n"
        "Все инструменты Pro уже доступны. Можно сразу начинать генерацию."
    )
    try:
        response = requests.post(
            f"https://api.telegram.org/bot{BOT_TOKEN}/sendMessage",
            json={
                "chat_id": int(telegram_id),
                "text": text,
                "parse_mode": "HTML",
                "disable_web_page_preview": True,
                "reply_markup": {"inline_keyboard": [
                    [{"text": "Начать генерацию", "web_app": {"url": WEBAPP_URL.rstrip("/") + "/webapp/index.html?view=home"}}],
                    [{"text": "Открыть Pro Studio", "web_app": {"url": WEBAPP_URL.rstrip("/") + "/webapp/index.html?view=tools"}}],
                ]},
            },
            timeout=20,
        )
        data = response.json() if response.content else {}
        if response.status_code >= 400 or not data.get("ok"):
            raise RuntimeError(f"Telegram sendMessage failed: {response.status_code} {data}")
        return True
    except Exception as exc:
        prostudio_error("SUBSCRIPTION_CONGRATULATION_FAILED", exc, telegram_id=telegram_id)
        return False


def reset_developer_subscription(telegram_id: int, reset_credits: bool = False) -> dict:
    if not DATABASE_URL:
        raise RuntimeError("DATABASE_URL is not configured")

    ensure_payment_tables()
    ensure_user_exists(telegram_id)

    conn = db_connect(DATABASE_URL)
    cursor = conn.cursor()
    try:
        cursor.execute("""
            UPDATE subscriptions
            SET status = 'cancelled'
            WHERE telegram_id = %s
              AND status = 'active'
        """, (telegram_id,))
        cancelled = cursor.rowcount

        if reset_credits:
            cursor.execute("""
                UPDATE users
                SET subscription = 'free', balance = 0
                WHERE telegram_id = %s
            """, (telegram_id,))
        else:
            cursor.execute("""
                UPDATE users
                SET subscription = 'free'
                WHERE telegram_id = %s
            """, (telegram_id,))

        conn.commit()
    finally:
        cursor.close()
        conn.close()

    return {
        "cancelled_subscriptions": cancelled,
        "reset_credits": reset_credits,
    }


# =====================================================
# =====================================================


def paypal_configured() -> bool:
    # PayPal is retired, even while old Railway Variables are being removed.
    return False


# =====================================================
# PYTHON-БЛОК: paypal_subscriptions_configured
# Both Pro plan ids must be set (env-only, see PAYPAL_PRO_MONTHLY_PLAN_ID/
# PAYPAL_PRO_YEARLY_PLAN_ID above) before any subscription endpoint may
# proceed - Orders/Capture credit purchases (paypal_configured() alone)
# work independently of this.
# =====================================================
def paypal_subscriptions_configured() -> bool:
    return bool(paypal_configured() and PAYPAL_PRO_MONTHLY_PLAN_ID and PAYPAL_PRO_YEARLY_PLAN_ID)


def paypal_access_token(api_base: str = None) -> str:
    if not paypal_configured():
        raise RuntimeError("PayPal credentials are not configured")

    base = api_base or PAYPAL_API_BASE
    response = requests.post(
        f"{base}/v1/oauth2/token",
        auth=(PAYPAL_CLIENT_ID, PAYPAL_CLIENT_SECRET),
        data={"grant_type": "client_credentials"},
        headers={"Accept": "application/json", "Accept-Language": "en_US"},
        timeout=30,
    )
    if response.status_code >= 400:
        print("PAYPAL TOKEN ERROR:", response.status_code, response.text[:1000])
        raise RuntimeError("PayPal token request failed")

    token = response.json().get("access_token")
    if not token:
        raise RuntimeError("PayPal token response did not include access_token")
    return token


def paypal_headers(api_base: str = None) -> dict:
    return {
        "Authorization": f"Bearer {paypal_access_token(api_base)}",
        "Content-Type": "application/json",
        "Accept": "application/json",
    }


def paypal_return_url(telegram_id: int, pack_id: str, status: str) -> str:
    params = urllib.parse.urlencode({
        "view": "shop",
        "payment": status,
        "provider": "paypal",
        "pack_id": pack_id or "",
        "telegram_id": str(telegram_id or ""),
    })
    return SHOP_WEBAPP_URL + ("&" if "?" in SHOP_WEBAPP_URL else "?") + params


# =====================================================
# PYTHON-БЛОК: paypal_website_return_url
# A Website-authenticated Orders/Capture purchase (create_paypal_order's
# is_website branch) must return the buyer to the Website's own Store page,
# never to the Telegram Mini App's SHOP_WEBAPP_URL above - a plain browser
# outside Telegram can't do anything useful with that URL. Website identity
# is resolved server-side from the account's own session anyway (see
# resolve_web_session_uid), so this deliberately carries no telegram_id/
# pack_id query params - nothing here is trusted, it's a landing page only.
# =====================================================
def paypal_website_return_url(status: str) -> str:
    return f"{WEBSITE_URL.rstrip('/')}/store.html?payment={status}"


def paypal_purchase_type(item: dict) -> str:
    return "subscription" if item.get("kind") == "subscription" else "tokens"


def create_paypal_order(telegram_id: int, pack_id: str, item: dict, is_website: bool = False) -> dict:
    amount_value = f"{float(item['usd']):.2f}"
    payload = shop_payload("paypal", telegram_id, pack_id, item)
    if is_website:
        return_url = paypal_website_return_url("success")
        cancel_url = paypal_website_return_url("cancelled")
    else:
        return_url = paypal_return_url(telegram_id, pack_id, "success")
        cancel_url = paypal_return_url(telegram_id, pack_id, "cancel")
    body = {
        "intent": "CAPTURE",
        "purchase_units": [
            {
                "reference_id": pack_id,
                "custom_id": payload,
                "description": item.get("title") or "SYLVEX purchase",
                "amount": {
                    "currency_code": "USD",
                    "value": amount_value,
                },
            }
        ],
        "payment_source": {
            "paypal": {
                "experience_context": {
                    "brand_name": "SYLVEX",
                    "shipping_preference": "NO_SHIPPING",
                    "user_action": "PAY_NOW",
                    "return_url": return_url,
                    "cancel_url": cancel_url,
                }
            }
        },
    }
    response = requests.post(
        f"{PAYPAL_API_BASE}/v2/checkout/orders",
        headers={**paypal_headers(), "PayPal-Request-Id": f"sylvex-{telegram_id}-{pack_id}-{uuid4().hex}"},
        json=body,
        timeout=30,
    )
    if response.status_code >= 400:
        print("PAYPAL ORDER ERROR:", response.status_code, response.text[:1000])
        raise RuntimeError("PayPal order request failed")
    return response.json()


def paypal_approve_url(order: dict) -> str:
    for link in order.get("links") or []:
        if link.get("rel") in {"approve", "payer-action"} and link.get("href"):
            return link["href"]
    return ""


# =====================================================
# СОХРАНЕНИЕ В БАЗУ ДАННЫХ: save_paypal_order
# Записывает состояние пользователя, job, metadata или результат генерации в общую базу Mini App и Telegram Bot.
# =====================================================
def save_paypal_order(telegram_id: int, pack_id: str, item: dict, order: dict, checkout_url: str):
    if not DATABASE_URL:
        return

    ensure_payment_tables()
    conn = db_connect(DATABASE_URL)
    cursor = conn.cursor()
    try:
        cursor.execute("""
            INSERT INTO paypal_orders (
                telegram_id, pack_id, purchase_type, paypal_order_id, amount, currency, status, checkout_url, payload, raw_event
            )
            VALUES (%s, %s, %s, %s, %s, 'USD', %s, %s, %s, %s::jsonb)
            ON CONFLICT (paypal_order_id) DO UPDATE
            SET checkout_url = EXCLUDED.checkout_url,
                status = EXCLUDED.status,
                raw_event = EXCLUDED.raw_event,
                updated_at = CURRENT_TIMESTAMP
        """, (
            telegram_id,
            pack_id,
            paypal_purchase_type(item),
            order.get("id"),
            int(round(float(item["usd"]) * 100)),
            (order.get("status") or "created").lower(),
            checkout_url,
            shop_payload("paypal", telegram_id, pack_id, item),
            json.dumps(order),
        ))
        conn.commit()
    finally:
        cursor.close()
        conn.close()


def verify_paypal_webhook(headers, event: dict) -> bool:
    if not PAYPAL_WEBHOOK_ID:
        print("PAYPAL WEBHOOK: PAYPAL_WEBHOOK_ID is not configured")
        return False

    required = {
        "auth_algo": headers.get("paypal-auth-algo"),
        "cert_url": headers.get("paypal-cert-url"),
        "transmission_id": headers.get("paypal-transmission-id"),
        "transmission_sig": headers.get("paypal-transmission-sig"),
        "transmission_time": headers.get("paypal-transmission-time"),
    }
    if not all(required.values()):
        return False

    body = {
        **required,
        "webhook_id": PAYPAL_WEBHOOK_ID,
        "webhook_event": event,
    }
    bases = [PAYPAL_API_BASE]
    alternate = "https://api-m.paypal.com" if PAYPAL_API_BASE != "https://api-m.paypal.com" else "https://api-m.sandbox.paypal.com"
    bases.append(alternate)
    for base in bases:
        try:
            response = requests.post(
                f"{base}/v1/notifications/verify-webhook-signature",
                headers=paypal_headers(base),
                json=body,
                timeout=30,
            )
        except Exception as exc:
            print("PAYPAL WEBHOOK VERIFY ERROR:", base, exc)
            continue
        if response.status_code >= 400:
            print("PAYPAL WEBHOOK VERIFY ERROR:", base, response.status_code, response.text[:1000])
            continue
        if response.json().get("verification_status") == "SUCCESS":
            return True
    return False


def paypal_capture_details(resource: dict) -> dict:
    order_id = resource.get("supplementary_data", {}).get("related_ids", {}).get("order_id")
    capture_id = resource.get("id")
    amount = resource.get("amount") or {}
    return {
        "order_id": order_id,
        "capture_id": capture_id,
        "status": resource.get("status") or "",
        "amount": int(round(float(amount.get("value") or 0) * 100)),
        "currency": amount.get("currency_code") or "USD",
    }


def finalize_paypal_capture(event: dict) -> bool:
    resource = event.get("resource") or {}
    details = paypal_capture_details(resource)
    order_id = details["order_id"]
    capture_id = details["capture_id"]
    if not order_id or not capture_id:
        return False
    if (details["status"] or "").upper() != "COMPLETED":
        return False
    if not DATABASE_URL:
        return False

    ensure_payment_tables()
    conn = db_connect(DATABASE_URL)
    cursor = conn.cursor()
    try:
        cursor.execute("""
            SELECT telegram_id, pack_id, amount, currency, status, payload
            FROM paypal_orders
            WHERE paypal_order_id = %s
        """, (order_id,))
        row = cursor.fetchone()
        if not row:
            return False

        telegram_id, pack_id, stored_amount, stored_currency, status, payload = row
        if status == "completed":
            return False
        item = shop_item(pack_id)
        if not item:
            return False

        charge_id = f"paypal_capture_{capture_id}"
        created = finalize_shop_payment(
            telegram_id=int(telegram_id),
            provider="paypal",
            item=item,
            amount=details["amount"] or stored_amount,
            currency=details["currency"] or stored_currency or "USD",
            payload=payload or shop_payload("paypal", int(telegram_id), pack_id, item),
            charge_id=charge_id,
        )
        cursor.execute("""
            UPDATE paypal_orders
            SET paypal_capture_id = COALESCE(paypal_capture_id, %s),
                status = CASE WHEN %s THEN 'completed' ELSE status END,
                raw_event = %s::jsonb,
                updated_at = CURRENT_TIMESTAMP
            WHERE paypal_order_id = %s
        """, (capture_id, created, json.dumps(event), order_id))
        conn.commit()
        if created:
            try:
                sync_user_to_db({
                    "telegram_id": int(telegram_id),
                    "username": None,
                    "first_name": None,
                    "status": "free",
                    "balance": 0,
                })
            except Exception as exc:
                print("PAYPAL WEBHOOK: sync failed", exc)
        return created
    finally:
        cursor.close()
        conn.close()


# Every PayPal subscription-lifecycle event this webhook must not silently
# drop, mapped to the paypal_subscriptions.status it records. Only
# `revoke=True` events actually end SYLVEX Pro access - a single
# PAYMENT.FAILED is PayPal's own dunning/retry process still in flight, not
# a final state (PayPal itself follows up with SUSPENDED once retries are
# exhausted, which does revoke), so it's recorded for visibility without
# cutting the subscriber off mid-retry.
_PAYPAL_SUBSCRIPTION_LIFECYCLE_EVENTS = {
    "BILLING.SUBSCRIPTION.CANCELLED": ("cancelled", True),
    "BILLING.SUBSCRIPTION.SUSPENDED": ("suspended", True),
    "BILLING.SUBSCRIPTION.EXPIRED": ("expired", True),
    "BILLING.SUBSCRIPTION.PAYMENT.FAILED": ("payment_failed", False),
}


# =====================================================
# PYTHON-БЛОК: sync_paypal_subscription_lifecycle_event
# Handles the non-payment subscription lifecycle events PayPal sends over
# this same webhook - CANCELLED/SUSPENDED/EXPIRED (which must end SYLVEX
# Pro access immediately, the same way a manual admin cancel already does:
# flip subscriptions.status off 'active' and clear users.subscription, so
# get_user_state()'s own active-subscription query - status='active' AND
# expires_at > NOW() - stops finding it right away rather than waiting for
# expires_at to naturally lapse) and PAYMENT.FAILED (recorded only, access
# unchanged - see _PAYPAL_SUBSCRIPTION_LIFECYCLE_EVENTS above). Idempotent:
# redelivering the same event is a no-op once paypal_subscriptions.status
# already matches.
# =====================================================
def sync_paypal_subscription_lifecycle_event(event: dict) -> bool:
    event_type = event.get("event_type") or ""
    mapping = _PAYPAL_SUBSCRIPTION_LIFECYCLE_EVENTS.get(event_type)
    if not mapping:
        return False
    new_status, revoke = mapping

    resource = event.get("resource") or {}
    subscription_id = resource.get("id") or paypal_subscription_id_from_event(event)
    if not subscription_id or not DATABASE_URL:
        return False

    ensure_payment_tables()
    conn = db_connect(DATABASE_URL)
    cursor = conn.cursor()
    try:
        cursor.execute(
            "SELECT telegram_id, status FROM paypal_subscriptions WHERE paypal_subscription_id = %s",
            (subscription_id,),
        )
        row = cursor.fetchone()
        if not row:
            return False
        telegram_id, current_status = row
        if current_status == new_status:
            return False  # already applied - PayPal redelivered the same event

        cursor.execute(
            """
            UPDATE paypal_subscriptions
            SET status = %s, raw_event = %s::jsonb, updated_at = CURRENT_TIMESTAMP
            WHERE paypal_subscription_id = %s
            """,
            (new_status, json.dumps(event), subscription_id),
        )
        if revoke:
            cursor.execute(
                "UPDATE subscriptions SET status = %s WHERE telegram_id = %s AND status = 'active'",
                (new_status, int(telegram_id)),
            )
            cursor.execute(
                "UPDATE users SET subscription = NULL WHERE telegram_id = %s AND subscription IS NOT NULL",
                (int(telegram_id),),
            )
        conn.commit()
        return True
    finally:
        cursor.close()
        conn.close()


def paypal_subscription_pack_for_plan(plan_id: str, plan_type: str = "") -> str:
    normalized_type = (plan_type or "").strip().lower()
    # `and PAYPAL_PRO_MONTHLY_PLAN_ID` guards against an unconfigured (empty
    # string) env var matching an equally-empty/missing plan_id - without
    # it, "" == "" would silently resolve an unconfigured deployment to
    # sub_month for any request that simply omits plan_id.
    if (plan_id and plan_id == PAYPAL_PRO_MONTHLY_PLAN_ID) or normalized_type in {"month", "monthly"}:
        return "sub_month"
    if (plan_id and plan_id == PAYPAL_PRO_YEARLY_PLAN_ID) or normalized_type in {"year", "yearly", "annual"}:
        return "sub_year"
    return ""


# =====================================================
# СОХРАНЕНИЕ В БАЗУ ДАННЫХ: save_paypal_subscription
# Записывает состояние пользователя, job, metadata или результат генерации в общую базу Mini App и Telegram Bot.
# =====================================================
def save_paypal_subscription(telegram_id: int, subscription_id: str, plan_id: str, plan_type: str = "") -> bool:
    if not DATABASE_URL:
        return False

    pack_id = paypal_subscription_pack_for_plan(plan_id, plan_type)
    item = shop_item(pack_id)
    if not item or not pack_id:
        return False

    ensure_payment_tables()
    ensure_user_exists(telegram_id)
    conn = db_connect(DATABASE_URL)
    cursor = conn.cursor()
    try:
        cursor.execute("""
            INSERT INTO paypal_subscriptions (
                telegram_id, pack_id, plan_id, paypal_subscription_id, amount, currency, status, payload
            )
            VALUES (%s, %s, %s, %s, %s, 'USD', 'pending', %s)
            ON CONFLICT (paypal_subscription_id) DO UPDATE
            SET pack_id = EXCLUDED.pack_id,
                plan_id = EXCLUDED.plan_id,
                status = CASE
                    WHEN paypal_subscriptions.status = 'active' THEN paypal_subscriptions.status
                    ELSE 'pending'
                END,
                updated_at = CURRENT_TIMESTAMP
            WHERE paypal_subscriptions.telegram_id = EXCLUDED.telegram_id
              AND paypal_subscriptions.plan_id = EXCLUDED.plan_id
        """, (
            telegram_id,
            pack_id,
            plan_id,
            subscription_id,
            int(round(float(item["usd"]) * 100)),
            shop_payload("paypal_subscription", telegram_id, pack_id, item),
        ))
        saved = cursor.rowcount > 0
        conn.commit()
        return saved
    finally:
        cursor.close()
        conn.close()


def paypal_subscription_id_from_event(event: dict) -> str:
    resource = event.get("resource") or {}
    event_type = event.get("event_type") or ""
    if event_type.startswith("BILLING.SUBSCRIPTION."):
        return resource.get("id") or ""
    return (
        resource.get("billing_agreement_id")
        or resource.get("billing_subscription_id")
        or resource.get("subscription_id")
        or resource.get("supplementary_data", {}).get("related_ids", {}).get("billing_agreement_id")
        or ""
    )


def paypal_subscription_payment_details(event: dict) -> dict:
    resource = event.get("resource") or {}
    amount = resource.get("amount") or {}
    if "total" in amount:
        value = amount.get("total")
        currency = amount.get("currency") or "USD"
    else:
        value = amount.get("value")
        currency = amount.get("currency_code") or "USD"
    charge_id = resource.get("id") or paypal_subscription_id_from_event(event)
    try:
        cents = int(round(float(value or 5.0) * 100))
    except Exception:
        cents = 500
    return {"amount": cents, "currency": currency, "charge_id": charge_id}


def activate_paypal_subscription_from_event(event: dict) -> bool:
    if event.get("event_type") != "PAYMENT.SALE.COMPLETED":
        return False
    subscription_id = paypal_subscription_id_from_event(event)
    if not subscription_id or not DATABASE_URL:
        return False

    details = paypal_subscription_payment_details(event)
    ensure_payment_tables()
    conn = db_connect(DATABASE_URL)
    cursor = conn.cursor()
    try:
        cursor.execute("""
            SELECT telegram_id, pack_id, amount, currency, status, payload
            FROM paypal_subscriptions
            WHERE paypal_subscription_id = %s
        """, (subscription_id,))
        row = cursor.fetchone()
        if not row:
            # Webhook may arrive before browser onApprove. Recover ownership from PayPal's signed binding.
            verified = verified_paypal_subscription(subscription_id)
            plan = str(verified.get("plan_id") or "")
            uid = read_binding(verified.get("custom_id"), plan)
            if not save_paypal_subscription(uid, subscription_id, plan):
                raise HTTPException(status_code=503, detail="paypal_subscription_binding_pending")
            cursor.execute("SELECT telegram_id, pack_id, amount, currency, status, payload FROM paypal_subscriptions WHERE paypal_subscription_id=%s", (subscription_id,))
            row = cursor.fetchone()
            if not row:
                raise HTTPException(status_code=503, detail="paypal_subscription_binding_pending")

        telegram_id, pack_id, stored_amount, stored_currency, status, payload = row
        item = shop_item(pack_id or "sub_month")
        if not item:
            return False

        event_type = event.get("event_type") or ""
        if not details.get("charge_id") or int(details.get("amount") or 0) != int(stored_amount) or details.get("currency") != stored_currency:
            raise HTTPException(status_code=400, detail="paypal_payment_amount_mismatch")

        charge_prefix = "paypal_sale" if event_type == "PAYMENT.SALE.COMPLETED" else "paypal_subscription"
        charge_source = details["charge_id"] or subscription_id
        charge_id = f"{charge_prefix}_{charge_source}"
        created = finalize_shop_payment(
            telegram_id=int(telegram_id),
            provider="paypal_subscription",
            item=item,
            amount=details["amount"] or stored_amount,
            currency=details["currency"] or stored_currency or "USD",
            payload=payload or shop_payload("paypal_subscription", int(telegram_id), pack_id, item),
            charge_id=charge_id,
        )
        cursor.execute("""
            UPDATE paypal_subscriptions
            SET status = CASE WHEN %s THEN 'active' ELSE status END,
                raw_event = %s::jsonb,
                updated_at = CURRENT_TIMESTAMP
            WHERE paypal_subscription_id = %s
        """, (created, json.dumps(event), subscription_id))
        conn.commit()
        if created:
            try:
                sync_user_to_db({
                    "telegram_id": int(telegram_id),
                    "username": None,
                    "first_name": None,
                    "status": "free",
                    "balance": 0,
                })
            except Exception as exc:
                print("PAYPAL SUBSCRIPTION WEBHOOK: sync failed", exc)
        return created
    finally:
        cursor.close()
        conn.close()


# =====================================================
# LEMONSQUEEZY: subscription checkout + webhook
#
# Simpler than the PayPal integration above: LemonSqueezy checkouts accept
# arbitrary custom metadata (checkout_data.custom) that is echoed back on
# every webhook event about that checkout/subscription
# (meta.custom_data), so telegram_id/pack_id travel with the purchase
# itself - no separate orders-tracking table or owner-binding HMAC needed.
# Only subscription packs (sub_month/sub_year) are wired up; grant logic is
# entirely reused from finalize_shop_payment()/apply_payment() (idempotent
# on charge_id) - the same function PayPal and Stars already use.
# =====================================================
def lemonsqueezy_variant_for_pack(pack_id: str) -> str:
    return {
        "sub_month": LEMONSQUEEZY_VARIANT_MONTH or "",
        "sub_year": LEMONSQUEEZY_VARIANT_YEAR or "",
    }.get(pack_id, "")


def lemonsqueezy_pack_for_variant(variant_id) -> str:
    variant = str(variant_id or "")
    if variant and LEMONSQUEEZY_VARIANT_MONTH and variant == str(LEMONSQUEEZY_VARIANT_MONTH):
        return "sub_month"
    if variant and LEMONSQUEEZY_VARIANT_YEAR and variant == str(LEMONSQUEEZY_VARIANT_YEAR):
        return "sub_year"
    return ""


def lemonsqueezy_headers() -> dict:
    return {
        "Authorization": f"Bearer {LEMONSQUEEZY_API_KEY}",
        "Accept": "application/vnd.api+json",
        "Content-Type": "application/vnd.api+json",
    }


def verify_lemonsqueezy_webhook(raw_body: bytes, signature_header: str) -> bool:
    if not LEMONSQUEEZY_WEBHOOK_SECRET or not signature_header:
        return False
    digest = hmac.new(LEMONSQUEEZY_WEBHOOK_SECRET.encode("utf-8"), raw_body, hashlib.sha256).hexdigest()
    try:
        return hmac.compare_digest(digest, signature_header.strip())
    except (TypeError, ValueError):
        return False


