# СОХРАНЕНИЕ В БАЗУ ДАННЫХ: save_generation
# Записывает состояние пользователя, job, metadata или результат генерации в общую базу Mini App и Telegram Bot.
# =====================================================
def save_generation(telegram_id: int, generation_type: str, prompt: str, status: str = "done"):
    if not DATABASE_URL or not telegram_id:
        return
    try:
        with db_connection(DATABASE_URL) as conn:
            cursor = conn.cursor()
            cursor.execute("""
                INSERT INTO generations (telegram_id, generation_type, prompt, status)
                VALUES (%s, %s, %s, %s)
            """, (telegram_id, generation_type, prompt, status))
            cursor.close()
    except Exception as exc:
        print("GENERATION SAVE FAILED:", exc)

_PROSTUDIO_SCHEMA_READY = False


def ensure_prostudio_table():
    # This used to run its full ~25-statement DDL batch (CREATE TABLE/INDEX +
    # ALTER TABLE ADD COLUMN) behind a global lock on every single call - and
    # it's called from nearly every hot-path function (job claim, job
    # create, active-job check, heartbeat...). With N concurrent workers
    # that serializes all of them behind one Python lock for a full DB round
    # trip each time, on every job. The schema only ever needs to be ensured
    # once per process lifetime; ensure_provider_slot_table already uses
    # this exact double-checked-locking cache pattern.
    global _PROSTUDIO_SCHEMA_READY
    if _PROSTUDIO_SCHEMA_READY:
        return
    if not DATABASE_URL:
        return

    with PROSTUDIO_SCHEMA_LOCK:
        if _PROSTUDIO_SCHEMA_READY:
            return
        conn = db_connect(DATABASE_URL)
        cursor = conn.cursor()
        try:
            # Release the schema lock on rollback as well as commit; a failed
            # migration must not leave a session lock on a pooled connection.
            cursor.execute("SELECT pg_advisory_xact_lock(%s)", (742193601,))
            cursor.execute("""CREATE TABLE IF NOT EXISTS prostudio_edit_sessions (
                telegram_id BIGINT NOT NULL, id TEXT NOT NULL, title TEXT NOT NULL DEFAULT '',
                preview_url TEXT NOT NULL DEFAULT '', result_count INTEGER NOT NULL DEFAULT 0,
                state_json JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY (telegram_id, id))""")
            cursor.execute("""CREATE INDEX IF NOT EXISTS idx_edit_sessions_owner_updated
                ON prostudio_edit_sessions (telegram_id, updated_at DESC)""")
            # User-set conversation title and pin (History menu); messages
            # themselves stay in prostudio_messages.
            cursor.execute("""CREATE TABLE IF NOT EXISTS prostudio_conversation_meta (
                telegram_id BIGINT NOT NULL, conversation_id TEXT NOT NULL,
                title TEXT, pinned_at TIMESTAMPTZ, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                PRIMARY KEY (telegram_id, conversation_id))""")
            cursor.execute("""CREATE TABLE IF NOT EXISTS prostudio_grid_projects (
                telegram_id BIGINT NOT NULL, id TEXT NOT NULL, title TEXT NOT NULL DEFAULT '',
                preview_url TEXT NOT NULL DEFAULT '', node_count INTEGER NOT NULL DEFAULT 0,
                state_json JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY (telegram_id, id))""")
            cursor.execute("""CREATE INDEX IF NOT EXISTS idx_grid_projects_owner_updated
                ON prostudio_grid_projects (telegram_id, updated_at DESC)""")
            # SYLVEX Video Editor projects (webapp/js/video-editor/project.js).
            # share_token reopens the same project outside Telegram.
            cursor.execute("""CREATE TABLE IF NOT EXISTS prostudio_video_projects (
                telegram_id BIGINT NOT NULL, id TEXT NOT NULL, title TEXT NOT NULL DEFAULT '',
                preview_url TEXT NOT NULL DEFAULT '', share_token TEXT NOT NULL,
                state_json JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY (telegram_id, id))""")
            cursor.execute("""CREATE INDEX IF NOT EXISTS idx_video_projects_owner_updated
                ON prostudio_video_projects (telegram_id, updated_at DESC)""")
            cursor.execute("""CREATE INDEX IF NOT EXISTS idx_video_projects_share
                ON prostudio_video_projects (id, share_token)""")
            cursor.execute("""
        CREATE TABLE IF NOT EXISTS prostudio_messages (
            id SERIAL PRIMARY KEY,
            conversation_id TEXT NOT NULL,
            telegram_id BIGINT NOT NULL,
            mode TEXT,
            prompt TEXT,
            response_text TEXT,
            image_url TEXT,
            created_at TIMESTAMP DEFAULT NOW()
        )
        """)
            cursor.execute("""
            CREATE INDEX IF NOT EXISTS idx_prostudio_messages_user_conv
            ON prostudio_messages (telegram_id, conversation_id, created_at DESC)
            """)
            # /api/public/prostudio/gallery filters by telegram_id alone (no
            # conversation_id predicate) and orders by created_at DESC, id
            # DESC - the index above can't serve that ordering without a
            # conversation_id equality filter (conversation_id sits between
            # telegram_id and created_at), so Postgres fell back to a full
            # table scan + sort across every user's messages. This index's
            # column order matches the gallery query's WHERE + ORDER BY
            # exactly, so it can walk rows in the query's own order and stop
            # as soon as LIMIT is satisfied.
            cursor.execute("""
            CREATE INDEX IF NOT EXISTS idx_prostudio_messages_user_created
            ON prostudio_messages (telegram_id, created_at DESC, id DESC)
            """)
            cursor.execute("ALTER TABLE prostudio_messages ADD COLUMN IF NOT EXISTS images_json TEXT")
            cursor.execute("ALTER TABLE prostudio_messages ADD COLUMN IF NOT EXISTS thumbnails_json TEXT")
            cursor.execute("ALTER TABLE prostudio_messages ADD COLUMN IF NOT EXISTS thumb_url TEXT")
            cursor.execute("ALTER TABLE prostudio_messages ADD COLUMN IF NOT EXISTS video_url TEXT")
            cursor.execute("ALTER TABLE prostudio_messages ADD COLUMN IF NOT EXISTS videos_json TEXT")
            cursor.execute("ALTER TABLE prostudio_messages ADD COLUMN IF NOT EXISTS audio_url TEXT")
            cursor.execute("ALTER TABLE prostudio_messages ADD COLUMN IF NOT EXISTS audios_json TEXT")
            cursor.execute("ALTER TABLE prostudio_messages ADD COLUMN IF NOT EXISTS metadata_json TEXT")
            cursor.execute("ALTER TABLE prostudio_messages ADD COLUMN IF NOT EXISTS status TEXT DEFAULT 'completed'")
            cursor.execute("ALTER TABLE prostudio_messages ADD COLUMN IF NOT EXISTS model TEXT")
            cursor.execute("ALTER TABLE prostudio_messages ADD COLUMN IF NOT EXISTS provider TEXT")
            cursor.execute("ALTER TABLE prostudio_messages ADD COLUMN IF NOT EXISTS cost INTEGER DEFAULT 0")
            cursor.execute("ALTER TABLE prostudio_messages ADD COLUMN IF NOT EXISTS request_json JSONB DEFAULT '{}'::jsonb")
            cursor.execute("ALTER TABLE prostudio_messages ADD COLUMN IF NOT EXISTS response_json JSONB DEFAULT '{}'::jsonb")
            cursor.execute("ALTER TABLE prostudio_messages ADD COLUMN IF NOT EXISTS updated_at TIMESTAMP DEFAULT NOW()")
            cursor.execute("ALTER TABLE prostudio_messages ADD COLUMN IF NOT EXISTS completed_at TIMESTAMP")
            cursor.execute("""
            CREATE TABLE IF NOT EXISTS prostudio_drafts (
                telegram_id BIGINT NOT NULL,
                mode TEXT NOT NULL,
                conversation_id TEXT,
                draft_text TEXT DEFAULT '',
                attachment_json JSONB DEFAULT '{}'::jsonb,
                updated_at TIMESTAMP DEFAULT NOW(),
                PRIMARY KEY (telegram_id, mode)
            )
            """)
            cursor.execute("""
            CREATE TABLE IF NOT EXISTS prostudio_resources (
                id TEXT PRIMARY KEY,
                telegram_id BIGINT NOT NULL,
                resource_type TEXT NOT NULL,
                name TEXT NOT NULL,
                description TEXT DEFAULT '',
                gender TEXT DEFAULT '',
                preview_url TEXT DEFAULT '',
                photos_json JSONB DEFAULT '[]'::jsonb,
                metadata_json JSONB DEFAULT '{}'::jsonb,
                status TEXT DEFAULT 'ready',
                created_at TIMESTAMP DEFAULT NOW(),
                updated_at TIMESTAMP DEFAULT NOW()
            )
            """)
            cursor.execute("""
            CREATE TABLE IF NOT EXISTS prostudio_voice_avatars (
                provider TEXT NOT NULL,
                voice_id TEXT NOT NULL,
                seed BIGINT NOT NULL,
                avatar_key TEXT UNIQUE NOT NULL,
                image_data BYTEA,
                content_type TEXT DEFAULT 'image/png',
                avatar_path TEXT DEFAULT '',
                status TEXT DEFAULT 'pending',
                error_text TEXT DEFAULT '',
                created_at TIMESTAMP DEFAULT NOW(),
                updated_at TIMESTAMP DEFAULT NOW(),
                PRIMARY KEY (provider, voice_id)
            )
            """)
            cursor.execute("""
            CREATE INDEX IF NOT EXISTS idx_prostudio_voice_avatars_status
            ON prostudio_voice_avatars (status, updated_at)
            """)
            cursor.execute("""
            CREATE INDEX IF NOT EXISTS idx_prostudio_resources_user_type
            ON prostudio_resources (telegram_id, resource_type, updated_at DESC)
            """)
            cursor.execute("""
            CREATE TABLE IF NOT EXISTS prostudio_visual_stats (
                resource_id TEXT NOT NULL,
                resource_type TEXT NOT NULL,
                likes_count INTEGER DEFAULT 0,
                selects_count INTEGER DEFAULT 0,
                heygen_stats_json JSONB DEFAULT '{}'::jsonb,
                updated_at TIMESTAMP DEFAULT NOW(),
                PRIMARY KEY (resource_id, resource_type)
            )
            """)
            cursor.execute("""
            CREATE TABLE IF NOT EXISTS prostudio_visual_user_state (
                telegram_id BIGINT NOT NULL,
                resource_id TEXT NOT NULL,
                resource_type TEXT NOT NULL,
                liked BOOLEAN DEFAULT FALSE,
                favorite BOOLEAN DEFAULT FALSE,
                selected_count INTEGER DEFAULT 0,
                updated_at TIMESTAMP DEFAULT NOW(),
                PRIMARY KEY (telegram_id, resource_id, resource_type)
            )
            """)
            cursor.execute("""
            CREATE TABLE IF NOT EXISTS prostudio_generation_jobs (
                id TEXT PRIMARY KEY,
                telegram_id BIGINT NOT NULL,
                conversation_id TEXT,
                mode TEXT NOT NULL,
                model TEXT,
                provider TEXT,
                prompt TEXT DEFAULT '',
                status TEXT DEFAULT 'queued',
                cost INTEGER DEFAULT 0,
                attempts INTEGER DEFAULT 0,
                locked_at TIMESTAMP,
                heartbeat_at TIMESTAMP,
                provider_wait_until TIMESTAMP,
                request_json JSONB DEFAULT '{}'::jsonb,
                response_json JSONB DEFAULT '{}'::jsonb,
                error_json JSONB DEFAULT '{}'::jsonb,
                result_json JSONB DEFAULT '{}'::jsonb,
                stage_json JSONB DEFAULT '{}'::jsonb,
                created_at TIMESTAMP DEFAULT NOW(),
                updated_at TIMESTAMP DEFAULT NOW(),
                completed_at TIMESTAMP
            )
            """)
            # IF NOT EXISTS still takes AccessExclusiveLock for ALTER TABLE.
            # Avoid those lock upgrades on every new web/worker process when
            # the columns already exist, and migrate before taking index locks.
            cursor.execute("""
                SELECT attname FROM pg_attribute
                WHERE attrelid = 'prostudio_generation_jobs'::regclass
                  AND attnum > 0 AND NOT attisdropped
            """)
            job_columns = {row[0] for row in cursor.fetchall()}
            for column, definition in (
                ("attempts", "INTEGER DEFAULT 0"),
                ("locked_at", "TIMESTAMP"),
                ("heartbeat_at", "TIMESTAMP"),
                ("provider_wait_until", "TIMESTAMP"),
                ("stage_json", "JSONB DEFAULT '{}'::jsonb"),
            ):
                if column not in job_columns:
                    cursor.execute(
                        f"ALTER TABLE prostudio_generation_jobs ADD COLUMN IF NOT EXISTS {column} {definition}"
                    )
            cursor.execute("""
            CREATE INDEX IF NOT EXISTS idx_prostudio_jobs_user_mode
            ON prostudio_generation_jobs (telegram_id, mode, updated_at DESC)
            """)
            cursor.execute("""
            CREATE TABLE IF NOT EXISTS generation_charges (
                id SERIAL PRIMARY KEY,
                generation_id TEXT UNIQUE NOT NULL,
                telegram_id BIGINT NOT NULL,
                mode TEXT,
                model TEXT,
                provider TEXT,
                credits INTEGER NOT NULL,
                balance_after INTEGER,
                created_at TIMESTAMP DEFAULT NOW()
            )
            """)
            cursor.execute("""
            CREATE INDEX IF NOT EXISTS idx_generation_charges_user
            ON generation_charges (telegram_id, created_at DESC)
            """)
            cursor.execute("""
                CREATE INDEX IF NOT EXISTS idx_prostudio_jobs_provider_wait
                ON prostudio_generation_jobs (status, provider_wait_until, created_at)
            """)
            cursor.execute("""
            CREATE TABLE IF NOT EXISTS prostudio_errors (
                id SERIAL PRIMARY KEY,
                telegram_id BIGINT,
                job_id TEXT,
                provider TEXT,
                model TEXT,
                endpoint TEXT,
                request_id TEXT,
                status TEXT DEFAULT 'failed',
                error_text TEXT,
                request_json JSONB DEFAULT '{}'::jsonb,
                response_json JSONB DEFAULT '{}'::jsonb,
                stack_trace TEXT,
                created_at TIMESTAMP DEFAULT NOW()
            )
            """)
            cursor.execute("""
            CREATE TABLE IF NOT EXISTS prostudio_error_reports (
                id SERIAL PRIMARY KEY,
                telegram_id BIGINT NOT NULL,
                mode TEXT,
                provider TEXT,
                model TEXT,
                job_id TEXT,
                prompt TEXT,
                error_text TEXT,
                raw_error TEXT,
                status TEXT DEFAULT 'open',
                created_at TIMESTAMP DEFAULT NOW()
            )
            """)
            cursor.execute("""
                CREATE INDEX IF NOT EXISTS idx_prostudio_error_reports_user
                ON prostudio_error_reports (telegram_id, created_at DESC)
            """)
            # "Generated with this Character" history: one row per generated
            # media URL from a completed generation job that had a Character
            # actively selected/committed at submission time - a job that
            # returns several images (e.g. count=4) must produce several
            # rows, one per image, not one row for the whole job.
            # Deliberately a dedicated table (not just a metadata_json filter
            # over prostudio_messages) so the record of what counts as "this
            # Character's history" is unambiguous and never duplicated - the
            # UNIQUE index on (character_id, job_id, media_url) lets each
            # per-image insert use ON CONFLICT DO NOTHING, so a job that
            # gets marked completed more than once (retry/race) still
            # produces exactly one row per distinct image, never a
            # duplicate. Never stores a second copy of the media file -
            # media_url always points at the same URL the completed
            # generation itself already serves.
            cursor.execute("""
            CREATE TABLE IF NOT EXISTS prostudio_character_history (
                id TEXT PRIMARY KEY,
                character_id TEXT NOT NULL,
                telegram_id BIGINT NOT NULL,
                job_id TEXT NOT NULL,
                media_url TEXT NOT NULL,
                prompt TEXT DEFAULT '',
                model TEXT DEFAULT '',
                created_at TIMESTAMP DEFAULT NOW()
            )
            """)
            # The original index only covered (character_id, job_id), which
            # made every image after the first in a multi-image job collide
            # as a duplicate and get silently dropped. Replace it with one
            # that also includes media_url, so each distinct image of the
            # same job gets its own row.
            cursor.execute("DROP INDEX IF EXISTS idx_prostudio_character_history_job")
            cursor.execute("""
            CREATE UNIQUE INDEX IF NOT EXISTS idx_prostudio_character_history_job_media
            ON prostudio_character_history (character_id, job_id, media_url)
            """)
            cursor.execute("""
            CREATE INDEX IF NOT EXISTS idx_prostudio_character_history_lookup
            ON prostudio_character_history (character_id, telegram_id, created_at DESC)
            """)
            generation_storage.ensure_table(cursor)
            conn.commit()
            _PROSTUDIO_SCHEMA_READY = True
        except Exception:
            conn.rollback()
            raise
        finally:
            cursor.close()
            conn.close()

# telegram_id_required_response: the exact same 400 JSONResponse
# ({"ok": False, "error": "telegram_id_required"}) was constructed
# inline, identically, at 32 separate endpoint call sites (DUP-3). This
# is purely the response construction - how each endpoint obtains,
# parses, or validates telegram_id before deciding to call this is
# unchanged.
def telegram_id_required_response() -> JSONResponse:
    return JSONResponse({"ok": False, "error": "telegram_id_required"}, status_code=400)


def _json_list(value) -> list:
    if isinstance(value, list):
        return [item for item in value if item]
    if not value:
        return []
    try:
        data = json.loads(value)
        return [item for item in data if item] if isinstance(data, list) else []
    except Exception:
        return []

def _json_obj(value) -> dict:
    if isinstance(value, dict):
        return value
    if not value:
        return {}
    try:
        data = json.loads(value)
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}

# Job error records may carry raw provider/exception text (repr(exc), raw_error,
# traceback) that can embed secrets from a failed HTTP call. Any route that
# returns a job's stored error to its owner must go through this whitelist.
_PUBLIC_JOB_ERROR_FIELDS = {"ok", "error", "message", "status_code", "provider", "type"}


def _public_error_json(value) -> dict:
    if not isinstance(value, dict):
        return {}
    return {k: v for k, v in value.items() if k in _PUBLIC_JOB_ERROR_FIELDS}

def _safe_json_dumps(value) -> str:
    try:
        return json.dumps(value if value is not None else {}, ensure_ascii=False)
    except Exception:
        return "{}"

def _sql_text(value, max_text: int = 2000) -> str:
    if value is None:
        return ""
    if isinstance(value, str):
        return value[:max_text]
    if isinstance(value, (dict, list)):
        return _safe_json_dumps(_sanitize_event_payload(value, max_text=max_text, max_items=50, depth=5))[:max_text]
    return str(value)[:max_text]

def prostudio_debug(stage: str, **data):
    safe = _sanitize_event_payload(data, max_text=700, max_items=30, depth=4)
    print(f"PROSTUDIO DEBUG {stage}:", safe)

# =====================================================
# ОБРАБОТКА ОШИБОК: prostudio_error
# Преобразует техническую ошибку провайдера в понятное сообщение для пользователя и сохраняет диагностические данные для логов.
# =====================================================
def prostudio_error(stage: str, exc: Exception = None, **data):
    safe = _sanitize_event_payload(data, max_text=1000, max_items=30, depth=4)
    if exc is not None:
        safe["error"] = str(exc)
        safe["traceback"] = traceback.format_exc()
    print(f"PROSTUDIO ERROR {stage}:", safe)

PROSTUDIO_ACTIVE_JOB_STATUSES = ("queued", "processing", "provider_processing")


class ActiveProstudioJobError(RuntimeError):
    def __init__(self, job_id: str, status: str):
        super().__init__("active_generation_exists")
        self.job_id = str(job_id or "")
        self.status = str(status or "queued")


def publish_prostudio_queue_notification(conn, job_id: str) -> bool:
    """Wake worker services after the queued row has been committed.

    A notification failure never loses the durable job: workers immediately
    fall back to the original polling interval whenever LISTEN is unhealthy.
    """
    if not conn or not job_id:
        return False
    cursor = None
    try:
        cursor = conn.cursor()
        cursor.execute("SELECT pg_notify(%s, %s)", (PROSTUDIO_QUEUE_CHANNEL, str(job_id)[:240]))
        conn.commit()
        return True
    except Exception as exc:
        try:
            conn.rollback()
        except Exception:
            pass
        prostudio_error("WORKER_QUEUE_NOTIFY_FAILED", exc, job_id=job_id)
        return False
    finally:
        if cursor is not None:
            cursor.close()


def get_active_prostudio_job(telegram_id: int) -> dict:
    if not DATABASE_URL or not telegram_id:
        return {}
    ensure_prostudio_table()
    # Text responses are synchronous and never belong to the media worker
    # queue.  Jobs from the older implementation can still be present after a
    # deploy; treating them as active would restore a permanent UI lock on
    # every Mini App start.  Finish those legacy records explicitly instead of
    # silently deleting them, then continue looking for a real media job.
    cleanup_orphaned_text_prostudio_jobs(telegram_id)
    conn = db_connect(DATABASE_URL)
    cursor = conn.cursor()
    try:
        cursor.execute("""
            SELECT id, status, mode, model, provider, conversation_id, created_at, updated_at
            FROM prostudio_generation_jobs
            WHERE telegram_id = %s
              AND status IN ('queued', 'processing', 'provider_processing')
              AND LOWER(COALESCE(mode, '')) NOT IN ('text', 'chat', 'pro', 'lite')
            ORDER BY created_at ASC
            LIMIT 1
        """, (int(telegram_id),))
        row = cursor.fetchone()
        if not row:
            job = {}
        else:
            job = {
            "id": row[0],
            "job_id": row[0],
            "status": row[1],
            "mode": row[2],
            "model": row[3],
            "provider": row[4],
            "conversation_id": row[5],
            "created_at": _to_iso(row[6]),
            "updated_at": _to_iso(row[7]),
        }
    finally:
        cursor.close()
        conn.close()
    if job:
        recovery = recover_stale_prostudio_job(job["id"])
        if recovery.get("recovered"):
            return {}
    return job


def cleanup_orphaned_text_prostudio_jobs(telegram_id: int):
    """Terminally fail legacy text jobs that cannot be handled by a worker."""
    if not DATABASE_URL or not telegram_id:
        return
    conn = None
    cursor = None
    try:
        ensure_reservations(lambda: db_connect(DATABASE_URL))
        conn = db_connect(DATABASE_URL)
        cursor = conn.cursor()
        cursor.execute("""
            SELECT id
            FROM prostudio_generation_jobs
            WHERE telegram_id = %s
              AND status IN ('queued', 'processing', 'provider_processing')
              AND LOWER(COALESCE(mode, '')) IN ('text', 'chat', 'pro', 'lite')
            FOR UPDATE
        """, (int(telegram_id),))
        job_ids = [str(row[0]) for row in cursor.fetchall()]
        if not job_ids:
            conn.rollback()
            return
        error_payload = _safe_json_dumps({
            "ok": False,
            "error": "stale_task_cleanup",
            "message": "Текстовый запрос был остановлен после обновления приложения.",
        })
        cursor.execute("""
            UPDATE prostudio_generation_jobs
            SET status = 'failed', error_json = %s::jsonb,
                locked_at = NULL, heartbeat_at = NULL, provider_wait_until = NULL,
                updated_at = NOW(), completed_at = NOW()
            WHERE id = ANY(%s)
        """, (error_payload, job_ids))
        for job_id in job_ids:
            release_generation(cursor, job_id)
        conn.commit()
        prostudio_debug("LEGACY_TEXT_JOBS_CLEANED", telegram_id=int(telegram_id), count=len(job_ids))
    except Exception as exc:
        if conn is not None:
            conn.rollback()
        prostudio_error("LEGACY_TEXT_JOBS_CLEANUP_FAILED", exc, telegram_id=telegram_id)
    finally:
        if cursor is not None:
            cursor.close()
        if conn is not None:
            conn.close()


# =====================================================
# СОХРАНЕНИЕ В БАЗУ ДАННЫХ: create_prostudio_generation_job
# Записывает состояние пользователя, job, metadata или результат генерации в общую базу Mini App и Telegram Bot.
# =====================================================
def create_prostudio_generation_job(payload: dict) -> str:
    job_id = str(uuid4())
    telegram_id = int(payload.get("telegram_id") or 0)
    client_request_id = str(payload.get("client_request_id") or "").strip()
    prostudio_debug(
        "JOB_CREATE_START",
        job_id=job_id,
        telegram_id=telegram_id,
        mode=payload.get("mode") or payload.get("category") or "text",
        model=payload.get("model") or "",
        provider=payload.get("provider") or "",
        has_database=bool(DATABASE_URL),
        client_request_id=client_request_id,
    )
    if not DATABASE_URL or not telegram_id:
        prostudio_debug("JOB_CREATE_SKIPPED_DB", job_id=job_id, has_database=bool(DATABASE_URL), telegram_id=telegram_id)
        raise SecurityError("generation_queue_unavailable", 503)
    ensure_prostudio_table()
    ensure_reservations(lambda: db_connect(DATABASE_URL))
    conn = db_connect(DATABASE_URL)
    cursor = conn.cursor()
    try:
        # Serialize job creation per Telegram user across every web process.
        # The check and INSERT share one transaction, so simultaneous clicks
        # cannot create two active jobs.
        cursor.execute("SELECT pg_advisory_xact_lock(%s)", (telegram_id,))
        # Take the INSERT's table lock before any SELECT or balance reservation.
        # Otherwise a concurrent ALTER can queue behind our AccessShareLock,
        # then block our upgrade to RowExclusiveLock: a lock-upgrade deadlock.
        # RowExclusiveLock is compatible with other job creators/workers.
        cursor.execute("LOCK TABLE prostudio_generation_jobs IN ROW EXCLUSIVE MODE")
        if client_request_id:
            # A repeated request carrying the same client_request_id is a
            # transport-level retry/replay of the same user action (reload,
            # reconnect, double-submit of an in-flight request), never a new
            # generation - hand back the job that request already created
            # instead of dispatching a second provider call.
            cursor.execute("""
                SELECT id
                FROM prostudio_generation_jobs
                WHERE telegram_id = %s
                  AND request_json->>'client_request_id' = %s
                ORDER BY created_at DESC
                LIMIT 1
            """, (telegram_id, client_request_id))
            existing = cursor.fetchone()
            if existing:
                conn.rollback()
                prostudio_debug("JOB_CREATE_IDEMPOTENT_REPLAY", job_id=existing[0], client_request_id=client_request_id)
                return existing[0]
        cursor.execute("""
            SELECT id, status
            FROM prostudio_generation_jobs
            WHERE telegram_id = %s
              AND status IN ('queued', 'processing', 'provider_processing')
            ORDER BY created_at ASC
            LIMIT 1
        """, (telegram_id,))
        active = cursor.fetchone()
        if active:
            conn.rollback()
            raise ActiveProstudioJobError(active[0], active[1])
        price = payload.get("price_snapshot") if isinstance(payload.get("price_snapshot"), dict) else calculate_generation_price(payload).get("price_snapshot", {})
        payload["price_snapshot"] = price
        reserve_generation(cursor, telegram_id, job_id, int(price.get("final_credits") or 0))
        cursor.execute("""
            INSERT INTO prostudio_generation_jobs (
                id, telegram_id, conversation_id, mode, model, provider, prompt, status, request_json
            ) VALUES (%s, %s, %s, %s, %s, %s, %s, 'queued', %s::jsonb)
        """, (
            job_id,
            telegram_id,
            payload.get("conversation_id") or None,
            payload.get("mode") or payload.get("category") or "text",
            payload.get("model") or "",
            payload.get("provider") or "",
            payload.get("prompt") or "",
            _safe_json_dumps(payload),
        ))
        conn.commit()
        publish_prostudio_queue_notification(conn, job_id)
        prostudio_debug("JOB_CREATE_DONE", job_id=job_id, status="queued")
    except ActiveProstudioJobError:
        raise
    except Exception as exc:
        conn.rollback()
        prostudio_error("JOB_CREATE_FAILED", exc, job_id=job_id, telegram_id=telegram_id)
        raise
    finally:
        cursor.close()
        conn.close()
    return job_id


def reserve_direct_text_generation(telegram_id: int, credits: int, generation_id: str = "") -> str:
    """Reserve credits before calling a provider for work that is not queued
    as a media job (direct text, priced helpers). A caller-supplied
    generation_id is the idempotency key: reusing it is refused, so a
    retried request can never reserve or charge twice."""
    if not DATABASE_URL or not telegram_id:
        raise SecurityError("generation_queue_unavailable", 503)
    generation_id = generation_id or f"text-{uuid4()}"
    ensure_reservations(lambda: db_connect(DATABASE_URL))
    conn = db_connect(DATABASE_URL)
    cursor = conn.cursor()
    try:
        cursor.execute("SELECT pg_advisory_xact_lock(%s)", (telegram_id,))
        cursor.execute("SELECT 1 FROM generation_reservations WHERE generation_id = %s", (generation_id,))
        if cursor.fetchone():
            raise SecurityError("duplicate_request", 409)
        reserve_generation(cursor, telegram_id, generation_id, credits)
        conn.commit()
        return generation_id
    except Exception:
        conn.rollback()
        raise
    finally:
        cursor.close()
        conn.close()


def helper_generation_id(label: str, telegram_id: int, client_request_id: str = "") -> str:
    key = str(client_request_id or "").strip()[:128]
    if not key:
        return f"helper-{label}-{uuid4()}"
    digest = hashlib.sha256(f"{label}:{telegram_id}:{key}".encode("utf-8")).hexdigest()[:32]
    return f"helper-{label}-{digest}"


def settled_helper_credits(reserved: int, actual: Optional[int], label: str) -> int:
    """What a usage-billed helper is charged: the provider-reported usage at
    the SYLVEX rule, never above the reservation the user agreed to. Unknown
    usage settles at the reserved upper bound."""
    reserved = int(reserved or 0)
    if actual is None:
        return reserved
    if actual > reserved:
        print("HELPER_USAGE_ABOVE_RESERVATION:", {"label": label, "reserved": reserved, "actual": int(actual)})
        return reserved
    return max(0, int(actual))


async def run_billed_helper(telegram_id: int, credits: int, label: str, call, *, client_request_id: str = "", model: str = "", provider: str = "", usage_credits=None):
    """Priced helper call (Grid plan, idea routing, voice tools, previews,
    assistant AI mode): reserve the SYLVEX price, dispatch inside one billing
    scope, settle on success, release on failure. Unknown/zero price fails
    closed before any provider is contacted. For usage-billed LLM helpers
    `credits` is the capped upper bound and usage_credits(result) the actual
    provider usage at the SYLVEX rule; the difference is returned."""
    credits = int(credits or 0)
    if not telegram_id:
        raise SecurityError("telegram_id_required", 401)
    if credits <= 0:
        raise SecurityError("pricing_not_configured", 402)
    generation_id = helper_generation_id(label, telegram_id, client_request_id)
    await asyncio.to_thread(reserve_direct_text_generation, telegram_id, credits, generation_id)
    try:
        with billing_scope(generation_id, credits):
            result = await call()
    except BaseException:
        await asyncio.to_thread(release_direct_text_generation, generation_id)
        raise
    ok = result.get("ok", result.get("success")) if isinstance(result, dict) else bool(result)
    if not ok:
        await asyncio.to_thread(release_direct_text_generation, generation_id)
        return result
    charged_credits = credits
    if usage_credits is not None:
        charged_credits = settled_helper_credits(credits, usage_credits(result), label)
    billing = await asyncio.to_thread(
        charge_generation_balance, telegram_id, generation_id,
        result if isinstance(result, dict) else {},
        {"mode": "helper", "model": model or label, "provider": provider,
         "price_snapshot": {"final_credits": charged_credits, "reserved_credits": credits}},
    )
    if not billing.get("charged") and not billing.get("already_charged"):
        await asyncio.to_thread(release_direct_text_generation, generation_id)
        raise SecurityError("billing_failed", 503)
    if isinstance(result, dict):
        result.setdefault("cost_credits", charged_credits)
    return result


# Provider-backed helpers with no SYLVEX tariff. Each stays blocked until it
# has a price and is routed through run_billed_helper(); removing an entry
# without that wiring still fails closed at the dispatcher guard.
UNPRICED_HELPERS = frozenset({
    "home_idea_realtime",        # OpenAI Realtime voice session
    "transcribe",                # dictation (OpenAI/Gemini STT)
    "voice_clone",               # ElevenLabs instant voice clone
    "voice_avatar_generation",   # automatic voice avatar images
})


def unpriced_helper_response(operation: str) -> JSONResponse:
    """Provider-backed helper with no SYLVEX tariff: blocked, never free."""
    print("UNPRICED_HELPER_BLOCKED:", {"operation": operation})
    return JSONResponse(
        {"ok": False, "error": "pricing_not_configured", "message": "Функция временно недоступна."},
        status_code=402,
    )


# Provider list prices, USD per 1M tokens (input, output). Credits follow
# the SYLVEX rule: ceil(provider_cost_usd * 1.5 * 100) - see sylvex_credits().
# grok_3 / qwen_* were estimated from each provider's published tier when
# they were first priced; verify against xAI / DashScope before relying on them.
TEXT_TOKEN_USD_PER_MILLION = {
    "byteplus_seed_2_lite": ("0.25", "2.00"), "gpt-6-astra": ("10.00", "50.00"), "gpt-6.1-sol": ("2.00", "10.00"),
    "gpt-5.6": ("4.00", "20.00"), "gpt-5.5": ("5.00", "30.00"),
    "gpt-5": ("1.25", "10.00"), "gpt-5-mini": ("0.25", "2.00"), "gpt-4.1": ("2.00", "8.00"),
    "gpt-4.1-mini": ("0.40", "1.60"), "gpt-4o": ("2.50", "10.00"), "gpt-4o-mini": ("0.15", "0.60"),
    "gemini_3_1_pro": ("2.00", "12.00"), "gemini_3_1_flash": ("0.75", "3.75"),
    "gemini_2_5_pro": ("1.25", "10.00"), "gemini_2_5_flash": ("0.30", "2.50"),
    "grok_4_1": ("2.00", "6.00"), "grok_4_fast": ("1.25", "2.50"),
    "grok_3": ("1.25", "2.50"), "qwen_plus": ("0.40", "1.20"), "qwen_turbo": ("0.05", "0.20"), "qwen_max": ("2.00", "6.00"),
}
TEXT_LONG_CONTEXT_RATES = {
    "byteplus_seed_2_lite": (128_000, "0.50", "4.00"),
    "gemini_3_1_pro": (200_000, "4.00", "18.00"),
    "gemini_2_5_pro": (200_000, "2.50", "15.00"),
    "grok_4_1": (200_000, "4.00", "12.00"),
    "grok_4_fast": (200_000, "2.50", "5.00"),
    "grok_3": (200_000, "2.50", "5.00"),
    "qwen_plus": (256_000, "1.20", "3.60"),
}
TEXT_CACHED_INPUT_FACTOR = {
    "gpt-6-astra": Decimal("0.10"), "gpt-6.1-sol": Decimal("0.05"),
    "byteplus_seed_2_lite": Decimal("0.20"),
    "gemini_3_1_pro": Decimal("0.25"), "gemini_3_1_flash": Decimal("0.25"),
    "gemini_2_5_pro": Decimal("0.25"), "gemini_2_5_flash": Decimal("0.25"),
    "qwen_plus": Decimal("0.20"), "qwen_turbo": Decimal("0.20"), "qwen_max": Decimal("0.20"),
}
# Upper bound used only for reservations: an input image on the OpenAI/Gemini
# vision paths costs fewer tokens than this at the sizes SYLVEX sends.
HELPER_IMAGE_TOKEN_BOUND = 1600


def text_token_rates(model: str, input_tokens: int = 0) -> Optional[tuple]:
    raw = str(model or "").strip()
    for candidate in dict.fromkeys([raw, normalize_text_model(raw) if raw else raw, raw.replace("-", "_").replace(".", "_")]):
        rates = TEXT_TOKEN_USD_PER_MILLION.get(candidate)
        if rates:
            long_tier = TEXT_LONG_CONTEXT_RATES.get(candidate)
            if long_tier and int(input_tokens or 0) > int(long_tier[0]):
                return Decimal(long_tier[1]), Decimal(long_tier[2])
            return tuple(Decimal(value) for value in rates)
    return None


def text_tokens_credits(model: str, input_tokens: int, output_tokens: int, cached_input_tokens: int = 0) -> int:
    """SYLVEX credits for a token count of `model`; 0 = no rate (fail closed)."""
    rates = text_token_rates(model, input_tokens)
    if not rates:
        return 0
    total_input = max(0, int(input_tokens or 0))
    cached = min(total_input, max(0, int(cached_input_tokens or 0)))
    uncached = total_input - cached
    cached_factor = TEXT_CACHED_INPUT_FACTOR.get(normalize_text_model(model), Decimal("0.10"))
    cost = (
        Decimal(uncached) * rates[0]
        + Decimal(cached) * rates[0] * cached_factor
        + Decimal(max(0, int(output_tokens or 0))) * rates[1]
    ) / Decimal(1_000_000)
    return sylvex_credits(cost)


def helper_text_reservation(model: str, input_text: str, max_output_tokens: int, image_count: int = 0) -> int:
    """Upper bound for one capped helper LLM call: every input UTF-8 byte
    counted as a token (a byte-level tokenizer never emits more tokens than
    bytes), each image at HELPER_IMAGE_TOKEN_BOUND, and the full output cap
    that is sent to the provider. The charge settles on actual usage."""
    input_tokens = len(str(input_text or "").encode("utf-8")) + max(0, int(image_count or 0)) * HELPER_IMAGE_TOKEN_BOUND
    return text_tokens_credits(model, input_tokens, int(max_output_tokens or 0))


def text_usage_tokens(metadata) -> Optional[tuple]:
    """(input_tokens, output_tokens) reported by the provider, reasoning and
    thinking tokens included in output; None when the response had none."""
    if not isinstance(metadata, dict):
        return None
    usage = metadata.get("usage")
    if isinstance(usage, dict):
        if "input_tokens" in usage or "output_tokens" in usage:
            return int(usage.get("input_tokens") or 0), int(usage.get("output_tokens") or 0)
        if "prompt_tokens" in usage or "completion_tokens" in usage:
            return int(usage.get("prompt_tokens") or 0), int(usage.get("completion_tokens") or 0)
    gemini = metadata.get("usageMetadata")
    if isinstance(gemini, dict):
        return (
            int(gemini.get("promptTokenCount") or 0) + int(gemini.get("toolUsePromptTokenCount") or 0),
            int(gemini.get("candidatesTokenCount") or 0) + int(gemini.get("thoughtsTokenCount") or 0),
        )
    return None


def text_usage_details(metadata) -> Optional[dict]:
    """Normalize usage details used by audited text settlement.

    xAI's exact cost is authoritative and already includes caching, context
    tiers, service tier and tool calls (1 USD = 10^10 ticks).
    """
    tokens = text_usage_tokens(metadata)
    if tokens is None:
        return None
    usage = metadata.get("usage") if isinstance(metadata, dict) else {}
    cached = 0
    exact_cost_usd = None
    if isinstance(usage, dict):
        details = usage.get("input_tokens_details") or usage.get("prompt_tokens_details") or {}
        if isinstance(details, dict):
            cached = int(details.get("cached_tokens") or details.get("cache_read_tokens") or 0)
        cached = max(cached, int(usage.get("cache_read_input_tokens") or 0))
        if usage.get("cost_in_usd_ticks") is not None:
            exact_cost_usd = Decimal(str(usage.get("cost_in_usd_ticks") or 0)) / Decimal("10000000000")
    gemini = metadata.get("usageMetadata") if isinstance(metadata, dict) else {}
    if isinstance(gemini, dict):
        cached = max(cached, int(gemini.get("cachedContentTokenCount") or 0))
    return {
        "input_tokens": int(tokens[0]),
        "output_tokens": int(tokens[1]),
        "cached_input_tokens": cached,
        "exact_cost_usd": exact_cost_usd,
    }


# A one-minute production plan normally fits well below this cap. The Grid
# director uses OpenAI Background mode below, so long reasoning is polled by
# response id instead of holding one provider socket open until completion.
GRID_PLAN_MAX_OUTPUT_TOKENS = max(4096, min(24000, int(os.getenv("GRID_PLAN_MAX_OUTPUT_TOKENS") or 12000)))
GRID_PLAN_FALLBACK_MAX_OUTPUT_TOKENS = max(2048, min(GRID_PLAN_MAX_OUTPUT_TOKENS, int(os.getenv("GRID_PLAN_FALLBACK_MAX_OUTPUT_TOKENS") or 6000)))
GRID_PLANNER_CREATE_TIMEOUT_SECONDS = max(10, min(45, int(os.getenv("GRID_PLANNER_CREATE_TIMEOUT_SECONDS") or 20)))
# Background responses are already detached from the provider connection, so
# the Grid request must wait for a terminal provider status rather than impose
# the old 150s/90s per-model cut-offs. Keep one deliberately generous safety
# limit for both attempts. The new variable also prevents stale Railway values
# for the two retired per-model settings from reintroducing early cancellation.
GRID_PLANNER_POLL_SAFETY_LIMIT_SECONDS = max(
    300, min(600, int(os.getenv("GRID_PLANNER_POLL_SAFETY_LIMIT_SECONDS") or 600))
)
_grid_planner_reasoning_effort = (os.getenv("GRID_PLANNER_REASONING_EFFORT") or "medium").strip().lower()
GRID_PLANNER_REASONING_EFFORT = _grid_planner_reasoning_effort if _grid_planner_reasoning_effort in {"low", "medium", "high"} else "medium"
_grid_planner_model = (os.getenv("GRID_PLANNER_MODEL") or "gpt-6-astra").strip()
GRID_PLANNER_MODEL = _grid_planner_model if _grid_planner_model in TEXT_TOKEN_USD_PER_MILLION else "gpt-6-astra"
_grid_planner_fallback_model = (os.getenv("GRID_PLANNER_FALLBACK_MODEL") or "gpt-6.1-sol").strip()
GRID_PLANNER_FALLBACK_MODEL = _grid_planner_fallback_model if _grid_planner_fallback_model in TEXT_TOKEN_USD_PER_MILLION else "gpt-6.1-sol"
HOME_IDEA_MAX_OUTPUT_TOKENS = 4000
ASSISTANT_MAX_OUTPUT_TOKENS = 8000
OBJECT_VISION_MAX_OUTPUT_TOKENS = 4000


def text_generation_price_input(payload: dict) -> tuple:
    """(input_text, image_count) of what text_generation() sends for this
    payload - system prompt, history, prompt and attachment text - so a
    capped helper reservation covers the whole request."""
    opts = payload.get("text_options") or {}
    tool = str(opts.get("tool") or "text").strip().lower()
    parts = [text_system_prompt(tool, str(opts.get("style") or "neutral").strip().lower(), str(opts.get("format") or "markdown").strip().lower(), normalize_text_model(payload.get("model") or "gpt-5.5"))]
    if sylvex_text_policy(opts):
        parts.append(sylvex_text_policy(opts))
    for item in (payload.get("history") or [])[-10:]:
        if isinstance(item, dict) and item.get("content"):
            parts.append(str(item.get("content")))
    parts.append(f"Mode: {payload.get('mode') or 'text'}\nTool: {tool}\nPrompt: {payload.get('prompt') or ''}")
    attachment = payload.get("attachment") or {}
    images = 0
    if isinstance(attachment, dict) and attachment:
        mime = str(attachment.get("mime") or attachment.get("content_type") or "").lower()
        parts.append(f"Attachment: {attachment.get('name')} ({mime})")
        if mime.startswith("image/"):
            images = 1
        else:
            parts.append(text_attachment_plain_text(attachment))
    return "\n".join(parts), images


# Main Text product (/generate): every request is sent with an output cap, so
# the reservation below is a true upper bound; the charge then settles on the
# provider-reported usage and the difference is returned to the user.
TEXT_MIN_OUTPUT_TOKENS = 256
TEXT_MAX_OUTPUT_TOKENS = max(TEXT_MIN_OUTPUT_TOKENS, int(os.getenv("TEXT_MAX_OUTPUT_TOKENS") or 8000))
# A user-attached image is sent at its uploaded size. Upper bound per image
# across the vision paths: OpenAI patch models cap at 1536 patches x 2.46,
# tile models at 85 + 170 x 8 tiles; Gemini/Grok stay below this.
TEXT_IMAGE_TOKEN_BOUND = 4000
# text_attachment_plain_text() returns at most 60000 characters; at up to 4
# UTF-8 bytes each this bounds a document whose text was not measured.
TEXT_DOCUMENT_BYTE_BOUND = 60000 * 4
# Server-side measurement of the attached document (set by /generate only).
TEXT_ATTACHMENT_BYTES_KEY = "_sylvex_attachment_text_bytes"


def text_output_cap(payload: dict) -> int:
    """Output tokens the provider may return for one Text request: the
    client's max_output_tokens clamped to [TEXT_MIN, TEXT_MAX], or TEXT_MAX."""
    opts = payload.get("text_options") if isinstance(payload.get("text_options"), dict) else {}
    try:
        requested = int(opts.get("max_output_tokens") or 0)
    except (TypeError, ValueError):
        requested = 0
    if requested <= 0:
        return TEXT_MAX_OUTPUT_TOKENS
    return max(TEXT_MIN_OUTPUT_TOKENS, min(TEXT_MAX_OUTPUT_TOKENS, requested))


def text_media_attachment(payload: dict) -> bool:
    """Audio/video attachment, or a tool that only works on one. The Text
    product has no tariff for transcription or audio/video input tokens, so
    these requests are refused before any provider is contacted."""
    attachment = payload.get("attachment") if isinstance(payload.get("attachment"), dict) else {}
    mime = str(attachment.get("mime") or attachment.get("content_type") or "").lower()
    opts = payload.get("text_options") if isinstance(payload.get("text_options"), dict) else {}
    tool = str(opts.get("tool") or "").strip().lower()
    return mime.startswith(("audio/", "video/")) or tool in {"audio_to_text", "video_to_text", "video_prompt"}


def text_generation_reservation(payload: dict) -> tuple:
    """(credits, input_token_bound, output_token_cap) for one main Text
    request. Input is bounded by UTF-8 bytes (a byte-level tokenizer never
    emits more tokens than bytes) of the system prompt, last 10 history
    items, prompt and attachment label; an image adds TEXT_IMAGE_TOKEN_BOUND;
    a document adds its measured text bytes when /generate measured it, else
    TEXT_DOCUMENT_BYTE_BOUND. Output is the cap sent to the provider."""
    model = normalize_text_model(payload.get("model") or "gpt-5.5")
    opts = payload.get("text_options") if isinstance(payload.get("text_options"), dict) else {}
    tool = str(opts.get("tool") or "text").strip().lower()
    parts = [text_system_prompt(tool, str(opts.get("style") or "neutral").strip().lower(), str(opts.get("format") or "markdown").strip().lower(), normalize_text_model(payload.get("model") or "gpt-5.5"))]
    if sylvex_text_policy(opts):
        parts.append(sylvex_text_policy(opts))
    for item in (payload.get("history") or [])[-10:]:
        if isinstance(item, dict) and item.get("content"):
            parts.append(str(item.get("content")))
    parts.append(f"Mode: {payload.get('mode') or 'text'}\nTool: {tool}\nPrompt: {payload.get('prompt') or ''}")
    attachment = payload.get("attachment") if isinstance(payload.get("attachment"), dict) else {}
    if attachment:
        parts.append(f"Attached document text:\n\nAttachment: {attachment.get('name')} ({attachment.get('mime')}) {attachment.get('content_type')}")
    input_tokens = len("\n\n".join(parts).encode("utf-8"))
    if attachment:
        mime = str(attachment.get("mime") or attachment.get("content_type") or "").lower()
        measured = payload.get(TEXT_ATTACHMENT_BYTES_KEY)
        if mime.startswith("image/"):
            input_tokens += TEXT_IMAGE_TOKEN_BOUND
        elif isinstance(measured, int) and not isinstance(measured, bool) and measured >= 0:
            input_tokens += measured
        else:
            input_tokens += TEXT_DOCUMENT_BYTE_BOUND
    output_cap = text_output_cap(payload)
    return text_tokens_credits(model, input_tokens, output_cap), input_tokens, output_cap


def text_generation_usage_credits(model: str):
    """usage_credits callback for run_billed_helper around text_generation()."""
    def _credits(result):
        if not isinstance(result, dict):
            return None
        if result.get("provider") == "sylvex-fast":
            return 0  # answered locally, no provider call
        return text_usage_credits(model, result.get("metadata"))
    return _credits


def text_usage_credits(model: str, metadata) -> Optional[int]:
    details = text_usage_details(metadata)
    if details is None:
        return None
    if details["exact_cost_usd"] is not None:
        return sylvex_credits(details["exact_cost_usd"])
    return text_tokens_credits(
        model,
        details["input_tokens"],
        details["output_tokens"],
        details["cached_input_tokens"],
    )


def release_direct_text_generation(generation_id: str) -> None:
    if not DATABASE_URL or not generation_id:
        return
    conn = db_connect(DATABASE_URL)
    cursor = conn.cursor()
    try:
        release_generation(cursor, generation_id)
        conn.commit()
    except Exception:
        conn.rollback()
    finally:
        cursor.close()
        conn.close()

# =====================================================
# ЭТАПЫ ГЕНЕРАЦИИ: record_prostudio_job_stage / prostudio_job_progress
# Подтверждённые этапы job для ThoughtLine: время отправки провайдеру,
# принятия задачи и начала обработки (services/generation_stages.py).
# Записывается один раз и только пока job активен; на статус, биллинг и
# результат не влияет.
# =====================================================
def record_prostudio_job_stage(job_id: str, stage: str) -> None:
    if not DATABASE_URL or not job_id or stage not in generation_stages.STAGES:
        return
    try:
        with db_connection(DATABASE_URL) as conn:
            cursor = conn.cursor()
            cursor.execute("""
                UPDATE prostudio_generation_jobs
                SET stage_json = COALESCE(stage_json, '{}'::jsonb) || jsonb_build_object(%s::text, EXTRACT(EPOCH FROM NOW()))
                WHERE id = %s
                  AND status IN ('queued', 'processing', 'provider_processing')
                  AND NOT (COALESCE(stage_json, '{}'::jsonb) ? %s)
            """, (stage, job_id, stage))
            conn.commit()
            cursor.close()
    except Exception as exc:
        prostudio_error("JOB_STAGE_RECORD_FAILED", exc, job_id=job_id, stage=stage)


def prostudio_job_progress(status: str, stage_json, created_at, completed_at, server_time) -> dict:
    """Confirmed stages as epoch seconds, in order, for the job endpoint."""
    recorded = stage_json if isinstance(stage_json, dict) else {}
    stages = {}
    if created_at is not None:
        stages["received"] = created_at
    for stage in generation_stages.STAGES:
        value = recorded.get(stage)
        if isinstance(value, (int, float)):
            stages[stage] = float(value)
    if status == "completed" and completed_at is not None:
        stages["ready"] = completed_at
    elif status in {"failed", "cancelled", "canceled"} and completed_at is not None:
        stages["failed"] = completed_at
    return {"stages": stages, "server_time": server_time}


# =====================================================
# СОХРАНЕНИЕ В БАЗУ ДАННЫХ: update_prostudio_generation_job
# Записывает состояние пользователя, job, metadata или результат генерации в общую базу Mini App и Telegram Bot.
# =====================================================
def update_prostudio_generation_job(job_id: str, status: str, result: Optional[dict] = None, error: Optional[dict] = None, conversation_id: str = ""):
    prostudio_debug(
        "JOB_UPDATE_START",
        job_id=job_id,
        status=status,
        result_keys=sorted((result or {}).keys()) if isinstance(result, dict) else [],
        error_keys=sorted((error or {}).keys()) if isinstance(error, dict) else [],
        conversation_id=conversation_id or "",
    )
    if not DATABASE_URL or not job_id:
        prostudio_debug("JOB_UPDATE_SKIPPED_DB", job_id=job_id, status=status, has_database=bool(DATABASE_URL))
        return False
    conn = cursor = None
    try:
        ensure_prostudio_table()
        ensure_reservations(lambda: db_connect(DATABASE_URL))
        conn = db_connect(DATABASE_URL)
        cursor = conn.cursor()
        cursor.execute("SELECT status, result_json FROM prostudio_generation_jobs WHERE id=%s FOR UPDATE", (job_id,))
        current = cursor.fetchone()
        if not current:
            conn.rollback()
            return False
        # A terminal job (completed or failed) must never be overwritten by a
        # late/duplicate callback - e.g. a straggling poll response arriving
        # after stale-job recovery already marked the job failed and
        # refunded its reservation, or a retried provider call resolving
        # after the first attempt's response already settled the job.
        # Re-affirming the same terminal status is harmless and allowed.
        if current[0] in {"completed", "failed"} and status != current[0]:
            conn.rollback()
            return False
        if current[0] == "completed" and status == "completed":
            # History finishes independently of R2/thumbnail tasks. Its stale
            # provider URLs must never replace media those tasks committed.
            previous_result = _json_obj(current[1]) if len(current) > 1 else {}
            result = merge_generation_result_fields(previous_result, result or {}, preserve_existing_media=True)
        if status in {"failed", "cancelled", "canceled"}:
            release_generation(cursor, job_id)
        cursor.execute("""
            UPDATE prostudio_generation_jobs
            SET status = %s,
                conversation_id = COALESCE(NULLIF(%s, ''), conversation_id),
                response_json = COALESCE(%s::jsonb, response_json),
                result_json = COALESCE(%s::jsonb, result_json),
                error_json = COALESCE(%s::jsonb, error_json),
                cost = CASE WHEN %s IN ('completed', 'provider_processing') THEN COALESCE(%s, cost) ELSE cost END,
                updated_at = NOW(),
                completed_at = CASE WHEN %s IN ('completed', 'failed') THEN NOW() ELSE completed_at END
            WHERE id = %s
        """, (
            status,
            conversation_id or "",
            _safe_json_dumps(result or {}),
            _safe_json_dumps(result or {}),
            _safe_json_dumps(_sanitize_event_payload(error or {}, max_text=1200, max_items=50, depth=5)),
            status,
            int((result or {}).get("cost_credits") or (result or {}).get("cost") or (result or {}).get("price") or 0),
            status,
            job_id,
        ))
        rowcount = cursor.rowcount
        if (current[0] != "completed" and status == "completed" and isinstance(result, dict)
                and result.get("storage_status") == "pending"):
            generation_storage.enqueue(cursor, job_id, str(result.get("type") or ""), result)
        conn.commit()
        prostudio_debug("JOB_UPDATE_DONE", job_id=job_id, status=status, rowcount=rowcount)
        return rowcount > 0
    except Exception as exc:
        if conn is not None:
            conn.rollback()
        prostudio_error("JOB_UPDATE_FAILED", exc, job_id=job_id, status=status)
        return False

    finally:
        if cursor is not None:
            cursor.close()
        if conn is not None:
            conn.close()

# =====================================================
# СОХРАНЕНИЕ В БАЗУ ДАННЫХ: claim_next_prostudio_generation_job
# Записывает состояние пользователя, job, metadata или результат генерации в общую базу Mini App и Telegram Bot.
# =====================================================
def claim_next_prostudio_generation_job() -> Optional[dict]:
    if not DATABASE_URL:
        prostudio_debug("WORKER_CLAIM_SKIPPED_DB")
        return None
    try:
        ensure_prostudio_table()
        conn = db_connect(DATABASE_URL)
        cursor = conn.cursor()
        try:
            cursor.execute("""
                UPDATE prostudio_generation_jobs
                SET status = 'processing',
                    attempts = COALESCE(attempts, 0) + 1,
                    locked_at = NOW(),
                    heartbeat_at = NOW(),
                    provider_wait_until = NULL,
                    updated_at = NOW()
                WHERE id = (
                    SELECT id
                    FROM prostudio_generation_jobs
                    WHERE status = 'queued'
                      AND COALESCE(attempts, 0) < %s
                      AND (provider_wait_until IS NULL OR provider_wait_until <= NOW())
                    ORDER BY created_at ASC
                    LIMIT 1
                    FOR UPDATE SKIP LOCKED
                )
                RETURNING id, request_json, attempts, EXTRACT(EPOCH FROM (NOW() - created_at))
            """, (PROSTUDIO_MAX_JOB_ATTEMPTS,))
            row = cursor.fetchone()
            conn.commit()
        finally:
            cursor.close()
            conn.close()
        if not row:
            # An empty queue is the normal worker state. Logging it on every
            # poll (every two seconds by default) floods Railway logs and can
            # hide actionable errors without adding diagnostic value.
            return None
        payload = _json_obj(row[1])
        # Time between the client's submit (job row created) and a worker
        # actually picking it up - the first place SYLVEX-side queueing
        # latency (as opposed to provider latency) would show up.
        queue_wait_ms = round(float(row[3] or 0) * 1000)
        claimed = {"id": row[0], "payload": payload, "attempts": row[2] or 1, "queue_wait_ms": queue_wait_ms}
        prostudio_debug(
            "WORKER_CLAIM_DONE",
            job_id=row[0],
            attempts=row[2] or 1,
            mode=payload.get("mode") or payload.get("category") or "",
            model=payload.get("model") or "",
            provider=payload.get("provider") or "",
            queue_wait_ms=queue_wait_ms,
        )
        return claimed
    except Exception as exc:
        prostudio_error("WORKER_CLAIM_FAILED", exc)
        return None

def requeue_stale_prostudio_jobs():
    """Compatibility entry point: terminally recover abandoned active jobs."""
    if not DATABASE_URL:
        return
    try:
        ensure_prostudio_table()
        conn = db_connect(DATABASE_URL)
        cursor = conn.cursor()
        try:
            cursor.execute("""
                SELECT id
                FROM prostudio_generation_jobs
                WHERE status IN ('queued', 'processing', 'provider_processing')
                  AND COALESCE(heartbeat_at, updated_at, created_at) < NOW() - (%s || ' minutes')::interval
                ORDER BY created_at ASC
                LIMIT 200
            """, (PROSTUDIO_STALE_PROCESSING_MINUTES,))
            job_ids = [str(row[0]) for row in cursor.fetchall()]
        finally:
            cursor.close()
            conn.close()
        for job_id in job_ids:
            recover_stale_prostudio_job(job_id)
    except Exception as exc:
        prostudio_error("STALE_JOB_RECOVERY_FAILED", exc)


def _recover_stale_prostudio_job_once(job_id: str, force: bool = False) -> dict:
    """Atomically fail an abandoned job only when no live provider lease exists."""
    if not DATABASE_URL or not job_id:
        return {"recovered": False, "reason": "database_or_job_missing"}
    ensure_prostudio_table()
    ensure_reservations(lambda: db_connect(DATABASE_URL))
    ensure_provider_slot_table(DATABASE_URL)
    threshold_seconds = max(60, int(PROSTUDIO_STALE_PROCESSING_MINUTES) * 60)
    conn = db_connect(DATABASE_URL)
    cursor = conn.cursor()
    detected = None
    released_slots = []
    try:
        cursor.execute("SELECT pg_advisory_xact_lock(hashtext(%s))", (f"prostudio-stale:{job_id}",))
        cursor.execute("""
            SELECT id, status, provider, created_at, updated_at, heartbeat_at,
                   EXTRACT(EPOCH FROM (NOW() - created_at)),
                   EXTRACT(EPOCH FROM (NOW() - heartbeat_at)),
                   result_json
            FROM prostudio_generation_jobs
            WHERE id = %s
            FOR UPDATE
        """, (job_id,))
        row = cursor.fetchone()
        if not row:
            conn.rollback()
            return {"recovered": False, "reason": "job_not_found"}
        old_status = str(row[1] or "")
        if old_status not in PROSTUDIO_ACTIVE_JOB_STATUSES:
            conn.rollback()
            return {"recovered": False, "reason": "job_not_active", "status": old_status}

        cursor.execute("""
            SELECT provider, worker_id, heartbeat_at, lease_until,
                   (lease_until > NOW()) AS is_live
            FROM prostudio_provider_slots
            WHERE job_id = %s
            ORDER BY lease_until DESC
        """, (job_id,))
        slot_rows = cursor.fetchall()
        live_slot = next((slot for slot in slot_rows if bool(slot[4])), None)
        heartbeat_age = float(row[7]) if row[7] is not None else None
        reference_time = row[5] or row[4] or row[3]
        cursor.execute("SELECT EXTRACT(EPOCH FROM (NOW() - %s::timestamp))", (reference_time,))
        stale_age = float(cursor.fetchone()[0] or 0)
        if stale_age <= threshold_seconds and not force:
            conn.rollback()
            return {"recovered": False, "reason": "heartbeat_fresh", "status": old_status}
        if live_slot:
            conn.rollback()
            return {
                "recovered": False, "reason": "live_provider_slot", "status": old_status,
                "worker_id": str(live_slot[1] or ""),
            }

        worker_id = str(slot_rows[0][1] or "") if slot_rows else ""
        provider = str(row[2] or (slot_rows[0][0] if slot_rows else "") or "")
        age_seconds = float(row[6] or 0)
        saved_result = _json_obj(row[8])
        cursor.execute(
            "SELECT EXISTS(SELECT 1 FROM generation_charges WHERE generation_id = %s)",
            (job_id,),
        )
        has_charge = bool(cursor.fetchone()[0])
        has_final_result = generation_has_completed_result(saved_result, "")
        reason = "stale_worker_recovered"
        detected = {
            "job_id": job_id, "old_status": old_status,
            "age_seconds": round(age_seconds, 3),
            "heartbeat_age_seconds": round(heartbeat_age, 3) if heartbeat_age is not None else None,
            "worker_id": worker_id, "provider": provider, "reason": reason,
            "has_final_result": has_final_result, "has_charge": has_charge,
        }
        prostudio_debug("PROSTUDIO_STALE_JOB_DETECTED", **detected)
        cursor.execute("""
            DELETE FROM prostudio_provider_slots
            WHERE job_id = %s AND lease_until <= NOW()
            RETURNING provider, worker_id
        """, (job_id,))
        released_slots = cursor.fetchall()
        error_payload = {
            "ok": False,
            "error_code": "generation_timeout",
            "error": reason,
            "message": "Предыдущая генерация была остановлена после перезапуска worker.",
        }
        cursor.execute("""
            UPDATE prostudio_generation_jobs
            SET status = 'failed', error_json = %s::jsonb,
                locked_at = NULL, heartbeat_at = NULL, provider_wait_until = NULL,
                updated_at = NOW(), completed_at = NOW()
            WHERE id = %s AND status = %s
        """, (_safe_json_dumps(error_payload), job_id, old_status))
        if cursor.rowcount != 1:
            conn.rollback()
            return {"recovered": False, "reason": "job_changed_concurrently"}
        release_generation(cursor, job_id)
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    finally:
        cursor.close()
        conn.close()

    for slot_provider, slot_worker in released_slots:
        slot_log = dict(detected)
        slot_log["provider"] = str(slot_provider or detected["provider"])
        slot_log["worker_id"] = str(slot_worker or detected["worker_id"])
        prostudio_debug("PROSTUDIO_STALE_SLOT_RELEASED", **slot_log)
    prostudio_debug("PROSTUDIO_STALE_JOB_RECOVERED", **detected)
    return {"recovered": True, "status": "failed", **detected}


def recover_stale_prostudio_job(job_id: str, force: bool = False) -> dict:
    """Retry the atomic recovery when concurrent runtime DDL causes a deadlock."""
    for attempt in range(1, 5):
        try:
            return _recover_stale_prostudio_job_once(job_id, force=force)
        except (psycopg2.errors.DeadlockDetected, psycopg2.errors.LockNotAvailable) as exc:
            prostudio_debug(
                "PROSTUDIO_STALE_RECOVERY_RETRY",
                job_id=job_id,
                attempt=attempt,
                worker_id=WORKER_ID,
                reason=type(exc).__name__,
            )
            if attempt >= 4:
                raise
            time.sleep(min(2.0, 0.25 * (2 ** (attempt - 1))) + random.uniform(0.0, 0.2))

