@app.post("/api/public/prostudio/grid/montage")
async def public_grid_montage(request: Request):
    """Start an idempotent, recoverable Final Montage without another AI charge."""
    owner = _grid_projects_owner(request)
    data = await request.json()
    try:
        clean = grid_montage_service.validate_request(data if isinstance(data, dict) else {})
    except ValueError as exc:
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=422)
    client_request_id = str((data or {}).get("client_request_id") or "").strip()[:240]
    project_id = str((data or {}).get("grid_project_id") or "")[:160]
    node_id = str((data or {}).get("grid_node_id") or "")[:180]
    await asyncio.to_thread(ensure_prostudio_table)

    def create_job():
        job_id = str(uuid.uuid4())
        with db_connection(DATABASE_URL) as conn:
            with conn.cursor() as cur:
                cur.execute("SELECT pg_advisory_xact_lock(%s)", (owner,))
                if client_request_id:
                    cur.execute("""SELECT id,status FROM prostudio_generation_jobs
                        WHERE telegram_id=%s AND request_json->>'client_request_id'=%s
                        ORDER BY created_at DESC LIMIT 1""", (owner, client_request_id))
                    existing = cur.fetchone()
                    if existing:
                        return existing[0], existing[1], False
                stored = {**clean, "client_request_id": client_request_id,
                          "grid_project_id": project_id, "grid_node_id": node_id}
                cur.execute("""INSERT INTO prostudio_generation_jobs
                    (id,telegram_id,mode,model,provider,prompt,status,cost,request_json)
                    VALUES (%s,%s,'video','final_montage','local-ffmpeg','Final Montage','processing',0,%s::jsonb)""",
                    (job_id, owner, _safe_json_dumps(stored)))
                return job_id, "processing", True

    try:
        job_id, status, created = await asyncio.to_thread(create_job)
    except Exception as exc:
        prostudio_error("GRID_FINAL_MONTAGE_JOB_CREATE_FAILED", exc, telegram_id=owner)
        return JSONResponse({"ok": False, "error": "grid_montage_job_create_failed"}, status_code=503)

    if created:
        def render_job():
            stopped = threading.Event()
            def heartbeat():
                while not stopped.wait(30):
                    try:
                        with db_connection(DATABASE_URL) as conn:
                            with conn.cursor() as cur:
                                cur.execute("""UPDATE prostudio_generation_jobs
                                    SET heartbeat_at=NOW(),updated_at=NOW()
                                    WHERE id=%s AND status='processing'""", (job_id,))
                    except Exception as exc:
                        prostudio_error("GRID_FINAL_MONTAGE_HEARTBEAT_FAILED", exc, job_id=job_id)
            threading.Thread(target=heartbeat, name=f"grid-montage-heartbeat-{job_id[:8]}", daemon=True).start()
            try:
                result = grid_montage_service.render(clean)
                result.update({"generation_id": job_id, "job_id": job_id})
                update_prostudio_generation_job(job_id, "completed", result=result)
            except Exception as exc:
                prostudio_error("GRID_FINAL_MONTAGE_FAILED", exc, job_id=job_id, telegram_id=owner)
                update_prostudio_generation_job(job_id, "failed", error={"error": "grid_montage_failed", "message": "Final montage could not be rendered."})
            finally:
                stopped.set()
        threading.Thread(target=render_job, name=f"grid-montage-{job_id[:8]}", daemon=True).start()
    return {"ok": True, "job_id": job_id, "generation_id": job_id, "status": status}


def _load_history_stored_media(telegram_id: int, rows: list, metadata_index: int, response_index: int) -> dict:
    """One owner-scoped batch lookup; history rows and financial fields stay untouched."""
    job_ids = list(dict.fromkeys(
        job_id for row in rows
        if (job_id := history_generation_id(_json_obj(row[metadata_index]), _json_obj(row[response_index])))
    ))
    if not DATABASE_URL or not telegram_id or not job_ids:
        return {}
    try:
        with db_connection(DATABASE_URL) as conn:
            with conn.cursor() as cursor:
                cursor.execute("""SELECT id, result_json FROM prostudio_generation_jobs
                    WHERE telegram_id=%s AND id=ANY(%s) AND status='completed'
                      AND (result_json->>'storage_status'='completed'
                           OR result_json->>'storage_recovery_version'='1')""", (telegram_id, job_ids))
                return {str(row[0]): _json_obj(row[1]) for row in cursor.fetchall()}
    except Exception as exc:
        prostudio_error("HISTORY_STORED_MEDIA_LOOKUP_FAILED", exc)
        return {}


@app.get("/api/public/prostudio/conversations")
async def public_prostudio_conversations(
    telegram_id: int = 0,
    conversation_id: str = "",
    mode: str = "",
    limit: int = 30,
    offset: int = 0,
):
    if not DATABASE_URL or not telegram_id:
        return {"ok": True, "conversations": [], "messages": []}

    try:
        await asyncio.to_thread(ensure_prostudio_table)

        limit = max(1, min(int(limit or 30), 100))
        offset = max(0, int(offset or 0))

        if conversation_id:
            def _fetch_conversation_messages():
                with db_connection(DATABASE_URL) as conn:
                    cursor = conn.cursor()
                    cursor.execute("""
                        SELECT
                            prompt, response_text, image_url, images_json, thumbnails_json, thumb_url,
                            video_url, videos_json, audio_url, audios_json, metadata_json, created_at,
                            status, model, provider, cost, response_json, id
                        FROM prostudio_messages
                        WHERE telegram_id = %s
                          AND conversation_id = %s
                        ORDER BY created_at ASC, id ASC
                        LIMIT %s OFFSET %s
                    """, (telegram_id, conversation_id, limit, offset))
                    rows = cursor.fetchall()
                    cursor.close()
                return rows
            rows = await asyncio.to_thread(_fetch_conversation_messages)
            stored_media = await asyncio.to_thread(_load_history_stored_media, telegram_id, rows, 10, 16)
            messages = []
            for (
                prompt, response_text, image_url, images_json, thumbnails_json, thumb_url,
                video_url, videos_json, audio_url, audios_json, metadata_json, created_at,
                status, model, provider, cost, response_json, message_id,
            ) in rows:
                images = _json_list(images_json) or ([image_url] if image_url else [])
                thumbs = _json_list(thumbnails_json) or ([thumb_url] if thumb_url else [])
                videos = _json_list(videos_json) or ([video_url] if video_url else [])
                audios = _json_list(audios_json) or ([audio_url] if audio_url else [])
                created_value = created_at.isoformat() if hasattr(created_at, "isoformat") else created_at
                metadata = _json_obj(metadata_json)
                response_data = _json_obj(response_json)
                if images:
                    if not metadata:
                        metadata = {
                            "type": "image",
                            "prompt": prompt or "",
                            "result_images": images,
                            "result_thumbnails": thumbs,
                            "image_url": images[0] if images else "",
                            "result_url": images[0] if images else "",
                            "full_url": images[0] if images else "",
                            "thumbnail_url": thumbs[0] if thumbs else "",
                            "thumb_url": thumbs[0] if thumbs else "",
                        }
                if metadata:
                    metadata["created_at"] = metadata.get("created_at") or created_value
                    metadata["status"] = metadata.get("status") or status or "completed"
                    metadata["model"] = metadata.get("model") or model or ""
                    metadata["provider"] = metadata.get("provider") or provider or ""
                    metadata["cost"] = metadata.get("cost") or cost or 0
                    response_data = _json_obj(response_json)
                    if response_data.get("job_id") and not metadata.get("job_id"):
                        metadata["job_id"] = response_data.get("job_id")
                committed = stored_media.get(history_generation_id(metadata, response_data))
                if committed:
                    media = overlay_stored_history_media({"type": mode or metadata.get("type"),
                        "images": images, "image_url": images[0] if images else "",
                        "videos": videos, "video_url": videos[0] if videos else "",
                        "audios": audios, "audio_url": audios[0] if audios else "",
                        "thumbnails": thumbs, "thumbnail_url": thumbs[0] if thumbs else "", "metadata": metadata}, committed)
                    images, videos, audios, thumbs, metadata = (
                        media.get("images") or images, media.get("videos") or videos,
                        media.get("audios") or audios, media.get("thumbnails") or thumbs, media.get("metadata") or metadata)
                input_images = [url for url in _json_list(metadata.get("input_images")) if isinstance(url, str)] if metadata else []
                if prompt or input_images:
                    user_message = {
                        "role": "user",
                        "prompt": prompt or "",
                        "created_at": created_value,
                        "message_id": message_id,
                    }
                    if input_images:
                        user_message["images"] = input_images
                    messages.append(user_message)
                messages.append({
                    "role": "assistant",
                    "message_id": message_id,
                    "response_text": response_text or "",
                    "image_url": images[0] if images else "",
                    "images": images,
                    "thumbnail_url": thumbs[0] if thumbs else "",
                    "thumb_url": thumbs[0] if thumbs else "",
                    "thumbnails": thumbs,
                    "video_url": videos[0] if videos else "",
                    "videos": videos,
                    "audio_url": audios[0] if audios else "",
                    "audios": audios,
                    "metadata": metadata,
                    "status": status or "completed",
                    "model": model or "",
                    "provider": provider or "",
                    "cost": cost or 0,
                    "created_at": created_value,
                })
            return {"ok": True, "messages": messages, "limit": limit, "offset": offset}

        mode_filter = (mode or "").strip().lower()
        mode_where = "AND mode = %s" if mode_filter in {"image", "video", "music", "voice", "text"} else ""
        params = [telegram_id]
        if mode_where:
            params.append(mode_filter)
        params.append(telegram_id)
        params.extend([min(limit, 80), offset])
        # The Text tool lists pinned conversations first (newest pin on top).
        pinned_order = "(m.pinned_at IS NULL), m.pinned_at DESC," if mode_filter == "text" else ""
        def _fetch_conversation_list():
            with db_connection(DATABASE_URL) as conn:
                cursor = conn.cursor()
                cursor.execute(f"""
                    SELECT c.conversation_id, COALESCE(NULLIF(m.title, ''), c.title) AS title,
                           c.updated_at, c.type, c.created_at, m.pinned_at
                    FROM (
                        SELECT
                            conversation_id,
                            COALESCE(NULLIF(MAX(prompt), ''), 'Chat') AS title,
                            MAX(created_at) AS updated_at,
                            COALESCE(NULLIF(MAX(mode), ''), 'image') AS type,
                            MIN(created_at) AS created_at
                        FROM prostudio_messages
                        WHERE telegram_id = %s
                          {mode_where}
                        GROUP BY conversation_id
                    ) c
                    LEFT JOIN prostudio_conversation_meta m
                      ON m.telegram_id = %s AND m.conversation_id = c.conversation_id
                    ORDER BY {pinned_order} c.updated_at DESC
                    LIMIT %s OFFSET %s
                """, tuple(params))
                rows = cursor.fetchall()
                cursor.close()
            return rows
        rows = await asyncio.to_thread(_fetch_conversation_list)
        return {
            "ok": True,
            "conversations": [
                {
                    "id": row[0],
                    "title": (row[1] or "Chat")[:64],
                    "updated_at": row[2],
                    "type": row[3] or "image",
                    "created_at": row[4],
                    "pinned": bool(row[5]),
                }
                for row in rows
            ],
        }
    except Exception as exc:
        print("PROSTUDIO CONVERSATIONS FAILED:", exc)
        return {"ok": True, "conversations": [], "messages": []}

@app.post("/api/public/prostudio/conversations/meta")
async def update_public_prostudio_conversation_meta(request: Request):
    """Rename and/or pin a conversation from the History menu. Only the
    owner's own conversations can be changed."""
    telegram_id = int(getattr(request.state, "telegram_id", 0) or 0)
    if not telegram_id:
        return JSONResponse({"ok": False, "error": "login_required"}, status_code=401)
    body = await request.json()
    conversation_id = str((body or {}).get("conversation_id") or "").strip()[:120]
    if not conversation_id or not DATABASE_URL:
        return JSONResponse({"ok": False, "error": "conversation_required"}, status_code=400)
    has_title = "title" in (body or {})
    has_pin = "pinned" in (body or {})
    if not has_title and not has_pin:
        return JSONResponse({"ok": False, "error": "nothing_to_update"}, status_code=400)
    title = re.sub(r"\s+", " ", str((body or {}).get("title") or "")).strip()[:120] if has_title else None
    pinned = bool((body or {}).get("pinned")) if has_pin else None

    def _sync():
        ensure_prostudio_table()
        with db_connection(DATABASE_URL) as conn:
            cursor = conn.cursor()
            cursor.execute("""
                SELECT 1 FROM prostudio_messages WHERE telegram_id = %s AND conversation_id = %s LIMIT 1
            """, (telegram_id, conversation_id))
            if not cursor.fetchone():
                cursor.close()
                return False
            cursor.execute("""
                INSERT INTO prostudio_conversation_meta (telegram_id, conversation_id, title, pinned_at, updated_at)
                VALUES (%s, %s, %s, CASE WHEN %s THEN NOW() ELSE NULL END, NOW())
                ON CONFLICT (telegram_id, conversation_id) DO UPDATE SET
                    title = CASE WHEN %s THEN EXCLUDED.title ELSE prostudio_conversation_meta.title END,
                    pinned_at = CASE WHEN %s THEN EXCLUDED.pinned_at ELSE prostudio_conversation_meta.pinned_at END,
                    updated_at = NOW()
            """, (telegram_id, conversation_id, title or None, bool(pinned), has_title, has_pin))
            cursor.close()
            return True

    try:
        found = await asyncio.to_thread(_sync)
    except Exception as exc:
        prostudio_error("CONVERSATION_META_FAILED", exc, telegram_id=telegram_id)
        return JSONResponse({"ok": False, "error": "update_failed"}, status_code=500)
    if not found:
        return JSONResponse({"ok": False, "error": "conversation_not_found"}, status_code=404)
    return {"ok": True}


# =====================================================
# API ENDPOINT: delete_public_prostudio_conversation
# Принимает HTTP-запрос от Mini App или Telegram Bot.
# Маршрут FastAPI: @app.delete("/api/public/prostudio/conversations")
# Проверяет входные данные, работает с базой/провайдерами и возвращает JSON-ответ фронтенду.
# =====================================================
@app.delete("/api/public/prostudio/conversations")
async def delete_public_prostudio_conversation(
    telegram_id: int = 0,
    conversation_id: str = "",
):
    if not DATABASE_URL or not telegram_id or not conversation_id:
        return {"ok": True}

    def _sync():
        ensure_prostudio_table()
        with db_connection(DATABASE_URL) as conn:
            cursor = conn.cursor()
            cursor.execute("""
                DELETE FROM prostudio_messages
                WHERE telegram_id = %s
                  AND conversation_id = %s
            """, (telegram_id, conversation_id))
            cursor.execute("""
                DELETE FROM prostudio_conversation_meta
                WHERE telegram_id = %s
                  AND conversation_id = %s
            """, (telegram_id, conversation_id))
            cursor.close()

    try:
        await asyncio.to_thread(_sync)
    except Exception as exc:
        print("PROSTUDIO CONVERSATION DELETE FAILED:", exc)

    return {"ok": True}


@app.get("/api/public/prostudio/gallery")
async def public_prostudio_gallery(telegram_id: int = 0, limit: int = 80, offset: int = 0):
    """Return completed generated content owned by one Mini App user."""
    if not DATABASE_URL or not telegram_id:
        return {"ok": True, "items": []}
    request_started = time.monotonic()
    safe_limit = max(1, min(int(limit or 80), 100))
    safe_offset = max(0, int(offset or 0))

    def _fetch_gallery_rows():
        ensure_start = time.monotonic()
        ensure_prostudio_table()
        print("GALLERY_TIMING:", {"stage": "ensure_prostudio_table", "ms": round((time.monotonic() - ensure_start) * 1000), "telegram_id": telegram_id})
        with db_connection(DATABASE_URL) as conn:
            cursor = conn.cursor()
            query_start = time.monotonic()
            cursor.execute("""
                SELECT id, conversation_id, mode, prompt, response_text, image_url, images_json,
                       thumbnails_json, thumb_url, video_url, videos_json, audio_url, audios_json,
                       metadata_json, created_at, status, model, provider, response_json
                FROM prostudio_messages
                WHERE telegram_id = %s
                  AND (COALESCE(image_url, '') <> '' OR COALESCE(video_url, '') <> ''
                       OR COALESCE(audio_url, '') <> '' OR COALESCE(response_text, '') <> '')
                ORDER BY created_at DESC, id DESC
                LIMIT %s OFFSET %s
            """, (telegram_id, safe_limit, safe_offset))
            print("GALLERY_TIMING:", {"stage": "select_prostudio_messages", "ms": round((time.monotonic() - query_start) * 1000), "telegram_id": telegram_id})
            rows = cursor.fetchall()
            cursor.close()
        return rows

    try:
        rows = await asyncio.to_thread(_fetch_gallery_rows)
        stored_media = await asyncio.to_thread(_load_history_stored_media, telegram_id, rows, 13, 18)
        print("GALLERY_TIMING:", {"stage": "total", "ms": round((time.monotonic() - request_started) * 1000), "telegram_id": telegram_id, "row_count": len(rows)})
        items = []
        for row in rows:
            (message_id, conversation_id, mode, prompt, response_text, image_url, images_json,
             thumbnails_json, thumb_url, video_url, videos_json, audio_url, audios_json,
             metadata_json, created_at, status, model, provider, response_json) = row
            images = _json_list(images_json) or ([image_url] if image_url else [])
            thumbs = _json_list(thumbnails_json) or ([thumb_url] if thumb_url else [])
            videos = _json_list(videos_json) or ([video_url] if video_url else [])
            audios = _json_list(audios_json) or ([audio_url] if audio_url else [])
            metadata = _json_obj(metadata_json)
            response_data = _json_obj(response_json)
            committed = stored_media.get(history_generation_id(metadata, response_data))
            if committed:
                media = overlay_stored_history_media({"type": mode or metadata.get("type"),
                    "images": images, "image_url": images[0] if images else "",
                    "videos": videos, "video_url": videos[0] if videos else "",
                    "audios": audios, "audio_url": audios[0] if audios else "",
                    "thumbnails": thumbs, "thumbnail_url": thumbs[0] if thumbs else "", "metadata": metadata}, committed)
                images, videos, audios, thumbs, metadata = (
                    media.get("images") or images, media.get("videos") or videos,
                    media.get("audios") or audios, media.get("thumbnails") or thumbs, media.get("metadata") or metadata)
            kind = str(metadata.get("type") or mode or ("video" if videos else "music" if audios else "image" if images else "text")).lower()
            media_url = (videos[0] if videos else audios[0] if audios else images[0] if images else "")
            # Third instance of the "images[0]-only" truncation bug class
            # found by the Pro Studio A-Z audit (the other two - the chat
            # mini-card and the Generation Info drawer - were already fixed).
            # media_urls carries the full set so a multi-image generation's
            # remaining images aren't silently dropped by this endpoint.
            media_urls = videos if videos else (audios if audios else images)
            preview_url = (
                thumbs[0] if thumbs else images[0] if images else
                metadata.get("thumbnail_url") or metadata.get("cover_url") or
                metadata.get("artwork_url") or metadata.get("image_url") or
                response_data.get("thumbnail_url") or response_data.get("cover_url") or
                response_data.get("image_url") or ""
            )
            items.append({
                "id": message_id, "conversation_id": conversation_id, "type": kind,
                "prompt": prompt or metadata.get("prompt") or "", "text": response_text or "",
                "title": metadata.get("title") or response_data.get("title") or prompt or "",
                "favorite": bool(metadata.get("favorite")),
                "dialogue": gallery_dialogue_blocks(metadata) if kind == "voice" else [],
                "genre": metadata.get("genre") or response_data.get("genre") or "",
                "media_url": media_url, "media_urls": media_urls, "preview_url": preview_url,
                "job_id": metadata.get("job_id") or response_data.get("job_id") or "",
                "status": status or metadata.get("status") or "completed",
                "model": metadata.get("model_label") or model or "", "provider": provider or "",
                "created_at": created_at.isoformat() if hasattr(created_at, "isoformat") else created_at,
            })
        return {"ok": True, "items": items, "limit": safe_limit, "offset": safe_offset}
    except Exception as exc:
        print("PROSTUDIO GALLERY FAILED:", exc)
        return {"ok": True, "items": []}


