TRANSCRIBE_ERRORS = {
    "transcribe_source_invalid": "Расшифровать можно только медиа, загруженное в проект.",
    "transcribe_source_unreadable": "Не удалось прочитать звук из этого файла.",
    "transcribe_too_long": "Расшифровка доступна для файлов до 30 минут.",
    "transcribe_failed": "Не удалось расшифровать речь. Попробуйте ещё раз.",
}


@app.post("/api/public/video-editor/transcribe")
async def public_video_editor_transcribe(request: Request):
    """Timestamped editing transcript of one project media file (OpenAI
    whisper-1 segments). Billed by audio length at the SYLVEX rule; a file
    without an audio track returns an empty transcript and costs nothing."""
    owner = _video_editor_owner(request)
    body = await request.json()
    url = str((body or {}).get("url") or "")

    def fail(code: str, status: int = 400):
        return JSONResponse({"ok": False, "error": code, "message": TRANSCRIBE_ERRORS[code]}, status_code=status)

    if not storage_key_from_url(url):
        return fail("transcribe_source_invalid")
    if not OPENAI_API_KEY:
        return fail("transcribe_failed", 503)
    suffix = video_probe.url_extension(url) or ".mp4"
    try:
        content = await asyncio.to_thread(video_editor_service.load_media_bytes, url)
        meta = await asyncio.to_thread(video_editor_service.probe_media, content, suffix)
    except Exception as exc:
        prostudio_error("VIDEO_EDITOR_TRANSCRIBE_LOAD_FAILED", exc)
        return fail("transcribe_source_unreadable")
    duration = float(meta.get("duration") or 0)
    if duration <= 0:
        return fail("transcribe_source_unreadable")
    if duration > video_editor_service.TRANSCRIBE_MAX_SECONDS:
        return fail("transcribe_too_long")
    if not meta.get("has_audio"):
        return {"ok": True, "segments": [], "duration": duration, "language": "", "cost_credits": 0}
    try:
        audio = await asyncio.to_thread(video_editor_service.extract_speech_audio, content, suffix)
    except Exception as exc:
        prostudio_error("VIDEO_EDITOR_TRANSCRIBE_EXTRACT_FAILED", exc)
        return fail("transcribe_source_unreadable")
    language = str((body or {}).get("language") or "")[:2].lower()
    result = await run_billed_helper(
        owner, video_editor_service.transcribe_credits(duration), "video_editor_transcribe",
        lambda: asyncio.to_thread(video_editor_service.transcribe_segments, audio, OPENAI_API_KEY, OPENAI_API_BASE, language),
        client_request_id=str((body or {}).get("client_request_id") or ""), model="whisper-1", provider="openai",
    )
    if not result.get("ok"):
        print("VIDEO EDITOR TRANSCRIBE FAILED:", result.get("error"))
        return fail("transcribe_failed", 502)
    return {"ok": True, "segments": result.get("segments") or [], "duration": duration,
            "language": result.get("language") or "", "cost_credits": result.get("cost_credits")}


@app.post("/api/public/prostudio/gallery/{message_id}/meta")
async def update_public_prostudio_gallery_item(message_id: int, request: Request):
    """Rename and/or (un)favorite one of the owner's generated results; the
    item keeps its place in the history."""
    telegram_id = int(getattr(request.state, "telegram_id", 0) or 0)
    if not telegram_id:
        return JSONResponse({"ok": False, "error": "login_required"}, status_code=401)
    body = await request.json()
    has_title = "title" in (body or {})
    has_favorite = "favorite" in (body or {})
    if not message_id or not DATABASE_URL or not (has_title or has_favorite):
        return JSONResponse({"ok": False, "error": "nothing_to_update"}, status_code=400)
    title = re.sub(r"\s+", " ", str((body or {}).get("title") or "")).strip()[:120] if has_title else None
    if has_title and not title:
        return JSONResponse({"ok": False, "error": "title_required"}, status_code=400)

    def _sync():
        ensure_prostudio_table()
        with db_connection(DATABASE_URL) as conn:
            cursor = conn.cursor()
            cursor.execute("SELECT metadata_json FROM prostudio_messages WHERE id = %s AND telegram_id = %s", (message_id, telegram_id))
            row = cursor.fetchone()
            if not row:
                cursor.close()
                return False
            metadata = _json_obj(row[0])
            if has_title:
                metadata["title"] = title
            if has_favorite:
                metadata["favorite"] = bool((body or {}).get("favorite"))
            cursor.execute("UPDATE prostudio_messages SET metadata_json = %s, updated_at = NOW() WHERE id = %s AND telegram_id = %s",
                           (json.dumps(metadata, ensure_ascii=False), message_id, telegram_id))
            cursor.close()
            return True

    try:
        found = await asyncio.to_thread(_sync)
    except Exception as exc:
        prostudio_error("GALLERY_META_FAILED", exc, telegram_id=telegram_id)
        return JSONResponse({"ok": False, "error": "update_failed"}, status_code=500)
    if not found:
        return JSONResponse({"ok": False, "error": "not_found"}, status_code=404)
    return {"ok": True}


@app.delete("/api/public/prostudio/gallery/{message_id}")
async def delete_public_prostudio_gallery_item(message_id: int, telegram_id: int = 0):
    """Delete one generated result without deleting the rest of its conversation."""
    if not DATABASE_URL or not telegram_id or not message_id:
        return {"ok": True}

    def _sync():
        ensure_prostudio_table()
        with db_connection(DATABASE_URL) as conn:
            cursor = conn.cursor()
            cursor.execute("DELETE FROM prostudio_messages WHERE id = %s AND telegram_id = %s", (message_id, telegram_id))
            cursor.close()

    try:
        await asyncio.to_thread(_sync)
    except Exception as exc:
        print("PROSTUDIO GALLERY DELETE FAILED:", exc)
    return {"ok": True}


_COMMUNITY_SCHEMA_LOCK = threading.Lock()
_COMMUNITY_SCHEMA_READY = False
def ensure_community_tables():
    # SQL-4: guarded the same way ensure_prostudio_table() already is.
    global _COMMUNITY_SCHEMA_READY
    if _COMMUNITY_SCHEMA_READY or not DATABASE_URL:
        return
    ensure_user_profiles_table()
    with _COMMUNITY_SCHEMA_LOCK:
        if _COMMUNITY_SCHEMA_READY:
            return
        conn = db_connect(DATABASE_URL)
        cursor = conn.cursor()
        try:
            cursor.execute("""
            CREATE TABLE IF NOT EXISTS community_posts (
                id BIGSERIAL PRIMARY KEY,
                telegram_id BIGINT NOT NULL,
                source_message_id BIGINT NOT NULL,
                content_type TEXT NOT NULL,
                media_url TEXT,
                media_urls JSONB DEFAULT '[]'::jsonb,
                preview_url TEXT,
                body TEXT,
                model TEXT,
                created_at TIMESTAMP DEFAULT NOW(),
                UNIQUE (telegram_id, source_message_id)
            )
            """)
            cursor.execute("ALTER TABLE community_posts ADD COLUMN IF NOT EXISTS media_urls JSONB DEFAULT '[]'::jsonb")
            cursor.execute("""
            CREATE TABLE IF NOT EXISTS community_likes (
                post_id BIGINT NOT NULL REFERENCES community_posts(id) ON DELETE CASCADE,
                telegram_id BIGINT NOT NULL,
                created_at TIMESTAMP DEFAULT NOW(),
                PRIMARY KEY (post_id, telegram_id)
            )
            """)
            cursor.execute("""
            CREATE TABLE IF NOT EXISTS community_comments (
                id BIGSERIAL PRIMARY KEY,
                post_id BIGINT NOT NULL REFERENCES community_posts(id) ON DELETE CASCADE,
                telegram_id BIGINT NOT NULL,
                body TEXT NOT NULL,
                parent_comment_id BIGINT REFERENCES community_comments(id) ON DELETE SET NULL,
                edited_at TIMESTAMP,
                created_at TIMESTAMP DEFAULT NOW()
            )
            """)
            cursor.execute("ALTER TABLE community_comments ADD COLUMN IF NOT EXISTS parent_comment_id BIGINT REFERENCES community_comments(id) ON DELETE SET NULL")
            cursor.execute("ALTER TABLE community_comments ADD COLUMN IF NOT EXISTS edited_at TIMESTAMP")
            cursor.execute("""
            CREATE TABLE IF NOT EXISTS community_comment_likes (
                comment_id BIGINT NOT NULL REFERENCES community_comments(id) ON DELETE CASCADE,
                telegram_id BIGINT NOT NULL,
                created_at TIMESTAMP DEFAULT NOW(),
                PRIMARY KEY (comment_id, telegram_id)
            )
            """)
            cursor.execute("CREATE INDEX IF NOT EXISTS idx_community_posts_created ON community_posts (created_at DESC)")
            cursor.execute("CREATE INDEX IF NOT EXISTS idx_community_comments_post ON community_comments (post_id, created_at)")
            cursor.execute("""
            CREATE TABLE IF NOT EXISTS community_friendships (
                requester_id BIGINT NOT NULL,
                addressee_id BIGINT NOT NULL,
                status TEXT NOT NULL DEFAULT 'pending',
                created_at TIMESTAMP DEFAULT NOW(), updated_at TIMESTAMP DEFAULT NOW(),
                PRIMARY KEY (requester_id, addressee_id),
                CHECK (requester_id <> addressee_id)
            )
            """)
            cursor.execute("""
            CREATE TABLE IF NOT EXISTS community_messages (
                id BIGSERIAL PRIMARY KEY,
                sender_id BIGINT NOT NULL,
                recipient_id BIGINT NOT NULL DEFAULT 0,
                body TEXT NOT NULL,
                read_at TIMESTAMP,
                created_at TIMESTAMP DEFAULT NOW()
            )
            """)
            cursor.execute("""
            CREATE TABLE IF NOT EXISTS community_notifications (
                id BIGSERIAL PRIMARY KEY,
                telegram_id BIGINT NOT NULL,
                actor_id BIGINT NOT NULL,
                kind TEXT NOT NULL,
                post_id BIGINT REFERENCES community_posts(id) ON DELETE CASCADE,
                comment_id BIGINT REFERENCES community_comments(id) ON DELETE CASCADE,
                body TEXT,
                read_at TIMESTAMP,
                created_at TIMESTAMP DEFAULT NOW()
            )
            """)
            cursor.execute("CREATE INDEX IF NOT EXISTS idx_community_messages_pair ON community_messages (sender_id, recipient_id, created_at DESC)")
            cursor.execute("CREATE INDEX IF NOT EXISTS idx_community_notifications_user ON community_notifications (telegram_id, created_at DESC)")
            conn.commit()
            _COMMUNITY_SCHEMA_READY = True
        except Exception:
            conn.rollback()
            raise
        finally:
            cursor.close()
            conn.close()


@app.get("/api/public/community/feed")
async def public_community_feed(telegram_id: int = 0, limit: int = 30, offset: int = 0):
    if not DATABASE_URL:
        return {"ok": True, "items": []}

    def _sync():
        ensure_community_tables()
        conn = db_connect(DATABASE_URL)
        cursor = conn.cursor()
        try:
            cursor.execute("""
                SELECT p.id, p.telegram_id, p.content_type, p.media_url, p.preview_url,
                       p.body, p.model, p.created_at,
                       COALESCE(up.display_name, u.first_name, 'SYLVEX User'),
                       COALESCE(up.custom_avatar_url, ''), COALESCE(u.username, ''),
                       COUNT(DISTINCT l.telegram_id),
                       BOOL_OR(l.telegram_id = %s), COUNT(DISTINCT c.id), p.media_urls,
                       (SELECT COUNT(*) FROM community_posts author_posts
                        JOIN community_likes author_likes ON author_likes.post_id = author_posts.id
                        WHERE author_posts.telegram_id = p.telegram_id)
                FROM community_posts p
                LEFT JOIN users u ON u.telegram_id = p.telegram_id
                LEFT JOIN user_profiles up ON up.telegram_id = p.telegram_id
                LEFT JOIN community_likes l ON l.post_id = p.id
                LEFT JOIN community_comments c ON c.post_id = p.id
                GROUP BY p.id, up.display_name, up.custom_avatar_url, u.first_name, u.username
                ORDER BY p.created_at DESC
                LIMIT %s OFFSET %s
            """, (telegram_id, max(1, min(int(limit), 50)), max(0, int(offset))))
            rows = cursor.fetchall()
            return [{
                "id": row[0], "author_id": row[1], "type": row[2], "media_url": row[3] or "",
                "preview_url": row[4] or row[3] or "", "body": row[5] or "", "model": row[6] or "",
                "created_at": _to_iso(row[7]), "author_name": row[8], "author_avatar": row[9] or "",
                "author_username": row[10] or "", "likes": int(row[11] or 0),
                "liked": bool(row[12]), "comments": int(row[13] or 0),
                "media_urls": _json_list(row[14]) or ([row[3]] if row[3] else []),
                "author_likes": int(row[15] or 0), "is_own": bool(telegram_id and int(row[1]) == telegram_id),
            } for row in rows]
        finally:
            cursor.close()
            conn.close()

    items = await asyncio.to_thread(_sync)
    return {"ok": True, "items": items}


