def _character_gender_text(gender: str) -> str:
    return "male" if gender == "male" else ("female" if gender == "female" else "a person")


def _character_identity_prompt(name: str, gender: str, description: str) -> str:
    gender_text = _character_gender_text(gender)
    desc = f" {description.strip()}" if description and description.strip() else ""
    return f'The character is {gender_text}, named "{name}".{desc}'.strip()


async def _openai_character_shot(prompt: str, reference_urls: list, quality: str = "high") -> str:
    payload = {
        "mode": "image",
        "category": "image",
        "provider": "openai",
        "model": "gpt_image_2",
        "prompt": prompt,
        "image_options": {
            "modelId": "gpt_image_2",
            "size": "1024x1024",
            "quality": quality,
            "count": 1,
            "referenceImageUrls": [url for url in reference_urls if url][:5],
        },
    }
    result = await run_provider_coroutine_off_loop(lambda: image_generation(payload))
    if not result.get("ok"):
        diagnostic = (
            result.get("raw_error")
            or result.get("details")
            or result.get("body_preview")
            or result.get("error")
            or "OpenAI character image generation failed"
        )
        raise RuntimeError(
            f"OpenAI character image generation failed"
            f" (status={result.get('status_code') or 'unknown'}, model={result.get('provider_model') or 'gpt-image-2'}): "
            f"{str(diagnostic)[:1200]}"
        )
    urls = materialize_image_urls(_json_list(result.get("images")) or [result.get("image_url")])
    if not urls:
        raise RuntimeError("OpenAI returned no character image")
    return urls[0]


# =====================================================
# СОХРАНЕНИЕ В БАЗУ ДАННЫХ: _record_character_job_progress
# Writes a lightweight stage/progress snapshot into the job's own
# result_json while it is still 'processing' - never flips the job's
# status, and is refused harmlessly by update_prostudio_generation_job's
# own terminal-status guard if the job has already gone failed/cancelled
# concurrently (e.g. stale recovery). This is what lets the frontend's
# pending Character card poll GET /api/public/prostudio/job/{job_id} and
# progressively show "1/4", "2/4", the generated Primary Face preview,
# etc., instead of a flat "Creating..." for the whole run.
# =====================================================
async def _record_character_job_progress(
    job_id: str,
    stage: str,
    completed_references: int,
    total_references: int = 4,
    primary_url: str = "",
) -> None:
    payload = {
        "stage": stage,
        "completed_references": completed_references,
        "total_references": total_references,
    }
    if primary_url:
        payload["primary_url"] = primary_url
    await asyncio.to_thread(update_prostudio_generation_job, job_id, "processing", payload)


async def _generate_openai_character_images(job_id: str, name: str, gender: str, description: str, photos: list) -> list:
    require_billing_scope("_generate_openai_character_images")
    # Character creation: the user supplies exactly one ordinary source
    # photo (which may be a plain selfie, not already a studio reference),
    # and AI automatically builds the standard 4-reference set from it -
    # Main identity, Full Body Front/Side/Back. Front/Side/Back are each
    # generated against the Main identity shot (and the previously
    # generated body shot) so identity and clothing stay locked across the
    # set, instead of four independently reinterpreted generations.
    #
    # Each stage is individually timed and logged (CHARACTER_*_START/DONE,
    # with job_id + elapsed_seconds) so a slow/stale-looking job can be
    # diagnosed as "provider generation is genuinely still running" versus
    # a SYLVEX-side save/UI delay after generation already finished.
    identity = _character_identity_prompt(name, gender, description)
    source_photo = photos[0] if photos else ""

    primary_prompt = (
        "Create a professional primary identity reference photo of the exact same person shown in the uploaded "
        f"photo. {identity} "
        "The uploaded photo may be an ordinary photo or selfie, not already a professional reference - reconstruct "
        "it into a polished professional portrait/fashion-shoot style photo, as if a professional photographer is "
        "photographing this person during a photoshoot: the person poses toward the camera with direct engagement, "
        "professional model-like facial posing, expressive and confident eyes, and a strong, intentional gaze - "
        "face oriented appropriately toward the camera, not looking away. The expression should be natural but "
        "photogenic, never a blank or dead expression, never a casual accidental-selfie look, and never "
        "exaggerated or theatrical. Use close framing appropriate for an identity reference: chest-up or "
        "waist-up, with the face and eyes sharply in focus and clearly visible, good even studio lighting, and a "
        "clean, restrained background. You may correct poor selfie framing, perspective, composition and "
        "lighting, but you must preserve the person's real identity exactly: facial structure, skin tone, age, "
        "gender, eye color, hairstyle, and visible clothing characteristics. Do not change who this person is, do "
        "not alter their facial identity, and do not beautify them into a different-looking or excessively "
        "idealized person - the same person, simply posing confidently for the camera like a professional model. "
        "No text, watermark, extra people, or collage."
    )
    primary_started = time.monotonic()
    prostudio_debug("CHARACTER_PRIMARY_START", job_id=job_id)
    primary_url = await _openai_character_shot(primary_prompt, [source_photo])
    prostudio_debug("CHARACTER_PRIMARY_DONE", job_id=job_id, elapsed_seconds=round(time.monotonic() - primary_started, 3))
    # Primary is the first reference whose URL the pending Character card
    # can show as a progressive preview (source thumbnail -> generated
    # Primary Face) while Front/Side/Back are still generating - Primary
    # completion is never treated as Character completion, only as the
    # start of the Front stage.
    await _record_character_job_progress(job_id, "front", 1, primary_url=primary_url)

    # Body-reference prompt: a deliberately neutral, non-sexual technical
    # identity reference. Production evidence showed gpt-image-2 rejecting
    # "Full Body Front" with safety_violations=[sexual] - this wording
    # exists specifically to avoid those false positives (explicit fully-
    # clothed/non-revealing/non-suggestive framing, explicit negatives for
    # lingerie/underwear/swimwear/transparent clothing/provocative or
    # body-focused posing) while keeping the same identity-lock intent
    # (same person, age, gender, skin tone, hair, body proportions,
    # consistent clothing) as before.
    def body_prompt(view_instruction: str) -> str:
        return (
            "Create a neutral technical full-body character identity reference. This is a non-sexual, "
            "non-suggestive character reference sheet intended only to document the person's identity, body "
            "proportions, clothing and viewing angle. The character must be fully clothed in ordinary "
            "non-revealing clothing and stand naturally in a neutral pose. "
            f"{identity} "
            "Use the provided reference image(s) to keep the exact same face, skin tone, approximate age, "
            "gender, eye color, hairstyle and body proportions as the character's established identity - this "
            "must be the same person as in the other reference views, not a new person. If the provided "
            "reference already shows the full body and outfit, preserve its general clothing style, colors, "
            "recognizable garments and accessories exactly. Otherwise, infer ordinary, neutral, non-revealing "
            "clothing for any body area not yet visible (such as legs, trousers and shoes), and then treat that "
            "completed outfit as fixed for every other view - never invent different trousers, shoes, jackets, "
            "colors or accessories between views, and never infer lingerie, underwear, swimwear, transparent "
            "clothing, or any other revealing clothing for a hidden body area. "
            f"{view_instruction} "
            "Neutral standing posture, arms naturally relaxed at the sides, no provocative posing, no "
            "body-emphasizing pose, no glamour or body-focused composition. No lingerie, no underwear, no "
            "swimwear, no transparent clothing, no exposed intimate areas, no erotic or suggestive "
            "presentation. Do not sexualize or exaggerate body proportions. Full body visible from head to "
            "feet, consistent camera distance and character scale, plain neutral gray studio background, "
            "consistent even lighting. This is a technical identity reference, not a lifestyle or fashion "
            "photograph. No text, watermark, extra people, or collage."
        )

    # Once Primary succeeds, the raw uploaded source photo is never resent -
    # every body reference is generated from the already-normalized,
    # already-safety-reviewed generated Character images, never from the
    # original user upload again.
    front_started = time.monotonic()
    prostudio_debug("CHARACTER_FRONT_START", job_id=job_id)
    front_url = await _openai_character_shot(
        body_prompt("Front: Full-body front view, standing straight and facing directly toward the camera."),
        [primary_url],
    )
    prostudio_debug("CHARACTER_FRONT_DONE", job_id=job_id, elapsed_seconds=round(time.monotonic() - front_started, 3))
    await _record_character_job_progress(job_id, "side", 2, primary_url=primary_url)

    side_started = time.monotonic()
    prostudio_debug("CHARACTER_SIDE_START", job_id=job_id)
    side_url = await _openai_character_shot(
        body_prompt("Side: Strict full-body side/profile view."),
        [primary_url, front_url],
    )
    prostudio_debug("CHARACTER_SIDE_DONE", job_id=job_id, elapsed_seconds=round(time.monotonic() - side_started, 3))
    await _record_character_job_progress(job_id, "back", 3, primary_url=primary_url)

    back_started = time.monotonic()
    prostudio_debug("CHARACTER_BACK_START", job_id=job_id)
    back_url = await _openai_character_shot(
        body_prompt("Back: Strict full-body back view, facing directly away from the camera."),
        [primary_url, front_url, side_url],
    )
    prostudio_debug("CHARACTER_BACK_DONE", job_id=job_id, elapsed_seconds=round(time.monotonic() - back_started, 3))
    return [primary_url, front_url, side_url, back_url]


# =====================================================
# СОХРАНЕНИЕ В БАЗУ ДАННЫХ: create_character_creation_job
# Character creation gets its own job lane in prostudio_generation_jobs
# rather than going through create_prostudio_generation_job(): it reserves
# its own composed price (4 x GPT Image 2 shot) and must never be blocked by - or block - an
# unrelated image/video/music/voice job, so it skips that function's
# single-active-job-per-user check entirely. The row is inserted already
# 'processing' (never 'queued'), so the generic worker pool's
# claim_next_prostudio_generation_job() - which only looks at 'queued'
# rows - can never pick it up and fail it with "Unknown generation mode"
# before _run_character_creation_job() gets to it.
# =====================================================
def _gpt_image_2_shot_price() -> int:
    """Existing GPT Image 2 tariff for one Character/Object reference shot
    (1024x1024, high quality, one reference image - the exact request
    _openai_character_shot() sends)."""
    estimate = calculate_generation_price({
        "mode": "image", "category": "image", "provider": "openai", "model": "gpt_image_2", "prompt": "",
        "image_options": {"modelId": "gpt_image_2", "size": "1024x1024", "quality": "high", "count": 1,
                          "referenceImageUrls": ["reference"]},
    })
    if not estimate.get("pricing_available", False):
        return 0
    return int((estimate.get("price_snapshot") or {}).get("final_credits") or 0)


CHARACTER_CREATION_SHOTS = 4  # Primary face + full body front/side/back


def character_creation_price() -> int:
    unit = _gpt_image_2_shot_price()
    return unit * CHARACTER_CREATION_SHOTS if unit > 0 else 0


OBJECT_VISION_SYSTEM_PROMPT = "You write extremely concise visual identity descriptions of physical objects for internal reference use only."


def object_vision_reservation(name: str, description: str) -> int:
    """Upper bound of the gpt-5.5 vision call (system + instruction text, one
    image, capped output); the job settles on the usage it reports."""
    return helper_text_reservation(
        "gpt-5.5", OBJECT_VISION_SYSTEM_PROMPT + _object_prompt_instruction_text(name, description),
        OBJECT_VISION_MAX_OUTPUT_TOKENS, image_count=1,
    )


def object_creation_price(name: str, description: str) -> int:
    image = _gpt_image_2_shot_price()
    vision = object_vision_reservation(name, description)
    return image + vision if image > 0 and vision > 0 else 0


def object_creation_settled_credits(reserved_total: int, vision_usage: dict) -> int:
    """Fixed GPT Image 2 shot + the vision call's actual usage (capped at its
    reservation; nothing when the call failed and the fallback prompt was
    used; the reservation when it answered without reporting usage)."""
    image = _gpt_image_2_shot_price()
    vision_reserved = max(0, int(reserved_total or 0) - image)
    if not vision_usage.get("answered"):
        return image
    return image + settled_helper_credits(vision_reserved, vision_usage.get("credits"), "object_vision")


def _creation_job_price_snapshot(credits: int, kind: str) -> dict:
    return {"pricing_version": "composed", "final_credits": int(credits), "currency": "⚡",
            "parameters": {"mode": kind}}


def create_character_creation_job(telegram_id: int, name: str, gender: str, description: str, photos: list, credits: int = 0) -> str:
    if not DATABASE_URL:
        raise SecurityError("generation_queue_unavailable", 503)
    ensure_prostudio_table()
    if int(credits or 0) <= 0:
        raise SecurityError("pricing_not_configured", 402)
    job_id = str(uuid4())
    ensure_reservations(lambda: db_connect(DATABASE_URL))
    conn = db_connect(DATABASE_URL)
    cursor = conn.cursor()
    try:
        cursor.execute("SELECT pg_advisory_xact_lock(%s)", (telegram_id,))
        reserve_generation(cursor, telegram_id, job_id, int(credits))
        cursor.execute("""
            INSERT INTO prostudio_generation_jobs (
                id, telegram_id, mode, model, provider, prompt, status, request_json, heartbeat_at
            ) VALUES (%s, %s, 'character_creation', 'gpt-image-2', 'openai', %s, 'processing', %s::jsonb, NOW())
        """, (
            job_id,
            telegram_id,
            name,
            _safe_json_dumps({"name": name, "gender": gender, "description": description, "photos": photos,
                              "price_snapshot": _creation_job_price_snapshot(credits, "character_creation")}),
        ))
        conn.commit()
    finally:
        cursor.close()
        conn.close()
    return job_id


# =====================================================
# ФОНОВАЯ ЗАДАЧА: _character_creation_heartbeat_loop
# Keeps a character_creation job's heartbeat fresh for the job's *entire*
# lifetime - including all four sequential GPT Image calls - so a healthy,
# still-running Character job can never be recovered as stale by
# requeue_stale_prostudio_jobs() (which only looks at heartbeat_at).
# Previously the only heartbeat write happened once, *after*
# _generate_openai_character_images() had already finished, so a Character
# creation taking longer than PROSTUDIO_STALE_PROCESSING_MINUTES (5 min by
# default) could be wrongly marked 'failed' mid-generation, while the
# background task kept running to completion regardless (nothing cancels
# it) - producing a "ghost" Character that materializes later even though
# the job itself stayed 'failed'.
# =====================================================
CHARACTER_CREATION_HEARTBEAT_SECONDS = 25.0  # within the requested 20-30s cadence


async def _character_creation_heartbeat_loop(job_id: str, finished_event: asyncio.Event):
    while not finished_event.is_set():
        try:
            await asyncio.wait_for(finished_event.wait(), timeout=CHARACTER_CREATION_HEARTBEAT_SECONDS)
            return
        except asyncio.TimeoutError:
            await asyncio.to_thread(heartbeat_prostudio_generation_job, job_id)


# classify_openai_creation_error: the billing-limit/safety-policy/generic
# classification of an OpenAI creation-job failure was duplicated, regex
# for regex, between _run_character_creation_job and
# _run_object_creation_job below - this is the one place that logic lives
# now. Only the safety-policy message differs between Character and
# Object (safety_message is each caller's own, already-translated
# user-facing text) - the billing-limit message, both regexes, and the
# generic fallback truncation are shared because they were always
# identical.
def classify_openai_creation_error(error_text: str, safety_message: str) -> dict:
    if re.search(r"billing hard limit|billing limit|insufficient[_ ]quota", error_text, re.I):
        return {
            "ok": False,
            "error": "Лимит расходов OpenAI исчерпан. Пополните баланс или увеличьте бюджет API-проекта OpenAI.",
            "provider": "openai",
        }
    if re.search(r"safety_violations|safety system|content policy|moderation", error_text, re.I):
        # A clean, generic message only - never the raw provider
        # diagnostic (which can contain response-body fragments), and
        # never a stack trace.
        return {"ok": False, "error": safety_message, "provider": "openai"}
    return {"ok": False, "error": error_text[:1200]}


# =====================================================
# ФОНОВАЯ ЗАДАЧА: _run_character_creation_job
# Runs off the request/response cycle: fired via asyncio.create_task
# right after create_character_creation_job() returns, so Character
# creation keeps running even if the browser that triggered it
# disconnects before this finishes. The generation/storage/resource-
# building logic below is unchanged from the previous synchronous
# endpoint - only the job bookkeeping around it (heartbeat, completed/
# failed write) is new. The frontend learns the outcome by polling
# GET /api/public/prostudio/job/{job_id}, the same endpoint every other
# Pro Studio generation job already uses.
# =====================================================
async def _settle_creation_job(job_id: str, telegram_id: int, credits: int, kind: str, result: dict) -> bool:
    billing = await asyncio.to_thread(
        charge_generation_balance, telegram_id, job_id, result,
        {"mode": kind, "model": "gpt-image-2", "provider": "openai",
         "price_snapshot": _creation_job_price_snapshot(credits, kind)},
    )
    return bool(billing.get("charged") or billing.get("already_charged"))


async def _run_character_creation_job(job_id: str, telegram_id: int, name: str, gender: str, description: str, photos: list, credits: int = 0):
    if int(credits or 0) <= 0:
        # Never dispatch an unpriced creation job; its row must not hang in 'processing'.
        await asyncio.to_thread(update_prostudio_generation_job, job_id, "failed", None,
                                {"ok": False, "error": "pricing_not_configured"})
        return
    with billing_scope(job_id, credits):
        await _run_character_creation_job_billed(job_id, telegram_id, name, gender, description, photos, credits)


async def _run_character_creation_job_billed(job_id: str, telegram_id: int, name: str, gender: str, description: str, photos: list, credits: int):
    job_started = time.monotonic()
    finished_event = asyncio.Event()
    heartbeat_task = asyncio.create_task(
        _character_creation_heartbeat_loop(job_id, finished_event),
        name=f"character-creation-heartbeat-{job_id}",
    )
    try:
        images = await _generate_openai_character_images(job_id, name, gender, description, photos)
        # A job that has already gone truly terminal (failed/cancelled) by
        # the time generation finishes - e.g. an explicit cancel, or (in
        # theory, now that the heartbeat above runs continuously) a stale
        # recovery that still slipped in - must never gain a Character
        # resource afterwards. This is what prevents a "ghost Character"
        # from appearing later, after the UI already received a real
        # terminal failure for this job.
        current_status = await asyncio.to_thread(get_prostudio_generation_job_status, job_id)
        if current_status in {"failed", "cancelled", "canceled"}:
            prostudio_debug(
                "CHARACTER_RESOURCE_SAVE_SKIPPED_TERMINAL_JOB",
                job_id=job_id,
                status=current_status,
            )
            return
        await _record_character_job_progress(job_id, "saving", 4, primary_url=images[0] if images else "")
        # SYLVEX-only Character pipeline: GPT Image generates the reference
        # set, SYLVEX stores it, and the Character is created under its own
        # internal id - there is no provider-registration step (HeyGen or
        # otherwise) and nothing here can make Character creation fail on
        # an external provider's behalf. heygenPhotoAvatarId/
        # heygenAvatarGroupId below stay empty for a Character created this
        # way; other SYLVEX features (e.g. built-in preset Characters, or a
        # future explicit "sync to HeyGen" action) may still populate and
        # use those same fields - this endpoint just never writes them.
        stable_id = uuid4().hex
        # The expandable Character reference library (Character System V2):
        # each entry has its own stable id and a role label, so the
        # composer's manual reference-selection UI can show "Primary Face /
        # Full Body Front / Full Body Side / Full Body Back" checkboxes
        # instead of an unlabeled, fixed-size array. referenceImages/
        # previewUrl/avatarUrl below stay as the flat, backward-compatible
        # view every existing consumer already reads - this list is purely
        # additive.
        reference_roles = ["Primary Face", "Full Body Front", "Full Body Side", "Full Body Back"]
        reference_library = [
            {"id": uuid4().hex, "url": url, "role": reference_roles[index] if index < len(reference_roles) else "Additional", "added_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())}
            for index, url in enumerate(images[:4])
        ]
        resource = {
            "id": f"custom_character_{stable_id}",
            "resource_type": "character",
            "name": name,
            "gender": gender,
            "description": description,
            "prompt": "",
            "previewUrl": images[0],
            "avatarUrl": images[0],
            "primaryReferenceUrl": images[0],
            "referenceImages": images[1:4],
            "referenceLibrary": reference_library,
            "sourceImages": images[1:4],
            "originalSourceImages": photos,
            "avatar_id": "",
            "heygenPhotoAvatarId": "",
            "heygenAvatarGroupId": "",
            "provider": "openai",
            "ai_provider": "openai",
            "model": "gpt-image-2",
            "ai_model": "gpt-image-2",
            "type": "custom",
            "status": "ready",
            "created_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        }
        save_started = time.monotonic()
        prostudio_debug("CHARACTER_RESOURCE_SAVE_START", job_id=job_id)
        saved = await asyncio.to_thread(save_prostudio_resource, telegram_id, resource)
        prostudio_debug("CHARACTER_RESOURCE_SAVE_DONE", job_id=job_id, elapsed_seconds=round(time.monotonic() - save_started, 3))
        final_resource = {**resource, **saved}
        result = {
            "ok": True,
            "type": "character",
            "character_id": final_resource["id"],
            "resource": final_resource,
            # generation_result_urls() falls back to this generic key for
            # any mode it doesn't specifically recognise (ours included),
            # which is what lets the poll endpoint see this job as
            # genuinely completed rather than holding it at
            # "provider_processing".
            "result_url": final_resource["previewUrl"],
        }
        if not await _settle_creation_job(job_id, telegram_id, credits, "character_creation", result):
            raise RuntimeError("character_creation_billing_failed")
        await asyncio.to_thread(update_prostudio_generation_job, job_id, "completed", result)
        prostudio_debug("CHARACTER_JOB_COMPLETED", job_id=job_id, elapsed_seconds=round(time.monotonic() - job_started, 3))
    except Exception as exc:
        # The full diagnostic (including any provider safety-violation
        # payload fragment _openai_character_shot folded into the
        # exception message) is preserved server-side here, in
        # prostudio_error's own log line - never trimmed, never bypassed.
        # Provider safety is never disabled or retried around; a rejected
        # request simply terminates this job as failed, same as any other
        # generation failure.
        prostudio_error("CHARACTER_CREATE_FAILED", exc, telegram_id=telegram_id, name=name, job_id=job_id)
        error_payload = classify_openai_creation_error(
            str(exc),
            "Не удалось сгенерировать референс персонажа: запрос был отклонён системой безопасности провайдера изображений. Попробуйте другое фото или измените описание персонажа.",
        )
        await asyncio.to_thread(update_prostudio_generation_job, job_id, "failed", None, error_payload)
    finally:
        finished_event.set()
        await asyncio.gather(heartbeat_task, return_exceptions=True)


@app.post("/api/public/prostudio/character")
async def public_prostudio_create_character(request: Request):
    data = await request.json()
    telegram_id = int(data.get("telegram_id") or 0)
    name = str(data.get("name") or "").strip()
    gender = str(data.get("gender") or "").strip()
    description = str(data.get("description") or "").strip()
    # Character creation: exactly one source photo, which becomes the
    # identity source for the AI-generated 4-reference set below - the
    # user never uploads the final reference set directly.
    photos = (_json_list(data.get("photos")) or _json_list(data.get("referenceImages")))[:1]
    if not telegram_id:
        return telegram_id_required_response()
    if len(name) < 2:
        return JSONResponse({"ok": False, "error": "name_required"}, status_code=400)
    if not photos:
        return JSONResponse({"ok": False, "error": "reference_image_required"}, status_code=400)
    credits = character_creation_price()
    if credits <= 0:
        return unpriced_helper_response("character_creation")
    try:
        job_id = await asyncio.to_thread(create_character_creation_job, telegram_id, name, gender, description, photos, credits)
    except SecurityError:
        raise
    except Exception as exc:
        prostudio_error("CHARACTER_JOB_CREATE_FAILED", exc, telegram_id=telegram_id, name=name)
        return JSONResponse({"ok": False, "error": str(exc)[:1200]}, status_code=502)
    # Fired but never awaited, so it keeps running after this response is
    # sent - Character creation must continue even if the browser that
    # made this request disconnects. Kept on app.state.background_tasks
    # (same convention as the generation worker loop) only to prevent
    # premature garbage collection; it is not awaited there either.
    task = asyncio.create_task(_run_character_creation_job(job_id, telegram_id, name, gender, description, photos, credits))
    background_tasks = getattr(app.state, "background_tasks", None)
    if isinstance(background_tasks, list):
        background_tasks.append(task)
    return JSONResponse({"ok": True, "job_id": job_id, "status": "processing"}, status_code=202)


# =====================================================
# API ENDPOINT: public_prostudio_character_creation_jobs
# Owner-scoped list of this telegram_id's character_creation jobs, so the
# frontend's pending-Character-card UI can restore itself after a reload
# (or the browser/Mini App being closed entirely) purely from the backend
# - never from localStorage, which is only ever an optional fast cache.
# Bounded to a recent window so the result stays small without needing
# pagination. WHERE telegram_id = %s is the only thing that can ever
# select a row here - there is no path by which this can return another
# user's jobs.
# Маршрут FastAPI: @app.get("/api/public/prostudio/character-creation-jobs")
# =====================================================
@app.get("/api/public/prostudio/character-creation-jobs")
async def public_prostudio_character_creation_jobs(telegram_id: int = 0):
    if not telegram_id:
        return telegram_id_required_response()
    if not DATABASE_URL:
        return {"ok": True, "jobs": []}

    def _sync():
        ensure_prostudio_table()
        with db_connection(DATABASE_URL) as conn:
            cursor = conn.cursor()
            cursor.execute("""
                SELECT id, status, request_json, result_json, error_json, created_at, updated_at
                FROM prostudio_generation_jobs
                WHERE telegram_id = %s AND mode = 'character_creation'
                  AND created_at > NOW() - INTERVAL '24 hours'
                ORDER BY created_at DESC
                LIMIT 20
            """, (telegram_id,))
            rows = cursor.fetchall()
            cursor.close()
        return rows

    try:
        rows = await asyncio.to_thread(_sync)
    except Exception as exc:
        prostudio_error("CHARACTER_JOBS_LIST_FAILED", exc, telegram_id=telegram_id)
        return JSONResponse({"ok": False, "error": "character_jobs_list_failed"}, status_code=500)

    jobs = []
    for row in rows:
        job_id, status, request_json, result_json, error_json, created_at, updated_at = row
        request = _json_obj(request_json)
        result = _json_obj(result_json) if result_json else None
        # Same whitelist/translation the single-job GET endpoint
        # (public_prostudio_job) already applies - an error record can
        # carry raw provider/exception text, which must never reach the
        # client untranslated.
        error = _public_error_json(_json_obj(error_json))
        if error:
            normalized_error = user_generation_error_text(error.get("error") or error.get("message") or error)
            error["error"] = normalized_error
            error["message"] = normalized_error
        jobs.append({
            "job_id": job_id,
            "status": status,
            "name": request.get("name") or "",
            "gender": request.get("gender") or "",
            "description": request.get("description") or "",
            "photos": _json_list(request.get("photos")),
            "created_at": _to_iso(created_at),
            "updated_at": _to_iso(updated_at),
            "result": result or None,
            "error": error or None,
        })
    return {"ok": True, "jobs": jobs}


# =====================================================
# Object Creation V2: single reference + auto objectPrompt, background job
# Mirrors the Character Creation V2 job architecture (own job lane in
# prostudio_generation_jobs, heartbeat, terminal-status guard, owner-scoped
# jobs-list endpoint) but with a much simpler pipeline: exactly one
# normalized reference image, plus a short auxiliary textual identity
# descriptor (objectPrompt) generated independently via a vision-capable
# text call - never a second usable generation reference, never a
# Front/Side/Back set. Reference-image generation and objectPrompt
# analysis run in parallel (asyncio.gather); a failed objectPrompt analysis
# never fails the Object creation - the reference image is the critical
# result, and a safe fallback (Description, else name) is used instead.
# =====================================================
def _object_reference_prompt(name: str, description: str) -> str:
    desc = f" Additional details from the owner: {description.strip()[:600]}" if description and description.strip() else ""
    return (
        "Create one clean, professional reference photo of the exact same physical object shown in the "
        f'uploaded photo (named "{name}" by its owner).{desc} '
        "Preserve the object's real identity exactly: its type, shape, proportions, construction, material, "
        "colors, texture, patterns, hardware, buttons, zippers, handles and other functional parts, any "
        "visible branding, logos or text, and every other distinctive identifying detail. This must remain "
        "recognizably the same physical object, never a redesigned, restyled or loosely inspired version of "
        "it. "
        "You may remove the original background and surrounding environment, remove unrelated objects, "
        "reconstruct hidden or occluded areas where reasonably necessary, improve framing and lighting, and "
        "present the object clearly centered on a clean neutral studio-style background - none of that "
        "original photographic environment is part of the object's identity. Do not unnecessarily redesign "
        "the object itself. No text, watermark, people, hands, or collage - the object alone, clearly lit "
        "and in sharp focus."
    )


def _object_prompt_instruction_text(name: str, description: str) -> str:
    instruction = (
        "You are generating a short internal visual identity descriptor for a saved Object reference image, "
        "used later to help preserve this object's appearance across unrelated future AI image generations. "
        "Look only at the physical object itself. Describe only stable visual properties: object category or "
        "type, overall shape, proportions, material, primary and secondary colors, texture, important "
        "structural parts, distinctive features, patterns, and any branding, logo or text that is actually "
        "visible. Do not invent details that are not visible or reasonably identifiable from the image. "
        "Do not mention the background, room, scene, lighting, camera angle, hands, body, or any other "
        "surrounding object - describe the object only. "
        "Respond with one or two concise descriptive sentences and nothing else: no preamble, no quotes, no "
        "labels, no markdown."
    )
    if name and name.strip():
        instruction += f' The object is named "{name.strip()}".'
    if description and description.strip():
        instruction += (
            " The owner also provided this description, which you may incorporate only where it does not "
            f"conflict with what is actually visible: {description.strip()[:600]}"
        )
    return instruction


def _object_prompt_fallback(name: str, description: str) -> str:
    if description and description.strip():
        return description.strip()[:600]
    return (name or "Object").strip()


async def _record_object_job_progress(job_id: str, stage: str, reference_url: str = "") -> None:
    payload = {"stage": stage}
    if reference_url:
        payload["reference_url"] = reference_url
    await asyncio.to_thread(update_prostudio_generation_job, job_id, "processing", payload)


async def _generate_object_reference_image(job_id: str, name: str, description: str, source_photo: str) -> str:
    prompt = _object_reference_prompt(name, description)
    started = time.monotonic()
    prostudio_debug("OBJECT_REFERENCE_START", job_id=job_id)
    # Reuses the same generic GPT Image orchestration Character creation
    # uses for its own shots - this helper has no Character-specific
    # semantics beyond its name, it is just "run one GPT Image edit/
    # generate call against these reference URLs".
    url = await _openai_character_shot(prompt, [source_photo])
    prostudio_debug("OBJECT_REFERENCE_DONE", job_id=job_id, elapsed_seconds=round(time.monotonic() - started, 3))
    return url


async def _analyze_object_prompt(job_id: str, name: str, description: str, image_url: str, usage: Optional[dict] = None) -> str:
    if not image_url:
        raise RuntimeError("object_prompt_analysis_missing_image")
    instruction = _object_prompt_instruction_text(name, description)
    messages = [
        {"role": "system", "content": OBJECT_VISION_SYSTEM_PROMPT},
        {"role": "user", "content": [
            {"type": "text", "text": instruction},
            {"type": "image_url", "image_url": {"url": image_url}},
        ]},
    ]
    started = time.monotonic()
    prostudio_debug("OBJECT_PROMPT_ANALYSIS_START", job_id=job_id)
    # call_text_provider() is a plain blocking (requests.post-based)
    # function, the same lower-level text-provider primitive the
    # "Промпт по фото" vision tool uses - gpt-5.5 runs through the
    # Responses API path, which already knows how to turn an image_url
    # content part into input_image for OpenAI. asyncio.to_thread() keeps
    # that blocking call off the event loop, same as every other blocking
    # provider/DB call in this job.
    result = await asyncio.to_thread(call_text_provider, "gpt-5.5", messages, None, OBJECT_VISION_MAX_OUTPUT_TOKENS)
    if not result.get("ok"):
        raise RuntimeError(str(result.get("error") or "object_prompt_analysis_failed")[:600])
    if usage is not None:
        usage["answered"] = True
        usage["credits"] = text_usage_credits("gpt-5.5", result.get("metadata"))
    text = str(result.get("text") or "").strip()
    if not text:
        raise RuntimeError("object_prompt_analysis_empty")
    prostudio_debug("OBJECT_PROMPT_ANALYSIS_DONE", job_id=job_id, elapsed_seconds=round(time.monotonic() - started, 3))
    return text[:600]


def create_object_creation_job(telegram_id: int, name: str, description: str, photos: list, credits: int = 0) -> str:
    if not DATABASE_URL:
        raise SecurityError("generation_queue_unavailable", 503)
    ensure_prostudio_table()
    if int(credits or 0) <= 0:
        raise SecurityError("pricing_not_configured", 402)
    job_id = str(uuid4())
    ensure_reservations(lambda: db_connect(DATABASE_URL))
    conn = db_connect(DATABASE_URL)
    cursor = conn.cursor()
    try:
        cursor.execute("SELECT pg_advisory_xact_lock(%s)", (telegram_id,))
        reserve_generation(cursor, telegram_id, job_id, int(credits))
        cursor.execute("""
            INSERT INTO prostudio_generation_jobs (
                id, telegram_id, mode, model, provider, prompt, status, request_json, heartbeat_at
            ) VALUES (%s, %s, 'object_creation', 'gpt-image-2', 'openai', %s, 'processing', %s::jsonb, NOW())
        """, (
            job_id,
            telegram_id,
            name,
            _safe_json_dumps({"name": name, "description": description, "photos": photos,
                              "price_snapshot": _creation_job_price_snapshot(credits, "object_creation")}),
        ))
        conn.commit()
    finally:
        cursor.close()
        conn.close()
    return job_id


async def _run_object_creation_job(job_id: str, telegram_id: int, name: str, description: str, photos: list, credits: int = 0):
    if int(credits or 0) <= 0:
        # Never dispatch an unpriced creation job; its row must not hang in 'processing'.
        await asyncio.to_thread(update_prostudio_generation_job, job_id, "failed", None,
                                {"ok": False, "error": "pricing_not_configured"})
        return
    with billing_scope(job_id, credits):
        await _run_object_creation_job_billed(job_id, telegram_id, name, description, photos, credits)


async def _run_object_creation_job_billed(job_id: str, telegram_id: int, name: str, description: str, photos: list, credits: int):
    job_started = time.monotonic()
    finished_event = asyncio.Event()
    # The same generic heartbeat loop Character creation uses - it only
    # ever touches the job row by job_id, nothing Character-specific.
    heartbeat_task = asyncio.create_task(
        _character_creation_heartbeat_loop(job_id, finished_event),
        name=f"object-creation-heartbeat-{job_id}",
    )
    source_photo = photos[0] if photos else ""
    try:
        await _record_object_job_progress(job_id, "reference")
        vision_usage = {}
        reference_result, prompt_result = await asyncio.gather(
            _generate_object_reference_image(job_id, name, description, source_photo),
            _analyze_object_prompt(job_id, name, description, source_photo, vision_usage),
            return_exceptions=True,
        )
        if isinstance(reference_result, BaseException):
            raise reference_result
        reference_url = reference_result
        if isinstance(prompt_result, BaseException):
            prostudio_error("OBJECT_PROMPT_ANALYSIS_FAILED", prompt_result, job_id=job_id, telegram_id=telegram_id)
            object_prompt = _object_prompt_fallback(name, description)
        else:
            object_prompt = prompt_result or _object_prompt_fallback(name, description)

        # Same "never resurrect a ghost resource after a terminal failure"
        # guard Character creation uses.
        current_status = await asyncio.to_thread(get_prostudio_generation_job_status, job_id)
        if current_status in {"failed", "cancelled", "canceled"}:
            prostudio_debug("OBJECT_RESOURCE_SAVE_SKIPPED_TERMINAL_JOB", job_id=job_id, status=current_status)
            return
        await _record_object_job_progress(job_id, "saving", reference_url=reference_url)

        stable_id = uuid4().hex
        # referenceImages/sourceImages/photos are deliberately NOT set here -
        # save_prostudio_resource() picks its persisted photos_json from
        # sourceImages > source_images > photos > referenceImages (in that
        # priority order), so leaving only referenceImages = [reference_url]
        # is what guarantees exactly one persisted/reloaded reference, ever -
        # the raw upload only ever lives in originalSourceImages metadata.
        resource = {
            "id": f"custom_object_{stable_id}",
            "resource_type": "object",
            "name": name,
            "description": description,
            "objectPrompt": object_prompt,
            "prompt": object_prompt,
            "previewUrl": reference_url,
            "primaryReferenceUrl": reference_url,
            "referenceImages": [reference_url],
            "originalSourceImages": photos,
            "provider": "openai",
            "ai_provider": "openai",
            "model": "gpt-image-2",
            "ai_model": "gpt-image-2",
            "type": "custom",
            "status": "ready",
            "created_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        }
        save_started = time.monotonic()
        prostudio_debug("OBJECT_RESOURCE_SAVE_START", job_id=job_id)
        saved = await asyncio.to_thread(save_prostudio_resource, telegram_id, resource)
        prostudio_debug("OBJECT_RESOURCE_SAVE_DONE", job_id=job_id, elapsed_seconds=round(time.monotonic() - save_started, 3))
        final_resource = {**resource, **saved}
        result = {
            "ok": True,
            "type": "object",
            "object_id": final_resource["id"],
            "resource": final_resource,
            "result_url": final_resource["previewUrl"],
        }
        if not await _settle_creation_job(job_id, telegram_id, object_creation_settled_credits(credits, vision_usage), "object_creation", result):
            raise RuntimeError("object_creation_billing_failed")
        await asyncio.to_thread(update_prostudio_generation_job, job_id, "completed", result)
        prostudio_debug("OBJECT_JOB_COMPLETED", job_id=job_id, elapsed_seconds=round(time.monotonic() - job_started, 3))
    except Exception as exc:
        prostudio_error("OBJECT_CREATE_FAILED", exc, telegram_id=telegram_id, name=name, job_id=job_id)
        error_payload = classify_openai_creation_error(
            str(exc),
            "Не удалось сгенерировать референс объекта: запрос был отклонён системой безопасности провайдера изображений. Попробуйте другое фото или измените описание объекта.",
        )
        await asyncio.to_thread(update_prostudio_generation_job, job_id, "failed", None, error_payload)
    finally:
        finished_event.set()
        await asyncio.gather(heartbeat_task, return_exceptions=True)


@app.post("/api/public/prostudio/object")
async def public_prostudio_create_object(request: Request):
    data = await request.json()
    telegram_id = int(data.get("telegram_id") or 0)
    name = str(data.get("name") or "").strip()
    description = str(data.get("description") or "").strip()
    # Object creation: exactly one source photo - more than one uploaded is
    # capped to the first, never rejected outright (same contract as
    # Character creation's own single-photo cap).
    photos = (_json_list(data.get("photos")) or _json_list(data.get("referenceImages")))[:1]
    if not telegram_id:
        return telegram_id_required_response()
    if not name:
        return JSONResponse({"ok": False, "error": "name_required"}, status_code=400)
    if not photos:
        return JSONResponse({"ok": False, "error": "reference_image_required"}, status_code=400)
    # Dedicated per-user abuse guard, checked only here - at the exact
    # moment a new Object Creation job is submitted - never on polling/
    # status-read/jobs-list below. See services/request_limits.py's
    # check_object_creation_quota() for why this is its own bucket rather
    # than reusing the shared COSTLY 'provider' quota. Raises
    # SecurityError('object_creation_rate_limited', 429) when exceeded,
    # caught by the global SecurityError handler below.
    await check_object_creation_request_quota(telegram_id)
    credits = object_creation_price(name, description)
    if credits <= 0:
        return unpriced_helper_response("object_creation")
    try:
        job_id = await asyncio.to_thread(create_object_creation_job, telegram_id, name, description, photos, credits)
    except SecurityError:
        raise
    except Exception as exc:
        prostudio_error("OBJECT_JOB_CREATE_FAILED", exc, telegram_id=telegram_id, name=name)
        return JSONResponse({"ok": False, "error": str(exc)[:1200]}, status_code=502)
    task = asyncio.create_task(_run_object_creation_job(job_id, telegram_id, name, description, photos, credits))
    background_tasks = getattr(app.state, "background_tasks", None)
    if isinstance(background_tasks, list):
        background_tasks.append(task)
    return JSONResponse({"ok": True, "job_id": job_id, "status": "processing"}, status_code=202)


@app.get("/api/public/prostudio/object-creation-jobs")
async def public_prostudio_object_creation_jobs(telegram_id: int = 0):
    if not telegram_id:
        return telegram_id_required_response()
    if not DATABASE_URL:
        return {"ok": True, "jobs": []}

    def _sync():
        ensure_prostudio_table()
        with db_connection(DATABASE_URL) as conn:
            cursor = conn.cursor()
            cursor.execute("""
                SELECT id, status, request_json, result_json, error_json, created_at, updated_at
                FROM prostudio_generation_jobs
                WHERE telegram_id = %s AND mode = 'object_creation'
                  AND created_at > NOW() - INTERVAL '24 hours'
                ORDER BY created_at DESC
                LIMIT 20
            """, (telegram_id,))
            rows = cursor.fetchall()
            cursor.close()
        return rows

    try:
        rows = await asyncio.to_thread(_sync)
    except Exception as exc:
        prostudio_error("OBJECT_JOBS_LIST_FAILED", exc, telegram_id=telegram_id)
        return JSONResponse({"ok": False, "error": "object_jobs_list_failed"}, status_code=500)

    jobs = []
    for row in rows:
        job_id, status, request_json, result_json, error_json, created_at, updated_at = row
        request = _json_obj(request_json)
        result = _json_obj(result_json) if result_json else None
        error = _public_error_json(_json_obj(error_json))
        if error:
            normalized_error = user_generation_error_text(error.get("error") or error.get("message") or error)
            error["error"] = normalized_error
            error["message"] = normalized_error
        jobs.append({
            "job_id": job_id,
            "status": status,
            "name": request.get("name") or "",
            "description": request.get("description") or "",
            "photos": _json_list(request.get("photos")),
            "created_at": _to_iso(created_at),
            "updated_at": _to_iso(updated_at),
            "result": result or None,
            "error": error or None,
        })
    return {"ok": True, "jobs": jobs}


def _load_character_resource(telegram_id: int, resource_id: str) -> Optional[dict]:
    # Single-resource counterpart to load_prostudio_resources() (which
    # returns every character/object/voice at once) - used by the
    # reference-library endpoints below, which only ever need one specific
    # Character, scoped to its owner.
    if not DATABASE_URL or not telegram_id or not resource_id:
        return None
    with db_connection(DATABASE_URL) as conn:
        cursor = conn.cursor()
        cursor.execute(
            "SELECT name, description, gender, preview_url, photos_json, metadata_json, status "
            "FROM prostudio_resources WHERE id = %s AND telegram_id = %s AND resource_type = 'character'",
            (resource_id, telegram_id),
        )
        row = cursor.fetchone()
        cursor.close()
    if not row:
        return None
    name, description, gender, preview, photos_json, metadata_json, status = row
    resource = _json_obj(metadata_json)
    resource.update({
        "id": resource_id,
        "name": name or resource.get("name") or "",
        "description": description or resource.get("description") or "",
        "gender": gender or resource.get("gender") or "",
        "status": status or resource.get("status") or "ready",
        "resource_type": "character",
    })
    if not resource.get("referenceLibrary"):
        photos = _json_list(photos_json)
        avatar = resource.get("avatarUrl") or preview or ""
        resource["referenceLibrary"] = [
            {"id": f"{resource_id}_ref_{index}", "url": url, "role": "Additional"}
            for index, url in enumerate(([avatar] + photos) if avatar else photos) if url
        ]
    return resource


# =====================================================
# API ENDPOINT: public_prostudio_add_character_reference
# Expandable Character reference library (Character System V2): appends a
# new reference image to an existing Character - either a freshly uploaded
# photo or, per the "Add generated image to Character References" product
# rule, a generated result the user explicitly chose to add. A generated
# image never joins the library on its own; this endpoint only runs when
# the frontend calls it from an explicit user action.
# =====================================================
@app.post("/api/public/prostudio/character/{resource_id}/references")
async def public_prostudio_add_character_reference(resource_id: str, request: Request):
    data = await request.json()
    telegram_id = int(data.get("telegram_id") or 0)
    url = str(data.get("url") or "").strip()
    role = str(data.get("role") or "Additional").strip() or "Additional"
    set_primary = bool(data.get("set_primary") or data.get("setPrimary"))
    if not telegram_id:
        return telegram_id_required_response()
    if not url:
        return JSONResponse({"ok": False, "error": "reference_url_required"}, status_code=400)
    resource = await asyncio.to_thread(_load_character_resource, telegram_id, resource_id)
    if not resource:
        return JSONResponse({"ok": False, "error": "character_not_found"}, status_code=404)
    library = resource.get("referenceLibrary") or []
    if any(entry.get("url") == url for entry in library):
        return JSONResponse({"ok": False, "error": "reference_already_in_library"}, status_code=409)
    new_entry = {"id": uuid4().hex, "url": url, "role": role, "added_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())}
    library.append(new_entry)
    resource["referenceLibrary"] = library
    resource["referenceImages"] = [entry["url"] for entry in library if entry["url"] != resource.get("primaryReferenceUrl")]
    if set_primary:
        resource["primaryReferenceUrl"] = url
        resource["avatarUrl"] = url
        resource["previewUrl"] = url
    saved = await asyncio.to_thread(save_prostudio_resource, telegram_id, resource)
    return {"ok": True, "resource": {**resource, **saved}, "reference": new_entry}


# =====================================================
# API ENDPOINT: public_prostudio_set_character_primary_reference
# Lets the user designate which library entry is the Character's Primary
# Reference (used by default whenever the Character is selected, per the
# "normal user must not be forced to select references every time" rule).
# =====================================================
@app.post("/api/public/prostudio/character/{resource_id}/primary-reference")
async def public_prostudio_set_character_primary_reference(resource_id: str, request: Request):
    data = await request.json()
    telegram_id = int(data.get("telegram_id") or 0)
    reference_id = str(data.get("reference_id") or data.get("referenceId") or "").strip()
    if not telegram_id:
        return telegram_id_required_response()
    resource = await asyncio.to_thread(_load_character_resource, telegram_id, resource_id)
    if not resource:
        return JSONResponse({"ok": False, "error": "character_not_found"}, status_code=404)
    library = resource.get("referenceLibrary") or []
    match = next((entry for entry in library if entry.get("id") == reference_id), None)
    if not match:
        return JSONResponse({"ok": False, "error": "reference_not_found"}, status_code=404)
    resource["primaryReferenceUrl"] = match["url"]
    resource["avatarUrl"] = match["url"]
    resource["previewUrl"] = match["url"]
    saved = await asyncio.to_thread(save_prostudio_resource, telegram_id, resource)
    return {"ok": True, "resource": {**resource, **saved}}


# =====================================================
# API ENDPOINT: public_prostudio_character_history
# "Generated with this Character" - every generation is private to the
# user who ran it (telegram_id-scoped) even for a shared/built-in
# Character, so this never exposes another user's generations and a
# shared Character's own canonical record is never mutated by it.
# =====================================================
@app.get("/api/public/prostudio/character/{resource_id}/history")
async def public_prostudio_character_history(resource_id: str, telegram_id: int = 0, limit: int = 50):
    if not telegram_id:
        return telegram_id_required_response()
    if not DATABASE_URL:
        return {"ok": True, "items": []}
    safe_limit = max(1, min(int(limit or 50), 200))

    def _fetch_rows():
        ensure_prostudio_table()
        with db_connection(DATABASE_URL) as conn:
            cursor = conn.cursor()
            cursor.execute("""
                SELECT id, media_url, prompt, model, created_at
                FROM prostudio_character_history
                WHERE telegram_id = %s AND character_id = %s
                ORDER BY created_at DESC, id DESC
                LIMIT %s
            """, (telegram_id, resource_id, safe_limit))
            rows = cursor.fetchall()
            cursor.close()
        return rows

    try:
        rows = await asyncio.to_thread(_fetch_rows)
    except Exception as exc:
        print("PROSTUDIO CHARACTER HISTORY FAILED:", exc)
        return {"ok": True, "items": []}

    items = []
    for entry_id, media_url, prompt, model, created_at in rows:
        items.append({
            "id": entry_id,
            "prompt": prompt or "",
            "model": model or "",
            "media_url": media_url or "",
            "media_urls": [media_url] if media_url else [],
            "preview_url": media_url or "",
            "created_at": created_at.isoformat() if hasattr(created_at, "isoformat") else created_at,
        })
    return {"ok": True, "items": items, "character_id": resource_id}


# =====================================================
# API ENDPOINT: public_prostudio_delete_character_history_entry
# Deletes a single "Generated with this Character" History row - only the
# row itself. Never touches the generated media file in R2 (media_url is
# simply a reference, not something this table owns) and never touches the
# Pro Studio generation/job that originally produced it - prostudio_messages/
# prostudio_generation_jobs are untouched. Scoped by history_entry_id +
# character_id + telegram_id together, so a DELETE naming another user's
# telegram_id (or a history_id that belongs to a different Character/user)
# simply matches zero rows rather than deleting anything.
# =====================================================
@app.delete("/api/public/prostudio/character/{resource_id}/history/{history_id}")
async def public_prostudio_delete_character_history_entry(resource_id: str, history_id: str, telegram_id: int = 0):
    if not telegram_id:
        return telegram_id_required_response()
    if not DATABASE_URL:
        return {"ok": True, "deleted": False}

    def _sync():
        ensure_prostudio_table()
        with db_connection(DATABASE_URL) as conn:
            cursor = conn.cursor()
            cursor.execute(
                "DELETE FROM prostudio_character_history WHERE id = %s AND character_id = %s AND telegram_id = %s",
                (history_id, resource_id, telegram_id),
            )
            deleted = cursor.rowcount > 0
            cursor.close()
        return deleted

    try:
        deleted = await asyncio.to_thread(_sync)
        return {"ok": True, "deleted": deleted, "id": history_id}
    except Exception as exc:
        prostudio_error("CHARACTER_HISTORY_DELETE_FAILED", exc, resource_id=resource_id, history_id=history_id, telegram_id=telegram_id)
        return JSONResponse({"ok": False, "error": "history_delete_failed"}, status_code=500)


# =====================================================
# API ENDPOINT: public_prostudio_delete_resource
# Удаляет только пользовательский ресурс персонажа/объекта из каталога Mini App.
# =====================================================
@app.delete("/api/public/prostudio/resources/{resource_id}")
async def public_prostudio_delete_resource(resource_id: str, telegram_id: int = 0):
    if not telegram_id:
        return telegram_id_required_response()
    if not resource_id or not resource_id.startswith("custom_"):
        return JSONResponse({"ok": False, "error": "only_custom_resources_can_be_deleted"}, status_code=400)
    if not DATABASE_URL:
        return {"ok": True, "deleted": False, "resource_id": resource_id}

    def _sync():
        ensure_prostudio_table()
        with db_connection(DATABASE_URL) as conn:
            cursor = conn.cursor()
            cursor.execute(
                "DELETE FROM prostudio_resources WHERE id = %s AND telegram_id = %s",
                (resource_id, telegram_id),
            )
            deleted = cursor.rowcount > 0
            # Only a Character accumulates prostudio_character_history rows
            # (Objects/voices never do - see record_character_generation_history),
            # so this cleanup only ever runs for a custom_character_ id, and
            # only once the resource itself was actually deleted. Scoped to
            # this same telegram_id, so one user deleting their Character
            # can never touch another user's history rows for a
            # differently-owned Character that happens to reuse the id
            # (ids are globally unique uuid4 hex already, but the WHERE
            # clause makes the ownership boundary explicit regardless).
            if deleted and resource_id.startswith("custom_character_"):
                cursor.execute(
                    "DELETE FROM prostudio_character_history WHERE character_id = %s AND telegram_id = %s",
                    (resource_id, telegram_id),
                )
            cursor.close()
        if deleted:
            log_user_event(telegram_id, "miniapp", "resource", "resource_deleted", {"id": resource_id})
        return deleted

    try:
        deleted = await asyncio.to_thread(_sync)
        return {"ok": True, "deleted": deleted, "resource_id": resource_id}
    except Exception as exc:
        prostudio_error("RESOURCE_DELETE_FAILED", exc, resource_id=resource_id, telegram_id=telegram_id)
        return JSONResponse({"ok": False, "error": "resource_delete_failed"}, status_code=500)


# =====================================================
# API ENDPOINT: public_prostudio_upload_media
# Принимает HTTP-запрос от Mini App или Telegram Bot.
# Маршрут FastAPI: @app.post("/api/public/prostudio/upload-media")
# Проверяет входные данные, работает с базой/провайдерами и возвращает JSON-ответ фронтенду.
# =====================================================
try:
    import pillow_heif as _pillow_heif
    _pillow_heif.register_heif_opener()
    HEIC_UPLOAD_SUPPORTED = True
except Exception:
    # Degrade gracefully rather than crash startup if the dependency is ever
    # missing in a given deploy - HEIC/HEIF simply falls back to the
    # pre-existing "unsupported_extension" 400 below.
    HEIC_UPLOAD_SUPPORTED = False


def _convert_heic_to_jpeg(content):
    # iPhones default to HEIC and Pro Studio's own file picker lists
    # .heic/.heif as selectable (openNativeFilePicker in cabinet.js), but no
    # AI provider or browser <img> tag reliably consumes HEIC. Decode once
    # here and store a normal JPEG instead - everything downstream
    # (validated_upload_type's dimension/format check, storage, the
    # generation reference pipeline) then sees a plain, already-supported
    # image the same as any other upload.
    from PIL import Image
    import io
    with Image.open(io.BytesIO(content)) as img:
        buffer = io.BytesIO()
        img.convert("RGB").save(buffer, format="JPEG", quality=92)
        return buffer.getvalue()


def _probe_image_dimensions(content):
    # Best-effort only, for the UPLOAD_MEDIA_REJECTED diagnostic below - never
    # raises and never gates acceptance (that stays validated_upload_type's
    # job). A corrupt/undecodable upload simply logs width/height as None.
    try:
        from PIL import Image
        import io
        with Image.open(io.BytesIO(content)) as img:
            return img.width, img.height
    except Exception:
        return None, None


def _log_upload_media_rejected(reason, media_kind, suffix, mime, size_bytes, status, width=None, height=None):
    # Deliberately excludes filename/URLs/auth - safe to leave in production
    # logs. This is the only place upload-media rejections were observable
    # from (the shared SecurityError handler that a couple of these branches
    # raise through just returns bare JSON with no server-side log line at
    # all), so a 400 here was previously undiagnosable without frontend
    # network-tab access.
    if media_kind == "video" or str(mime or "").startswith("video/"):
        video_probe.log_video_reference_event(
            "upload_media", meta={"bytes": size_bytes, "extension": suffix, "mime": mime, "width": width, "height": height},
            validation=reason, inputs={"video": True},
        )
    print("UPLOAD_MEDIA_REJECTED:", {
        "reason": reason,
        "kind": media_kind,
        "mime": mime,
        "bytes": size_bytes,
        "suffix": suffix,
        "width": width,
        "height": height,
        "status": status,
    })


# Telegram bot inputs (photos, reference videos) re-hosted in SYLVEX storage,
# so providers receive a signed SYLVEX URL and never a Telegram file URL
# (those embed the bot token). The bot authenticates with a shared secret
# header; without TELEGRAM_MEDIA_SERVICE_TOKEN configured the route refuses.
TELEGRAM_MEDIA_SERVICE_TOKEN = os.getenv("TELEGRAM_MEDIA_SERVICE_TOKEN", "").strip()
TELEGRAM_MEDIA_EXTENSIONS = {".jpg", ".jpeg", ".png", ".webp", ".mp4", ".mov", ".m4v", ".webm"}
TELEGRAM_MEDIA_MAX_BYTES = 25 * 1024 * 1024  # Bot API downloads stop at 20 MB


def _prostudio_upload_spec(filename: str, content_type: str, kind: str) -> dict:
    media_kind = (kind or "").strip().lower()
    clean_name = pathlib.Path(filename or "").name
    suffix = pathlib.Path(clean_name).suffix.lower()
    mime = (content_type or "").lower().split(";", 1)[0].strip()
    is_video = media_kind == "video" or mime.startswith("video/")
    is_audio = media_kind == "audio" or mime.startswith("audio/")
    is_file = media_kind in {"file", "document"} or mime.startswith(("text/", "application/pdf", "application/json", "application/msword", "application/vnd.openxmlformats-officedocument"))
    if is_video:
        allowed_exts = {".mp4", ".mov", ".m4v", ".webm", ".mpeg", ".mpg", ".avi", ".flv", ".wmv", ".3gp"}
    elif is_audio:
        allowed_exts = {".mp3", ".wav", ".m4a", ".aac", ".ogg", ".oga", ".webm", ".flac", ".aiff", ".aif"}
    elif is_file:
        allowed_exts = {".txt", ".md", ".json", ".csv", ".pdf", ".doc", ".docx"}
    else:
        allowed_exts = {".jpg", ".jpeg", ".png", ".webp"}
        if HEIC_UPLOAD_SUPPORTED:
            allowed_exts |= {".heic", ".heif"}
    return {
        "media_kind": media_kind, "filename": clean_name, "suffix": suffix,
        "content_type": mime, "is_video": is_video, "is_audio": is_audio,
        "is_file": is_file, "allowed_exts": allowed_exts,
        "max_bytes": 200 * 1024 * 1024 if is_video else 50 * 1024 * 1024,
        "uploaded_kind": "video" if is_video else ("audio" if is_audio else ("file" if is_file else "image")),
        "folder": "documents" if is_file else "video-inputs",
    }


def _direct_upload_capability(owner: int, key: str, size: int, content_type: str, expires: int) -> str:
    message = f"{int(owner)}:{key}:{int(size)}:{content_type}:{int(expires)}"
    return hmac.new(signing_key(), message.encode(), hashlib.sha256).hexdigest()


def _copy_storage_object_to_path(key: str, destination: pathlib.Path, max_bytes: int) -> int:
    body, _, _ = storage_get_object(key)
    copied = 0
    with destination.open("wb") as output:
        for chunk in storage_iter_object(body, max_bytes=max_bytes + 1):
            copied += len(chunk)
            output.write(chunk)
    return copied


@app.post("/api/public/prostudio/upload-media/init")
async def public_prostudio_upload_media_init(request: Request):
    owner = _core_account_owner(request)
    data = await request.json()
    spec = _prostudio_upload_spec(data.get("filename"), data.get("content_type"), data.get("kind"))
    size = int(data.get("size") or 0)
    if spec["suffix"] not in spec["allowed_exts"] or size <= 0 or size > spec["max_bytes"]:
        return JSONResponse({"ok": False, "error": "invalid_upload"}, status_code=400)
    # HEIC requires server conversion and therefore stays on the compatible
    # multipart route. Everything already provider-compatible goes directly.
    if not storage_direct_upload_enabled() or spec["suffix"] in {".heic", ".heif"}:
        return {"ok": True, "direct": False}
    key = generated_key(spec["folder"], f"{uuid4().hex}{spec['suffix']}")
    upload_url = await asyncio.to_thread(storage_presigned_put_url, key, spec["content_type"] or "application/octet-stream")
    if not upload_url:
        return {"ok": True, "direct": False}
    expires = int(time.time()) + 900
    token = _direct_upload_capability(owner, key, size, spec["content_type"], expires)
    return {
        "ok": True, "direct": True, "upload_url": upload_url, "object_key": key,
        "expires": expires, "upload_token": token,
    }


@app.post("/api/public/prostudio/upload-media/complete")
async def public_prostudio_upload_media_complete(request: Request):
    owner = _core_account_owner(request)
    data = await request.json()
    key = str(data.get("object_key") or "")
    size = int(data.get("size") or 0)
    expires = int(data.get("expires") or 0)
    token = str(data.get("upload_token") or "")
    spec = _prostudio_upload_spec(data.get("filename"), data.get("content_type"), data.get("kind"))
    expected = _direct_upload_capability(owner, key, size, spec["content_type"], expires)
    if expires < time.time() or not token or not hmac.compare_digest(token, expected):
        raise SecurityError("invalid_upload_capability", 403)
    expected_prefix = generated_key(spec["folder"], "placeholder").rsplit("/", 1)[0] + "/"
    if not key.startswith(expected_prefix) or spec["suffix"] not in spec["allowed_exts"] or size <= 0 or size > spec["max_bytes"]:
        raise SecurityError("invalid_upload", 400)
    temp_path = None
    try:
        head = await asyncio.to_thread(storage_head_object, key)
        if int(head.get("size") or 0) != size:
            raise SecurityError("upload_size_mismatch", 400)
        with tempfile.NamedTemporaryFile(prefix="sylvex-upload-verify-", suffix=spec["suffix"], delete=False) as temp_file:
            temp_path = pathlib.Path(temp_file.name)
        copied = await asyncio.to_thread(_copy_storage_object_to_path, key, temp_path, spec["max_bytes"])
        if copied != size:
            raise SecurityError("upload_size_mismatch", 400)
        validated_type = await asyncio.to_thread(validated_upload_path, temp_path, spec["suffix"])
        video_meta = await asyncio.to_thread(video_probe.probe_video_file, temp_path, spec["suffix"], size) if spec["uploaded_kind"] == "video" else None
        if video_meta:
            await asyncio.to_thread(
                storage_put_bytes, video_probe.encode_sidecar(video_meta),
                video_probe.sidecar_key(key), "application/json",
            )
        public_url = await asyncio.to_thread(storage_register_existing_object, key, validated_type, size)
        return {
            "ok": True, "kind": spec["uploaded_kind"], "url": public_url,
            "path": key, "content_type": validated_type, "bytes": size,
            "video_meta": video_meta,
        }
    except Exception:
        await asyncio.to_thread(storage_delete, key)
        raise
    finally:
        if temp_path is not None:
            temp_path.unlink(missing_ok=True)


@app.post("/api/internal/telegram-media")
async def internal_telegram_media(request: Request):
    presented = str(request.headers.get("x-sylvex-media-token") or "").strip()
    if not TELEGRAM_MEDIA_SERVICE_TOKEN:
        return JSONResponse({"ok": False, "error": "telegram_media_not_configured"}, status_code=503)
    if not presented or not hmac.compare_digest(presented, TELEGRAM_MEDIA_SERVICE_TOKEN):
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    form = await request.form()
    file = form.get("file")
    if not file or not hasattr(file, "read"):
        return JSONResponse({"ok": False, "error": "file_required"}, status_code=400)
    suffix = pathlib.Path(getattr(file, "filename", "") or "").suffix.lower()
    if suffix not in TELEGRAM_MEDIA_EXTENSIONS:
        return JSONResponse({"ok": False, "error": "unsupported_media_format"}, status_code=400)
    content = await read_upload(file, TELEGRAM_MEDIA_MAX_BYTES)
    if not content:
        return JSONResponse({"ok": False, "error": "empty_file"}, status_code=400)
    content_type = validated_upload_type(content, suffix)
    key = generated_key("telegram-inputs", f"{uuid4().hex}{suffix}")
    url = await asyncio.to_thread(storage_put_bytes, content, key, content_type)
    print("TELEGRAM MEDIA REHOSTED:", {"key": key, "content_type": content_type, "bytes": len(content)})
    return {"ok": True, "url": url, "content_type": content_type, "bytes": len(content)}


# =====================================================
# ЗАГРУЗКА ФАЙЛОВ: public_prostudio_upload_media
# Получает файл или ссылку, приводит её к безопасному формату и передаёт дальше в генерацию или сохранение.
# =====================================================
@app.post("/api/public/prostudio/upload-media")
async def public_prostudio_upload_media(file: UploadFile = File(...), kind: str = "image", request: Request = None):
    if request is not None:
        _core_account_owner(request)
    spec = _prostudio_upload_spec(file.filename, file.content_type, kind)
    media_kind, filename, suffix, content_type = spec["media_kind"], spec["filename"], spec["suffix"], spec["content_type"]
    is_video, is_audio, is_file = spec["is_video"], spec["is_audio"], spec["is_file"]
    allowed_exts, max_bytes = spec["allowed_exts"], spec["max_bytes"]

    if suffix not in allowed_exts:
        _log_upload_media_rejected("unsupported_extension", media_kind, suffix, content_type, 0, 400)
        return JSONResponse({"ok": False, "error": "Unsupported media format"}, status_code=400)

    try:
        content = await read_upload(file, max_bytes)
    except SecurityError as exc:
        _log_upload_media_rejected(exc.code, media_kind, suffix, content_type, max_bytes, exc.status)
        raise
    if not content:
        _log_upload_media_rejected("empty_file", media_kind, suffix, content_type, 0, 400)
        return JSONResponse({"ok": False, "error": "Empty file"}, status_code=400)
    if suffix in {".heic", ".heif"}:
        try:
            content = _convert_heic_to_jpeg(content)
        except Exception:
            _log_upload_media_rejected("heic_decode_failed", media_kind, suffix, content_type, len(content), 400)
            return JSONResponse({"ok": False, "error": "Could not read this HEIC photo"}, status_code=400)
        suffix = ".jpg"
    try:
        content_type = validated_upload_type(content, suffix)
    except SecurityError as exc:
        width, height = (_probe_image_dimensions(content) if suffix in {".jpg", ".jpeg", ".png", ".webp"} else (None, None))
        _log_upload_media_rejected(exc.code, media_kind, suffix, content_type, len(content), exc.status, width, height)
        raise
    if len(content) > max_bytes:
        _log_upload_media_rejected("file_too_large", media_kind, suffix, content_type, len(content), 400)
        return JSONResponse({"ok": False, "error": "File is too large"}, status_code=400)

    stored_name = f"{uuid4().hex}{suffix}"
    public_folder = spec["folder"]
    public_path = generated_key(public_folder, stored_name)
    public_url = storage_put_bytes(content, public_path, content_type)
    uploaded_kind = spec["uploaded_kind"]
    video_meta = None
    if uploaded_kind == "video":
        # Duration/dimensions for the per-model reference-video check at
        # generation time (validate_reference_video_media). A video ffmpeg
        # cannot read is still accepted, as before.
        video_meta = await asyncio.to_thread(video_probe.probe_video_bytes, content, suffix)
        if video_meta:
            try:
                await asyncio.to_thread(
                    storage_put_bytes, video_probe.encode_sidecar(video_meta),
                    video_probe.sidecar_key(public_path), "application/json",
                )
            except Exception as exc:
                print("PROSTUDIO VIDEO PROBE SIDECAR FAILED:", type(exc).__name__)
    print("PROSTUDIO MEDIA UPLOAD:", {
        "kind": uploaded_kind,
        "filename": filename,
        "content_type": content_type,
        "bytes": len(content),
        "url": public_url,
        "video_meta": video_meta,
    })
    return {
        "ok": True,
        "kind": uploaded_kind,
        "url": public_url,
        "path": public_path,
        "inline_url": (
            f"data:{content_type or 'image/png'};base64,{base64.b64encode(content).decode('ascii')}"
            if uploaded_kind == "image" and len(content) <= 12 * 1024 * 1024
            else ""
        ),
        "content_type": content_type,
        "bytes": len(content),
        "video_meta": video_meta,
    }


