# =====================================================
# API ENDPOINT: public_telegram_sync
# Принимает HTTP-запрос от Mini App или Telegram Bot.
# Маршрут FastAPI: @app.post("/api/public/telegram/sync")
# Проверяет входные данные, работает с базой/провайдерами и возвращает JSON-ответ фронтенду.
# =====================================================
@app.post("/api/public/telegram/sync")
# =====================================================
# СИНХРОНИЗАЦИЯ С TELEGRAM: public_telegram_sync
# Отправляет готовый результат или статус в Telegram Bot и сохраняет признак отправки в metadata карточки.
# =====================================================
async def public_telegram_sync(request: Request):
    payload = await request.json()
    try:
        signed = validated_user(payload.get("initData") or "", TELEGRAM_AUTH_TOKENS)
        user_data = fallback_public_user({"initDataUnsafe": {"user": signed}})
        try:
            user = await asyncio.to_thread(sync_user_to_db, user_data)
        except Exception:
            return JSONResponse({"ok": False, "error": "user_sync_unavailable"}, status_code=503)
        return {"ok": True, "user": user}
    except SecurityError:
        # initData went stale mid-session (Mini App open longer than
        # TELEGRAM_AUTH_MAX_AGE_SECONDS) - the middleware already
        # re-authenticated this exact request through the sliding
        # tg-session cookie fallback (see services/security.py), so
        # request.state.telegram_id is still trustworthy even though there's
        # no fresh Telegram profile payload to sync. Return the already-
        # stored record unchanged rather than failing the whole Mini App.
        telegram_id = int(getattr(request.state, "telegram_id", 0) or 0)
        if not telegram_id:
            raise HTTPException(status_code=401, detail="expired_or_invalid_telegram_user")
        try:
            user = await asyncio.to_thread(get_user_state, telegram_id)
        except Exception:
            return JSONResponse({"ok": False, "error": "user_sync_unavailable"}, status_code=503)
        return {"ok": True, "user": user}


# =====================================================
# WEB SESSION: independent SYLVEX Website/Browser account
#
# The website is a second client of this same backend (see
# sylvex-website/backend/WEB_API_CONTRACT.md). Every route below
# authenticates with a browser session cookie (or a mailed one-time token),
# never Telegram initData. See services/account_identity.py for the account
# model: a website registration gets its own real `sylvex_accounts.account_id`
# (the "SYLVEX ID"), independent of Telegram. The session cookie carries
# only that account_id. Legacy business tables retain an internal numeric
# storage key, but it is resolved inside the Core and is never returned as
# client identity or required in a Website/Browser request.
# =====================================================
# Optional: scope the session cookie to the whole registrable domain (e.g.
# ".sylvex.ai") instead of the default host-only cookie (api.sylvex.ai
# only). Not required for the website (api.sylvex.ai) and the API to share
# the cookie - same-site is enough for that - but makes it explicit and
# would let a future same-domain subdomain reuse the same session. Unset by
# default (host-only), matching every other optional env var here.
WEB_SESSION_COOKIE_DOMAIN = os.getenv("WEB_SESSION_COOKIE_DOMAIN", "").strip() or None


async def _set_web_session_cookie(response, account_id: int, generation: int = None):
    # generation=None (the common case: register/login/OAuth/telegram-
    # confirm) fetches the account's current session-generation counter -
    # almost always 0, since nothing has ever revoked this account's
    # sessions. The one caller that already knows the freshly-bumped value
    # (password-change, right after calling revoke_web_sessions) passes it
    # explicitly instead, so the reissued cookie is minted from that exact
    # value rather than a second, separately-timed read of it - see
    # services/security.py's module comment on COOKIE-2 for why that
    # distinction is what actually closes the race, not just a clock with
    # finer resolution.
    if generation is None:
        generation = await asyncio.to_thread(current_web_session_generation, account_id)
    token = create_web_session_token(account_id, generation)
    response.set_cookie(
        WEB_SESSION_COOKIE, token, max_age=WEB_SESSION_MAX_AGE,
        httponly=True, secure=True, samesite="none", path="/",
        domain=WEB_SESSION_COOKIE_DOMAIN,
    )


async def _web_session_account_id(request: Request):
    token = request.cookies.get(WEB_SESSION_COOKIE)
    if not token:
        return None
    try:
        account_id, generation = verify_web_session_token(token)
    except SecurityError:
        return None
    # COOKIE-2: a token whose signature/expiry still check out can still be
    # a stale copy of one invalidated since by logout/password-change/
    # account-delete (see revoke_web_sessions) - reject it the same way an
    # expired one already is, rather than trusting the signature alone.
    # Plain integer comparison against the account's current generation -
    # no clock involved, so there is no ambiguous-ordering window (see
    # services/security.py's module comment on COOKIE-2).
    current_generation = await asyncio.to_thread(current_web_session_generation, account_id)
    if generation < current_generation:
        return None
    return account_id


def _web_session_payload(account_id: int) -> dict:
    payload_started = time.monotonic()
    summary_start = time.monotonic()
    summary = account_identity_service.get_account_summary(DATABASE_URL, account_id)
    print("SESSION_ME_TIMING:", {"stage": "get_account_summary", "ms": round((time.monotonic() - summary_start) * 1000), "account_id": account_id})
    if not summary:
        return {"authenticated": False}
    state_start = time.monotonic()
    state = get_user_state(summary["active_telegram_id"]) or {}
    print("SESSION_ME_TIMING:", {"stage": "get_user_state", "ms": round((time.monotonic() - state_start) * 1000), "account_id": account_id, "telegram_id": summary["active_telegram_id"]})
    print("SESSION_ME_TIMING:", {"stage": "total", "ms": round((time.monotonic() - payload_started) * 1000), "account_id": account_id})
    created_at = state.get("created_at")
    if hasattr(created_at, "strftime"):
        member_since = created_at.strftime("%Y-%m")
    elif isinstance(created_at, str) and len(created_at) >= 7 and created_at[4] == "-":
        member_since = created_at[:7]  # users.created_at is TEXT in production
    else:
        member_since = None
    return {
        "authenticated": True,
        "account_id": int(account_id),
        "sylvex_user_id": int(account_id),
        "identity_type": "web_account",
        "display_name": state.get("display_name") or state.get("first_name"),
        "first_name": state.get("first_name"),
        "username": state.get("username"),
        "avatar_url": state.get("custom_avatar_url"),
        "balance": state.get("balance", 0),
        "subscription_plan": state.get("subscription_plan"),
        "generations_count": state.get("generations_count", 0),
        "member_since": member_since,
        "email": summary.get("email"),
        "email_verified": bool(summary.get("email_verified")),
        "has_email": bool(summary.get("has_email")),
        "has_password": bool(summary.get("has_password")),
        "oauth": summary.get("oauth") or {},
    }


@app.get("/api/web/auth/config")
async def web_auth_config():
    # The static Website can't read Railway env vars directly - this hands
    # it the one value it needs to initialize Google Identity Services.
    # GOOGLE_OAUTH_CLIENT_ID is a public OAuth client identifier (it's sent
    # to Google from the browser on every sign-in), never a secret - do not
    # add anything else here (client secrets, session secrets, API keys).
    google_client_id = os.getenv("GOOGLE_OAUTH_CLIENT_ID", "").strip()
    return {
        "google_client_id": google_client_id,
        "google_enabled": bool(google_client_id),
    }


@app.post("/api/web/auth/telegram")
async def web_auth_telegram(request: Request):
    # "Login with Telegram" only ever signs into an account that has
    # already completed the Connect Telegram merge below - Telegram is
    # never a website *registration* method (spec requirement #1).
    payload = await request.json()
    try:
        signed = await asyncio.to_thread(verify_telegram_login_widget, payload, TELEGRAM_AUTH_TOKENS)
    except SecurityError as exc:
        return JSONResponse({"ok": False, "error": exc.code}, status_code=exc.status)
    if not DATABASE_URL:
        return JSONResponse({"ok": False, "error": "accounts_not_configured"}, status_code=503)
    try:
        account_id = await asyncio.to_thread(account_identity_service.login_via_telegram_widget, DATABASE_URL, signed["id"])
    except AccountError as exc:
        return JSONResponse({"ok": False, "error": exc.code}, status_code=exc.status)
    body = await asyncio.to_thread(_web_session_payload, account_id)
    response = JSONResponse({"ok": True, **body})
    await _set_web_session_cookie(response, account_id)
    return response


