@app.post("/api/web/assistant/message")
async def web_assistant_message(request: Request):
    telegram_id = await _assistant_uid(request)
    body = await request.json()
    content = str((body or {}).get("content") or "").strip()
    conversation_id = str((body or {}).get("conversation_id") or "").strip()
    client_request_id = str((body or {}).get("client_request_id") or "").strip()

    # Attachment contract: the browser sends only an opaque attachment_id
    # (from /api/web/assistant/files or /api/web/assistant/attachments/
    # from-history), never a URL - see _assistant_resolve_attachments below,
    # which is the only place a client-supplied id is turned into a real
    # URL, and only after verifying it belongs to this caller. A free/guest
    # client that never uploaded anything has no id to send, so it instead
    # sends `has_attachment: true` purely to select the Guide FILES
    # template - this flag never causes a fetch or reaches OpenAI.
    raw_ids = (body or {}).get("attachment_ids")
    attachment_ids = [str(x).strip() for x in raw_ids if str(x or "").strip()][:4] if isinstance(raw_ids, list) else []
    single_attachment_id = str((body or {}).get("attachment_id") or "").strip()
    if single_attachment_id and single_attachment_id not in attachment_ids:
        attachment_ids.insert(0, single_attachment_id)
    has_local_attachment = bool((body or {}).get("has_attachment"))

    if not content and not attachment_ids and not has_local_attachment:
        return JSONResponse({"ok": False, "error": "message_required"}, status_code=400)
    if len(content) > 8000:
        return JSONResponse({"ok": False, "error": "message_too_long"}, status_code=413)

    persist = bool(telegram_id and DATABASE_URL)
    connect = _assistant_connect()

    if attachment_ids and not persist:
        # An attachment can only ever belong to a real, authenticated
        # account (uploading requires a subscription) - a guest or a
        # database-less deployment can never own one, so reject outright
        # rather than attempting a lookup that could never succeed.
        return JSONResponse({"ok": False, "error": "attachment_not_found"}, status_code=404)

    resolved_attachments = []
    if persist:
        await asyncio.to_thread(assistant_store.ensure_assistant_tables, connect)
        if attachment_ids:
            resolved_attachments = await _assistant_resolve_attachments(connect, telegram_id, attachment_ids)
            if resolved_attachments is None:
                return JSONResponse({"ok": False, "error": "attachment_not_found"}, status_code=404)
        if conversation_id:
            owner = await asyncio.to_thread(assistant_store.get_conversation_owner, connect, conversation_id)
            if owner != telegram_id:
                raise HTTPException(status_code=404, detail="conversation_not_found")
        else:
            conversation = await asyncio.to_thread(
                assistant_store.create_conversation, connect, telegram_id, assistant_store.derive_title(content),
            )
            conversation_id = conversation["id"]

        # Idempotent-retry short-circuit (double-click / refresh / network
        # replay): never regenerate, and for AI mode never re-call OpenAI,
        # for a client_request_id already answered in this conversation.
        if client_request_id:
            existing_reply = await asyncio.to_thread(
                assistant_store.find_reply_for_client_request_id, connect, conversation_id, client_request_id,
            )
            if existing_reply:
                return {"ok": True, "conversation_id": conversation_id, "replay": True, "message": existing_reply}

    state = await asyncio.to_thread(get_user_state, telegram_id) if telegram_id else {}
    subscriber = state.get("subscription_status") == "active"
    has_attachment = bool(resolved_attachments) or has_local_attachment

    if persist:
        stored_attachments = [
            {"id": a["id"], "name": a["name"], "mime": a["mime"], "kind": a["kind"]} for a in resolved_attachments
        ] or ([{"local": True}] if has_local_attachment else [])
        await asyncio.to_thread(
            assistant_store.add_message, connect, conversation_id, telegram_id, "user", content,
            attachments=stored_attachments, mode=("ai" if subscriber else "guide"),
            client_request_id=client_request_id,
        )

    # ---------- Guide Mode: zero OpenAI cost, deterministic ----------
    if not subscriber:
        if has_attachment:
            # Section 13: a free user's attachment must never reach an AI
            # call, regardless of what they typed alongside it. Guide mode
            # never resolves/fetches attachment content - it only reacts to
            # the fact that one was referenced.
            files_intent = assistant_intent_by_id("FILES")
            reply_text = files_intent["text"]
            actions = list(files_intent["actions"])
            intent_id = "FILES"
        else:
            routed = route_intent(content)
            primary = routed["primary"]
            actions = list(primary.get("actions") or [])
            for extra in routed["secondary"]:
                extra_actions = extra.get("actions") or []
                if extra_actions:
                    actions.append(extra_actions[0])
            reply_text = primary["text"]
            intent_id = primary["id"]

        message = None
        if persist:
            message = await asyncio.to_thread(
                assistant_store.add_message, connect, conversation_id, telegram_id, "assistant", reply_text,
                actions=actions, mode="guide", intent=intent_id,
            )
            await asyncio.to_thread(assistant_store.touch_conversation, connect, conversation_id, reply_text, "guide")
        log_user_event(
            telegram_id=telegram_id or 0, source="assistant", event_type="guide",
            event_name="assistant_intent_detected", payload={"intent": intent_id},
        )
        return {
            "ok": True, "mode": "guide", "conversation_id": conversation_id,
            "message": message or {
                "role": "assistant", "content": reply_text, "actions": actions,
                "intent": intent_id, "status": "completed",
            },
        }

    # ---------- AI Mode: subscriber, streaming ----------
    if not OPENAI_API_KEY:
        return JSONResponse({"ok": False, "error": "ai_not_configured"}, status_code=503)
    await check_request_quota(telegram_id, "/api/web/assistant/message")

    history_messages = []
    if persist:
        conversation = await asyncio.to_thread(assistant_store.get_conversation, connect, conversation_id, telegram_id)
        prior = (conversation.get("messages") or [])[:-1][-20:]  # exclude the user turn just added, bound context
        for item in prior:
            role = "assistant" if item["role"] == "assistant" else "user"
            history_messages.append({"role": role, "content": item["content"]})

    last_user_content = content
    # Only ever built from resolved_attachments (verified, server-owned
    # records) - never from raw request-body fields - so an image_url
    # handed to OpenAI, or a URL this server fetches for document text, can
    # only ever be one of this account's own validated uploads.
    primary_attachment = resolved_attachments[0] if resolved_attachments else None
    if primary_attachment and str(primary_attachment.get("mime") or "").startswith("image/"):
        parts = []
        if content:
            parts.append({"type": "text", "text": content})
        parts.append({"type": "image_url", "image_url": {"url": primary_attachment["url"]}})
        last_user_content = parts
    elif primary_attachment:
        doc_text = await asyncio.to_thread(_assistant_document_text, primary_attachment)
        if doc_text:
            last_user_content = (
                content + "\n\nAttached document (" + str(primary_attachment.get("name") or "") + "):\n" + doc_text
            ).strip()

    messages = [{"role": "system", "content": ASSISTANT_SYSTEM_PROMPT}]
    messages.extend(history_messages)
    messages.append({"role": "user", "content": last_user_content})

    # AI mode is billed per message at the existing text tariff of the
    # assistant model: reserved before the stream opens, charged once any
    # text was produced, released when nothing was (error/disconnect).
    # Capped output; reserved at the upper bound, settled on the usage the
    # stream reports (the reservation when the stream ends without it).
    assistant_images = sum(
        1 for message in messages if isinstance(message.get("content"), list)
        for part in message["content"] if isinstance(part, dict) and part.get("type") in {"image_url", "input_image"}
    )
    assistant_credits = helper_text_reservation(
        OPENAI_ASSISTANT_MODEL,
        json.dumps([m if not isinstance(m.get("content"), list) else {**m, "content": [p for p in m["content"] if not (isinstance(p, dict) and p.get("type") in {"image_url", "input_image"})]} for m in messages], ensure_ascii=False),
        ASSISTANT_MAX_OUTPUT_TOKENS, assistant_images,
    )
    if assistant_credits <= 0:
        return unpriced_helper_response("assistant_ai")
    assistant_generation_id = helper_generation_id("assistant", telegram_id, client_request_id)
    try:
        await asyncio.to_thread(reserve_direct_text_generation, telegram_id, assistant_credits, assistant_generation_id)
    except SecurityError as exc:
        return JSONResponse({"ok": False, "error": exc.code, "paywall": exc.status == 402}, status_code=exc.status)

    stream_id = uuid4().hex
    with _ASSISTANT_STOP_LOCK:
        _ASSISTANT_STOP_FLAGS[stream_id] = False

    async def event_stream():
        import queue as queue_module
        collected = []
        error_code = None
        cancelled = False
        billing_settled = False
        try:
            yield f"data: {json.dumps({'type': 'start', 'stream_id': stream_id, 'conversation_id': conversation_id})}\n\n"
            q = queue_module.Queue()
            stream_usage = {}

            def worker():
                try:
                    for delta in stream_assistant_reply(OPENAI_API_KEY, OPENAI_API_BASE, OPENAI_ASSISTANT_MODEL, messages,
                                                        max_output_tokens=ASSISTANT_MAX_OUTPUT_TOKENS, usage_sink=stream_usage):
                        q.put(("delta", delta))
                        with _ASSISTANT_STOP_LOCK:
                            if _ASSISTANT_STOP_FLAGS.get(stream_id):
                                q.put(("cancelled", None))
                                return
                    q.put(("done", None))
                except Exception as exc:
                    q.put(("error", str(exc) or "ai_temporarily_unavailable"))

            with billing_scope(assistant_generation_id, assistant_credits):
                worker_context = contextvars.copy_context()
            threading.Thread(target=worker_context.run, args=(worker,), daemon=True).start()
            while True:
                kind, value = await asyncio.to_thread(q.get)
                if kind == "delta":
                    collected.append(value)
                    yield f"data: {json.dumps({'type': 'delta', 'text': value})}\n\n"
                elif kind == "cancelled":
                    cancelled = True
                    break
                elif kind == "error":
                    error_code = value
                    break
                else:
                    break
            final_text = "".join(collected)
            if final_text:
                billing = await asyncio.to_thread(
                    charge_generation_balance, telegram_id, assistant_generation_id,
                    {"type": "text", "model": OPENAI_ASSISTANT_MODEL},
                    {"mode": "assistant", "model": OPENAI_ASSISTANT_MODEL, "provider": "openai",
                     "price_snapshot": {"final_credits": settled_helper_credits(
                         assistant_credits,
                         text_usage_credits(OPENAI_ASSISTANT_MODEL, stream_usage) if stream_usage else None,
                         "assistant"),
                         "reserved_credits": assistant_credits}},
                )
                billing_settled = bool(billing.get("charged") or billing.get("already_charged"))
        finally:
            with _ASSISTANT_STOP_LOCK:
                _ASSISTANT_STOP_FLAGS.pop(stream_id, None)
            if not billing_settled:
                await asyncio.to_thread(release_direct_text_generation, assistant_generation_id)

        final_text = "".join(collected)
        prompt_block = _assistant_extract_prompt(final_text)
        actions = []
        if prompt_block:
            actions.append({"label": "Use Prompt", "type": "use_prompt", "prompt": prompt_block})
            actions.append({"label": "Open in Pro Studio", "type": "open_pro_studio", "prompt": prompt_block})
        if final_text:
            actions.append({"label": "Copy", "type": "copy"})
            actions.append({"label": "Regenerate", "type": "regenerate"})

        status = "cancelled" if cancelled else ("error" if (error_code and not final_text) else "completed")
        saved_message = None
        if persist and (final_text or error_code):
            saved_message = await asyncio.to_thread(
                assistant_store.add_message, connect, conversation_id, telegram_id, "assistant", final_text,
                actions=actions, mode="ai", status=status, error=error_code or "",
            )
            await asyncio.to_thread(assistant_store.touch_conversation, connect, conversation_id, final_text[:160], "ai")

        if error_code and not final_text:
            yield f"data: {json.dumps({'type': 'error', 'error': error_code, 'message': translate_provider_error(error_code, 'openai', OPENAI_ASSISTANT_MODEL, 'AI temporarily unavailable. Please try again.')})}\n\n"
        elif cancelled:
            yield f"data: {json.dumps({'type': 'cancelled', 'message_id': (saved_message or {}).get('id')})}\n\n"
        else:
            yield f"data: {json.dumps({'type': 'done', 'message_id': (saved_message or {}).get('id'), 'actions': actions, 'prompt': prompt_block})}\n\n"
        log_user_event(telegram_id=telegram_id, source="assistant", event_type="ai", event_name="assistant_ai_message", payload={"status": status})

    return StreamingResponse(event_stream(), media_type="text/event-stream")


@app.post("/api/web/assistant/stop")
async def web_assistant_stop(request: Request):
    body = await request.json()
    stream_id = str((body or {}).get("stream_id") or "").strip()
    if not stream_id:
        return JSONResponse({"ok": False, "error": "stream_id_required"}, status_code=400)
    with _ASSISTANT_STOP_LOCK:
        found = stream_id in _ASSISTANT_STOP_FLAGS
        if found:
            _ASSISTANT_STOP_FLAGS[stream_id] = True
    return {"ok": True, "stopped": found}


@app.post("/api/web/assistant/files")
async def web_assistant_upload_file(request: Request, file: UploadFile = File(...)):
    telegram_id = int(getattr(request.state, "telegram_id", 0) or 0)
    if not telegram_id:
        return JSONResponse({"ok": False, "error": "login_required"}, status_code=401)
    if not DATABASE_URL:
        return JSONResponse({"ok": False, "error": "database_not_configured"}, status_code=503)
    # Real analysis is a Pro feature (section 13/14) - gating the upload
    # itself (not just the later /message analysis step) means a free
    # client can never get a stored attachment URL to begin with; the
    # Website's own attachment preview for free users stays entirely
    # client-side (an object URL), never reaching this endpoint at all.
    state = await asyncio.to_thread(get_user_state, telegram_id)
    if state.get("subscription_status") != "active":
        return JSONResponse({
            "ok": False, "error": "subscription_required",
            "message": "File analysis is available with SYLVEX Pro.",
        }, status_code=403)

    filename = pathlib.Path(file.filename or "").name
    suffix = pathlib.Path(filename).suffix.lower()
    content_type = (file.content_type or "").lower()
    is_document = suffix in {".txt", ".md", ".csv", ".pdf"} or content_type in {
        "text/plain", "text/markdown", "text/csv", "application/pdf",
    }
    allowed_exts = {".txt", ".md", ".csv", ".pdf"} if is_document else {".jpg", ".jpeg", ".png", ".webp"}
    if suffix not in allowed_exts:
        return JSONResponse({"ok": False, "error": "unsupported_file_type"}, status_code=400)

    max_bytes = 20 * 1024 * 1024
    content = await read_upload(file, max_bytes)
    if not content:
        return JSONResponse({"ok": False, "error": "empty_file"}, status_code=400)
    if len(content) > max_bytes:
        return JSONResponse({"ok": False, "error": "file_too_large"}, status_code=413)
    content_type = validated_upload_type(content, suffix)

    stored_name = f"{uuid4().hex}{suffix}"
    key = generated_key("assistant-attachments", stored_name)
    url = storage_put_bytes(content, key, content_type)
    kind = "document" if is_document else "image"

    # Register the attachment under an opaque id instead of handing the
    # browser a raw URL to echo back later - /api/web/assistant/message
    # only ever accepts this id, resolving the URL itself from this
    # ownership-checked record (see _assistant_resolve_attachments), never
    # trusting a URL supplied directly in a later request body.
    connect = _assistant_connect()
    await asyncio.to_thread(assistant_store.ensure_assistant_tables, connect)
    record = await asyncio.to_thread(
        assistant_store.create_attachment, connect, telegram_id, url, filename, content_type, len(content), kind,
    )
    return {
        "ok": True,
        "file": {
            "id": record["id"], "url": record["url"], "name": record["name"],
            "mime": record["mime"], "size": record["size"], "kind": record["kind"],
        },
    }


@app.post("/api/web/assistant/attachments/from-history")
async def web_assistant_attachment_from_history(request: Request):
    """Registers an existing SYLVEX generation (from this user's own Pro
    Studio history) as an Assistant attachment. Never trusts a media URL
    from the request body - the media_url used is looked up server-side
    from prostudio_messages, filtered to rows this account owns, exactly
    like public_prostudio_gallery already does for the same table."""
    telegram_id = int(getattr(request.state, "telegram_id", 0) or 0)
    if not telegram_id:
        return JSONResponse({"ok": False, "error": "login_required"}, status_code=401)
    if not DATABASE_URL:
        return JSONResponse({"ok": False, "error": "database_not_configured"}, status_code=503)
    state = await asyncio.to_thread(get_user_state, telegram_id)
    if state.get("subscription_status") != "active":
        return JSONResponse({
            "ok": False, "error": "subscription_required",
            "message": "Referencing SYLVEX history in a conversation is available with SYLVEX Pro.",
        }, status_code=403)

    body = await request.json()
    try:
        history_message_id = int((body or {}).get("message_id") or 0)
    except (TypeError, ValueError):
        history_message_id = 0
    if not history_message_id:
        return JSONResponse({"ok": False, "error": "message_id_required"}, status_code=400)

    def _fetch_owned_item():
        ensure_prostudio_table()
        with db_connection(DATABASE_URL) as conn:
            cursor = conn.cursor()
            cursor.execute(
                "SELECT image_url, images_json, video_url, videos_json, audio_url, audios_json, "
                "metadata_json, prompt FROM prostudio_messages WHERE id = %s AND telegram_id = %s",
                (history_message_id, telegram_id),
            )
            row = cursor.fetchone()
            cursor.close()
        return row

    row = await asyncio.to_thread(_fetch_owned_item)
    if not row:
        return JSONResponse({"ok": False, "error": "history_item_not_found"}, status_code=404)

    image_url, images_json, video_url, videos_json, audio_url, audios_json, metadata_json, prompt = row
    images = _json_list(images_json) or ([image_url] if image_url else [])
    videos = _json_list(videos_json) or ([video_url] if video_url else [])
    audios = _json_list(audios_json) or ([audio_url] if audio_url else [])
    media_url = videos[0] if videos else (audios[0] if audios else (images[0] if images else ""))
    if not media_url:
        return JSONResponse({"ok": False, "error": "history_item_has_no_media"}, status_code=400)

    kind = "video" if videos else "music" if audios else "image" if images else "document"
    mime = {"video": "video/mp4", "music": "audio/mpeg", "image": "image/png"}.get(kind, "text/plain")
    metadata = _json_obj(metadata_json)
    name = str(metadata.get("title") or prompt or "SYLVEX item")[:200]

    connect = _assistant_connect()
    await asyncio.to_thread(assistant_store.ensure_assistant_tables, connect)
    record = await asyncio.to_thread(
        assistant_store.create_attachment, connect, telegram_id, media_url, name, mime, 0, kind,
    )
    return {
        "ok": True,
        "file": {
            "id": record["id"], "url": record["url"], "name": record["name"],
            "mime": record["mime"], "size": record["size"], "kind": record["kind"],
        },
    }


@app.post("/api/web/assistant/realtime/session")
async def web_assistant_realtime_session(request: Request):
    telegram_id = int(getattr(request.state, "telegram_id", 0) or 0)
    if not telegram_id:
        return JSONResponse({"ok": False, "error": "login_required"}, status_code=401)
    state = await asyncio.to_thread(get_user_state, telegram_id)
    if state.get("subscription_status") != "active":
        return JSONResponse({
            "ok": False, "error": "subscription_required",
            "message": "Live voice mode is available with SYLVEX Pro.",
        }, status_code=403)
    if "assistant_realtime" in UNPRICED_HELPERS:
        return unpriced_helper_response("assistant_realtime")
    if not OPENAI_API_KEY:
        return JSONResponse({"ok": False, "error": "openai_not_configured"}, status_code=503)
    await check_request_quota(telegram_id, "/api/web/assistant/realtime/session")

    sdp = (await request.body()).decode("utf-8", errors="ignore").strip()
    if not sdp:
        return JSONResponse({"ok": False, "error": "sdp_required"}, status_code=400)
    instructions = (
        "You are SYLVEX Assistant. Present yourself as SYLVEX Assistant. Speak naturally and "
        "concisely. Help the user develop a creative idea into a clear plan for image, video, "
        "voice, music or text generation in SYLVEX. If the user explicitly asks which "
        "underlying AI provider or model powers this feature, answer accurately based on the "
        "configured provider/model - never reveal API keys or other internal secrets."
    )
    try:
        # An active SYLVEX Pro subscription is the entitlement for this
        # provider call. Open an explicit zero-credit scope so the shared
        # provider guard can distinguish this authorized subscription use
        # from an accidental unbilled dispatch.
        realtime_session_id = f"assistant-realtime:{telegram_id}:{uuid4().hex}"
        with billing_scope(realtime_session_id, 0, free=True):
            content, status_code, content_type = await asyncio.to_thread(
                mint_realtime_session, OPENAI_API_KEY, sdp, instructions, telegram_id, OPENAI_ASSISTANT_REALTIME_MODEL,
            )
        return Response(content=content, status_code=status_code, media_type=content_type)
    except Exception as exc:
        prostudio_error("ASSISTANT_REALTIME_FAILED", exc)
        return JSONResponse({"ok": False, "error": "realtime_unavailable"}, status_code=502)


@app.post("/api/web/auth/logout")
async def web_auth_logout(request: Request):
    # COOKIE-2: revoke the session server-side too, not just drop the
    # cookie from this browser - a copy captured elsewhere (network
    # capture, a synced device) would otherwise keep working for the rest
    # of WEB_SESSION_MAX_AGE. Best-effort: an already-invalid/missing
    # cookie just means there is nothing to revoke.
    account_id = await _web_session_account_id(request)
    if account_id is not None:
        await asyncio.to_thread(revoke_web_sessions, account_id)
    response = JSONResponse({"ok": True})
    # Must match every attribute the cookie was originally set with
    # (_set_web_session_cookie: secure=True, samesite="none"). Starlette's
    # delete_cookie() defaults to secure=False/samesite="lax", and browsers
    # refuse to let a non-Secure Set-Cookie clear a Secure one - so without
    # this, logout silently did nothing and the session cookie never
    # actually went away.
    response.delete_cookie(
        WEB_SESSION_COOKIE, path="/", secure=True, samesite="none", httponly=True,
        domain=WEB_SESSION_COOKIE_DOMAIN,
    )
    return response


