@app.post("/api/public/telegram/referrals")
async def public_activate_referrals(request: Request):
    payload = await request.json()
    telegram_id = int(payload.get("telegram_id") or 0)

    if not telegram_id:
        user_data = fallback_public_user(payload)
        telegram_id = int(user_data.get("telegram_id") or 0)

    if not telegram_id:
        return telegram_id_required_response()

    # No separate init_data re-check here: SecurityMiddleware already fully
    # authenticated this request (real initData or, once it goes stale
    # mid-session, the sliding tg-session cookie fallback - see
    # services/security.py) and force-rewrote payload["telegram_id"] to the
    # verified uid, so a second, redundant validated_user() call on the
    # (possibly now-stale) raw init_data string here would only reject
    # requests the middleware already proved legitimate.

    claim_code = str(payload.get("claim_code") or "").strip()
    if claim_code:
        state = claim_referral(int(telegram_id), claim_code)
        log_user_event(
            telegram_id=telegram_id,
            source="mini_app",
            event_type="referral",
            event_name="referral_opened_shop",
            payload={"code": claim_code, "claimed": state.get("claimed", False)},
        )
        return state

    state = get_referral_state(int(telegram_id), activate=bool(payload.get("activate", True)))
    log_user_event(
        telegram_id=telegram_id,
        source="mini_app",
        event_type="referral",
        event_name="referral_link_activated",
        payload={"code": state.get("code")},
    )
    return state


