def text_model_identity_line(model: str = "") -> str:
    label, maker = TEXT_MODEL_IDENTITY.get(str(model or ""), ("", ""))
    if not label:
        return ("You are the text model the user selected, running inside the SYLVEX app. "
                "Do not call yourself SYLVEX Assistant or SYLVEX.")
    return (f"You are {label} by {maker}, the text model the user selected, running inside the SYLVEX app. "
            f"If the user asks which model you are, say that you are {label} by {maker}. "
            "Do not call yourself SYLVEX Assistant, SYLVEX AI or SYLVEX; the SYLVEX Assistant is a separate mode.")


def text_system_prompt(tool: str, style: str, output_format: str, model: str = "") -> str:
    tool_notes = {
        "text": "Generate high-quality text for the user's task.",
        "document": "Create a structured document with clear sections, headings, and final actionable content.",
        "prompt": "Create production-ready AI prompts with role, goal, context, constraints, output format, and examples when useful.",
        "structured_dialogue": "Turn the source into a structured dialogue: speakers, timestamps or scenes when available, key points, and clean readable lines.",
        "translate": "Translate the supplied text or extracted media/document content. Preserve formatting and meaning, and state the detected source language when helpful.",
        "summarize": "Create a concise structured summary with key points, decisions, action items, and important quotes when present.",
        "rewrite": "Rewrite and improve the supplied content while preserving intent. Make it clearer, cleaner, and ready to publish.",
        "extract": "Extract readable text, facts, entities, tasks, dates, tables, and useful structured information from the supplied content.",
        "image_prompt": "Analyze the supplied image and create a detailed production-ready prompt. Include subject, style, composition, lighting, camera, mood, details, and negative prompt when useful.",
        "video_prompt": "Analyze the supplied video visually and create a detailed production-ready prompt. Describe subject, scenes, motion, camera, composition, lighting, mood, style, timing, transitions, and negative prompt when useful. If transcript is available, use it as extra context without replacing the visual analysis.",
        "audio_to_text": "Transcribe and clean audio into accurate text. Preserve meaning and structure.",
        "video_to_text": "Transcribe video speech and structure it as scenes, dialogue, summary, and action points.",
    }
    style_notes = {
        "neutral": "Use a neutral professional tone.",
        "business": "Use a business-ready concise tone.",
        "creative": "Use a vivid creative tone.",
        "technical": "Use a precise technical tone.",
        "telegram": "Use a compact Telegram-friendly tone.",
    }
    format_note = "If PDF is selected, still return clean Markdown text; the backend will also create a PDF file."
    return (
        text_model_identity_line(model) + " "
        + tool_notes.get(tool, tool_notes["text"]) + " "
        + style_notes.get(style, style_notes["neutral"]) + " "
        + format_note
        + " Always answer in the user's language unless they request another language."
    )


# Text chat policy (Pro Studio Text and Quick Access Text): stay within the
# SYLVEX creative workflow, send SYLVEX account/platform questions to the
# separate SYLVEX Assistant, and recommend only models available in SYLVEX.
# The model never switches sections itself; it only offers internal links
# that the client renders as buttons.
SYLVEX_TEXT_LINK_GUIDANCE = (
    "You work inside SYLVEX, an AI creative platform with Image, Video, Music and Voice "
    "(text-to-speech) studios and Text models. Help fully with writing and improving prompts, scripts, "
    "descriptions, generation planning, image/video/music/voice-related tasks, text creation and editing, "
    "and other work connected to the user's creative workflow. "
    "If a request is clearly unrelated to SYLVEX, content creation, generation or that workflow, do not act "
    "as an unrestricted general-purpose assistant: reply briefly and politely that Text models in SYLVEX work "
    "within the SYLVEX creative workflow, and offer help with a related task. "
    "Questions about SYLVEX itself (the user's account, balance, subscription, payments, platform features or "
    "behaviour, support) belong to the separate SYLVEX Assistant. Do not answer them as the official SYLVEX "
    "Assistant: reply with one short sentence pointing the user there and add the link "
    "[Open SYLVEX Assistant](sylvex://assistant) on its own line. "
    "When the user clearly wants something a studio produces, you may add at most one short link of the form "
    "[Open Video Studio](sylvex://open/video); allowed targets: sylvex://open/image, sylvex://open/video, "
    "sylvex://open/music, sylvex://open/voice. Never say you switched sections or started a generation. "
    "Translate link text to the user's language and do not add links that are not relevant."
)
SYLVEX_CATALOG_MODES = ("image", "video", "music", "voice", "text")


def sylvex_text_catalog(value) -> dict:
    """Models the client can actually select, as {mode: [(id, label)]};
    ids and labels are reduced to safe short strings."""
    catalog = {}
    if not isinstance(value, dict):
        return catalog
    for mode in SYLVEX_CATALOG_MODES:
        items = []
        for item in (value.get(mode) or [])[:80] if isinstance(value.get(mode), list) else []:
            if not isinstance(item, (list, tuple)) or len(item) < 2:
                continue
            model_id = re.sub(r"[^a-zA-Z0-9_.:\-]", "", str(item[0] or ""))[:80]
            label = re.sub(r"[\[\]()<>\n\r]", " ", str(item[1] or "")).strip()[:60]
            if model_id and label:
                items.append((model_id, label))
        if items:
            catalog[mode] = items
    return catalog


def sylvex_text_policy(opts: dict) -> str:
    """System guidance for the Text chat ("" for other text callers)."""
    if not isinstance(opts, dict):
        return ""
    policies = []
    if opts.get("grid_direct_output"):
        policies.append(
            "This request comes from a SYLVEX Grid text node. Return only the requested production artifact "
            "(for example the final prompt, lyrics, script, dialogue, or copy). Do not add introductions, "
            "recommendations, explanations, parameter lists, headings, or closing remarks unless the user "
            "explicitly asked for them. Preserve the requested language and make the result ready for the "
            "directly connected next node."
        )
    if opts.get("sylvex_links") and str(opts.get("tool") or "text").strip().lower() == "text":
        policy = SYLVEX_TEXT_LINK_GUIDANCE
        catalog = sylvex_text_catalog(opts.get("sylvex_catalog"))
        if catalog:
            listing = "\n".join(f"{mode}: " + "; ".join(f"{model_id}={label}" for model_id, label in items) for mode, items in catalog.items())
            policy += (
                " When the user asks which model fits an image, video, music, voice or text task, recommend only "
                "models from the list of models available in SYLVEX below and never offer other models as choices. "
                "For every model you recommend add a link with its exact name and id: "
                "[Label →](sylvex://model/<section>/<id>), for example [Kling 3.0 →](sylvex://model/video/kling_3_0). "
                "Available models (section: id=name):\n" + listing
            )
        policies.append(policy)
    policy = "\n\n".join(policies)
    return policy


def quick_text_reply(prompt: str, attachment: dict, history: list, tool: str, output_format: str) -> str:
    if attachment or history or tool not in {"text", ""} or output_format == "pdf":
        return ""
    value = re.sub(r"\s+", " ", str(prompt or "").strip().lower())
    greetings = {
        "привет", "здравствуй", "здравствуйте", "салам", "ассаламу алейкум",
        "hello", "hi", "hey", "добрый день", "добрый вечер", "доброе утро",
    }
    if value in greetings:
        return "Привет! Чем помочь?"
    return ""


def openai_compatible_text_request(provider: str, endpoint_base: str, api_key: str, provider_model: str, messages: list, extra_body: Optional[dict] = None, request_timeout: Optional[int] = None) -> tuple[bool, str, dict]:
    require_billing_scope("openai_compatible_text_request")
    if not api_key:
        return False, f"{provider.upper()} API key is not configured", {}
    endpoint = endpoint_base.rstrip("/") + "/chat/completions"
    response = requests.post(
        endpoint,
        headers={"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"},
        data=json.dumps({"model": provider_model, "messages": messages, **(extra_body or {})}),
        timeout=max(10, min(90, int(request_timeout or 45))),
    )
    try:
        data = response.json() if response.content else {}
    except Exception:
        data = {"raw": response.text}
    if response.status_code >= 400:
        if isinstance(data, dict):
            data["_http_status"] = response.status_code
        return False, raw_error_text(data) or response.text, data if isinstance(data, dict) else {}
    text = ""
    if isinstance(data, dict):
        text = data.get("choices", [{}])[0].get("message", {}).get("content", "")
    return True, text, data if isinstance(data, dict) else {}


def openai_responses_text_request(
    provider_model: str,
    messages: list,
    max_output_tokens: Optional[int] = None,
    request_timeout: Optional[int] = None,
    response_format: Optional[dict] = None,
    background: bool = False,
    poll_timeout_seconds: Optional[int] = None,
    reasoning_effort: Optional[str] = None,
    idempotency_key: str = "",
) -> tuple[bool, str, dict]:
    require_billing_scope("openai_responses_text_request")
    if not OPENAI_API_KEY:
        return False, "OPENAI API key is not configured", {}
    response_input = []
    for message in messages or []:
        role = str(message.get("role") or "user")
        raw_content = message.get("content")
        # In the Responses API, prior assistant turns are response output
        # items.  They must use output_text, while user/system/developer turns
        # use input_text.  Sending input_text for an assistant history item
        # causes the API error: "Supported values are output_text and refusal".
        text_part_type = "output_text" if role == "assistant" else "input_text"
        if isinstance(raw_content, list):
            content = []
            for part in raw_content:
                if not isinstance(part, dict):
                    continue
                if part.get("type") == "text":
                    content.append({"type": text_part_type, "text": str(part.get("text") or "")})
                elif part.get("type") == "image_url" and role != "assistant":
                    image_url = (part.get("image_url") or {}).get("url")
                    if image_url:
                        content.append({"type": "input_image", "image_url": image_url})
        else:
            content = [{"type": text_part_type, "text": str(raw_content or "")}]
        response_input.append({"role": role, "content": content})
    request_payload = {
        "model": provider_model,
        "input": response_input,
        **({"max_output_tokens": int(max_output_tokens)} if max_output_tokens else {}),
    }
    if isinstance(response_format, dict) and response_format.get("type"):
        request_payload["text"] = {"format": response_format}
    if reasoning_effort in {"low", "medium", "high", "xhigh", "max"}:
        request_payload["reasoning"] = {"effort": reasoning_effort}
    if background:
        # OpenAI Background mode returns a response id quickly and lets the
        # caller poll. This avoids holding one provider connection open while
        # a reasoning model builds a large Grid graph.
        request_payload.update({"background": True, "store": False})
    headers = {"Authorization": f"Bearer {OPENAI_API_KEY}", "Content-Type": "application/json"}
    create_headers = dict(headers)
    if idempotency_key:
        create_headers["Idempotency-Key"] = re.sub(r"[^a-zA-Z0-9_.:-]", "-", str(idempotency_key))[:256]
    endpoint = OPENAI_API_BASE.rstrip("/") + "/responses"
    response = requests.post(
        endpoint,
        headers=create_headers,
        data=json.dumps(request_payload),
        timeout=max(10, min(90, int(request_timeout or (20 if background else 90)))),
    )
    try:
        data = response.json() if response.content else {}
    except Exception:
        data = {"raw": response.text}
    if response.status_code >= 400:
        if isinstance(data, dict):
            data["_http_status"] = response.status_code
        return False, raw_error_text(data) or response.text, data if isinstance(data, dict) else {}

    if background:
        response_id = str(data.get("id") or "") if isinstance(data, dict) else ""
        status = str(data.get("status") or "") if isinstance(data, dict) else ""
        if not response_id:
            return False, "OpenAI background response id is missing", data if isinstance(data, dict) else {}
        deadline = time.monotonic() + max(30, min(600, int(poll_timeout_seconds or 180)))
        last_status = ""
        while status in {"queued", "in_progress"} and time.monotonic() < deadline:
            if status != last_status:
                print("OPENAI_BACKGROUND_RESPONSE:", json.dumps({
                    "response_id": response_id, "model": provider_model, "status": status,
                }))
                last_status = status
            time.sleep(2)
            try:
                polled = requests.get(
                    f"{endpoint}/{response_id}", headers=headers,
                    timeout=max(10, min(30, int(request_timeout or 20))),
                )
            except requests.RequestException:
                if time.monotonic() < deadline:
                    continue
                raise
            try:
                polled_data = polled.json() if polled.content else {}
            except Exception:
                polled_data = {"raw": polled.text}
            if polled.status_code >= 400:
                if polled.status_code in {408, 409, 425, 429, 500, 502, 503, 504} and time.monotonic() < deadline:
                    continue
                if isinstance(polled_data, dict):
                    polled_data["_http_status"] = polled.status_code
                return False, raw_error_text(polled_data) or polled.text, polled_data if isinstance(polled_data, dict) else {}
            data = polled_data if isinstance(polled_data, dict) else {}
            status = str(data.get("status") or "")
        if status in {"queued", "in_progress"}:
            try:
                requests.post(f"{endpoint}/{response_id}/cancel", headers=headers, timeout=15)
            except requests.RequestException:
                pass
            raise requests.ReadTimeout(f"OpenAI background response exceeded {int(poll_timeout_seconds or 180)} seconds")
        print("OPENAI_BACKGROUND_RESPONSE:", json.dumps({
            "response_id": response_id, "model": provider_model, "status": status or "unknown",
        }))
        if status != "completed":
            error_data = data.get("error") if isinstance(data.get("error"), dict) else data
            return False, raw_error_text(error_data) or f"OpenAI background response ended with status {status or 'unknown'}", data

    text = str(data.get("output_text") or "") if isinstance(data, dict) else ""
    if not text and isinstance(data, dict):
        text = "\n".join(
            str(part.get("text") or "")
            for output in data.get("output") or [] if isinstance(output, dict)
            for part in output.get("content") or [] if isinstance(part, dict) and part.get("type") == "output_text"
        ).strip()
    return True, text, data if isinstance(data, dict) else {}


def gemini_text_request(provider_model: str, messages: list, max_output_tokens: Optional[int] = None, request_timeout: Optional[int] = None) -> tuple[bool, str, dict]:
    require_billing_scope("gemini_text_request")
    api_key = env_value("GEMINI_API_KEY", "GEMINI-API-KEY", "GOOGLE_API_KEY", "GOOGLE-API-KEY")
    if not api_key:
        return False, "GEMINI_API_KEY is not configured", {}
    # Older deployments used shorthand names that are not valid for the
    # Gemini v1beta generateContent endpoint.  Keep the UI model IDs stable
    # while sending the provider's published endpoint-compatible names.
    provider_model = {
        "gemini-3.1-pro": "gemini-3.1-pro-preview",
        "gemini-3.1-flash": "gemini-3.1-flash-preview",
    }.get(str(provider_model or "").strip(), provider_model)
    system_text = "\n\n".join(str(item.get("content") or "") for item in messages if item.get("role") == "system")
    contents = []
    for item in messages:
        role = item.get("role")
        if role == "system":
            continue
        raw_content = item.get("content")
        parts = []
        if isinstance(raw_content, list):
            for part in raw_content:
                if not isinstance(part, dict):
                    continue
                if part.get("type") == "text":
                    parts.append({"text": str(part.get("text") or "")})
                elif part.get("type") == "image_url":
                    image_url = ((part.get("image_url") or {}).get("url") or "")
                    if image_url.startswith("data:image/") and ";base64," in image_url:
                        head, data = image_url.split(";base64,", 1)
                        parts.append({"inline_data": {"mime_type": head.replace("data:", "") or "image/png", "data": data}})
                elif part.get("type") == "gemini_file":
                    gemini_part = part.get("part")
                    if isinstance(gemini_part, dict):
                        parts.append(gemini_part)
        else:
            parts = [{"text": str(raw_content or "")}]
        contents.append({
            "role": "model" if role == "assistant" else "user",
            "parts": parts or [{"text": ""}],
        })
    endpoint_base = env_value("GEMINI_TEXT_ENDPOINT", "GEMINI-GENERATE-CONTENT-ENDPOINT", default="https://generativelanguage.googleapis.com/v1beta/models").rstrip("/")
    endpoint = f"{endpoint_base}/{provider_model}:generateContent"
    request_payload = {"contents": contents}
    if max_output_tokens:
        request_payload["generationConfig"] = {"maxOutputTokens": int(max_output_tokens)}
    if system_text:
        request_payload["systemInstruction"] = {"parts": [{"text": system_text}]}
    response = requests.post(
        endpoint,
        headers={"x-goog-api-key": api_key, "Content-Type": "application/json"},
        data=json.dumps(request_payload),
        timeout=max(10, min(90, int(request_timeout or 45))),
    )
    try:
        data = response.json() if response.content else {}
    except Exception:
        data = {"raw": response.text}
    if response.status_code >= 400:
        if isinstance(data, dict):
            data["_http_status"] = response.status_code
        return False, raw_error_text(data) or response.text, data if isinstance(data, dict) else {}
    text_parts = []
    for candidate in (data.get("candidates") or []) if isinstance(data, dict) else []:
        for part in ((candidate.get("content") or {}).get("parts") or []):
            if isinstance(part, dict) and part.get("text"):
                text_parts.append(str(part.get("text")))
    return True, "\n".join(text_parts).strip(), data if isinstance(data, dict) else {}


def call_text_provider(
    model: str,
    messages: list,
    attachment: Optional[dict] = None,
    max_output_tokens: Optional[int] = None,
    request_timeout: Optional[int] = None,
    response_format: Optional[dict] = None,
    openai_background: bool = False,
    openai_poll_timeout_seconds: Optional[int] = None,
    reasoning_effort: Optional[str] = None,
    idempotency_key: str = "",
) -> dict:
    require_billing_scope("call_text_provider")
    cfg = TEXT_MODEL_VARIANTS.get(model) or TEXT_MODEL_VARIANTS["gpt-5.5"]
    provider = cfg.get("provider") or "openai"
    provider_model = cfg.get("provider_model") or model
    request_messages = with_text_media_attachment(messages, attachment or {}, provider)
    # Output cap (priced helpers only): the reservation is computed from it,
    # so the provider must never return more.
    cap_body = {"max_tokens": int(max_output_tokens)} if max_output_tokens else {}
    if provider == "gemini":
        ok, text, data = gemini_text_request(provider_model, request_messages, max_output_tokens, request_timeout)
    elif provider in {"grok", "xai"}:
        api_key = env_value("XAI_API_KEY", "XAI-API-KEY", "GROK_API_KEY", "GROK-API-KEY")
        endpoint_base = env_value("XAI_API_BASE", "GROK_API_BASE", default="https://api.x.ai/v1")
        ok, text, data = openai_compatible_text_request("grok", endpoint_base, api_key, provider_model, request_messages, cap_body or None, request_timeout)
        provider = "grok"
    elif provider == "qwen":
        api_key = env_value("DASHSCOPE_API_KEY", "DASHSCOPE-API-KEY", "QWEN_API_KEY", "QWEN-API-KEY")
        endpoint_base = env_value("QWEN_TEXT_API_BASE", "DASHSCOPE_COMPATIBLE_API_BASE", default="https://dashscope-intl.aliyuncs.com/compatible-mode/v1")
        # Pricing is pinned to Qwen's non-thinking tier. Sending this flag is
        # required; otherwise the alias may enable thinking and bill a
        # different output rate than the one reserved for the user.
        ok, text, data = openai_compatible_text_request(
            "qwen", endpoint_base, api_key, provider_model, request_messages,
            {"enable_thinking": False, **cap_body}, request_timeout,
        )
    elif provider == "byteplus":
        endpoint_base = BYTEPLUS_ARK_ENDPOINT
        ok, text, data = openai_compatible_text_request("byteplus", endpoint_base, BYTEPLUS_ARK_API_KEY, provider_model, request_messages, {"thinking": {"type": "disabled"}, **cap_body}, request_timeout)
    else:
        if cfg.get("api") == "responses":
            ok, text, data = openai_responses_text_request(
                provider_model, request_messages, max_output_tokens, request_timeout, response_format,
                background=openai_background,
                poll_timeout_seconds=openai_poll_timeout_seconds,
                reasoning_effort=reasoning_effort,
                idempotency_key=idempotency_key,
            )
        else:
            ok, text, data = openai_compatible_text_request("openai", OPENAI_API_BASE, OPENAI_API_KEY, provider_model, request_messages,
                                                            {"max_completion_tokens": int(max_output_tokens)} if max_output_tokens else None, request_timeout)
        provider = "openai"
    if not ok:
        return {"ok": False, "error": text, "provider": provider, "model": model, "provider_model": provider_model, "metadata": data}
    return {"ok": True, "text": text, "provider": provider, "model": model, "provider_model": provider_model, "metadata": data}


def text_generation(payload: dict) -> dict:
    require_billing_scope("text_generation")
    if text_media_attachment(payload):
        # Transcription and audio/video input tokens have no SYLVEX tariff:
        # fail closed before any provider is contacted.
        print("UNPRICED_HELPER_BLOCKED:", {"operation": "text_media_attachment"})
        return {"ok": False, "error": "pricing_not_configured", "message": "Аудио и видео во вложениях пока недоступны в Text."}
    prompt = (payload.get("prompt") or "").strip()
    history = payload.get("history") or []
    mode = payload.get("mode") or "text"
    model = normalize_text_model(payload.get("model") or "gpt-5.5")
    attachment = payload.get("attachment") or {}
    text_options = payload.get("text_options") or {}
    if not isinstance(text_options, dict):
        text_options = {}
    tool = str(text_options.get("tool") or "text").strip().lower()
    style = str(text_options.get("style") or "neutral").strip().lower()
    output_format = str(text_options.get("format") or "markdown").strip().lower()
    model_cfg = TEXT_MODEL_VARIANTS.get(model) or TEXT_MODEL_VARIANTS["gpt-5.5"]
    model_provider = model_cfg.get("provider") or "openai"
    attachment_mime = str((attachment or {}).get("mime") or (attachment or {}).get("content_type") or "").lower()
    gemini_media_tools = {"video_prompt", "audio_to_text", "video_to_text"}
    if tool in gemini_media_tools and model_provider != "gemini":
        return {"ok": False, "error": "Этот медиа-инструмент доступен только для моделей Gemini.", "model": model, "tool": tool}
    # "Промпт по фото" needs the model to actually see the attached image.
    # with_text_media_attachment() only forwards image content for these
    # three providers - Qwen/BytePlus never receive it, so without this gate
    # they would silently answer as if they'd seen the photo and still bill
    # the user for the (fabricated) analysis.
    image_prompt_vision_providers = {"openai", "gemini", "grok"}
    if tool == "image_prompt" and model_provider not in image_prompt_vision_providers:
        return {"ok": False, "error": "Промпт по фото доступен только для моделей с поддержкой изображений (OpenAI, Gemini, Grok).", "model": model, "tool": tool}
    if tool == "image_prompt" and not attachment_mime.startswith("image/"):
        return {"ok": False, "error": "Для создания промта по фото загрузите изображение."}
    if tool == "video_prompt" and not attachment_mime.startswith("video/"):
        return {"ok": False, "error": "Для создания промта загрузите поддерживаемый видеофайл."}
    if tool == "video_to_text" and not attachment_mime.startswith("video/"):
        return {"ok": False, "error": "Для извлечения текста загрузите поддерживаемый видеофайл."}
    if tool == "audio_to_text" and not attachment_mime.startswith("audio/"):
        return {"ok": False, "error": "Для извлечения текста загрузите поддерживаемый аудиофайл."}

    quick_reply = quick_text_reply(prompt, attachment, history, tool, output_format)
    if quick_reply:
        return {
            "ok": True,
            "type": "text",
            "text": quick_reply,
            "provider": "sylvex-fast",
            "model": "instant-reply",
            "tool": tool,
            "format": output_format,
        }

    transcript = ""
    transcript_error = ""
    direct_gemini_media = model_provider == "gemini" and (
        (tool in {"video_prompt", "video_to_text"} and attachment_mime.startswith("video/"))
        or (tool == "audio_to_text" and attachment_mime.startswith("audio/"))
    )
    should_transcribe_media = bool(attachment) and (
        tool in {"audio_to_text", "video_to_text", "structured_dialogue", "translate", "summarize", "extract"}
        or attachment_mime.startswith("audio/")
        or attachment_mime.startswith("video/")
    ) and not direct_gemini_media
    if should_transcribe_media and attachment_mime.startswith(("audio/", "video/")):
        transcript, transcript_error = text_media_transcript(payload, attachment, tool)
        if transcript_error:
            return {"ok": False, "error": transcript_error}
        prompt = (prompt + "\n\n" if prompt else "") + "Source transcript:\n" + transcript
    elif direct_gemini_media:
        if tool == "video_prompt":
            media_instruction = "Analyze the attached video itself and generate a production-ready prompt from its visible scenes, motion, camera, style, lighting, sound, and pacing."
        elif tool == "video_to_text":
            media_instruction = "Analyze the attached video's visual and audio streams. Return an accurate transcript plus scenes, visible actions, speakers, and timestamps when possible."
        else:
            media_instruction = "Analyze the attached audio or music file. Transcribe all intelligible speech or lyrics and identify speakers, timestamps, language, and important non-speech or musical sections when possible."
        prompt = (prompt + "\n\n" if prompt else "") + media_instruction
    elif attachment:
        attachment_text = text_attachment_plain_text(attachment)
        if attachment_text:
            prompt = (prompt + "\n\n" if prompt else "") + "Attached document text:\n" + attachment_text

    system_prompt = text_system_prompt(tool, style, output_format, model)
    policy = sylvex_text_policy(text_options)
    if policy:
        system_prompt += " " + policy
    messages = [{"role": "system", "content": system_prompt}]
    for item in history[-10:]:
        role = item.get("role") if item.get("role") in ("user", "assistant") else "user"
        content = item.get("content")
        if content:
            messages.append({"role": role, "content": content})
    if attachment:
        prompt = (prompt + f"\n\nAttachment: {attachment.get('name')} ({attachment.get('mime')})").strip()
    messages.append({"role": "user", "content": f"Mode: {mode}\nTool: {tool}\nPrompt: {prompt}"})

    request_timeout = payload.get("_provider_timeout_seconds")
    response_format = payload.get("_response_format") if isinstance(payload.get("_response_format"), dict) else None
    openai_background = bool(payload.get("_openai_background"))
    openai_poll_timeout_seconds = payload.get("_openai_poll_timeout_seconds")
    reasoning_effort = str(payload.get("_reasoning_effort") or "").strip().lower() or None
    idempotency_key = str(payload.get("_openai_idempotency_key") or "").strip()
    if request_timeout or response_format or openai_background or reasoning_effort or idempotency_key:
        generated = call_text_provider(
            model, messages, attachment,
            payload.get("output_token_cap") or text_output_cap(payload), request_timeout, response_format,
            openai_background=openai_background,
            openai_poll_timeout_seconds=openai_poll_timeout_seconds,
            reasoning_effort=reasoning_effort,
            idempotency_key=idempotency_key,
        )
    else:
        generated = call_text_provider(model, messages, attachment, payload.get("output_token_cap") or text_output_cap(payload))
    if not generated.get("ok"):
        return generated
    text = generated.get("text") or ""
    pdf_url = save_text_pdf(text, "SYLVEX Text") if output_format == "pdf" else ""
    if pdf_url:
        text = (text or "").rstrip() + "\n\nPDF: " + pdf_url
    return {
        "ok": True,
        "type": "text",
        "text": text,
        "provider": generated.get("provider") or "openai",
        "model": model,
        "provider_model": generated.get("provider_model") or model,
        "tool": tool,
        "format": output_format,
        "document_url": pdf_url,
        "file_url": pdf_url,
        "files": [pdf_url] if pdf_url else [],
        "transcript": transcript,
        "metadata": generated.get("metadata") or {},
    }

def openai_image_frontend_model(frontend_model: str, provider_model: str = "") -> str:
    raw = str(frontend_model or "").strip().replace("-", "_").replace(".", "_").lower()
    if raw in OPENAI_IMAGE_MODEL_VARIANTS:
        return raw
    model = str(provider_model or "").strip().replace("-", "_").replace(".", "_").lower()
    if model == "gpt_image_2":
        return "gpt_image_2"
    if model in {"gpt_image_2_5_sunburst", "gpt_image_25_sunburst"}:
        return "gpt_image_2_5_sunburst"
    return "gpt_image_1"


def normalize_openai_image_quality(frontend_model: str, provider_model: str, opts: dict) -> str:
    key = openai_image_frontend_model(frontend_model, provider_model)
    cfg = OPENAI_IMAGE_MODEL_VARIANTS.get(key) or OPENAI_IMAGE_MODEL_VARIANTS["gpt_image_1"]
    raw = str((opts or {}).get("quality") or cfg.get("default_quality") or "medium").strip().lower()
    if raw == "standard":
        raw = "medium"
    allowed = {"low", "medium", "high", "xhigh", "max"} if key == "gpt_image_2_5_sunburst" else {"low", "medium", "high"}
    if raw not in allowed:
        return cfg.get("default_quality") or "medium"
    return raw


def normalize_openai_image_size(size: str, frontend_model: str = "", provider_model: str = "") -> str:
    raw = str(size or "").strip().lower()
    key = openai_image_frontend_model(frontend_model, provider_model)
    if key in {"gpt_image_2_5_sunburst", "gpt_image_2"}:
        match = re.fullmatch(r"(\d{3,4})x(\d{3,4})", raw)
        if match:
            width, height = map(int, match.groups())
            pixels = width * height
            ratio = width / height if height else 0
            if width % 16 == 0 and height % 16 == 0 and width <= 3840 and height <= 3840 and 655360 <= pixels <= 8294400 and 1 / 3 <= ratio <= 3:
                return raw
    if raw in {"1024x1024", "1536x1024", "1024x1536", "auto"}:
        return raw
    if key in {"gpt_image_1", "gpt_image_2"}:
        # Both models only accept these 3 real OpenAI image sizes - 4:3/16:9
        # and 3:4/9:16 are not distinct boxes here (see the comment on the
        # gpt_image_2 sizes list in cabinet.js), so only the ratios that
        # actually correspond to a real, distinct box are recognized.
        if raw in {"2:3", "2x3", "9:16", "portrait"}:
            return "1024x1536"
        if raw in {"3:2", "3x2", "16:9", "landscape"}:
            return "1536x1024"
        return "1024x1024"
    if raw in {"1:1", "1x1", "square"}:
        return "1024x1024"
    if raw in {"4:3", "4x3", "16:9", "landscape"}:
        return "1536x1024"
    if raw in {"3:4", "3x4", "9:16", "portrait"}:
        return "1024x1536"
    return "1024x1024"


def image_reference_urls(payload: dict) -> list:
    opts = payload.get("image_options") or {}
    refs = []
    source_values = (
        opts.get("referenceImageUrls"),
        opts.get("reference_image_urls"),
        opts.get("referenceImages"),
        opts.get("images"),
    )
    for value in source_values:
        if isinstance(value, str):
            refs.append(value)
        elif isinstance(value, list):
            refs.extend(value)
    user_refs = []
    for url in refs:
        if isinstance(url, str) and url.strip() and url not in user_refs:
            user_refs.append(url)
    character_refs = []
    for url in _json_list(opts.get("characterReferences"))[:4]:
        if isinstance(url, str) and url.strip() and url not in character_refs:
            character_refs.append(url)
    object_refs = []
    for url in _json_list(opts.get("objectReferences"))[:4]:
        if isinstance(url, str) and url.strip() and url not in object_refs:
            object_refs.append(url)
    # Round-robin merge (same fairness pattern as seedream_merge_references)
    # instead of a flat concat: every provider consumer of this list
    # truncates it to a fixed cap (e.g. reference_images[:5] for OpenAI,
    # refs[:5] for Flux.2), so a naive [user, character, object] order let
    # enough user uploads silently starve Character/Object out of the
    # request entirely, with no error and no truncation notice.
    groups = [user_refs, character_refs, object_refs]
    clean = []
    seen = set()
    index = 0
    while any(index < len(group) for group in groups):
        for group in groups:
            if index < len(group) and group[index] not in seen:
                seen.add(group[index])
                clean.append(group[index])
        index += 1
    return clean


def openai_image_reference_file(url: str, index: int = 0) -> tuple | None:
    raw = str(url or "").strip()
    if not raw:
        return None
    content = b""
    mime_type = "image/png"
    filename = f"reference-{index + 1}.png"
    try:
        if raw.startswith("data:image/") and ";base64," in raw:
            head, data = raw.split(";base64,", 1)
            mime_type = head.replace("data:", "") or mime_type
            ext = mime_type.split("/", 1)[1].replace("jpeg", "jpg") or "png"
            filename = f"reference-{index + 1}.{ext}"
            content = base64.b64decode(data)
        elif storage_key_from_url(raw):
            content = storage_read_bytes(raw)
            filename = pathlib.Path(urllib.parse.urlparse(raw).path).name or filename
        elif raw.startswith("/webapp/"):
            local_path = safe_local_path(WEBAPP_DIR, raw.replace("/webapp/", "", 1))
            content = local_path.read_bytes()
            filename = local_path.name or filename
            suffix = local_path.suffix.lower()
            if suffix in {".jpg", ".jpeg"}:
                mime_type = "image/jpeg"
            elif suffix == ".webp":
                mime_type = "image/webp"
            elif suffix == ".png":
                mime_type = "image/png"
        elif raw.startswith("/generated/"):
            local_path = safe_local_path(WEBAPP_DIR, raw.replace("/generated/", "generated/", 1))
            content = local_path.read_bytes()
            filename = local_path.name or filename
            suffix = local_path.suffix.lower()
            if suffix in {".jpg", ".jpeg"}:
                mime_type = "image/jpeg"
            elif suffix == ".webp":
                mime_type = "image/webp"
            elif suffix == ".png":
                mime_type = "image/png"
        else:
            response = safe_get(raw, timeout=60)
            response.raise_for_status()
            content = response.content
            content_type = (response.headers.get("content-type") or "").split(";", 1)[0].strip().lower()
            if content_type.startswith("image/"):
                mime_type = content_type
            parsed_name = pathlib.Path(urllib.parse.urlparse(raw).path).name
            if parsed_name:
                filename = parsed_name
        if not content:
            return None
        return ("image[]", (filename, content, mime_type))
    except Exception as exc:
        prostudio_error("OPENAI_IMAGE_REFERENCE_LOAD_FAILED", exc, source=_sql_text(raw, 180))
        return None

def validate_image_feature_request(payload: dict) -> Optional[dict]:
    opts = payload.get("image_options") or {}
    if is_edit_workspace_request(payload):
        try:
            edit_workspace_service.validate_options(opts)
        except ValueError as exc:
            return {"ok": False, "type": "image", "error": str(exc)}
        return None
    model = opts.get("modelId") or opts.get("model") or payload.get("model") or ""
    features = image_model_features(model)
    has_character = bool(opts.get("characterId") or opts.get("characterReferences"))
    has_object = bool(opts.get("objectId") or opts.get("objectReferences"))
    if has_character and not features["character"]:
        return {"ok": False, "type": "image", "error": "Selected model does not support character references", "model": model}
    if has_object and not features["object"]:
        return {"ok": False, "type": "image", "error": "Selected model does not support object references", "model": model}
    return None


def validate_video_feature_request(payload: dict) -> Optional[dict]:
    # Phase 1 Batch 5 (see /root/.claude/plans/splendid-moseying-starlight.md,
    # roadmap step 5): mirrors validate_image_feature_request's contract
    # exactly (Optional[dict], None on success, {"ok": False, ...} on
    # failure) so it plugs into the same "if feature_error: return
    # JSONResponse(feature_error, status_code=400)" idiom at this request's
    # own call site. This only ever rejects a visual reference IMAGE (a
    # character/object reference, or a start/end frame) the model can't
    # accept - characterId/characterName/objectId/objectName (text-only
    # conditioning) are never checked here and always reach
    # _build_video_payload, since every video model supports text
    # conditioning today (see
    # services.model_capabilities._video_character_capability). model_id is
    # resolved the same way estimate_video_generation_cost() already does
    # (video_options.model, then top-level payload.model) so this validates
    # against the exact model the rest of the video request path will use.
    #
    # Batch 5 fix (user-requested correction): start_image/end_image are
    # validated here too, not left to _build_video_payload's silent
    # stripping alone - a request naming a frame image the model can't
    # accept is rejected with the same HTTP 400 shape as an unsupported
    # character/object reference, before pricing runs. start_image is read
    # from both video_options and the top-level payload, matching exactly
    # what _build_video_payload itself accepts (opts.get("start_image") or
    # payload.get("start_image")); end_image has no such top-level fallback
    # in _build_video_payload, so none is checked here either. Both this
    # function and _build_video_payload's own gating read
    # model_capabilities.video_frame_support() - the same shared helper the
    # frontend and _kling_capability_supports_end_frame() already read from
    # - so the two can never independently drift.
    opts = payload.get("video_options") or payload.get("options") or {}
    model = (opts.get("model") or payload.get("model") or "").strip()
    reference_support = model_capabilities_service.video_character_object_visual_reference_supported(model)
    has_character_visual_reference = bool(opts.get("characterReferences"))
    has_object_visual_reference = bool(opts.get("objectReferences"))
    if has_character_visual_reference and not reference_support["character"]:
        return {"ok": False, "type": "video", "error": "Selected model does not support character reference images", "model": model}
    if has_object_visual_reference and not reference_support["object"]:
        return {"ok": False, "type": "video", "error": "Selected model does not support object reference images", "model": model}
    frame_support = model_capabilities_service.video_frame_support(model)
    has_start_image = bool(opts.get("start_image") or payload.get("start_image"))
    has_end_image = bool(opts.get("end_image"))
    if has_start_image and not frame_support["start_frame"]:
        return {"ok": False, "type": "video", "error": "Selected model does not support a start frame image", "model": model}
    if has_end_image and not frame_support["end_frame"]:
        return {"ok": False, "type": "video", "error": "Selected model does not support an end frame image", "model": model}
    # Uploaded image refs and uploaded/edit videos: rejected explicitly when
    # the model's adapter would drop them (no reference slot, or more images
    # than slots), instead of reaching the provider without them. Counted
    # exactly as _build_video_payload merges them.
    def _distinct(*values):
        seen = []
        for value in values:
            for item in (value if isinstance(value, (list, tuple)) else [value]):
                text = str(item or "").strip()
                if text and text not in seen:
                    seen.append(text)
        return seen
    uploaded_refs = _distinct(opts.get("reference_images"), opts.get("referenceImageUrls"))
    if not uploaded_refs and isinstance(payload.get("reference_images"), list):
        uploaded_refs = _distinct(payload.get("reference_images"))
    reference_error = model_capabilities_service.video_reference_input_error(
        model,
        start_image=has_start_image,
        uploaded_refs=len(uploaded_refs),
        character_refs=len(_distinct(opts.get("characterReferences"))[:4]),
        object_refs=len(_distinct(opts.get("objectReferences"))[:4]),
        has_video=bool(opts.get("input_video") or opts.get("video_url") or opts.get("reference_video")),
    )
    if reference_error:
        return {"ok": False, "type": "video", "error": reference_error, "model": model}
    return None


def normalize_grid_video_request(payload: dict) -> dict:
    """Normalize Grid's direct-edge video inputs before pricing/validation.

    A start/end frame occupies its own semantic slot and must never also be
    sent as a generic reference image.  This is deliberately Grid-only so
    established Pro Studio payloads and provider adapters stay unchanged.
    """
    if not isinstance(payload, dict) or not str(payload.get("grid_project_id") or "").strip():
        return payload
    mode = str(payload.get("mode") or payload.get("category") or "").lower()
    if mode != "video":
        return payload
    opts = payload.get("video_options")
    if not isinstance(opts, dict):
        opts = {}
        payload["video_options"] = opts

    def distinct(values):
        result = []
        for value in values if isinstance(values, (list, tuple)) else [values]:
            item = str(value or "").strip()
            if item and item not in result:
                result.append(item)
        return result

    start_image = str(opts.get("start_image") or payload.get("start_image") or "").strip()
    end_image = str(opts.get("end_image") or "").strip()
    refs = distinct(distinct(opts.get("reference_images") or []) + distinct(opts.get("referenceImageUrls") or []))
    refs = [item for item in refs if item not in {start_image, end_image}]
    opts["reference_images"] = refs
    opts["referenceImageUrls"] = list(refs)
    model = str(opts.get("model") or payload.get("model") or "").strip()
    config = _VIDEO_MODEL_CONFIG.get(model) or {}
    modes = list(config.get("modes") or [])
    requested_mode = str(opts.get("generation_mode") or opts.get("mode") or "text_to_video")
    if start_image and requested_mode == "text_to_video" and "image_to_video" in modes:
        requested_mode = "image_to_video"
    if requested_mode not in modes and modes:
        requested_mode = modes[0]
    opts["generation_mode"] = requested_mode
    opts["mode"] = requested_mode
    prostudio_debug(
        "GRID_VIDEO_REQUEST_NORMALIZED",
        project_id=str(payload.get("grid_project_id") or "")[:160],
        node_id=str(payload.get("grid_node_id") or "")[:180],
        model=model,
        mode=requested_mode,
        start_image=bool(start_image),
        end_image=bool(end_image),
        reference_images=len(refs),
    )
    return payload


def _reference_video_meta(url: str) -> dict:
    """What is known about a reference/edit video URL: its extension, plus
    size/duration/dimensions from the upload-time probe sidecar when the
    video is a Pro Studio upload in our storage."""
    meta = {"extension": video_probe.url_extension(url)}
    key = storage_key_from_url(url)
    if not key:
        return meta
    try:
        probed = video_probe.decode_sidecar(storage_read_bytes(video_probe.sidecar_key(key)))
    except Exception:
        probed = None
    if probed:
        meta.update({k: probed[k] for k in ("bytes", "duration", "width", "height", "extension") if probed.get(k) not in (None, "")})
    return meta


def _video_reference_inputs_summary(opts: dict, payload: Optional[dict] = None) -> dict:
    """Which reference inputs a video request carries (presence and counts
    only - never URLs)."""
    payload = payload or {}
    def _count(*values):
        found = set()
        for value in values:
            for item in (value if isinstance(value, (list, tuple)) else [value]):
                if str(item or "").strip():
                    found.add(str(item).strip())
        return len(found)
    return {
        "start_image": bool(opts.get("start_image") or payload.get("start_image")),
        "end_image": bool(opts.get("end_image")),
        "reference_images": _count(opts.get("reference_images"), opts.get("referenceImageUrls")),
        "character_images": _count(opts.get("characterReferences")),
        "object_images": _count(opts.get("objectReferences")),
        "video": bool(opts.get("input_video") or opts.get("video_url") or opts.get("reference_video")),
    }


def log_video_reference_failure(entry_point: str, payload: dict, result: Optional[dict] = None, validation: Optional[str] = None) -> Optional[dict]:
    """VIDEO_REFERENCE_REJECTED record for a video request that carried a
    reference input and was rejected by SYLVEX validation or the provider."""
    opts = payload.get("video_options") or payload.get("options") or {}
    inputs = _video_reference_inputs_summary(opts, payload)
    if not any(inputs.values()):
        return None
    meta = {}
    video_url = str(opts.get("reference_video") or opts.get("input_video") or opts.get("video_url") or "").strip()
    if video_url and not video_url.startswith("data:"):
        try:
            meta = _reference_video_meta(video_url)
        except Exception:
            meta = {}
    result = result if isinstance(result, dict) else {}
    response = result.get("provider_response") if isinstance(result.get("provider_response"), dict) else {}
    error_obj = response.get("error") if isinstance(response.get("error"), dict) else {}
    return video_probe.log_video_reference_event(
        entry_point,
        model=str(opts.get("model") or payload.get("model") or result.get("model") or ""),
        provider=str(result.get("provider") or payload.get("provider") or ""),
        meta=meta,
        validation=validation,
        provider_status=result.get("status_code") or response.get("status_code"),
        provider_error_code=result.get("code") or error_obj.get("code") or response.get("code"),
        provider_error=(result.get("raw_error") or result.get("details") or result.get("error")) if result else None,
        inputs=inputs,
    )


async def validate_reference_video_media(payload: dict) -> Optional[dict]:
    """Reject a reference/edit video the selected model's documented limits
    rule out (registry reference_inputs: extension, size, duration -
    per orientation where it differs - and dimensions). Same response shape
    as validate_video_feature_request(). Models without known limits, and
    facts the server cannot know (no probe sidecar), are not checked."""
    opts = payload.get("video_options") or payload.get("options") or {}
    model = (opts.get("model") or payload.get("model") or "").strip()
    capability = model_capabilities_service.get_capability(model)
    limits = capability.reference_inputs if capability else None
    if not limits or not limits.accepts_video:
        return None
    has_limit = any(value is not None for value in (
        limits.video_min_seconds, limits.video_max_seconds, limits.video_max_bytes,
        limits.video_min_px, limits.video_max_px, limits.video_min_ratio, limits.video_max_ratio, limits.video_max_area,
    )) or bool(limits.video_extensions)
    if not has_limit:
        return None
    urls = []
    for field in ("input_video", "video_url", "reference_video"):
        value = str(opts.get(field) or "").strip()
        if value and not value.startswith("data:") and value not in urls:
            urls.append(value)
    orientation = str(opts.get("character_orientation") or ((opts.get("video_template") or {}).get("character_orientation") if isinstance(opts.get("video_template"), dict) else "") or "image")
    for url in urls:
        meta = await asyncio.to_thread(_reference_video_meta, url)
        error = video_probe.reference_video_limit_error(limits, meta, orientation=orientation)
        if error:
            return {"ok": False, "type": "video", "error": error, "model": model}
    return None


def image_dimensions(size: str) -> tuple[int, int]:
    raw = str(size or "").strip().lower()
    if "x" in raw:
        try:
            width, height = [int(part) for part in raw.split("x", 1)]
            return width, height
        except Exception:
            pass
    if raw in {"16:9", "landscape"}:
        return 1536, 864
    if raw in {"9:16", "portrait"}:
        return 864, 1536
    if raw in {"4:3", "4x3"}:
        return 1408, 1056
    if raw in {"3:4", "3x4"}:
        return 1056, 1408
    if raw in {"1:1", "1x1", "auto"}:
        return 1024, 1024
    return 1024, 1024


def normalize_flux_aspect_ratio(size: str) -> str:
    raw = str(size or "").strip().lower()
    aliases = {
        "square": "1:1",
        "1x1": "1:1",
        "4x3": "4:3",
        "3x4": "3:4",
        "landscape": "16:9",
        "portrait": "9:16",
    }
    value = aliases.get(raw, raw)
    if value in {"1:1", "4:3", "3:4", "16:9", "9:16"}:
        return value
    return "1:1"


# =====================================================
# ОБРАБОТКА ОШИБОК: provider_error_text
# Преобразует техническую ошибку провайдера в понятное сообщение для пользователя и сохраняет диагностические данные для логов.
# =====================================================
def provider_error_text(value, fallback: str = "Provider request failed") -> str:
    return raw_error_text(value, fallback)


# =====================================================
# ОБРАБОТКА ОШИБОК: image_error_response
# Преобразует техническую ошибку провайдера в понятное сообщение для пользователя и сохраняет диагностические данные для логов.
# =====================================================
def image_error_response(provider: str, frontend_model: str, provider_model: str, endpoint: str, error: str, response=None, data: dict = None) -> dict:
    status_code = getattr(response, "status_code", None) if response is not None else None
    body_preview = ""
    details = ""
    if data:
        status_code = data.get("status_code") or status_code
        body_preview = data.get("body_preview") or ""
        details = provider_error_text(data.get("details") or data.get("error") or data.get("message") or "", "")
    if response is not None and not body_preview:
        try:
            body_preview = response.text[:1000]
        except Exception:
            body_preview = ""
    raw_message = provider_error_text(error, "Provider request failed")
    message = translate_provider_error(error, provider=provider, model=frontend_model)
    return {
        "ok": False,
        "type": "image",
        "error": message,
        "message": message,
        "raw_error": raw_message,
        "details": details,
        "provider": provider,
        "frontend_model": frontend_model or "",
        "provider_model": provider_model or "",
        "endpoint": endpoint or "",
        "status_code": status_code,
        "body_preview": body_preview,
    }


async def finalize_image_result(payload: dict, images: list) -> dict:
    job_id = str(payload.get("job_id") or "")
    if job_id:
        # Job pipeline: the original image is the user-visible result and
        # must not wait on thumbnail generation (Pillow decode + R2 upload,
        # multiplied by quantity). Thumbnails are computed and merged into
        # the job's result_json in the background afterward.
        result = _build_image_result_without_thumbnails(images)
        asyncio.create_task(
            _finalize_image_thumbnails_background(job_id, result.get("images") or images)
        )
    else:
        result = attach_image_thumbnails({"ok": True, "type": "image", "image_url": images[0], "images": images})
    telegram_id = int(payload.get("telegram_id") or 0)
    result["sent_to_telegram"] = False
    if telegram_id and not payload.get("skip_telegram"):
        try:
            result["sent_to_telegram"] = await asyncio.to_thread(
                send_generated_images_to_telegram,
                telegram_id,
                images,
                "Готово ✅\nСгенерировано в SYLVEX Pro Studio",
            )
        except Exception as exc:
            print("TELEGRAM SEND GENERATED IMAGES FAILED:", str(exc))
    return result


def flux_headers() -> dict:
    api_key = os.getenv("BFL_API_KEY") or os.getenv("FLUX_API_KEY") or os.getenv("FLUX-API-KEY")
    if not api_key:
        return {}
    return {"accept": "application/json", "x-key": api_key, "Content-Type": "application/json"}


# =====================================================
# POLLING-ПРОЦЕСС: poll_flux_image
# Проверяет статус внешней задачи у AI-провайдера.
# При completed извлекает результат, при failed возвращает понятную ошибку, при processing продолжает ожидание.
# =====================================================
def poll_flux_image(polling_url: str, frontend_model: str, provider_model: str, max_attempts: int = 180) -> tuple[list, dict]:
    headers = flux_headers()
    for attempt in range(1, max_attempts + 1):
        try:
            response = safe_get(polling_url, headers=headers, timeout=60)
        except requests.RequestException as exc:
            return [], image_error_response("flux", frontend_model, provider_model, polling_url, "Provider request failed", data={"body_preview": str(exc)[:1000]})
        data = safe_provider_json(response, "flux", polling_url)
        if response.status_code >= 400 or data.get("ok") is False:
            return [], image_error_response("flux", frontend_model, provider_model, polling_url, data.get("error") or "Provider request failed", response, data)
        status = data.get("status")
        print("FLUX IMAGE POLL:", {"attempt": attempt, "status": status, "has_image_url": bool((data.get("result") or {}).get("sample"))})
        if status == "Ready":
            image_url = (data.get("result") or {}).get("sample")
            return ([image_url] if image_url else []), {}
        if status in {"Error", "Failed", "Request Moderated", "Content Moderated"}:
            return [], image_error_response("flux", frontend_model, provider_model, polling_url, "Flux generation failed", data=data)
        time.sleep(1)
    return [], image_error_response("flux", frontend_model, provider_model, polling_url, "Flux generation timeout")


# =====================================================
# ЗАПРОС К AI-ПРОВАЙДЕРУ: call_flux_image
# Формирует официальный payload, отправляет запрос во внешний AI API и нормализует ответ для общего lifecycle генерации.
# =====================================================
def call_flux_image(frontend_model: str, provider_model: str, endpoint: str, prompt: str, payload: dict, size: str) -> tuple[list, dict, dict]:
    headers = flux_headers()
    if not headers:
        return [], image_error_response("flux", frontend_model, provider_model, endpoint, "Provider API key is missing"), {}
    refs = image_reference_urls(payload)
    options = payload.get("image_options") or {}
    output_format = options.get("output_format") or "jpeg"
    normalized_provider_model = str(provider_model or "").strip().lower()
    if normalized_provider_model.startswith("flux-kontext-"):
        request_payload = {
            "prompt": prompt,
            "aspect_ratio": normalize_flux_aspect_ratio(size),
            "output_format": output_format,
        }
        for index, ref in enumerate(refs[:4], start=1):
            key = "input_image" if index == 1 else f"input_image_{index}"
            request_payload[key] = ref
    else:
        width, height = image_dimensions(size)
        request_payload = {
            "prompt": prompt,
            "width": width,
            "height": height,
            "output_format": output_format,
        }
        # flux_2/flux_2_turbo advertise simultaneous Character+Object
        # reference support (up to 4 each), same as FLUX.2 [max] elsewhere
        # in this file - forward every reference via BFL's numbered
        # input_image/input_image_2.. scheme instead of only refs[0],
        # which silently dropped every reference past the first.
        for index, ref in enumerate(refs[:FLUX_2_MAX_MAX_INPUT_IMAGES], start=1):
            key = "input_image" if index == 1 else f"input_image_{index}"
            request_payload[key] = ref
    submit_endpoint = f"{endpoint.rstrip('/')}/{provider_model}"
    try:
        response = requests.post(submit_endpoint, headers=headers, json=request_payload, timeout=60)
    except requests.RequestException as exc:
        return [], image_error_response("flux", frontend_model, provider_model, submit_endpoint, "Provider request failed", data={"body_preview": str(exc)[:1000]}), request_payload
    data = safe_provider_json(response, "flux", submit_endpoint)
    if response.status_code >= 400 or data.get("ok") is False:
        return [], image_error_response("flux", frontend_model, provider_model, submit_endpoint, data.get("error") or "Provider request failed", response, data), request_payload
    polling_url = data.get("polling_url")
    if not polling_url:
        return [], image_error_response("flux", frontend_model, provider_model, submit_endpoint, "Flux polling_url not found", data=data), request_payload
    images, error = poll_flux_image(polling_url, frontend_model, provider_model)
    return images, error, request_payload


def ideogram_headers(json_content: bool = True) -> dict:
    api_key = env_value("IDEOGRAM_API_KEY", "IDEOGRAM-API-KEY")
    if not api_key:
        return {}
    headers = {"Api-Key": api_key}
    if json_content:
        headers["Content-Type"] = "application/json"
    return headers


def ideogram_frontend_model(frontend_model: str, provider_model: str = "") -> str:
    raw = str(frontend_model or "").strip().replace("-", "_")
    if raw in IDEOGRAM_MODEL_VARIANTS:
        return raw
    model = str(provider_model or "").lower()
    if "v4" in model or raw in {"ideogram_4", "ideogram_4_0"}:
        return "ideogram_4_0"
    return "ideogram_3_0"


def ideogram_rendering_speed(frontend_model: str, provider_model: str, opts: Optional[dict] = None) -> str:
    key = ideogram_frontend_model(frontend_model, provider_model)
    cfg = IDEOGRAM_MODEL_VARIANTS.get(key) or {}
    speed = str((opts or {}).get("rendering_speed") or cfg.get("rendering_speed") or "TURBO").upper()
    if key == "ideogram_4_0" and speed == "FLASH":
        return "TURBO"
    valid = {"FLASH", "TURBO", "DEFAULT", "QUALITY"}
    return speed if speed in valid else str(cfg.get("rendering_speed") or "TURBO").upper()


def ideogram_size_params(frontend_model: str, provider_model: str, size: str) -> dict:
    raw = str(size or "").strip().lower().replace("_", "-")
    if raw in {"", "auto"}:
        return {}
    is_v4 = ideogram_frontend_model(frontend_model, provider_model) == "ideogram_4_0"
    if is_v4:
        mapping = {
            "1:1": {"resolution": "2048x2048"},
            "1x1": {"resolution": "2048x2048"},
            "4:3": {"resolution": "2496x1664"},
            "4x3": {"resolution": "2496x1664"},
            "3:4": {"resolution": "1664x2496"},
            "3x4": {"resolution": "1664x2496"},
            "16:9": {"resolution": "2880x1440"},
            "16x9": {"resolution": "2880x1440"},
            "9:16": {"resolution": "1440x2880"},
            "9x16": {"resolution": "1440x2880"},
        }
        return mapping.get(raw, {"resolution": "2048x2048"})
    mapping = {
        "1:1": {"aspect_ratio": "1x1"},
        "1x1": {"aspect_ratio": "1x1"},
        "1:1-hd": {"resolution": "1024x1024"},
        "1:1 hd": {"resolution": "1024x1024"},
        "4:3": {"aspect_ratio": "4x3"},
        "4x3": {"aspect_ratio": "4x3"},
        "3:4": {"aspect_ratio": "3x4"},
        "3x4": {"aspect_ratio": "3x4"},
        "16:9": {"aspect_ratio": "16x9"},
        "16x9": {"aspect_ratio": "16x9"},
        "9:16": {"aspect_ratio": "9x16"},
        "9x16": {"aspect_ratio": "9x16"},
    }
    return mapping.get(raw, {"aspect_ratio": "1x1"})


# =====================================================
# БАЛАНС И СТОИМОСТЬ: ideogram_cost_info
# Рассчитывает стоимость генерации, проверяет токены пользователя или фиксирует списание после успешного результата.
# =====================================================
def ideogram_cost_info(frontend_model: str, provider_model: str, rendering_speed: str, count: int, has_character: bool = False) -> dict:
    key = ideogram_frontend_model(frontend_model, provider_model)
    cfg = IDEOGRAM_MODEL_VARIANTS.get(key) or IDEOGRAM_MODEL_VARIANTS["ideogram_3_0"]
    speed = str(rendering_speed or cfg.get("rendering_speed") or "TURBO").upper()
    cost_key = f"{speed}_CHARACTER" if has_character and key == "ideogram_3_0" else speed
    unit_usd = float((cfg.get("cost_usd") or {}).get(cost_key, 0))
    unit_credits = int((cfg.get("cost_credits") or {}).get(cost_key, 0))
    image_count = max(1, int(count or 1))
    label_speed = speed.title()
    if has_character and key == "ideogram_3_0":
        label_speed += " + Character"
    return {
        "cost": unit_credits * image_count,
        "cost_credits": unit_credits * image_count,
        "unit_cost_credits": unit_credits,
        "cost_usd": round(unit_usd * image_count, 3),
        "unit_cost_usd": unit_usd,
        "generation_cost": f"${unit_usd * image_count:.3f}",
        "rendering_speed": speed,
        "model_label": f"{cfg.get('label_prefix', 'Ideogram')} {label_speed}",
    }


def recraft_frontend_model(frontend_model: str, provider_model: str = "") -> str:
    raw = str(frontend_model or "").strip().replace("-", "_")
    if raw in RECRAFT_MODEL_VARIANTS:
        return raw
    model = str(provider_model or "").lower()
    if "v4_1_pro_vector" in model or "v4.1_pro_vector" in model:
        return "recraft_v4_1_pro_vector"
    if "v4_1_pro" in model or "v4.1_pro" in model:
        return "recraft_v4_1_pro"
    if "v3" in model:
        return "recraft_v3"
    return "recraft_v4_1"


def recraft_headers() -> dict:
    api_key = env_value("RECRAFT_API_KEY", "RECRAFT-API-KEY")
    if not api_key:
        return {}
    return {
        "Authorization": f"Bearer {api_key}",
        "Content-Type": "application/json",
    }


def recraft_size_value(size: str) -> str:
    raw = str(size or "").strip()
    if raw.lower() in {"", "auto"}:
        return ""
    supported = {"1:1", "16:9", "9:16", "3:4", "4:3"}
    return raw if raw in supported else "1:1"


def recraft_available_tools(frontend_model: str, provider_model: str = "") -> list:
    key = recraft_frontend_model(frontend_model, provider_model)
    cfg = RECRAFT_MODEL_VARIANTS.get(key) or {}
    tools = []
    for tool_id in cfg.get("tools") or []:
        item = RECRAFT_TOOL_CATALOG.get(tool_id)
        if item:
            tools.append({"id": tool_id, **item})
    return tools


# =====================================================
# БАЛАНС И СТОИМОСТЬ: recraft_cost_info
# Рассчитывает стоимость генерации, проверяет токены пользователя или фиксирует списание после успешного результата.
# =====================================================
