def qwen_image_size(size: str, frontend_model: str, provider_model: str = "") -> str:
    ratio = str(size or "").strip().lower().replace("x", ":")
    key = qwen_frontend_model(frontend_model, provider_model)
    if ratio in {"", "auto"}:
        return "2048*2048" if key in {"qwen_image_2", "qwen_image_2_pro"} else "1664*928"
    if key in {"qwen_image_2", "qwen_image_2_pro"}:
        return {
            "1:1": "2048*2048",
            "4:3": "2048*1536",
            "3:4": "1536*2048",
            "16:9": "2048*1152",
            "9:16": "1152*2048",
        }.get(ratio, "2048*2048")
    return {
        "1:1": "1328*1328",
        "4:3": "1472*1104",
        "3:4": "1104*1472",
        "16:9": "1664*928",
        "9:16": "928*1664",
    }.get(ratio, "1664*928")


def qwen_image_reference_value(value: str) -> str:
    """Return actual image bytes as a DashScope-compatible data URL when possible."""
    raw = str(value or "").strip()
    if raw.startswith("data:image/") and ";base64," in raw:
        return raw

    public_url = f"{WEBAPP_URL.rstrip('/')}{raw}" if raw.startswith("/") and WEBAPP_URL else raw
    content = b""
    content_type = mimetypes.guess_type(urllib.parse.urlparse(public_url).path)[0] or "image/png"
    try:
        if storage_key_from_url(public_url):
            content = storage_read_bytes(public_url)
        elif public_url.startswith(("http://", "https://")):
            response = safe_get(public_url, timeout=60)
            response.raise_for_status()
            content = response.content
            content_type = str(response.headers.get("content-type") or content_type).split(";", 1)[0].strip()
    except Exception as exc:
        prostudio_error("QWEN_IMAGE_REFERENCE_READ_FAILED", exc, source_type="storage" if storage_key_from_url(public_url) else "url")

    if content:
        if content.startswith(b"\xff\xd8\xff"):
            content_type = "image/jpeg"
        elif content.startswith(b"\x89PNG\r\n\x1a\n"):
            content_type = "image/png"
        elif content.startswith(b"RIFF") and content[8:12] == b"WEBP":
            content_type = "image/webp"
        return f"data:{content_type};base64,{base64.b64encode(content).decode('ascii')}"
    return public_url if public_url.startswith(("http://", "https://")) else ""


def qwen_image_edit_model(provider_model: str, has_images: bool) -> str:
    """Use an editing-capable Qwen model whenever an input image is present."""
    model = str(provider_model or "").strip()
    if not has_images:
        return model
    normalized = model.lower()
    generation_only_models = {
        "qwen-image",
        "qwen-image-max",
        "qwen-image-plus",
        "qwen-image-max-2025-12-30",
        "qwen-image-plus-2026-01-09",
    }
    if normalized in generation_only_models:
        return env_value(
            "QWEN_IMAGE_EDIT_MODEL",
            "QWEN-IMAGE-EDIT-MODEL",
            default="qwen-image-2.0",
        )
    return model


# =====================================================
# ЗАПРОС К AI-ПРОВАЙДЕРУ: call_qwen_image
# Формирует официальный payload, отправляет запрос во внешний AI API и нормализует ответ для общего lifecycle генерации.
# =====================================================
def call_qwen_image(frontend_model: str, provider_model: str, endpoint: str, prompt: str, payload: dict, size: str, count: int = 1) -> tuple[list, dict, dict]:
    headers = qwen_headers()
    if not headers:
        return [], image_error_response("qwen", frontend_model, provider_model, endpoint, "Provider API key is missing: DASHSCOPE_API_KEY"), {}
    opts = payload.get("image_options") or {}
    key = qwen_frontend_model(frontend_model, provider_model)
    received_references = image_reference_urls(payload)
    included_references = []
    for reference in received_references:
        image_value = qwen_image_reference_value(reference)
        if image_value and image_value not in included_references:
            included_references.append(image_value)
        if len(included_references) >= 3:
            break
    effective_provider_model = qwen_image_edit_model(provider_model, bool(included_references))
    seed_supported = bool((QWEN_MODEL_VARIANTS.get(key) or {}).get("seed"))
    seed = normalize_image_seed(opts.get("seed")) if seed_supported else None
    if seed is not None and seed > 2147483647:
        return [], image_error_response("qwen", frontend_model, provider_model, endpoint, "Seed must be between 0 and 2147483647"), {}
    image_count = max(1, int(count or 1))
    per_request_count = image_count if key in {"qwen_image_2", "qwen_image_2_pro"} else 1
    content = [{"image": reference} for reference in included_references]
    content.append({"text": prompt})
    request_parameters = {
        "negative_prompt": str(opts.get("negative_prompt") or "")[:500],
        "prompt_extend": False if included_references else bool(opts.get("prompt_extend", True)),
        "watermark": bool(opts.get("watermark", False)),
        "n": max(1, min(per_request_count, 6)),
    }
    # For editing, omitting size makes DashScope preserve the input image's
    # aspect ratio. Text-to-image keeps the explicitly selected output size.
    if not included_references:
        request_parameters["size"] = qwen_image_size(size, frontend_model, provider_model)
    request_payload = {
        "model": effective_provider_model,
        "input": {
            "messages": [
                {
                    "role": "user",
                    "content": content,
                }
            ]
        },
        "parameters": request_parameters,
    }
    if seed is not None:
        request_payload["parameters"]["seed"] = seed

    all_images = []
    last_payload = request_payload
    attempts = 1 if key in {"qwen_image_2", "qwen_image_2_pro"} else image_count
    for attempt in range(1, attempts + 1):
        try:
            prostudio_debug(
                "QWEN_IMAGE_PROVIDER_REQUEST",
                endpoint=endpoint,
                frontend_model=frontend_model,
                provider_model=effective_provider_model,
                size=request_payload["parameters"].get("size") or "source",
                count=request_payload["parameters"].get("n"),
                reference_count_received=len(received_references),
                image_count=len(included_references),
                inline_image_count=sum(1 for value in included_references if value.startswith("data:image/")),
                reference_count_omitted=max(0, len(received_references) - len(included_references)),
                attempt=attempt,
                seed_present=seed is not None,
            )
            response = requests.post(endpoint, headers=headers, data=json.dumps(request_payload), timeout=180)
        except requests.RequestException as exc:
            prostudio_error("QWEN_IMAGE_PROVIDER_REQUEST_FAILED", exc, endpoint=endpoint, frontend_model=frontend_model, provider_model=effective_provider_model)
            return [], image_error_response("qwen", frontend_model, effective_provider_model, endpoint, "Provider request failed", data={"body_preview": str(exc)[:1000]}), last_payload
        data = safe_provider_json(response, "qwen", endpoint)
        images = normalize_image_response(data)
        prostudio_debug(
            "QWEN_IMAGE_PROVIDER_RESPONSE",
            endpoint=endpoint,
            status_code=response.status_code,
            data_keys=sorted(data.keys()) if isinstance(data, dict) else [],
            image_count=len(images),
        )
        if response.status_code >= 400 or data.get("ok") is False:
            provider_error = provider_error_text(data.get("error") or data.get("message") or data, "Provider request failed")
            return [], image_error_response("qwen", frontend_model, effective_provider_model, endpoint, provider_error, response, data), last_payload
        for url in images:
            if url and url not in all_images:
                all_images.append(url)
        if len(all_images) >= image_count:
            break
    return all_images[:image_count], {}, last_payload


def google_image_frontend_model(frontend_model: str, provider_model: str = "") -> str:
    raw = str(frontend_model or "").strip().replace("-", "_").lower()
    if raw in GOOGLE_IMAGE_MODEL_VARIANTS:
        return raw
    model = str(provider_model or "").strip().lower()
    if model == "gemini-3.1-flash-image":
        return "nano_banana_2"
    if model == "gemini-3.1-flash-lite-image":
        return "nano_banana_2_lite"
    if model == "gemini-3-pro-image":
        return "nano_banana_pro"
    if model == "gemini-2.5-flash-image":
        return "nano_banana"
    if model == "imagen-4.0-fast-generate-001":
        return "imagen_4_fast"
    if model == "imagen-4.0-ultra-generate-001":
        return "imagen_4_ultra"
    if model == "imagen-4.0-generate-001":
        return "imagen_4_standard"
    return "nano_banana_2"


def google_image_aspect_ratio(size: str, imagen: bool = False) -> str:
    raw = str(size or "").strip().lower().replace("x", ":")
    if raw in {"", "auto"}:
        return "1:1" if imagen else "auto"
    supported = {
        "1:1",
        "16:9",
        "9:16",
        "3:4",
        "4:3",
        "1:2",
        "2:1",
        "20:9",
        "9:20",
    }
    if imagen:
        supported = {"1:1", "3:4", "4:3", "9:16", "16:9"}
    return raw if raw in supported else "1:1"


def google_image_resolution(opts: dict, frontend_model: str, provider_model: str = "") -> str:
    key = google_image_frontend_model(frontend_model, provider_model)
    cfg = GOOGLE_IMAGE_MODEL_VARIANTS.get(key) or GOOGLE_IMAGE_MODEL_VARIANTS["nano_banana_2"]
    raw = str(
        (opts or {}).get("resolution")
        or (opts or {}).get("image_resolution")
        or (opts or {}).get("quality")
        or cfg.get("default_resolution")
        or "1k"
    ).strip().lower()
    aliases = {"0.5": "0.5k", "512": "0.5k", "1024": "1k", "2048": "2k", "4096": "4k"}
    raw = aliases.get(raw, raw)
    if raw not in (cfg.get("cost_credits") or {}):
        return str(cfg.get("default_resolution") or "1k").lower()
    return raw


def google_interactions_image_size(resolution: str) -> str:
    raw = str(resolution or "").strip().lower()
    if raw in {"0.5k", "0.5", "512", "512px"}:
        return "512"
    if raw in {"2k", "2048"}:
        return "2K"
    if raw in {"4k", "4096"}:
        return "4K"
    return "1K"


def google_has_input_image(payload: dict) -> bool:
    return bool(image_reference_urls(payload))


# =====================================================
# БАЛАНС И СТОИМОСТЬ: google_image_cost_info
# Рассчитывает стоимость генерации, проверяет токены пользователя или фиксирует списание после успешного результата.
# =====================================================
def google_image_cost_info(frontend_model: str, provider_model: str, count: int, resolution: str = "", has_input_image: bool = False, *, reference_count: int = 0, prompt_text: str = "") -> dict:
    key = google_image_frontend_model(frontend_model, provider_model)
    cfg = GOOGLE_IMAGE_MODEL_VARIANTS.get(key) or GOOGLE_IMAGE_MODEL_VARIANTS["nano_banana_2"]
    res = google_image_resolution({"resolution": resolution}, key, cfg.get("provider_model") or provider_model)
    image_count = max(1, int(count or 1))
    if key in {"nano_banana", "imagen_4_fast", "imagen_4_standard", "imagen_4_ultra"}:
        return {
            "cost": 0, "cost_credits": 0, "cost_usd": 0,
            "generation_cost": "", "pricing_available": False,
            "pricing_error": "retired_provider_model", "model_label": cfg.get("label") or key,
        }
    output_provider_prices = {
        "nano_banana_2": {"0.5k": 0.045, "1k": 0.067, "2k": 0.101, "4k": 0.151},
        "nano_banana_2_lite": {"1k": 0.0336},
        "nano_banana_pro": {"1k": 0.134, "2k": 0.134, "4k": 0.24},
    }
    input_usd_per_million = {"nano_banana_2": 0.50, "nano_banana_2_lite": 0.25, "nano_banana_pro": 2.00}.get(key, 0)
    unit_provider_usd = float((output_provider_prices.get(key) or {}).get(res, 0))
    refs = max(int(bool(has_input_image)), int(reference_count or 0))
    # UTF-8 bytes are a safe reservation bound for text tokens. Google image
    # inputs are token billed; 1,120 tokens/reference is the conservative
    # bound used for the sizes accepted by this product.
    input_tokens = len(str(prompt_text or "").encode("utf-8")) + refs * 1120
    input_provider_usd = input_tokens * input_usd_per_million / 1_000_000
    provider_cost_usd = unit_provider_usd * image_count + input_provider_usd
    total_credits = sylvex_credits(provider_cost_usd)
    input_credits = sylvex_credits(input_provider_usd)
    return {
        "cost": total_credits,
        "cost_credits": total_credits,
        "unit_cost_credits": sylvex_credits(unit_provider_usd),
        "cost_usd": round(provider_cost_usd * 1.5, 6),
        "unit_cost_usd": round(unit_provider_usd * 1.5, 6),
        "provider_cost_usd": round(provider_cost_usd, 8),
        "provider_input_cost_usd": round(input_provider_usd, 8),
        "generation_cost": f"{total_credits} ⚡" if total_credits else "",
        "model_label": cfg.get("label") or frontend_model or provider_model,
        "resolution": res.upper(),
        "input_image_credits": input_credits,
        "input_image_count": refs,
        "input_image_cost_included": bool(refs),
        "input_image_surcharge_provisional": False,
    }


def google_image_usage_cost_usd(frontend_model: str, provider_model: str, count: int, resolution: str, metadata_items: list[dict]) -> Optional[float]:
    key = google_image_frontend_model(frontend_model, provider_model)
    input_rate = {"nano_banana_2": 0.50, "nano_banana_2_lite": 0.25, "nano_banana_pro": 2.00}.get(key)
    if input_rate is None:
        return None
    input_tokens = 0
    found = False
    for metadata in metadata_items or []:
        if not isinstance(metadata, dict):
            continue
        usage = metadata.get("usage") or {}
        gemini = metadata.get("usageMetadata") or {}
        if isinstance(usage, dict) and ("input_tokens" in usage or "prompt_tokens" in usage):
            input_tokens += int(usage.get("input_tokens") or usage.get("prompt_tokens") or 0)
            found = True
        if isinstance(gemini, dict) and "promptTokenCount" in gemini:
            input_tokens += int(gemini.get("promptTokenCount") or 0) + int(gemini.get("toolUsePromptTokenCount") or 0)
            found = True
    if not found:
        return None
    output_only = google_image_cost_info(frontend_model, provider_model, count, resolution)
    output_provider_usd = float(output_only.get("provider_cost_usd") or 0)
    return output_provider_usd + input_tokens * input_rate / 1_000_000


def grok_frontend_model(frontend_model: str, provider_model: str = "") -> str:
    raw = str(frontend_model or "").strip().replace("-", "_").lower()
    if raw in GROK_MODEL_VARIANTS:
        return raw
    model = str(provider_model or "").strip().lower()
    if model == "grok-imagine-image-quality" or "quality" in model:
        return "grok_pro"
    return "grok"


def grok_headers() -> dict:
    api_key = env_value("XAI_API_KEY", "XAI-API-KEY", "GROK_API_KEY", "GROK-API-KEY")
    if not api_key:
        return {}
    return {
        "Authorization": f"Bearer {api_key}",
        "Content-Type": "application/json",
    }


def grok_aspect_ratio(size: str) -> str:
    raw = str(size or "").strip().lower().replace("x", ":")
    supported = {
        "1:1",
        "2:3",
        "3:2",
        "16:9",
        "9:16",
        "3:4",
        "4:3",
        "1:2",
        "2:1",
        "19.5:9",
        "9:19.5",
        "20:9",
        "9:20",
    }
    if raw in supported:
        return raw
    return "1:1"


def grok_resolution_value(opts: dict) -> str:
    raw = str(
        (opts or {}).get("resolution")
        or (opts or {}).get("quality")
        or (opts or {}).get("image_resolution")
        or "1k"
    ).strip().lower()
    if raw in {"2", "2k"}:
        return "2k"
    return "1k"


def grok_has_input_image(payload: dict) -> bool:
    opts = payload.get("image_options") or {}
    if image_reference_urls(payload):
        return True
    for key in ("image_url", "input_image", "inputImage", "referenceImageUrl"):
        if isinstance(opts.get(key), str) and opts.get(key).strip():
            return True
    return False


def grok_input_image_url(payload: dict) -> str:
    opts = payload.get("image_options") or {}
    for key in ("image_url", "input_image", "inputImage", "referenceImageUrl"):
        value = opts.get(key)
        if isinstance(value, str) and value.strip():
            return value.strip()
    refs = image_reference_urls(payload)
    return refs[0] if refs else ""


def grok_has_selected_style(payload: dict) -> bool:
    opts = payload.get("image_options") or {}
    style = opts.get("style")
    if isinstance(style, dict):
        style = style.get("id") or style.get("style") or style.get("name")
    return str(style or "").strip().lower() not in {"", "auto", "none"}


def grok_image_edit_endpoint(endpoint: str) -> str:
    configured_endpoint = str(endpoint or "").rstrip("/")
    if configured_endpoint.endswith("/images/generations"):
        return configured_endpoint[: -len("/images/generations")] + "/images/edits"
    return "https://api.x.ai/v1/images/edits"


# =====================================================
# БАЛАНС И СТОИМОСТЬ: grok_cost_info
# Рассчитывает стоимость генерации, проверяет токены пользователя или фиксирует списание после успешного результата.
# =====================================================
def grok_cost_info(frontend_model: str, provider_model: str, count: int, resolution: str = "1k", has_input_image: bool = False, reference_count: int = 0) -> dict:
    key = grok_frontend_model(frontend_model, provider_model)
    cfg = GROK_MODEL_VARIANTS.get(key) or GROK_MODEL_VARIANTS["grok"]
    image_count = max(1, int(count or 1))
    res = "2k" if str(resolution or "").strip().lower() in {"2", "2k"} else "1k"
    unit_credits = int((cfg.get("cost_credits") or {}).get(res, 0))
    refs = max(int(bool(has_input_image)), int(reference_count or 0))
    input_credits = int(cfg.get("input_image_credits") or 0) * refs
    total_credits = unit_credits * image_count + input_credits
    generation_cost = f"{total_credits} ⚡" if total_credits else ""
    return {
        "cost": total_credits,
        "cost_credits": total_credits,
        "unit_cost_credits": unit_credits,
        "cost_usd": 0,
        "unit_cost_usd": 0,
        "generation_cost": generation_cost,
        "model_label": cfg.get("label") or frontend_model or provider_model,
        "resolution": res.upper(),
        "input_image_credits": input_credits,
        "input_image_count": refs,
        "input_image_surcharge_provisional": bool(has_input_image and cfg.get("input_image_surcharge_provisional")),
    }


# =====================================================
# БАЛАНС И СТОИМОСТЬ: openai_image_cost_info
# Рассчитывает стоимость генерации, проверяет токены пользователя или фиксирует списание после успешного результата.
# =====================================================
def openai_image_cost_info(frontend_model: str, provider_model: str, quality: str, count: int, *, prompt_text: str = "", reference_count: int = 0) -> dict:
    key = openai_image_frontend_model(frontend_model, provider_model)
    cfg = OPENAI_IMAGE_MODEL_VARIANTS.get(key) or OPENAI_IMAGE_MODEL_VARIANTS["gpt_image_1"]
    image_count = max(1, int(count or 1))
    normalized_quality = str(quality or cfg.get("default_quality") or "medium").strip().lower()
    allowed_quality = {"low", "medium", "high", "xhigh", "max"} if key == "gpt_image_2_5_sunburst" else {"low", "medium", "high"}
    if normalized_quality not in allowed_quality:
        normalized_quality = cfg.get("default_quality") or "medium"
    configured_user_usd = float((cfg.get("cost_usd") or {}).get(normalized_quality, 0))
    unit_provider_usd = configured_user_usd / 1.5
    text_rate = 5.0
    image_rate = 8.0 if key in {"gpt_image_2", "gpt_image_2_5_sunburst"} else 10.0
    prompt_tokens = len(str(prompt_text or "").encode("utf-8"))
    input_provider_usd = (prompt_tokens * text_rate + max(0, int(reference_count or 0)) * 4096 * image_rate) / 1_000_000
    provider_cost_usd = unit_provider_usd * image_count + input_provider_usd
    total_credits = sylvex_credits(provider_cost_usd)
    return {
        "cost": total_credits,
        "cost_credits": total_credits,
        "unit_cost_credits": sylvex_credits(unit_provider_usd),
        "cost_usd": round(provider_cost_usd * 1.5, 6),
        "unit_cost_usd": round(configured_user_usd, 6),
        "provider_cost_usd": round(provider_cost_usd, 8),
        "provider_input_cost_usd": round(input_provider_usd, 8),
        "input_reference_count": max(0, int(reference_count or 0)),
        "generation_cost": f"{total_credits} ⚡",
        "quality": normalized_quality,
        "model_label": cfg.get("label") or frontend_model or provider_model,
    }


def openai_image_usage_cost_usd(frontend_model: str, provider_model: str, usage: dict) -> Optional[float]:
    """Exact OpenAI Image token cost from response usage when available."""
    if not isinstance(usage, dict) or not any(key in usage for key in ("input_tokens", "output_tokens")):
        return None
    key = openai_image_frontend_model(frontend_model, provider_model)
    details = usage.get("input_tokens_details") or {}
    image_tokens = int(details.get("image_tokens") or 0) if isinstance(details, dict) else 0
    text_tokens = int(details.get("text_tokens") or 0) if isinstance(details, dict) else 0
    total_input = int(usage.get("input_tokens") or 0)
    if not image_tokens and not text_tokens:
        # Unknown input modality split: reserve at the more expensive image
        # input rate so settlement can never undercharge provider usage.
        image_tokens = total_input
    elif image_tokens + text_tokens < total_input:
        text_tokens += total_input - image_tokens - text_tokens
    output_tokens = int(usage.get("output_tokens") or 0)
    image_input_rate = Decimal("10") if key == "gpt_image_1" else Decimal("8")
    output_rate = Decimal("40") if key == "gpt_image_1" else Decimal("30")
    cost = (
        Decimal(text_tokens) * Decimal("5")
        + Decimal(image_tokens) * image_input_rate
        + Decimal(output_tokens) * output_rate
    ) / Decimal(1_000_000)
    return float(cost)


# =====================================================
# ЗАПРОС К AI-ПРОВАЙДЕРУ: call_grok_image
# Формирует официальный payload, отправляет запрос во внешний AI API и нормализует ответ для общего lifecycle генерации.
# =====================================================
def call_grok_image(frontend_model: str, provider_model: str, endpoint: str, prompt: str, payload: dict, size: str, count: int = 1) -> tuple[list, dict, dict, dict]:
    headers = grok_headers()
    if not headers:
        return [], image_error_response("grok", frontend_model, provider_model, endpoint, "Provider API key is missing"), {}, {}
    opts = payload.get("image_options") or {}
    resolution = grok_resolution_value(opts)
    input_image = grok_input_image_url(payload)
    is_style_edit = bool(input_image and grok_has_selected_style(payload))
    request_endpoint = endpoint
    if is_style_edit:
        request_endpoint = grok_image_edit_endpoint(endpoint)
        request_payload = {
            "model": provider_model,
            "prompt": (
                "Edit the supplied source image by applying the selected visual style. "
                "Treat the selected style as an instruction for this image, not as a request "
                "to create an unrelated image. Preserve the source image's main subject and "
                "composition while applying the style.\n\n"
                + str(prompt or "Apply the selected style to the source image.")
            ),
            "image": {"url": input_image, "type": "image_url"},
        }
    else:
        request_payload = {
            "model": provider_model,
            "prompt": prompt,
            "n": max(1, int(count or 1)),
            "aspect_ratio": grok_aspect_ratio(size),
            "resolution": resolution,
        }
        if input_image:
            request_payload["image_url"] = input_image
    try:
        prostudio_debug(
            "GROK_PROVIDER_REQUEST",
            endpoint=request_endpoint,
            frontend_model=frontend_model,
            provider_model=provider_model,
            aspect_ratio=request_payload.get("aspect_ratio"),
            resolution=request_payload.get("resolution"),
            count=request_payload.get("n"),
            has_input_image=bool(input_image),
            operation="style_edit" if is_style_edit else "generation",
        )
        response = requests.post(request_endpoint, headers=headers, json=request_payload, timeout=180)
    except requests.RequestException as exc:
        prostudio_error("GROK_PROVIDER_REQUEST_FAILED", exc, endpoint=request_endpoint, frontend_model=frontend_model, provider_model=provider_model)
        return [], image_error_response("grok", frontend_model, provider_model, request_endpoint, "Provider request failed", data={"body_preview": str(exc)[:1000]}), request_payload, {}
    data = safe_provider_json(response, "grok", request_endpoint)
    prostudio_debug(
        "GROK_PROVIDER_RESPONSE",
        endpoint=request_endpoint,
        status_code=response.status_code,
        data_keys=sorted(data.keys()) if isinstance(data, dict) else [],
        image_count=len(normalize_image_response(data)) if isinstance(data, dict) else 0,
    )
    if response.status_code >= 400 or data.get("ok") is False:
        return [], image_error_response("grok", frontend_model, provider_model, request_endpoint, data.get("error") or data.get("message") or "Provider request failed", response, data), request_payload, {}
    images = normalize_image_response(data)
    return images, {}, request_payload, {"usage": data.get("usage") or {}}


def google_image_headers() -> dict:
    api_key = env_value("GEMINI_API_KEY", "GEMINI-API-KEY", "GOOGLE_API_KEY", "GOOGLE-API-KEY")
    if not api_key:
        return {}
    return {
        "x-goog-api-key": api_key,
        "Content-Type": "application/json",
    }


def google_local_or_remote_image_part(url: str) -> dict:
    raw = str(url or "").strip()
    if not raw:
        return {}
    mime_type = "image/png"
    try:
        if raw.startswith("data:image/") and ";base64," in raw:
            head, data = raw.split(";base64,", 1)
            mime_type = head.replace("data:", "") or mime_type
            return {"type": "image", "mime_type": mime_type, "data": data}
        if storage_key_from_url(raw):
            data = storage_read_bytes(raw)
            suffix = pathlib.Path(urllib.parse.urlparse(raw).path).suffix.lower()
            if suffix in {".jpg", ".jpeg"}:
                mime_type = "image/jpeg"
            elif suffix == ".webp":
                mime_type = "image/webp"
            return {"type": "image", "mime_type": mime_type, "data": base64.b64encode(data).decode("utf-8")}
        if raw.startswith("/webapp/"):
            local_path = safe_local_path(WEBAPP_DIR, raw.replace("/webapp/", "", 1))
            data = local_path.read_bytes()
            suffix = local_path.suffix.lower()
            if suffix in {".jpg", ".jpeg"}:
                mime_type = "image/jpeg"
            elif suffix == ".webp":
                mime_type = "image/webp"
            return {"type": "image", "mime_type": mime_type, "data": base64.b64encode(data).decode("utf-8")}
        if raw.startswith("/generated/"):
            local_path = safe_local_path(WEBAPP_DIR, raw.replace("/generated/", "generated/", 1))
            data = local_path.read_bytes()
            suffix = local_path.suffix.lower()
            if suffix in {".jpg", ".jpeg"}:
                mime_type = "image/jpeg"
            elif suffix == ".webp":
                mime_type = "image/webp"
            return {"type": "image", "mime_type": mime_type, "data": base64.b64encode(data).decode("utf-8")}
        response = safe_get(raw, timeout=30)
        response.raise_for_status()
        content_type = (response.headers.get("content-type") or "").split(";")[0].strip().lower()
        if content_type.startswith("image/"):
            mime_type = content_type
        return {"type": "image", "mime_type": mime_type, "data": base64.b64encode(response.content).decode("utf-8")}
    except Exception as exc:
        print("GOOGLE IMAGE REFERENCE LOAD FAILED:", type(exc).__name__)
        return {}


def google_extract_images(data: dict) -> list:
    images = []

    def add_image(value, mime_type="image/png"):
        if isinstance(value, str) and value.strip():
            if value.startswith("http") or value.startswith("/"):
                images.append(value)
            else:
                images.append(f"data:{mime_type or 'image/png'};base64,{value}")

    def walk(node):
        if isinstance(node, dict):
            mime_type = node.get("mime_type") or node.get("mimeType") or "image/png"
            if isinstance(node.get("output_image"), dict):
                walk(node.get("output_image"))
            elif isinstance(node.get("output_image"), str):
                add_image(node.get("output_image"), mime_type)
            for key in ("data", "imageBytes", "bytesBase64Encoded"):
                if node.get(key):
                    add_image(node.get(key), mime_type)
            inline = node.get("inlineData") or node.get("inline_data")
            if isinstance(inline, dict):
                add_image(inline.get("data"), inline.get("mimeType") or inline.get("mime_type") or mime_type)
            for key in ("url", "uri"):
                if isinstance(node.get(key), str) and node.get(key).strip():
                    images.append(node[key].strip())
            for value in node.values():
                walk(value)
        elif isinstance(node, list):
            for item in node:
                walk(item)

    walk(data)
    clean = []
    for url in images:
        if url and url not in clean:
            clean.append(url)
    return clean


# =====================================================
# ЗАПРОС К AI-ПРОВАЙДЕРУ: call_google_image
# Формирует официальный payload, отправляет запрос во внешний AI API и нормализует ответ для общего lifecycle генерации.
# =====================================================
def call_google_image(frontend_model: str, provider_model: str, endpoint: str, prompt: str, payload: dict, size: str, count: int = 1) -> tuple[list, dict, dict, dict]:
    headers = google_image_headers()
    if not headers:
        return [], image_error_response("google", frontend_model, provider_model, endpoint, "Provider API key is missing"), {}, {}
    opts = payload.get("image_options") or {}
    key = google_image_frontend_model(frontend_model, provider_model)
    cfg = GOOGLE_IMAGE_MODEL_VARIANTS.get(key) or GOOGLE_IMAGE_MODEL_VARIANTS["nano_banana_2"]
    resolution = google_image_resolution(opts, key, provider_model)
    is_imagen = bool(cfg.get("imagen") or str(provider_model).startswith("imagen-"))
    aspect_ratio = google_image_aspect_ratio(size, imagen=is_imagen)

    if is_imagen:
        request_payload = {
            "instances": [{"prompt": prompt}],
            "parameters": {
                "sampleCount": max(1, min(int(count or 1), 4)),
                "aspectRatio": aspect_ratio,
            },
        }
        if key in {"imagen_4_standard", "imagen_4_ultra"}:
            request_payload["parameters"]["imageSize"] = resolution.upper()
        request_endpoint = endpoint.replace("{model}", provider_model)
    else:
        input_items = [{"type": "text", "text": prompt}]
        for ref in image_reference_urls(payload):
            part = google_local_or_remote_image_part(ref)
            if part:
                input_items.append(part)
        response_format = {
            "type": "image",
            "mime_type": "image/jpeg",
            "aspect_ratio": aspect_ratio,
            "image_size": google_interactions_image_size(resolution),
            "delivery": "inline",
        }
        request_payload = {
            "model": provider_model,
            "input": input_items,
            "store": False,
            "response_modalities": "image",
            "response_format": response_format,
        }
        request_endpoint = endpoint

    try:
        prostudio_debug(
            "GOOGLE_PROVIDER_REQUEST",
            endpoint=request_endpoint,
            frontend_model=frontend_model,
            provider_model=provider_model,
            aspect_ratio=aspect_ratio,
            resolution=resolution,
            count=count,
            is_imagen=is_imagen,
            has_references=bool(image_reference_urls(payload)),
            response_modalities=request_payload.get("response_modalities") if not is_imagen else [],
            response_format=request_payload.get("response_format") if not is_imagen else {},
        )
        response = requests.post(request_endpoint, headers=headers, data=json.dumps(request_payload), timeout=180)
    except requests.RequestException as exc:
        prostudio_error("GOOGLE_PROVIDER_REQUEST_FAILED", exc, endpoint=request_endpoint, frontend_model=frontend_model, provider_model=provider_model)
        return [], image_error_response("google", frontend_model, provider_model, request_endpoint, "Provider request failed", data={"body_preview": str(exc)[:1000]}), request_payload, {}
    data = safe_provider_json(response, "google", request_endpoint)
    prostudio_debug(
        "GOOGLE_PROVIDER_RESPONSE",
        endpoint=request_endpoint,
        status_code=response.status_code,
        data_keys=sorted(data.keys()) if isinstance(data, dict) else [],
        image_count=len(google_extract_images(data)) if isinstance(data, dict) else 0,
    )
    if response.status_code >= 400 or data.get("ok") is False:
        provider_error = provider_error_text(data.get("error") or data.get("message") or data, "Provider request failed")
        return [], image_error_response("google", frontend_model, provider_model, request_endpoint, provider_error, response, data), request_payload, {}
    return google_extract_images(data), {}, request_payload, {
        "usage": data.get("usage") or {},
        "usageMetadata": data.get("usageMetadata") or data.get("usage_metadata") or {},
    }


def sanitized_google_request_payload(request_payload: dict) -> dict:
    if not isinstance(request_payload, dict):
        return {}
    clean = json.loads(json.dumps(request_payload))
    input_items = clean.get("input")
    if isinstance(input_items, list):
        for item in input_items:
            if isinstance(item, dict) and item.get("data"):
                item["data"] = "[base64 image omitted]"
            if isinstance(item, dict) and isinstance(item.get("inlineData"), dict) and item["inlineData"].get("data"):
                item["inlineData"]["data"] = "[base64 image omitted]"
            if isinstance(item, dict) and isinstance(item.get("inline_data"), dict) and item["inline_data"].get("data"):
                item["inline_data"]["data"] = "[base64 image omitted]"
    return clean


# =====================================================
# ЗАПРОС К AI-ПРОВАЙДЕРУ: call_recraft_image
# Формирует официальный payload, отправляет запрос во внешний AI API и нормализует ответ для общего lifecycle генерации.
# =====================================================
def call_recraft_image(frontend_model: str, provider_model: str, endpoint: str, prompt: str, payload: dict, size: str, count: int = 1) -> tuple[list, dict, dict]:
    headers = recraft_headers()
    if not headers:
        return [], image_error_response("recraft", frontend_model, provider_model, endpoint, "Provider API key is missing"), {}
    opts = payload.get("image_options") or {}
    frontend_key = recraft_frontend_model(frontend_model, provider_model)
    seed_supported = bool((RECRAFT_MODEL_VARIANTS.get(frontend_key) or {}).get("seed"))
    seed = normalize_image_seed(opts.get("seed")) if seed_supported else None
    request_payload = {
        "prompt": prompt,
        "model": provider_model,
        "n": max(1, min(int(count or 1), 6)),
        "response_format": "url",
    }
    size_value = recraft_size_value(size)
    if size_value:
        request_payload["size"] = size_value
    if str(opts.get("photo_tool") or opts.get("tool") or "").strip().lower() == "logo":
        # Recraft V4.1 Pro Vector accepts style-reference URLs directly and
        # returns a native SVG from its vector generation endpoint.
        refs = image_reference_urls(payload)[:10]
        normalized_refs = []
        for ref in refs:
            raw_ref = str(ref or "").strip()
            if raw_ref.startswith("/webapp/"):
                local_path = safe_local_path(WEBAPP_DIR, raw_ref.replace("/webapp/", "", 1))
                content = local_path.read_bytes()
                mime = mimetypes.guess_type(local_path.name)[0] or "image/png"
                normalized_refs.append(f"data:{mime};base64,{base64.b64encode(content).decode('ascii')}")
            elif storage_key_from_url(raw_ref):
                content = storage_read_bytes(raw_ref)
                object_key = storage_key_from_url(raw_ref)
                mime = mimetypes.guess_type(object_key)[0] or "image/png"
                normalized_refs.append(f"data:{mime};base64,{base64.b64encode(content).decode('ascii')}")
            else:
                normalized_refs.append(raw_ref)
        if normalized_refs:
            request_payload["style_reference_urls"] = normalized_refs
        request_payload["style_match"] = "precise"
    if seed is not None:
        request_payload["random_seed"] = seed
    try:
        response = requests.post(endpoint, headers=headers, data=json.dumps(request_payload), timeout=120)
    except requests.RequestException as exc:
        return [], image_error_response("recraft", frontend_model, provider_model, endpoint, "Provider request failed", data={"body_preview": str(exc)[:1000]}), request_payload
    data = safe_provider_json(response, "recraft", endpoint)
    if response.status_code >= 400 or data.get("ok") is False:
        return [], image_error_response("recraft", frontend_model, provider_model, endpoint, data.get("error") or data.get("message") or "Provider request failed", response, data), request_payload
    images = normalize_image_response(data)
    return images, {}, request_payload


def sanitize_recraft_svg_xml(svg_bytes: bytes):
    """UPLOAD-3: parses and sanitizes a Recraft-returned SVG document in
    place - removes <script>/<foreignObject>/<iframe>/<object>/<embed>,
    event-handler attributes (onload, onclick, onerror, ...), and unsafe
    external href/src/url() references. Extracted out of
    persist_recraft_logo_assets() so the sanitizer can be exercised
    directly in tests without cairosvg/network/storage. Raises ValueError
    if the document isn't an SVG. Returns the sanitized root Element."""
    from xml.etree import ElementTree
    import re as _re

    root = ElementTree.fromstring(svg_bytes)
    if str(root.tag).split("}")[-1].lower() != "svg":
        raise ValueError("Recraft did not return an SVG document")
    blocked_tags = {"script", "foreignObject", "iframe", "object", "embed"}
    for parent in root.iter():
        for child in list(parent):
            if str(child.tag).split("}")[-1] in blocked_tags:
                parent.remove(child)
        for attr, value in list(parent.attrib.items()):
            # Strip event-handler attributes case-insensitively, regardless
            # of namespace prefix or odd casing (OnLoad, ONCLICK, ...) - an
            # attacker's only way to run script from an SVG we accept
            # otherwise, since <script> is already stripped above. Checked
            # before, and instead of, the href/src/url() checks so an
            # "on*" attribute can never fall through either branch unhandled.
            attr_name = str(attr).split("}")[-1].lower()
            if attr_name.startswith("on"):
                del parent.attrib[attr]
                continue
            value = str(value or "").strip()
            if attr_name in {"href", "src"} and value and not value.startswith(("#", "data:image/png;base64,", "data:image/jpeg;base64,", "data:image/webp;base64,")):
                del parent.attrib[attr]
            elif "url(" in value.lower() and _re.search(r"url\(\s*(['\"]?)(?!#|data:image/)[^)]+\)", value, _re.I):
                parent.attrib[attr] = _re.sub(r"url\(\s*(['\"]?)(?!#|data:image/)[^)]+\)", "none", value, flags=_re.I)
        if str(parent.tag).split("}")[-1].lower() == "style" and parent.text:
            parent.text = _re.sub(r"@import[^;]+;|url\(\s*(['\"]?)(?!#|data:image/)[^)]+\)", "", parent.text, flags=_re.I)
    return root


def persist_recraft_logo_assets(svg_url: str) -> tuple[str, str]:
    """Download native Recraft SVG, render a PNG preview, and persist both."""
    try:
        import cairosvg
        from xml.etree import ElementTree
    except ImportError as exc:
        raise RuntimeError("SVG preview renderer is unavailable") from exc
    response = safe_get(svg_url, timeout=120)
    response.raise_for_status()
    svg_bytes = response.content
    if not svg_bytes or len(svg_bytes) > 40 * 1024 * 1024:
        raise ValueError("Recraft returned an invalid or oversized SVG")
    root = sanitize_recraft_svg_xml(svg_bytes)
    svg_bytes = ElementTree.tostring(root, encoding="utf-8")
    try:
        view_box = [float(value) for value in str(root.get("viewBox") or "").replace(",", " ").split()]
        aspect = (view_box[2] / view_box[3]) if len(view_box) == 4 and view_box[2] > 0 and view_box[3] > 0 else 1.0
    except (TypeError, ValueError, ZeroDivisionError):
        aspect = 1.0
    aspect = min(10.0, max(0.1, aspect))
    max_preview_edge = 2048
    output_width = max_preview_edge if aspect >= 1 else max(1, round(max_preview_edge * aspect))
    output_height = max_preview_edge if aspect < 1 else max(1, round(max_preview_edge / aspect))
    png_bytes = cairosvg.svg2png(bytestring=svg_bytes, output_width=output_width, output_height=output_height)
    if not png_bytes:
        raise ValueError("Could not render the SVG preview")
    stem = uuid4().hex
    svg_saved_url = storage_put_bytes(svg_bytes, generated_key("documents", f"{stem}.svg"), "image/svg+xml")
    png_saved_url = storage_put_bytes(png_bytes, generated_key("images", f"{stem}.png"), "image/png")
    if not svg_saved_url or not png_saved_url:
        raise RuntimeError("Could not save the logo SVG and PNG preview")
    return svg_saved_url, png_saved_url


# =====================================================
# БАЛАНС И СТОИМОСТЬ: estimate_generation_cost
# Рассчитывает стоимость генерации, проверяет токены пользователя или фиксирует списание после успешного результата.
# =====================================================
# ElevenLabs Music is billed per generated minute (and an uploaded reference
# is billed like generated audio of its length). Override with the actual
# per-minute rate of the ElevenLabs account if it differs.
ELEVENLABS_MUSIC_USD_PER_MINUTE = Decimal(os.getenv("ELEVENLABS_MUSIC_USD_PER_MINUTE") or "0.15")


def elevenlabs_music_cost_info(music_options: dict) -> dict:
    """Duration-based price: provider cost of the requested length (plus the
    reference, if any) -> SYLVEX rule (x1.5, credits, round up)."""
    length_ms = elevenlabs_music_length_ms(music_options)
    reference = music_reference_audio(music_options)
    reference_ms = min(ELEVENLABS_MUSIC_REFERENCE_MAX_MS, reference["duration_ms"] or ELEVENLABS_MUSIC_REFERENCE_MAX_MS) if reference else 0
    provider_cost = (Decimal(length_ms + reference_ms) / Decimal(60000)) * ELEVENLABS_MUSIC_USD_PER_MINUTE
    credits = sylvex_credits(provider_cost)
    return {"credits": credits, "cost_usd": float(round(provider_cost, 4)), "generation_cost": f"{credits} ⚡",
            "pricing_available": credits > 0, "model_label": "ElevenLabs Music"}


def validate_music_reference_request(payload: dict) -> Optional[dict]:
    """A music reference is only accepted for a model that really sends it to
    the provider; otherwise the request is rejected, never silently ignored."""
    music_options = payload.get("music_options") or {}
    if not isinstance(music_options, dict) or "reference_audio" not in music_options:
        return None
    reference = music_reference_audio(music_options)
    model = str(music_options.get("model") or payload.get("model") or "").lower()
    if not reference:
        return {"ok": False, "type": "music", "error": "reference_invalid", "message": "Аудио-референс не загружен"}
    if model not in MUSIC_REFERENCE_MODELS:
        return {"ok": False, "type": "music", "error": "reference_not_supported", "message": "Эта модель не поддерживает аудио-референс"}
    if not reference["url"].startswith(("https://", "http://", "/")):
        return {"ok": False, "type": "music", "error": "reference_invalid", "message": "Аудио-референс не загружен"}
    if reference["duration_ms"] > ELEVENLABS_MUSIC_REFERENCE_MAX_MS:
        return {"ok": False, "type": "music", "error": "reference_too_long", "message": "Референс должен быть не длиннее 30 секунд"}
    return None


VOICE_DIALOGUE_ERRORS = {
    "dialogue_empty": "Добавьте хотя бы одну реплику",
    "dialogue_too_many_blocks": "Слишком много реплик в одном диалоге",
    "dialogue_invalid_block": "Реплика диалога повреждена. Обновите страницу",
    "dialogue_voice_missing": "Назначьте голос каждой реплике",
    "dialogue_text_missing": "Заполните текст каждой реплики",
    "dialogue_too_many_voices": "В одном диалоге можно использовать до 10 голосов",
    "dialogue_too_long": "Диалог длиннее 2000 символов. Сократите текст",
    "dialogue_model_not_supported": "Эта модель не поддерживает диалог по ролям",
}


def gallery_dialogue_blocks(metadata: dict) -> list:
    """Saved Quick Voice blocks (order, voice, text with inline tags) so a
    dialogue can be reopened and edited from history."""
    settings = metadata.get("settings") if isinstance(metadata.get("settings"), dict) else {}
    blocks = settings.get("dialogue_blocks")
    if not isinstance(blocks, list):
        return []
    return [
        {"voice_id": str(block.get("voice_id") or "")[:64], "voice_name": str(block.get("voice_name") or "")[:80], "text": str(block.get("text") or "")[:2000]}
        for block in blocks[:60] if isinstance(block, dict)
    ]


def normalize_voice_dialogue_request(payload: dict) -> Optional[dict]:
    """Quick Voice sends an ordered list of blocks, each with its own voice.
    The blocks are validated, the request is pinned to Text to Dialogue and
    the billed prompt is rebuilt from the blocks so the price always matches
    the text that is really voiced."""
    voice_options = payload.get("voice_options")
    if not isinstance(voice_options, dict) or "dialogue_blocks" not in voice_options:
        return None
    try:
        blocks = dialogue_blocks_from_options(voice_options)
    except ValueError as exc:
        code = str(exc)
        return {"ok": False, "type": "voice", "error": code, "message": VOICE_DIALOGUE_ERRORS.get(code, "Диалог не удалось отправить")}
    model = str(voice_options.get("model") or payload.get("model") or "").lower()
    if model not in ELEVENLABS_DIALOGUE_MODELS:
        return {"ok": False, "type": "voice", "error": "dialogue_model_not_supported", "message": VOICE_DIALOGUE_ERRORS["dialogue_model_not_supported"]}
    if model not in ELEVENLABS_DIALOGUE_TAG_MODELS:
        # Only Eleven v3 understands [tags]; other models would read them
        # aloud, so they are removed before voicing and before pricing.
        for block in blocks:
            block["text"] = strip_audio_tags(block["text"])
        if any(not block["text"] for block in blocks):
            return {"ok": False, "type": "voice", "error": "dialogue_text_missing", "message": VOICE_DIALOGUE_ERRORS["dialogue_text_missing"]}
    voices = list(dict.fromkeys(block["voice_id"] for block in blocks))
    voice_options.update({
        "model": model,
        "provider": "elevenlabs",
        "elevenlabs_tool": "dialogue",
        "dialogue_blocks": blocks,
        "speaker_voices": voices,
        "num_speakers": len(voices),
        "elevenlabs_voice": voices[0],
    })
    payload["model"] = model
    payload["provider"] = "elevenlabs"
    payload["prompt"] = "\n".join(block["text"] for block in blocks)
    return None


def estimate_generation_cost(payload: dict) -> dict:
    mode = (payload.get("mode") or payload.get("category") or "").lower()
    if mode == "music":
        model = str((payload.get("music_options") or {}).get("model") or payload.get("model") or "").lower()
        if model in ELEVENLABS_MUSIC_MODELS:
            return elevenlabs_music_cost_info(payload.get("music_options") or {})
        fixed_prices = {
            "google_lyria_3_pro": 12, "google_lyria_3_clip": 6,
            # Suno through the UdioAPI aggregator (services/audio_router.py):
            # SYLVEX's own per-generation prices. The other Chirp versions
            # stay unpriced (blocked) until they get one.
            "suno_chirp_5_5": 18, "suno_chirp_6": 18, "suno_chirp_6_mini": 15,
        }
        credits = fixed_prices.get(model)
        if credits is None:
            return {"credits": 0, "cost_usd": 0, "generation_cost": "", "pricing_available": False}
        return {"credits": credits, "cost_usd": round(credits / 150, 4), "generation_cost": f"{credits} ⚡", "pricing_available": True}
    if mode == "voice":
        options = payload.get("voice_options") or {}
        model = str(options.get("model") or payload.get("model") or "").lower()
        tool = str(options.get("runway_tool") or options.get("elevenlabs_tool") or "text_to_speech").lower()
        duration = max(1, int(float(options.get("duration") or 5)))
        characters = max(1, len(str(payload.get("prompt") or "")))
        if model.startswith("elevenlabs_"):
            # Existing per-character TTS tariff; every other ElevenLabs tool
            # has no confirmed cost basis and is not priced (fail closed).
            if elevenlabs_dispatch_tool(payload) not in ELEVENLABS_PRICED_TOOLS:
                return {"credits": 0, "cost_usd": 0, "generation_cost": "", "pricing_available": False}
            usd_per_thousand = Decimal("0.05") if any(value in model for value in ("flash", "turbo")) else Decimal("0.10")
            provider_cost = Decimal(characters) * usd_per_thousand / Decimal(1000)
            credits = max(1, sylvex_credits(provider_cost))
        elif model in {
            "gemini_3_1_flash_tts_preview",
            "gemini_2_5_flash_preview_tts",
            "gemini-3.1-flash-tts-preview",
            "gemini-2.5-flash-preview-tts",
        }:
            input_tokens = len(str(payload.get("prompt") or "").encode("utf-8"))
            output_tokens = duration * 25
            provider_cost = Decimal(input_tokens) * Decimal("0.50") / Decimal(1_000_000) + Decimal(output_tokens) * Decimal("10.00") / Decimal(1_000_000)
            if model in {"gemini_3_1_flash_tts_preview", "gemini-3.1-flash-tts-preview"}:
                provider_cost = Decimal(input_tokens) * Decimal("1.00") / Decimal(1_000_000) + Decimal(output_tokens) * Decimal("20.00") / Decimal(1_000_000)
            credits = max(1, sylvex_credits(provider_cost))
        elif model in {
            "gemini_2_5_pro_preview_tts",
            "gemini-2.5-pro-preview-tts",
        }:
            input_tokens = len(str(payload.get("prompt") or "").encode("utf-8"))
            output_tokens = duration * 25
            provider_cost = Decimal(input_tokens) * Decimal("1.00") / Decimal(1_000_000) + Decimal(output_tokens) * Decimal("20.00") / Decimal(1_000_000)
            credits = max(1, sylvex_credits(provider_cost))
        elif model.startswith("runway_") and tool == "sound_effect":
            credits = max(1, sylvex_credits(Decimal(duration) * Decimal("0.01")))
        elif model.startswith("runway_") and tool == "voice_isolation":
            credits = max(1, sylvex_credits(Decimal((duration + 5) // 6) * Decimal("0.01")))
        elif model.startswith("runway_") and tool == "voice_dubbing":
            credits = max(1, sylvex_credits(Decimal((duration + 1) // 2) * Decimal("0.01")))
        elif model.startswith("runway_") and tool == "speech_to_speech":
            credits = max(1, sylvex_credits(Decimal((duration + 2) // 3) * Decimal("0.01")))
        elif model.startswith("runway_"):
            credits = max(1, sylvex_credits(Decimal((characters + 49) // 50) * Decimal("0.01")))
        else:
            return {"credits": 0, "cost_usd": 0, "generation_cost": "", "pricing_available": False}
        return {"credits": credits, "cost_usd": round(credits / 150, 4), "generation_cost": f"{credits} ⚡", "pricing_available": True}
    if mode in {"text", "chat", "pro", "lite"}:
        model = normalize_text_model(payload.get("model") or "gpt-5.5")
        if not text_token_rates(model) or text_media_attachment(payload):
            return {"credits": 0, "cost_usd": 0, "generation_cost": "", "pricing_available": False}
        # Reservation upper bound; /generate settles on reported usage.
        credits, input_tokens, output_tokens = text_generation_reservation(payload)
        credits = max(1, credits)
        return {"credits": credits, "cost_usd": round(credits / 150, 4), "generation_cost": f"{credits} ⚡", "pricing_available": True,
                "billing": "usage", "max_credits": credits, "max_input_tokens": input_tokens, "output_token_cap": output_tokens}
    if mode == "video" and is_enhance_video_request(payload):
        info = enhance_video_cost_info(payload)
        info["operation"] = ENHANCE_VIDEO_TOOL_KEY
        return info
    if mode == "video" and is_animate_photo_request(payload):
        # Animate Photo is a flat 5-second Runway Gen-4.5 clip (unlike the
        # generic per-second/per-model video pricing table below) - always
        # the same 90 credits, computed from the named, adjustable Runway
        # rate constants rather than a hardcoded literal.
        info = animate_photo_cost_info()
        return {
            "credits": info["credits"],
            "cost_credits": info["credits"],
            "cost_usd": info["cost_usd"],
            "generation_cost": info["generation_cost"],
            "pricing_available": True,
            "operation": ANIMATE_PHOTO_TOOL_KEY,
        }
    if mode == "video":
        return estimate_video_generation_cost(payload)
    if mode != "image":
        return {"credits": 0, "cost_usd": 0, "generation_cost": ""}
    opts = payload.get("image_options") or {}
    # Operations below are existing product tools.  Their published tariffs
    # live here with every other authoritative estimate, not in either client.
    tool = str(opts.get("image_tool") or opts.get("tool") or opts.get("operation") or "").strip().lower()
    if tool == "try_on":
        # FASHN bills per garment (see generate_try_on_image, which chains
        # one /v1/run call per uploaded garment) - the price scales with it
        # instead of being a flat per-request fee like the other tools below.
        garment_count = max(1, min(FASHN_MAX_GARMENTS, len(opts.get("tryOnGarmentUrls") or [])))
        credits = FASHN_TRYON_CREDITS_PER_GARMENT * garment_count
        return {
            "credits": credits,
            "cost_credits": credits,
            "cost_usd": round(credits / 150, 4),
            "generation_cost": f"{credits} ⚡",
            "pricing_available": True,
            "operation": tool,
        }
    if tool == "remove_background":
        # Placed before tool_prices below - that dict's own "remove_bg" key
        # is a pre-existing, unrelated Recraft flat fee and must never be
        # matched by this tool's deliberately distinct "remove_background"
        # value.
        credits = IDEOGRAM_REMOVE_BG_CREDITS
        return {
            "credits": credits,
            "cost_credits": credits,
            "cost_usd": round(credits / 150, 4),
            "generation_cost": f"{credits} ⚡",
            "pricing_available": True,
            "operation": tool,
        }
    if tool == CHARACTER_REPLACE_TOOL_KEY:
        # Character Replace's real provider cost varies with how many
        # images the chosen identity source actually contributes (a plain
        # History/Upload image vs. a Character's avatar + up to 3
        # references), so - unlike the flat per-tool prices below - its
        # price is computed from the real image count via
        # character_replace_cost_info() (BFL's own $0.07 first-MP +
        # $0.03/extra-MP + $0.03/input-image formula, +50% SYLVEX markup).
        info = character_replace_cost_info(character_replace_input_image_count(opts))
        return {
            "credits": info["credits"],
            "cost_credits": info["credits"],
            "cost_usd": info["cost_usd"],
            "generation_cost": info["generation_cost"],
            "pricing_available": True,
            "operation": tool,
        }
    if tool == ENHANCE_PHOTO_TOOL_KEY:
        if str(opts.get("enhancePhotoModel") or "topaz").strip().lower() == SYLVEX_RESTORE_MODEL_KEY:
            return sylvex_restore_cost_info(opts)
        # Enhance Photo is a flat 1-Topaz-credit-per-request cost (unlike
        # Character Replace's per-image formula above) - always the same
        # 15 credits, computed from the named, adjustable
        # TOPAZ_CREDIT_COST_USD constant rather than a hardcoded literal.
        info = enhance_photo_cost_info()
        return {
            "credits": info["credits"],
            "cost_credits": info["credits"],
            "cost_usd": info["cost_usd"],
            "generation_cost": info["generation_cost"],
            "pricing_available": True,
            "operation": tool,
        }
    tool_prices = {
        "tryon": 9,             # Google Virtual Try-On
        "remove_bg": 2,         # Recraft Remove Background
        "upscaler": 1,          # Recraft Upscale / Refine
        "face_swap": 21,        # Nano Banana Pro image edit
    }
    if tool in tool_prices:
        credits = tool_prices[tool]
        return {
            "credits": credits,
            "cost_credits": credits,
            "cost_usd": round(credits / 150, 4),
            "generation_cost": f"{credits} ⚡",
            "pricing_available": True,
            "operation": tool,
        }
    requested_model = opts.get("modelId") or opts.get("model_id") or payload.get("model")
    mapping = image_provider_mapping(requested_model) if requested_model else {}
    provider = (mapping.get("provider") or payload.get("provider") or "").strip().lower()
    api_model = mapping.get("provider_model") or ""
    if provider == "openai":
        count = safe_image_count(opts.get("count") or 1, default=1, max_count=4)
        quality = normalize_openai_image_quality(requested_model, api_model, opts)
        refs = image_reference_urls(payload)
        info = openai_image_cost_info(
            requested_model, api_model, quality, count,
            prompt_text=payload.get("prompt") or "", reference_count=len(refs),
        )
        return {
            "credits": int(info.get("cost_credits") or info.get("cost") or 0),
            "cost_usd": info.get("cost_usd") or 0,
            "generation_cost": info.get("generation_cost") or "",
            "unit_cost_credits": info.get("unit_cost_credits") or 0,
            "unit_cost_usd": info.get("unit_cost_usd") or 0,
            "quality": info.get("quality") or "",
            "model_label": info.get("model_label") or "",
        }
    if provider == "recraft":
        count = safe_image_count(opts.get("count") or 1, default=1, max_count=4)
        info = recraft_cost_info(requested_model, api_model, count)
        return {
            "credits": int(info.get("cost_credits") or info.get("cost") or 0),
            "cost_usd": info.get("cost_usd") or 0,
            "generation_cost": info.get("generation_cost") or "",
            "unit_cost_credits": info.get("unit_cost_credits") or 0,
            "unit_cost_usd": info.get("unit_cost_usd") or 0,
            "model_label": info.get("model_label") or "",
        }
    if provider in ("byteplus", "bytedance") or re.search(r"seedream", f"{requested_model or ''} {api_model or ''}", re.I):
        count = safe_image_count(opts.get("count") or 1, default=1, max_count=4)
        requested_size = opts.get("size") or opts.get("resolution") or ""
        quality = normalize_seedream_quality(requested_model, api_model, opts)
        info = seedream_cost_info(
            requested_model, api_model, count, seedream_size_value(requested_size, quality),
            reference_count=len(image_reference_urls(payload)),
        )
        return {
            "credits": int(info.get("cost_credits") or info.get("cost") or 0),
            "cost_usd": info.get("cost_usd") or 0,
            "generation_cost": info.get("generation_cost") or "",
            "unit_cost_credits": info.get("unit_cost_credits") or 0,
            "unit_cost_usd": info.get("unit_cost_usd") or 0,
            "model_label": info.get("model_label") or "",
        }
    if provider == "flux":
        count = safe_image_count(opts.get("count") or 1, default=1, max_count=4)
        refs = image_reference_urls(payload)
        info = flux_cost_info(
            requested_model, api_model, count,
            output_size=opts.get("size") or opts.get("resolution") or "",
            reference_sizes=[1] * len(refs),
        )
        return {
            "credits": int(info.get("cost_credits") or info.get("cost") or 0),
            "cost_usd": info.get("cost_usd") or 0,
            "generation_cost": info.get("generation_cost") or "",
            "unit_cost_credits": info.get("unit_cost_credits") or 0,
            "unit_cost_usd": info.get("unit_cost_usd") or 0,
            "model_label": info.get("model_label") or "",
        }
    if provider == "qwen":
        count = safe_image_count(opts.get("count") or 1, default=1, max_count=4)
        info = qwen_cost_info(requested_model, api_model, count)
        return {
            "credits": int(info.get("cost_credits") or info.get("cost") or 0),
            "cost_usd": info.get("cost_usd") or 0,
            "generation_cost": info.get("generation_cost") or "",
            "unit_cost_credits": info.get("unit_cost_credits") or 0,
            "unit_cost_usd": info.get("unit_cost_usd") or 0,
            "model_label": info.get("model_label") or "",
        }
    if provider == "google":
        count = safe_image_count(opts.get("count") or 1, default=1, max_count=4)
        resolution = google_image_resolution(opts, requested_model, api_model)
        refs = image_reference_urls(payload)
        info = google_image_cost_info(
            requested_model, api_model, count, resolution, bool(refs),
            reference_count=len(refs), prompt_text=payload.get("prompt") or "",
        )
        return {
            "credits": int(info.get("cost_credits") or info.get("cost") or 0),
            "cost_usd": info.get("cost_usd") or 0,
            "generation_cost": info.get("generation_cost") or "",
            "unit_cost_credits": info.get("unit_cost_credits") or 0,
            "unit_cost_usd": info.get("unit_cost_usd") or 0,
            "resolution": info.get("resolution") or "",
            "model_label": info.get("model_label") or "",
            "input_image_credits": info.get("input_image_credits") or 0,
            "input_image_cost_included": bool(info.get("input_image_cost_included")),
        }
    if provider in ("grok", "xai"):
        count = safe_image_count(opts.get("count") or 1, default=1, max_count=4)
        resolution = grok_resolution_value(opts)
        refs = image_reference_urls(payload)
        info = grok_cost_info(requested_model, api_model, count, resolution, grok_has_input_image(payload), len(refs))
        return {
            "credits": int(info.get("cost_credits") or info.get("cost") or 0),
            "cost_usd": info.get("cost_usd") or 0,
            "generation_cost": info.get("generation_cost") or "",
            "unit_cost_credits": info.get("unit_cost_credits") or 0,
            "unit_cost_usd": info.get("unit_cost_usd") or 0,
            "resolution": info.get("resolution") or "",
            "model_label": info.get("model_label") or "",
            "input_image_credits": info.get("input_image_credits") or 0,
            "input_image_surcharge_provisional": bool(info.get("input_image_surcharge_provisional")),
        }
    if provider != "ideogram":
        return {"credits": 0, "cost_usd": 0, "generation_cost": ""}
    count = safe_image_count(opts.get("count") or 1, default=1, max_count=4)
    speed = ideogram_rendering_speed(requested_model, api_model, opts)
    info = ideogram_cost_info(requested_model, api_model, speed, count, False)
    return {
        "credits": int(info.get("cost_credits") or info.get("cost") or 0),
        "cost_usd": info.get("cost_usd") or 0,
        "generation_cost": info.get("generation_cost") or "",
        "unit_cost_credits": info.get("unit_cost_credits") or 0,
        "unit_cost_usd": info.get("unit_cost_usd") or 0,
        "model_label": info.get("model_label") or "",
    }


def voice_provider_usage_cost_usd(payload: dict, result: dict) -> Optional[float]:
    """Use provider-reported voice usage when it is available."""
    if not isinstance(result, dict):
        return None

    nodes = []

    def walk(value):
        if isinstance(value, dict):
            nodes.append(value)
            for child in value.values():
                walk(child)
        elif isinstance(value, list):
            for child in value:
                walk(child)

    walk(result)
    providers = {str(node.get("provider") or "").strip().lower() for node in nodes}
    options = payload.get("voice_options") or {}
    frontend_model = str(
        result.get("model") or options.get("model") or payload.get("model") or ""
    ).strip().lower()

    if "elevenlabs" in providers or frontend_model.startswith("elevenlabs_"):
        for node in nodes:
            raw = node.get("character_cost")
            if raw in (None, ""):
                continue
            try:
                billed_characters = max(0, int(float(raw)))
            except (TypeError, ValueError):
                continue
            usd_per_thousand = Decimal("0.05") if any(
                name in frontend_model for name in ("flash", "turbo")
            ) else Decimal("0.10")
            return float(Decimal(billed_characters) * usd_per_thousand / Decimal(1000))

    if "gemini" in providers or frontend_model.startswith("gemini"):
        rate = None
        if "3_1_flash" in frontend_model or "3.1-flash" in frontend_model:
            rate = (Decimal("1.00"), Decimal("20.00"))
        elif "2_5_flash" in frontend_model or "2.5-flash" in frontend_model:
            rate = (Decimal("0.50"), Decimal("10.00"))
        elif "2_5_pro" in frontend_model or "2.5-pro" in frontend_model:
            rate = (Decimal("1.00"), Decimal("20.00"))
        if rate:
            for node in nodes:
                usage = node.get("usageMetadata") or node.get("usage_metadata")
                if not isinstance(usage, dict) or not any(
                    key in usage for key in ("promptTokenCount", "candidatesTokenCount", "thoughtsTokenCount")
                ):
                    continue
                input_tokens = int(usage.get("promptTokenCount") or 0) + int(usage.get("toolUsePromptTokenCount") or 0)
                output_tokens = int(usage.get("candidatesTokenCount") or 0) + int(usage.get("thoughtsTokenCount") or 0)
                provider_cost = (
                    Decimal(input_tokens) * rate[0] + Decimal(output_tokens) * rate[1]
                ) / Decimal(1_000_000)
                return float(provider_cost)
    return None


def calculate_generation_price(payload: dict) -> dict:
    """Single entry point for all new estimates, reservations and settlements."""
    estimate = estimate_generation_cost(payload)
    if is_edit_workspace_request(payload) and str(payload.get("mode") or payload.get("category") or "image").lower() == "image":
        opts = payload.get("image_options") or {}
        operation = str(opts.get("editWorkspaceMode") or "edit").lower()
        if operation == "upscale":
            if is_edit_workspace_sylvex_restore(payload):
                estimate = sylvex_restore_cost_info(opts)
            else:
                settings = opts.get("editWorkspaceUpscale") if isinstance(opts.get("editWorkspaceUpscale"), dict) else {}
                settings = edit_workspace_service.upscale_parameters(settings)
                estimate = edit_upscale_cost_info(settings['width'], settings['height'])
        elif operation == "resize":
            estimate = {"credits": 0, "cost_credits": 0, "cost_usd": 0, "generation_cost": "0 ⚡", "pricing_available": True, "model_label": "Resize"}
        elif operation == "edit":
            selected_model = edit_workspace_image_model(payload)
            if selected_model not in EDIT_WORKSPACE_IMAGE_MODEL_IDS:
                estimate = {"credits": 0, "cost_usd": 0, "generation_cost": "", "pricing_available": False}
            # estimate_generation_cost() already resolved the selected model
            # and its real provider price before entering this workspace
            # override. Keep that estimate unchanged for the first Edit tool.
        else:
            source_url = str(opts.get("editWorkspaceSourceUrl") or opts.get("source_image_url") or "").strip()
            detail = openai_image_cost_info(
                "gpt_image_2_5_sunburst", "gpt-image-2.5-sunburst", "high", 1,
                prompt_text=opts.get("editWorkspacePrompt") or payload.get("prompt") or "",
                reference_count=1 if source_url else 0,
            )
            credits = max(1, int(detail.get("cost_credits") or 32))
            provider_cost = float(detail.get("cost_usd") or 0.3165)
            estimate = {"credits": credits, "cost_usd": provider_cost, "generation_cost": f"{credits} ⚡", "pricing_available": True, "model_label": "GPT Image 2.5 Sunburst"}
    video_options = payload.get("video_options") if isinstance(payload.get("video_options"), dict) else {}
    video_template = video_options.get("video_template") if isinstance(video_options.get("video_template"), dict) else {}
    if str(payload.get("mode") or payload.get("category") or "").lower() == "video" and video_template:
        model = str(video_template.get("preferred_model") or video_options.get("model") or payload.get("model") or "kling_o3_omni")
        duration = video_template.get("duration") or video_options.get("duration") or 5
        resolution = video_template.get("resolution") or video_options.get("resolution") or "720p"
        has_reference = bool(video_template.get("reference_video") or video_template.get("video_url") or video_template.get("template_video_url") or video_template.get("preview_video"))
        if has_reference:
            exact = video_catalog_template_price(model, int(duration), str(resolution), True)
            estimate = {**estimate, "credits": exact, "cost_credits": exact, "generation_cost": f"{exact} ⚡", "pricing_available": True}
    if is_remove_object_request(payload) and estimate.get("credits"):
        # Remove Object price = actual model generation cost + a flat Quick
        # Tool fee (REMOVE_OBJECT_TOOL_FEE_CREDITS). Added here - the single
        # choke point shared by the paywall check, the credit reservation
        # and the final settlement - so the fee is always part of the same
        # one reservation as the model cost and can never be charged (or
        # skipped) independently of it. No pricing UI reads this; per spec
        # the Quick Tool modal never displays cost.
        fee_credits = int(estimate["credits"]) + REMOVE_OBJECT_TOOL_FEE_CREDITS
        estimate = {**estimate, "credits": fee_credits, "cost_credits": fee_credits, "generation_cost": f"{fee_credits} ⚡"}
    if is_watermark_removal_request(payload) and estimate.get("credits"):
        fee_credits = int(estimate["credits"]) + WATERMARK_REMOVAL_TOOL_FEE_CREDITS
        estimate = {**estimate, "credits": fee_credits, "cost_credits": fee_credits, "generation_cost": f"{fee_credits} ⚡"}
    if not estimate.get("pricing_available", bool(estimate.get("credits"))):
        return estimate
    return apply_snapshot_to_estimate(payload, estimate)


# =====================================================
# ЗАГРУЗКА ФАЙЛОВ: ideogram_form_files
# Получает файл или ссылку, приводит её к безопасному формату и передаёт дальше в генерацию или сохранение.
# =====================================================
def ideogram_form_files(request_payload: dict) -> dict:
    return {
        key: (None, str(value))
        for key, value in (request_payload or {}).items()
        if value is not None and value != ""
    }


# =====================================================
# ЗАПРОС К AI-ПРОВАЙДЕРУ: call_ideogram_image
# Формирует официальный payload, отправляет запрос во внешний AI API и нормализует ответ для общего lifecycle генерации.
# =====================================================
def call_ideogram_image(frontend_model: str, provider_model: str, endpoint: str, prompt: str, payload: dict, size: str, count: int = 1) -> tuple[list, dict, dict]:
    headers = ideogram_headers(json_content=False)
    if not headers:
        return [], image_error_response("ideogram", frontend_model, provider_model, endpoint, "Provider API key is missing"), {}
    opts = payload.get("image_options") or {}
    frontend_key = ideogram_frontend_model(frontend_model, provider_model)
    rendering_speed = ideogram_rendering_speed(frontend_model, provider_model, opts)
    seed = normalize_image_seed(opts.get("seed")) if frontend_key == "ideogram_3_0" else None
    is_v4 = frontend_key == "ideogram_4_0"
    request_payload = {
        "rendering_speed": rendering_speed,
        **ideogram_size_params(frontend_model, provider_model, size),
    }
    if is_v4:
        request_payload["text_prompt"] = prompt
    else:
        request_payload["prompt"] = prompt
        request_payload["num_images"] = str(max(1, min(int(count or 1), 4)))
        if seed is not None:
            request_payload["seed"] = str(seed)

    images = []
    attempts = 1 if not is_v4 else max(1, min(int(count or 1), 4))
    try:
        for _ in range(attempts):
            response = requests.post(endpoint, headers=headers, files=ideogram_form_files(request_payload), timeout=120)
            data = safe_provider_json(response, "ideogram", endpoint)
            if response.status_code >= 400 or data.get("ok") is False:
                return [], image_error_response("ideogram", frontend_model, provider_model, endpoint, data.get("error") or "Provider request failed", response, data), request_payload
            for url in normalize_image_response(data):
                if url and url not in images:
                    images.append(url)
            if len(images) >= count:
                break
    except requests.RequestException as exc:
        return [], image_error_response("ideogram", frontend_model, provider_model, endpoint, "Provider request failed", data={"body_preview": str(exc)[:1000]}), request_payload
    return images, {}, request_payload


async def image_generation(payload: dict) -> dict:
    require_billing_scope("image_generation")
    if is_watermark_removal_request(payload):
        prostudio_error(
            "WATERMARK_REMOVAL_MISROUTED_TO_GENERIC_IMAGE_GENERATION",
            RuntimeError("watermark_removal job reached image_generation() instead of generate_watermark_removal_image()"),
            job_id=payload.get("job_id") or payload.get("generation_id") or "",
        )
        return {"ok": False, "type": "image", "error": "Не удалось удалить водяной знак. Попробуйте ещё раз.", "raw_error": "watermark_removal_misrouted_to_image_generation"}
    if is_edit_workspace_request(payload):
        prostudio_error("EDIT_WORKSPACE_MISROUTED_TO_GENERIC_IMAGE_GENERATION", RuntimeError("edit_workspace job reached generic image_generation"), job_id=payload.get("job_id") or "")
        return {"ok": False, "type": "image", "error": "Не удалось отредактировать изображение.", "raw_error": "edit_workspace_misrouted_to_image_generation"}
    if is_replace_object_request(payload):
        prostudio_error(
            "REPLACE_OBJECT_MISROUTED_TO_GENERIC_IMAGE_GENERATION",
            RuntimeError("replace_object job reached image_generation() instead of generate_replace_object_image()"),
            job_id=payload.get("job_id") or payload.get("generation_id") or "",
        )
        return {"ok": False, "type": "image", "error": "Не удалось создать изображение. Попробуйте ещё раз.", "raw_error": "replace_object_misrouted_to_image_generation"}
    if is_replace_character_request(payload):
        # Defense in depth: dispatch_prostudio_provider_request() must
        # always route a Character Replace job to
        # generate_character_replace_image() before it ever reaches this
        # generic dispatcher - if one gets here anyway (a future edit to
        # the dispatch ordering, a caller that bypasses
        # dispatch_prostudio_provider_request(), ...), fail loudly and
        # specifically instead of silently trying to map
        # "flux_2_max_character_replace" as if it were a real selectable
        # model.
        prostudio_error(
            "CHARACTER_REPLACE_MISROUTED_TO_GENERIC_IMAGE_GENERATION",
            RuntimeError("replace_character job reached image_generation() instead of generate_character_replace_image()"),
            job_id=payload.get("job_id") or payload.get("generation_id") or "",
        )
        return {
            "ok": False,
            "type": "image",
            "error": "Не удалось создать изображение. Попробуйте ещё раз.",
            "raw_error": "replace_character_misrouted_to_image_generation",
        }
    if is_enhance_photo_request(payload):
        # Defense in depth: dispatch_prostudio_provider_request() must
        # always route an Enhance Photo job to
        # generate_enhance_photo_image() before it ever reaches this
        # generic dispatcher - if one gets here anyway, fail loudly and
        # specifically instead of silently trying to map "topaz_enhance_
        # photo" as if it were a real selectable model.
        prostudio_error(
            "ENHANCE_PHOTO_MISROUTED_TO_GENERIC_IMAGE_GENERATION",
            RuntimeError("enhance_photo job reached image_generation() instead of generate_enhance_photo_image()"),
            job_id=payload.get("job_id") or payload.get("generation_id") or "",
        )
        return {
            "ok": False,
            "type": "image",
            "error": "Не удалось создать изображение. Попробуйте ещё раз.",
            "raw_error": "enhance_photo_misrouted_to_image_generation",
        }
    opts = payload.get("image_options") or {}
    prompt = build_image_prompt(payload)
    requested_model = opts.get("modelId") or opts.get("model_id") or payload.get("model")
    frontend_provider = (payload.get("provider") or "").strip().lower()
    prostudio_debug(
        "IMAGE_GENERATION_START",
        job_id=payload.get("job_id") or payload.get("generation_id") or "",
        requested_model=requested_model or "",
        frontend_provider=frontend_provider,
        size=opts.get("size") or opts.get("ratio") or "",
        count=opts.get("count") or 1,
        has_references=bool(image_reference_urls(payload)),
    )
    mapping = image_provider_mapping(requested_model) if requested_model else {}
    model_cfg = find_image_model(requested_model) or infer_image_model(requested_model, frontend_provider)

    if not mapping and requested_model:
        if frontend_provider in ("bytedance", "byteplus") or re.search(r"seedream", str(requested_model or ""), re.I):
            return unknown_byteplus_image_model_response(requested_model)
        return unknown_image_model_mapping_response(requested_model, frontend_provider)

    if not model_cfg and not mapping:
        return {
            "ok": False,
            "type": "image",
            "provider": frontend_provider,
            "model": requested_model or "",
            "error": "Unsupported image provider or model",
        }

    provider = (mapping.get("provider") or model_cfg.get("provider") or frontend_provider or "openai").strip().lower()
    api_model = mapping.get("provider_model") or model_cfg.get("api_model") or ""
    endpoint = mapping.get("endpoint") or model_cfg.get("endpoint") or ""

    if not api_model:
        return unknown_image_model_mapping_response(requested_model, provider)

    size = opts.get("size") or (model_cfg.get("sizes") or [{}])[0].get("id") or "1024x1024"
    count = safe_image_count(opts.get("count") or (model_cfg.get("counts") or [1])[0] or 1, default=1, max_count=4)
    prostudio_debug(
        "IMAGE_PROVIDER_RESOLVED",
        requested_model=requested_model or "",
        provider=provider,
        api_model=api_model,
        endpoint=endpoint,
        size=size,
        count=count,
    )

    if provider in ("byteplus", "bytedance") or re.search(r"seedream", api_model, re.I):
        if not BYTEPLUS_ARK_API_KEY:
            return image_error_response(provider, requested_model, api_model, f"{BYTEPLUS_ARK_ENDPOINT}/images/generations", "Provider API key is missing")

        images = []
        reference_images = image_reference_urls(payload)
        seed_supported = bool((SEEDREAM_MODEL_VARIANTS.get(seedream_frontend_model(requested_model, api_model)) or {}).get("seed"))
        seed = normalize_image_seed(opts.get("seed")) if seed_supported else None
        quality = normalize_seedream_quality(requested_model, api_model, opts)
        for index in range(1, count + 1):
            print(f"BYTEPLUS IMAGE REQUEST {index}/{count}")
            request_images, error = request_byteplus_seedream_image(api_model, prompt, reference_images, size=size, seed=seed, quality=quality)
            if request_images:
                for url in request_images:
                    if url and url not in images:
                        images.append(url)
                print(f"BYTEPLUS IMAGE SUCCESS {index}/{count}")
            else:
                print(f"BYTEPLUS IMAGE FAILED {index}/{count} {error or 'unknown error'}")
            if len(images) >= count:
                break
        if not images:
            return image_error_response(provider, requested_model, api_model, f"{BYTEPLUS_ARK_ENDPOINT}/images/generations", "Не удалось создать изображение. Попробуйте ещё раз.")
        result = await finalize_image_result(payload, images[:count])
        result.update(seedream_cost_info(requested_model, api_model, len(images[:count]), seedream_size_value(size, quality)))
        result["provider"] = "bytedance"
        result["model"] = requested_model
        result["provider_model"] = api_model
        return result

    if provider == "openai":
        if not OPENAI_API_KEY:
            return image_error_response(provider, requested_model, api_model, f"{OPENAI_API_BASE}/images/generations", "Provider API key is missing")
        openai_size = normalize_openai_image_size(size, requested_model, api_model)
        openai_quality = normalize_openai_image_quality(requested_model, api_model, opts)
        reference_images = image_reference_urls(payload)

        if reference_images:
            endpoint = f"{OPENAI_API_BASE}/images/edits"
            files = [
                file_part
                for file_part in (
                    openai_image_reference_file(url, index)
                    # One scene/source image plus avatar and three character references.
                    for index, url in enumerate(reference_images[:5])
                )
                if file_part
            ]
            if not files:
                return image_error_response(provider, requested_model, api_model, endpoint, "Не удалось обработать загруженное изображение.")

            request_data = {
                "model": api_model,
                "prompt": prompt,
                "size": openai_size,
                "quality": openai_quality,
                "n": str(count),
            }
            if api_model == "gpt-image-1":
                request_data["input_fidelity"] = "high"
            response = None
            request_exception = None
            for attempt in range(1, 3):
                try:
                    response = requests.post(
                        endpoint,
                        headers=openai_auth_headers(),
                        data=request_data,
                        files=files,
                        timeout=int(os.getenv("OPENAI_IMAGE_EDIT_TIMEOUT", "300")),
                    )
                    if response.status_code not in {408, 409, 429, 500, 502, 503, 504}:
                        break
                    print("OPENAI IMAGE EDIT TRANSIENT RESPONSE:", {
                        "attempt": attempt,
                        "status_code": response.status_code,
                        "model": api_model,
                    })
                except requests.RequestException as exc:
                    request_exception = exc
                    print("OPENAI IMAGE EDIT TRANSIENT ERROR:", {
                        "attempt": attempt,
                        "error": type(exc).__name__,
                        "model": api_model,
                    })
                if attempt < 2:
                    time.sleep(2)
            if response is None:
                return image_error_response(
                    provider,
                    requested_model,
                    api_model,
                    endpoint,
                    request_exception or "Provider request failed",
                    data={"body_preview": str(request_exception or "")[:1000]},
                )
            if response.status_code >= 400:
                data = safe_provider_json(response, provider, endpoint)
                return image_error_response(provider, requested_model, api_model, endpoint, data.get("error") or data.get("message") or "Provider request failed", response, data)
            data = safe_provider_json(response, provider, endpoint)
            images = normalize_image_response(data)
            print("OPENAI IMAGE EDIT PAYLOAD:", {"frontend_model": requested_model, "provider_model": api_model, "endpoint": endpoint, "references": len(files), "requested_count": count, "images_returned": len(images)})
            if images:
                final_images = images[:count]
                result = await finalize_image_result(payload, final_images)
                result.update(openai_image_cost_info(requested_model, api_model, openai_quality, len(final_images) or count))
                result["provider"] = "openai"
                result["model"] = requested_model
                result["provider_model"] = api_model
                result["quality"] = openai_quality
                result["request_payload"] = {**request_data, "image_count": len(files)}
                result["metadata"] = {"usage": data.get("usage") or {}}
                actual_cost = openai_image_usage_cost_usd(requested_model, api_model, data.get("usage") or {})
                if actual_cost is not None:
                    result["provider_cost_usd_actual"] = actual_cost
                return result
            return image_error_response(provider, requested_model, api_model, endpoint, "Provider returned no image")

        endpoint = f"{OPENAI_API_BASE}/images/generations"
        images = []
        # gpt-image-1/gpt-image-2 support n=1..4 natively on this endpoint; request
        # the whole batch in one call instead of one request per image so quantity
        # 1-4 costs one provider round trip, not up to four sequential ones.
        request_payload = {
            "model": api_model,
            "prompt": prompt,
            "size": openai_size,
            "quality": openai_quality,
            "n": count,
        }
        last_payload = request_payload
        try:
            response = requests.post(
                endpoint,
                headers=openai_headers(),
                data=json.dumps(request_payload),
                timeout=180,
            )
        except requests.RequestException as exc:
            return image_error_response(provider, requested_model, api_model, endpoint, "Provider request failed", data={"body_preview": str(exc)[:1000]})
        if response.status_code >= 400:
            data = safe_provider_json(response, provider, endpoint)
            return image_error_response(provider, requested_model, api_model, endpoint, data.get("error") or data.get("message") or "Provider request failed", response, data)
        data = safe_provider_json(response, provider, endpoint)
        if data.get("ok") is False:
            return image_error_response(provider, requested_model, api_model, endpoint, data.get("error") or "Provider returned invalid response", data=data)
        for url in normalize_image_response(data):
            if url and url not in images:
                images.append(url)
        print("OPENAI IMAGE PAYLOAD:", {"frontend_model": requested_model, "provider_model": api_model, "endpoint": endpoint, "requested_count": count, "payload": request_payload, "images_returned": len(images)})
        if images:
            final_images = images[:count]
            result = await finalize_image_result(payload, final_images)
            result.update(openai_image_cost_info(requested_model, api_model, openai_quality, len(final_images) or count))
            result["provider"] = "openai"
            result["model"] = requested_model
            result["provider_model"] = api_model
            result["quality"] = openai_quality
            result["request_payload"] = last_payload
            result["metadata"] = {"usage": data.get("usage") or {}}
            actual_cost = openai_image_usage_cost_usd(requested_model, api_model, data.get("usage") or {})
            if actual_cost is not None:
                result["provider_cost_usd_actual"] = actual_cost
            return result
        return image_error_response(provider, requested_model, api_model, endpoint, "Provider returned no image")

    if provider == "flux":
        images = []
        last_payload = {}
        for index in range(1, count + 1):
            request_images, error, request_payload = call_flux_image(requested_model, api_model, endpoint, prompt, payload, size)
            last_payload = request_payload
            print("FLUX IMAGE PAYLOAD:", {"frontend_model": requested_model, "provider_model": api_model, "endpoint": endpoint, "attempt": index, "payload": request_payload})
            if error:
                return error
            for url in request_images or []:
                if url and url not in images:
                    images.append(url)
            if len(images) >= count:
                break
        if images:
            final_images = images[:count]
            result = await finalize_image_result(payload, final_images)
            result.update(flux_cost_info(requested_model, api_model, len(final_images) or count))
            result["provider"] = "flux"
            result["model"] = requested_model
            result["provider_model"] = api_model
            result["request_payload"] = last_payload
            return result
        return image_error_response(provider, requested_model, api_model, endpoint, "Provider returned no image")

    if provider == "recraft":
        images, error, request_payload = call_recraft_image(requested_model, api_model, endpoint, prompt, payload, size, count)
        debug_payload = dict(request_payload or {})
        if debug_payload.get("style_reference_urls"):
            debug_payload["style_reference_urls"] = ["[style reference omitted]"] * len(debug_payload["style_reference_urls"])
        print("RECRAFT IMAGE PAYLOAD:", {"frontend_model": requested_model, "provider_model": api_model, "endpoint": endpoint, "payload": debug_payload})
        if error:
            return error
        if images:
            is_logo_vector = str((payload.get("image_options") or {}).get("photo_tool") or "").strip().lower() == "logo" and recraft_frontend_model(requested_model, api_model) == "recraft_v4_1_pro_vector"
            svg_url = ""
            if is_logo_vector:
                try:
                    svg_url, preview_url = await asyncio.to_thread(persist_recraft_logo_assets, images[0])
                except Exception as exc:
                    prostudio_error("RECRAFT_LOGO_ASSET_SAVE_FAILED", exc)
                    return image_error_response(provider, requested_model, api_model, endpoint, "Не удалось сохранить SVG и PNG-preview логотипа", data={"body_preview": str(exc)[:500]})
                final_images = [preview_url]
            else:
                final_images = images[:count]
            result = await finalize_image_result(payload, final_images)
            result.update(recraft_cost_info(requested_model, api_model, len(final_images) or count))
            result["provider"] = "recraft"
            result["model"] = requested_model
            result["provider_model"] = api_model
            if is_logo_vector:
                result["svg_url"] = svg_url
                result["svg_download_url"] = svg_url
                result["svg_urls"] = [svg_url]
            return result
        return image_error_response(provider, requested_model, api_model, endpoint, "Provider returned no image")

    if provider == "google":
        # Imagen models batch natively via sampleCount and return `count` images
        # in one call. Gemini's generateContent-based image models (nano banana)
        # have no batching parameter and always return exactly one image per
        # call, so repeat the call until `count` is reached, same as BytePlus.
        images = []
        error = None
        request_payload = {}
        provider_usage = []
        for attempt in range(1, count + 1):
            call_images, call_error, request_payload, call_usage = call_google_image(requested_model, api_model, endpoint, prompt, payload, size, count)
            if call_usage:
                provider_usage.append(call_usage)
            print("GOOGLE IMAGE PAYLOAD:", {
                "frontend_model": requested_model,
                "provider_model": api_model,
                "endpoint": endpoint,
                "payload_keys": list((request_payload or {}).keys()),
                "has_references": bool(image_reference_urls(payload)),
                "attempt": attempt,
            })
            if call_error:
                if not images:
                    error = call_error
                break
            for url in call_images or []:
                if url and url not in images:
                    images.append(url)
            if len(images) >= count:
                break
        if error:
            return error
        if images:
            final_images = images[:count]
            opts = payload.get("image_options") or {}
            result = await finalize_image_result(payload, final_images)
            result.update(google_image_cost_info(
                requested_model,
                api_model,
                len(final_images) or count,
                google_image_resolution(opts, requested_model, api_model),
                google_has_input_image(payload),
            ))
            result["provider"] = "google"
            result["model"] = requested_model
            result["provider_model"] = api_model
            result["request_payload"] = sanitized_google_request_payload(request_payload)
            result["metadata"] = {"provider_usage": provider_usage}
            actual_cost = google_image_usage_cost_usd(
                requested_model, api_model, len(final_images) or count,
                google_image_resolution(opts, requested_model, api_model), provider_usage,
            )
            if actual_cost is not None:
                result["provider_cost_usd_actual"] = actual_cost
            return result
        return image_error_response(provider, requested_model, api_model, endpoint, "Provider returned no image")

    if provider == "qwen":
        # call_qwen_image already loops internally until `count` images are
        # collected (qwen_image_2/qwen_image_2_pro batch natively via n up
        # to 6 in one call; other Qwen models are forced to n=1 and it
        # repeats the call itself) - no outer retry loop is needed here.
        images, error, request_payload = call_qwen_image(requested_model, api_model, endpoint, prompt, payload, size, count)
        qwen_content = (((request_payload or {}).get("input") or {}).get("messages") or [{}])[0].get("content") or []
        qwen_payload_image_count = sum(
            1 for item in qwen_content if isinstance(item, dict) and bool(item.get("image"))
        )
        print("QWEN IMAGE PAYLOAD:", {
            "frontend_model": requested_model,
            "provider_model": (request_payload or {}).get("model") or api_model,
            "endpoint": endpoint,
            "image_count": qwen_payload_image_count,
            "has_references": qwen_payload_image_count > 0,
            "content_types": [
                "image" if isinstance(item, dict) and item.get("image") else "text"
                for item in qwen_content
            ],
        })
        if error:
            return error
        if images:
            final_images = images[:count]
            result = await finalize_image_result(payload, final_images)
            result.update(qwen_cost_info(requested_model, api_model, len(final_images) or count))
            result["provider"] = "qwen"
            result["model"] = requested_model
            result["provider_model"] = (request_payload or {}).get("model") or api_model
            result["request_payload"] = request_payload
            return result
        return image_error_response(provider, requested_model, api_model, endpoint, "Provider returned no image")

    if provider in ("grok", "xai"):
        images, error, request_payload, provider_metadata = call_grok_image(requested_model, api_model, endpoint, prompt, payload, size, count)
        grok_request_endpoint = (
            grok_image_edit_endpoint(endpoint)
            if isinstance(request_payload, dict) and request_payload.get("image")
            else endpoint
        )
        has_grok_input = bool(isinstance(request_payload, dict) and (request_payload.get("image") or request_payload.get("image_url")))
        print("GROK IMAGE PAYLOAD:", {
            "frontend_model": requested_model,
            "provider_model": api_model,
            "endpoint": grok_request_endpoint,
            "payload": request_payload,
            "has_input_image": has_grok_input,
        })
        if error:
            return error
        if images:
            final_images = images[:count]
            result = await finalize_image_result(payload, final_images)
            result.update(grok_cost_info(
                requested_model,
                api_model,
                len(final_images) or count,
                request_payload.get("resolution") or "1k",
                has_grok_input,
            ))
            result["provider"] = "grok"
            result["model"] = requested_model
            result["provider_model"] = api_model
            result["request_payload"] = request_payload
            result["metadata"] = provider_metadata
            return result
        return image_error_response(provider, requested_model, api_model, endpoint, "Provider returned no image")

    if provider == "ideogram":
        images, error, request_payload = call_ideogram_image(requested_model, api_model, endpoint, prompt, payload, size, count)
        print("IDEOGRAM IMAGE PAYLOAD:", {"frontend_model": requested_model, "provider_model": api_model, "endpoint": endpoint, "payload": request_payload})
        if error:
            return error
        if images:
            final_images = images[:count]
            result = await finalize_image_result(payload, final_images)
            result.update(ideogram_cost_info(
                requested_model,
                api_model,
                request_payload.get("rendering_speed") or "TURBO",
                len(final_images) or count,
                False,
            ))
            result["provider"] = "ideogram"
            result["model"] = requested_model
            result["provider_model"] = api_model
            return result
        return image_error_response(provider, requested_model, api_model, endpoint, "Provider returned no image")

    return image_error_response(provider, requested_model, api_model, endpoint, "Image provider adapter is not connected")

# =====================================================
# API ENDPOINT: public_prostudio_image_capabilities
# Принимает HTTP-запрос от Mini App или Telegram Bot.
# Маршрут FastAPI: @app.get("/api/public/prostudio/image-capabilities")
# Проверяет входные данные, работает с базой/провайдерами и возвращает JSON-ответ фронтенду.
# =====================================================
@app.get("/api/public/prostudio/image-capabilities")
async def public_prostudio_image_capabilities():
    return get_image_capabilities()

# =====================================================
# API ENDPOINT: public_prostudio_model_capabilities
# Central Model Capability System (Phase 1, Batch 1 of the master
# remediation plan). Deploy-static, unauthenticated catalog data, added
# alongside (not replacing) /image-capabilities above - additive-only
# migration, per the approved plan. Supports conditional revalidation via
# If-None-Match so the frontend's bootstrap fetch can cheaply confirm its
# cached copy is still current instead of re-downloading the full payload.
# Маршрут FastAPI: @app.get("/api/public/prostudio/model-capabilities")
# =====================================================
@app.get("/api/public/prostudio/model-capabilities")
async def public_prostudio_model_capabilities(request: Request):
    client_version = (request.headers.get("if-none-match") or "").strip('"')
    if client_version and client_version == MODEL_CAPABILITIES_VERSION:
        return Response(status_code=304, headers={"ETag": f'"{MODEL_CAPABILITIES_VERSION}"'})
    body = {"ok": True, "version": MODEL_CAPABILITIES_VERSION, "models": model_capabilities_service.serialize_capabilities()}
    return JSONResponse(body, headers={"ETag": f'"{MODEL_CAPABILITIES_VERSION}"'})

def prostudio_video_templates_from_env() -> list:
    raw = os.getenv("VIDEO_TEMPLATES_JSON", "").strip()
    if not raw:
        return []
    try:
        parsed = json.loads(raw)
    except Exception as exc:
        prostudio_error("VIDEO_TEMPLATES_JSON_PARSE_FAILED", exc)
        return []
    items = parsed.get("templates") if isinstance(parsed, dict) else parsed
    if not isinstance(items, list):
        return []

    def _template_int(value, default=0):
        try:
            if isinstance(value, str):
                match = re.search(r"\d+", value)
                return int(match.group(0)) if match else default
            return int(value)
        except Exception:
            return default

    templates = []
    for index, item in enumerate(items):
        if not isinstance(item, dict):
            continue
        template_id = str(item.get("id") or f"template_{index + 1}").strip()
        title = str(item.get("title") or item.get("name") or template_id).strip()
        preview_video = str(item.get("preview_video") or item.get("previewVideo") or item.get("video") or "").strip()
        reference_video = str(item.get("reference_video") or item.get("referenceVideo") or preview_video).strip()
        if not template_id or not title or not reference_video:
            continue

        ratios = item.get("ratios") or item.get("aspect_ratios") or item.get("supported_ratios") or ["16:9", "1:1", "9:16"]
        if not isinstance(ratios, list):
            ratios = [ratios]
        ratios = [str(r).strip() for r in ratios if str(r or "").strip() in {"16:9", "1:1", "9:16"}]
        if not ratios:
            ratios = ["16:9"]

        models = item.get("models") or item.get("supported_models") or []
        if not isinstance(models, list):
            models = [models]
        models = [str(model).strip() for model in models if str(model or "").strip()]
        preferred_model = "kling_motion_3_0"
        duration = _template_int(item.get("duration"), 5) or 5
        resolution = str(item.get("resolution") or "720p").strip() or "720p"
        default_ratio = str(item.get("aspect_ratio") or item.get("ratio") or ratios[0]).strip()
        if default_ratio not in ratios:
            default_ratio = ratios[0]

        # Environment-defined cards use the same per-second Kling reference
        # tariff and the same fixed 20 ⚡ video-reference fee as built-in cards.
        calculated_cost = video_catalog_template_price(preferred_model, duration, resolution, True)

        templates.append({
            "id": template_id,
            "title": title,
            "description": str(item.get("description") or "").strip(),
            "preview_video": preview_video,
            "reference_video": reference_video,
            "aspect_ratio": default_ratio,
            "ratios": ratios,
            "models": ["kling_motion_3_0"],
            "preferred_model": preferred_model,
            "duration": duration,
            "resolution": resolution,
            "cost": calculated_cost,
            "cost_credits": calculated_cost,
            "generation_cost": f"{calculated_cost} ⚡",
        })
    return templates

def video_catalog_template_price(model: str, duration: int, resolution: str, has_video_reference: bool) -> int:
    """Exact fixed catalog-card price: Kling output seconds plus its reference fee."""
    resolution_key = str(resolution or "720p").lower()
    if resolution_key in {"1080", "1080p", "fhd"}:
        rate = 25.2 if has_video_reference else 16.8
    elif resolution_key in {"4k", "2160p", "uhd"}:
        rate = 63.0
    else:
        # Kling Omni with an input video costs 18.9 ⚡/sec at 720p.
        rate = 18.9 if has_video_reference or model == "kling_effects" else 12.6
    reference_fee = 20 if has_video_reference else 0
    return int(math.ceil(max(1, int(duration or 1)) * rate + reference_fee))


def prostudio_builtin_video_template_slots() -> list:
    russian_titles = [
        "Сброс сумки", "Ангел на шоссе", "Чемпион мира", "Воздушная доставка", "Масштабный отлёт камеры",
        "Баннер над городом", "Ужас в зеркале", "ASMR-распаковка", "Фотобудка", "Кубок мира LEGO",
        "Американские горки", "Рамен в Токио", "Полёт над облаками", "Уличная афиша", "Модное селфи",
        "Выход из отеля", "Красная дорожка", "На вершине Земли", "Полёт ангела", "Бой в снежном тоннеле",
        "Музыка в поле", "Погружение в радужку", "За кулисами кино", "Ночное видение", "Горный поход",
        "Концертная арена", "Y2K-глитч", "3D-каркас", "Городской таймлапс", "Высокая мода",
        "Магия огня", "Мир в бутылке", "Гигантская доставка", "Фэнтези-джунгли", "Горное приключение",
        "Поездка по открытой дороге", "Камера 360°", "Подъём камеры", "Эффект удара", "Обзор модного образа",
        "Улыбка на стадионе", "Кошачья встреча", "Звезда в аэропорту", "Реакция болельщика", "Празднование гола",
        "Дождь конфетти", "Спокойствие в огне", "Взлёт дрона", "Золотые частицы", "Реклама на билборде",
        "Эпичный отлёт дрона", "Акробатический переворот", "Приземление продукта", "Превращение улыбки", "Премьера на красной дорожке",
        "Кинематографическая погоня", "Одежда в полёте", "Белки и продукт", "Жидкий хром", "От героя к Земле",
        "Фотокопии", "Слёзы", "K-pop-фанкам", "Весёлые мордочки", "Надутые щёки", "Рокер-питомец",
    ]
    templates = []
    base_dir = WEBAPP_DIR / "assets" / "video-templates"
    for index in range(1, 68):
        slot = f"{index:02d}"
        template_id = f"builtin_video_template_{index}"
        slot_dir = base_dir / slot
        preview_file = slot_dir / "preview.mp4"
        if not preview_file.exists() and (slot_dir / "poster.mp4").exists():
            preview_file = slot_dir / "poster.mp4"
        poster_file = slot_dir / "poster.jpg"
        metadata_file = slot_dir / "template.json"
        prompt_file = slot_dir / "prompt.txt"
        preview_exists = preview_file.exists()
        poster_exists = poster_file.exists()
        if not preview_exists:
            continue
        metadata = {}
        if metadata_file.exists():
            try:
                parsed = json.loads(metadata_file.read_text(encoding="utf-8"))
                if isinstance(parsed, dict):
                    metadata = parsed
            except Exception as exc:
                prostudio_error("VIDEO_TEMPLATE_METADATA_FAILED", exc, slot=slot)
        prompt = ""
        if prompt_file.exists():
            try:
                prompt = prompt_file.read_text(encoding="utf-8").strip()
            except Exception as exc:
                prostudio_error("VIDEO_TEMPLATE_PROMPT_FAILED", exc, slot=slot)
        output = metadata.get("output") if isinstance(metadata.get("output"), dict) else {}
        effect_scene = str(metadata.get("effect_scene") or "").strip()
        is_provider_effect = index in {64, 65, 66} and bool(effect_scene)
        title = russian_titles[index - 1] if index <= len(russian_titles) else str(metadata.get("name") or template_id)
        folder_description = str(metadata.get("description") or "").strip()
        if is_provider_effect:
            descriptions = {
                64: "Оживляет мордочку питомца фирменным эффектом Wiggle Faces.",
                65: "Создаёт забавную анимацию лица с надутыми щёками.",
                66: "Превращает фото питомца в энергичную рок-анимацию.",
            }
            description = folder_description or descriptions[index]
        else:
            description = folder_description or f"Загрузите изображение для видео «{title}»."
        # Phase 1 Batch 7 correction (see /root/.claude/plans/splendid-moseying-starlight.md):
        # the Motion Catalog (non-effect, reference-video-driven templates)
        # is a dedicated fixed-model workflow and must always resolve to
        # kling_motion_3_0 - never kling_o3_omni - matching the env-sourced
        # templates in prostudio_video_templates_from_env() above, which
        # already hardcode kling_motion_3_0 for this same catalog.
        preferred_model = "kling_effects" if is_provider_effect else "kling_motion_3_0"
        duration = max(1, int(output.get("duration") or metadata.get("duration") or 5))
        resolution = str(output.get("resolution") or metadata.get("resolution") or "720p")
        has_video_reference = not is_provider_effect
        credits = video_catalog_template_price(preferred_model, duration, resolution, has_video_reference)
        item = {
            "id": template_id,
            "slot": slot,
            "title": title,
            "name": title,
            "description": description,
            "prompt": prompt or str(metadata.get("description") or title),
            "preview_exists": preview_exists,
            "poster_exists": poster_exists,
            "preview_video": f"/webapp/assets/video-templates/{slot}/{preview_file.name}" if preview_exists else "",
            "reference_video": "" if is_provider_effect else f"/webapp/assets/video-templates/{slot}/{preview_file.name}",
            "poster_url": f"/webapp/assets/video-templates/{slot}/poster.jpg" if poster_exists else "",
            "upload_path": f"webapp/assets/video-templates/{slot}/{preview_file.name}",
            "aspect_ratio": str(output.get("aspect_ratio") or "9:16"),
            "ratios": ["16:9", "1:1", "9:16"],
            "duration": duration,
            "resolution": resolution,
            "catalog_type": "kling_effect" if is_provider_effect else "video_template",
            "is_kling_effect": is_provider_effect,
            "effect_scene": effect_scene if is_provider_effect else "",
            "mode": "std" if is_provider_effect else "",
            "model_name": "kling-v1-6" if is_provider_effect else "",
            "input_count": int((metadata.get("input") or {}).get("count") or 1) if isinstance(metadata.get("input"), dict) else 1,
            "models": [preferred_model],
            "preferred_model": preferred_model,
            "cost": credits,
            "cost_credits": credits,
            "generation_cost": f"{credits} ⚡",
        }
        templates.append(item)
    return templates

def prostudio_kling_effects_library() -> list:
    effects_file = WEBAPP_DIR / "providers" / "kling" / "effects" / "effects.json"
    if not effects_file.exists():
        return []
    try:
        raw = json.loads(effects_file.read_text(encoding="utf-8"))
    except Exception as exc:
        prostudio_error("KLING_EFFECTS_JSON_PARSE_FAILED", exc)
        return []
    items = raw.get("effects") if isinstance(raw, dict) else raw
    if not isinstance(items, list):
        return []

    effects = []
    for index, item in enumerate(items):
        if not isinstance(item, dict):
            continue
        effect_id = str(item.get("id") or item.get("effect_scene") or item.get("scene") or f"effect_{index + 1}").strip()
        if not effect_id:
            continue
        title = str(item.get("title") or item.get("name") or effect_id).strip()
        effect_dir = WEBAPP_DIR / "providers" / "kling" / "effects" / effect_id
        preview_file = effect_dir / "preview.mp4"
        poster_file = effect_dir / "poster.jpg"
        preview_video = str(item.get("preview_video") or item.get("previewVideo") or item.get("demo_video") or item.get("video_url") or "").strip()
        poster_url = str(item.get("poster_url") or item.get("poster") or item.get("thumbnail_url") or item.get("preview_image") or "").strip()
        if not preview_video and preview_file.exists():
            preview_video = f"/webapp/providers/kling/effects/{effect_id}/preview.mp4"
        if not poster_url and poster_file.exists():
            poster_url = f"/webapp/providers/kling/effects/{effect_id}/poster.jpg"
        ratios = item.get("ratios") or item.get("aspect_ratios") or [str(item.get("aspect_ratio") or "9:16")]
        if not isinstance(ratios, list):
            ratios = [ratios]
        ratios = [str(r).strip() for r in ratios if str(r or "").strip() in {"16:9", "1:1", "9:16"}]
        if not ratios:
            ratios = ["16:9", "1:1", "9:16"]
        aspect_ratio = str(item.get("aspect_ratio") or item.get("ratio") or ratios[0]).strip()
        if aspect_ratio not in ratios:
            aspect_ratio = ratios[0]
        cost_credits = int(item.get("cost_credits") or item.get("cost") or 0)
        effects.append({
            "id": effect_id,
            "effect_scene": effect_id,
            "title": title,
            "name": title,
            "description": str(item.get("description") or item.get("hint") or "").strip(),
            "preview_video": preview_video,
            "poster_url": poster_url,
            "aspect_ratio": aspect_ratio,
            "ratios": ratios,
            "duration": int(item.get("duration") or 5),
            "resolution": str(item.get("resolution") or "720p"),
            "mode": str(item.get("mode") or "std"),
            "model_name": str(item.get("model_name") or "kling-v1-6"),
            "input_count": int(item.get("input_count") or item.get("images_required") or (2 if effect_id in {"hug", "kiss", "heart_gesture", "handshake"} else 1)),
            "cost": cost_credits,
            "cost_credits": cost_credits,
            "generation_cost": item.get("generation_cost") or (f"{cost_credits} ⚡" if cost_credits else ""),
            "upload_path": f"webapp/providers/kling/effects/{effect_id}/preview.mp4",
        })
    return effects


