@app.post("/api/public/prostudio/estimate")
async def public_prostudio_estimate(request: Request):
    """Return the existing authoritative Pro Studio estimate without creating a job."""
    try:
        payload = await request.json()
        if isinstance(payload, dict):
            grid_references_service.resolve_grid_catalog_references(payload, WEBAPP_URL)
            normalize_grid_video_request(payload)
            if payload.get("grid_project_id") and str(payload.get("mode") or payload.get("category") or "").lower() == "video":
                feature_error = validate_video_feature_request(payload)
                if feature_error:
                    prostudio_debug(
                        "GENERATION_ESTIMATE_VALIDATION_REJECTED",
                        status=422,
                        code=str(feature_error.get("error") or "invalid_video_options")[:160],
                        mode="video",
                        model=str(feature_error.get("model") or payload.get("model") or "")[:120],
                        invalid_fields=["video_options"],
                    )
                    return JSONResponse({**feature_error, "invalid_fields": ["video_options"]}, status_code=422)
        estimate = calculate_generation_price(payload if isinstance(payload, dict) else {})
        return {"ok": True, **estimate}
    except Exception as exc:
        prostudio_error("GENERATION_ESTIMATE_FAILED", exc)
        return JSONResponse({"ok": False, "error": "generation_estimate_failed"}, status_code=400)


GRID_TEXT_NODE_MODELS = (
    "gpt-5.6", "gpt-5.5", "gpt-5", "gpt-5-mini", "gpt-4.1", "gpt-4.1-mini",
    "gpt-4o", "gpt-4o-mini", "gemini_3_1_pro", "gemini_3_1_flash",
    "gemini_2_5_pro", "gemini_2_5_flash", "grok_4_1", "grok_4_fast", "grok_3",
    "qwen_plus", "qwen_turbo", "qwen_max", "byteplus_seed_2_lite",
)


def grid_planner_cost_hint(mode: str, model: str, settings: Optional[dict] = None) -> dict:
    """Small, non-binding catalog estimate so the director can honor budget.

    Actual reservations still use calculate_generation_price() when a node
    runs. This hint never authorizes or charges a generation.
    """
    settings = dict(settings or {})
    payload = {"mode": mode, "category": mode, "model": model, "prompt": "Production prompt"}
    payload[f"{mode}_options"] = {"model": model, **settings}
    try:
        estimate = calculate_generation_price(payload)
        available = bool(estimate.get("pricing_available", estimate.get("credits")))
        return {
            "sample_credits": int(estimate.get("credits") or estimate.get("cost_credits") or 0) if available else None,
            "sample_settings": settings,
        }
    except Exception:
        return {"sample_credits": None, "sample_settings": settings}


def grid_planner_catalog() -> dict:
    retired = {"sora_2", "sora_2_pro", "runway_gen3a_turbo", "runway_aleph", "luma_dream_machine", "minimax_hailuo_2_3"}
    videos = {}
    for model_id, config in _VIDEO_MODEL_CONFIG.items():
        modes = list(config.get("modes") or [])
        if model_id in retired or config.get("avatar") or "video_effects" in modes:
            continue
        default_duration = next(iter(config.get("durations") or [5]), 5)
        default_resolution = next(iter(config.get("resolutions") or ["720p"]), "720p")
        videos[model_id] = {
            "modes": modes,
            "durations": list(config.get("durations") or []),
            "ratios": list(config.get("ratios") or []),
            "resolutions": list(config.get("resolutions") or []),
            "sound": bool(config.get("sound")),
            "native_audio": bool(config.get("native_audio")),
            "start_image": bool(config.get("start_image")),
            "end_image": bool(config.get("end_image")),
            "video_upload": bool(config.get("video_upload")),
            "cost_hint": grid_planner_cost_hint("video", model_id, {
                "duration": default_duration, "resolution": default_resolution, "sound": False,
            }),
        }
    image_models = ["gpt_image_2", "seedream_5_0_pro", "nano_banana_2", "flux_2", "qwen_image_2_pro", "recraft_v4_1_pro", "ideogram_4_0", "grok_pro"]
    image_capabilities = {}
    for model_id in image_models:
        features = IMAGE_MODEL_FEATURES.get(model_id) or {}
        capability = {
            "character_reference": bool(features.get("character")),
            "object_reference": bool(features.get("object")),
            "seed": bool(features.get("seed")),
        }
        if model_id in SEEDREAM_MODEL_CAPABILITIES:
            capability["max_references"] = int(SEEDREAM_MODEL_CAPABILITIES[model_id].get("max_references") or 0)
        image_capabilities[model_id] = capability
    music_models = ["google_lyria_3_clip", "google_lyria_3_pro", "suno_chirp_6", "suno_chirp_5_5", "suno_chirp_6_mini"]
    voice_models = ["elevenlabs_eleven_v3", "elevenlabs_multilingual_v2", "gemini_3_1_flash_tts_preview", "gemini_2_5_pro_preview_tts", "gemini_2_5_flash_preview_tts", "runway_eleven_multilingual_v2"]
    return {
        "graph_limits": {"max_nodes": 100, "max_edges": 400, "max_reference_requests": 24},
        "text": {
            "models": [model for model in GRID_TEXT_NODE_MODELS if model in TEXT_MODEL_VARIANTS],
            "default": "gpt-5.6",
            "note": "These are editable/rerunnable Text-node models. They do not control Grid planning.",
        },
        "image": {
            "models": image_models,
            "capabilities": image_capabilities,
            "settings": {"size": ["1:1", "16:9", "9:16", "4:3", "3:4"], "resolution": ["1024", "2048", "4096"], "quality": ["standard", "high"], "count": [1, 2, 3, 4]},
            "cost_hints": {model: grid_planner_cost_hint("image", model, {"size": "16:9", "resolution": "1024", "quality": "standard", "count": 1}) for model in image_models},
        },
        "video": {"models": videos},
        "music": {
            "models": music_models,
            "settings": {"genre": ["auto", "pop", "rock", "rap", "jazz", "ambient", "cinematic", "electronic"], "duration": [30, 60, 120, 180], "mood": ["energetic", "calm", "dramatic", "romantic", "uplifting", "dark"], "tempo": ["slow", "medium", "fast"], "vocal": ["instrumental", "female", "male", "duet", "auto"]},
            "cost_hints": {model: grid_planner_cost_hint("music", model, {"duration": 60}) for model in music_models},
        },
        "voice": {
            "models": voice_models,
            "settings": {"target_language": ["auto", "en", "ru", "kk", "es", "de", "fr", "it", "tr", "ar"], "speaker_mode": ["single", "dialogue"], "runway_tool": ["text_to_speech", "sound_effect"], "emotion": "text", "speed": [0.5, 2.0]},
            "cost_hints": {model: grid_planner_cost_hint("voice", model, {"duration": 30}) for model in voice_models},
        },
        "montage": {"model": "final_montage", "settings": {"resolution": ["720p", "1080p"], "transition": ["cut", "fade"], "ducking": [True, False]}},
    }


def grid_plan_response_format() -> dict:
    """Responses API schema for the director's graph, not a fixed workflow."""
    string = {"type": "string"}
    return {
        "type": "json_schema", "name": "sylvex_grid_plan", "strict": False,
        "schema": {
            "type": "object", "additionalProperties": False, "required": ["action"],
            "properties": {
                "action": {"type": "string", "enum": ["plan", "clarify"]},
                "question": string, "title": string, "summary": string,
                "reference_requests": {"type": "array", "items": {
                    "type": "object", "additionalProperties": False,
                    "properties": {
                        "id": string, "kind": string, "label": string, "reason": string,
                        "required": {"type": "boolean"}, "used_by": {"type": "array", "items": string},
                    },
                }},
                "nodes": {"type": "array", "items": {
                    "type": "object", "additionalProperties": False,
                    "properties": {
                        "key": string, "type": string, "title": string, "role": string,
                        "model": string, "instruction": string, "output": string, "prompt": string,
                        "settings": {"type": "object", "additionalProperties": True},
                        "reference_ids": {"type": "array", "items": string},
                        "timeline": {"type": "object", "additionalProperties": True},
                    },
                }},
                "edges": {"type": "array", "items": {
                    "type": "object", "additionalProperties": False,
                    "properties": {"from": string, "output": string, "to": string, "input": string},
                }},
            },
        },
    }


def grid_planner_prompt(task: str, catalog: dict, context: dict) -> str:
    return f"""
You are SYLVEX Grid Director. You are the autonomous production brain for an open-ended node canvas. Return only the requested JSON object. Never generate media or claim that media has already been generated.

The Task block is only the user's brief. There is no user-selected planner model and there is no fixed workflow. You must infer the complete executable DAG in real time: what work is needed, how many nodes are needed, which node types and catalog models to use, every production-ready prompt, every supported setting, all references, and every edge. Do not force a brief into a predefined image chain, video chain, shot count, or template.

Work as the relevant professional team:
- video/film: director, screenwriter, cinematographer, editor and continuity supervisor;
- image: photographer, production designer, lighting and VFX specialist;
- music: composer, producer and lyricist;
- voice/dialogue/podcast: researcher, writer, dialogue editor and voice director;
- mixed or multi-part briefs: split the work into independent or connected branches and coordinate them as one director.

Only choose IDs and supported settings from this live catalog. Its cost hints are estimates for relative budget decisions; actual price is checked when each node runs:
{json.dumps(catalog, ensure_ascii=False)}

Director rules:
1. Allowed node types are text, image, video, music, voice and montage. Do not return the existing Task node. Create as many or as few nodes as the brief actually requires, up to the catalog limits.
2. A Text node is editable by the user and may use any text model from catalog.text. Its `output` must already contain finished production content, not a promise or instruction to write it later. The hidden Grid Director model is never exposed as a Task setting.
3. A request to compare N generators must produce one fair shared prompt and N parallel media nodes using N distinct compatible models, unless the user asks for another comparison method. Connect the shared Text node to every compared node so all receive exactly the same prompt.
4. A brief containing several deliverables must become the corresponding separate branches. Preserve intentional dependencies and let independent branches run in parallel. Never collapse multiple requested tasks into one generic block.
5. For a requested video duration, design the story and rhythm first, then choose compatible clip models and calculate the exact number of clips from their supported durations. The used `timeline.duration` values must sum to the requested total. Each shot gets its own finished Text prompt and Video node. `settings.duration` is the supported provider duration; `timeline.duration` is the amount used in the final edit. A 300-second project made of 10-second clips therefore needs 30 clips, not 3.
6. If the user requests a budget result, minimize the total estimated credits while still meeting required capabilities and duration. If quality is the priority, choose stronger compatible models. Never select a model merely because it appears first in the catalog.
7. Put real parameters in `settings`. Do not describe duration, ratio, resolution, sound or generation mode only in prose. Use only values supported by that model.
8. Repeating people, products, locations, logos and objects must have stable reference_ids on every relevant node. If a supplied reference is absent and identity matters, add one concise optional reference_requests item. The UI lets the user upload it, name it, or explicitly continue without it. If skipped, invent one original identity with concrete stable visual traits and reuse it unchanged.
   Attachments already listed in context.source_node.attachments are uploaded. Reuse their exact reference_id on every relevant node and do not ask the user to upload them again.
9. For continuity, use only officially supported reference capabilities. If a chosen video model cannot accept the needed image, choose another compatible model or create one shared Image asset and connect it to compatible Video nodes. Never route work to evade a provider's policy, identity restriction or safety control.
10. Decide whether native video sound is enough. Add shared music or voice only when the brief needs it. Spoken copy and lyrics must be finished in Text nodes and connected to Voice or Music. Multi-clip productions that need one final deliverable end in a montage with ordered timeline and audio settings.
11. Every edge represents real data transfer and the graph must be acyclic. Image references connect through image edges; exact shot prompts through text edges; clips and audio through video/audio edges.
12. Ask one short question in the user's language only when one missing fact makes a responsible plan impossible. Product/character/logo references are normally optional reference_requests, not blocking clarification. Otherwise make explicit professional assumptions and return action=plan.

Plan fields:
- action: plan or clarify; clarify also has question.
- plan: title, summary, reference_requests, nodes, edges.
- node: key, type, title, role, exact catalog model, instruction, finished output for Text, optional local prompt for media, settings, reference_ids, timeline.
- edge: from, output (text/image/video/audio), to, input (task/text/lyrics/image/video/audio).

Current editable Grid context. Preserve relevant explicit user choices, but do not treat a Task model from an old saved project as the director model:
{json.dumps(context, ensure_ascii=False)}

User brief:
<user_brief>{task}</user_brief>
""".strip()


def grid_requested_duration_seconds(task: str) -> int:
    """Read an explicit total production duration from a short user brief.

    This is deliberately small and deterministic: the planner still decides
    shot count and rhythm, while the server uses the result only to reject a
    structurally incomplete timeline before it reaches the Grid canvas.
    """
    text = str(task or "").casefold().replace(",", ".")
    units = {
        "hour": 3600, "hours": 3600, "hr": 3600, "hrs": 3600,
        "час": 3600, "часа": 3600, "часов": 3600,
        "minute": 60, "minutes": 60, "min": 60, "mins": 60,
        "минута": 60, "минуты": 60, "минуту": 60, "минут": 60, "мин": 60,
        "second": 1, "seconds": 1, "sec": 1, "secs": 1,
        "секунда": 1, "секунды": 1, "секунду": 1, "секунд": 1, "сек": 1,
    }
    total = 0.0
    pattern = r"(?<![\w.])(\d+(?:\.\d+)?)\s*(hours?|hrs?|minutes?|mins?|seconds?|secs?|час(?:а|ов)?|минут(?:а|ы|у)?|мин|секунд(?:а|ы|у)?|сек)(?!\w)"
    for match in re.finditer(pattern, text):
        total += float(match.group(1)) * units.get(match.group(2), 0)
    if total <= 0:
        words = {
            "one": 1, "two": 2, "three": 3, "four": 4, "five": 5,
            "один": 1, "одна": 1, "одну": 1, "две": 2, "два": 2,
            "три": 3, "четыре": 4, "пять": 5,
        }
        word_pattern = r"\b(" + "|".join(words) + r")[-\s]+(hours?|minutes?|seconds?|час(?:а|ов)?|минут(?:а|ы|у)?|секунд(?:а|ы|у)?)\b"
        for match in re.finditer(word_pattern, text):
            total += words[match.group(1)] * units.get(match.group(2), 0)
    if total <= 0 and (re.search(r"\b(?:one[-\s]minute|a[-\s]minute)\b", text) or re.search(r"\b(?:одно|одна)[-\s]?минут\w*", text) or "в течение минуты" in text):
        total = 60
    return max(0, min(7200, int(round(total))))


def clean_grid_plan(plan: dict, planner_model: str, catalog: dict, task: str = "") -> dict:
    if not isinstance(plan, dict) or plan.get("action") not in {"clarify", "plan"}:
        raise ValueError("invalid_planner_response")
    if plan.get("action") == "clarify":
        question = str(plan.get("question") or "").strip()[:500]
        if not question:
            raise ValueError("planner_question_missing")
        return {"action": "clarify", "question": question}
    allowed_types = {"text", "image", "video", "music", "voice", "montage"}
    allowed_inputs = {"task", "text", "lyrics", "image", "video", "audio"}
    allowed_outputs = {"text", "image", "video", "audio"}
    catalog_models = {
        "text": list(catalog.get("text", {}).get("models") or GRID_TEXT_NODE_MODELS),
        "image": list(catalog["image"]["models"]),
        "video": list(catalog["video"]["models"]),
        "music": list(catalog["music"]["models"]),
        "voice": list(catalog["voice"]["models"]),
        "montage": ["final_montage"],
    }
    raw_nodes = plan.get("nodes") or []
    raw_edges = plan.get("edges") or []
    if not isinstance(raw_nodes, list) or len(raw_nodes) > 100:
        raise ValueError("planner_node_limit")
    if not isinstance(raw_edges, list) or len(raw_edges) > 400:
        raise ValueError("planner_edge_limit")
    clean_nodes, keys = [], set()
    for index, item in enumerate(raw_nodes):
        if not isinstance(item, dict) or str(item.get("type") or "") not in allowed_types:
            raise ValueError("planner_node_invalid")
        node_type = str(item["type"])
        key = re.sub(r"[^a-zA-Z0-9_-]", "", str(item.get("key") or f"node_{index}"))[:64]
        if not key or key in keys:
            raise ValueError("planner_node_key_invalid")
        keys.add(key)
        model = str(item.get("model") or "").strip()
        if node_type == "text" and not model:
            model = planner_model if planner_model in catalog_models["text"] else str(catalog.get("text", {}).get("default") or "gpt-5.6")
        if model not in catalog_models[node_type]:
            raise ValueError(f"planner_{node_type}_model_invalid")
        settings = item.get("settings") if isinstance(item.get("settings"), dict) else {}
        timeline = item.get("timeline") if isinstance(item.get("timeline"), dict) else {}
        if node_type == "video":
            capability = (catalog.get("video", {}).get("models") or {}).get(model) or {}
            duration = settings.get("duration")
            if duration is not None and capability.get("durations") and duration not in capability["durations"]:
                raise ValueError("planner_video_duration_unsupported")
            ratio = settings.get("ratio")
            if ratio is not None and capability.get("ratios") and ratio not in capability["ratios"]:
                raise ValueError("planner_video_ratio_unsupported")
            resolution = settings.get("resolution")
            if resolution is not None and capability.get("resolutions") and resolution not in capability["resolutions"]:
                raise ValueError("planner_video_resolution_unsupported")
            generation_mode = settings.get("generation_mode")
            if generation_mode is not None and capability.get("modes") and generation_mode not in capability["modes"]:
                raise ValueError("planner_video_mode_unsupported")
        reference_ids = [re.sub(r"[^a-zA-Z0-9_-]", "", str(value))[:64] for value in (item.get("reference_ids") or [])[:12] if str(value).strip()]
        if reference_ids and node_type == "image":
            capability = (catalog.get("image", {}).get("capabilities") or {}).get(model) or {}
            if not (capability.get("character_reference") or capability.get("object_reference")):
                raise ValueError("planner_image_reference_unsupported")
            max_references = int(capability.get("max_references") or 0)
            if max_references and len(reference_ids) > max_references:
                raise ValueError("planner_image_reference_limit")
        if reference_ids and node_type == "video":
            capability = (catalog.get("video", {}).get("models") or {}).get(model) or {}
            if not (capability.get("start_image") or capability.get("video_upload")):
                raise ValueError("planner_video_reference_unsupported")
        clean_nodes.append({
            "key": key, "type": node_type,
            "title": str(item.get("title") or node_type)[:100],
            "role": str(item.get("role") or "")[:40],
            "model": model,
            "instruction": str(item.get("instruction") or "")[:12000],
            "output": str(item.get("output") or "")[:30000],
            "prompt": str(item.get("prompt") or "")[:30000],
            "settings": settings,
            "reference_ids": reference_ids,
            "timeline": timeline,
        })
    if not clean_nodes:
        raise ValueError("planner_nodes_missing")
    clean_edges, edge_keys = [], set()
    adjacency = {key: [] for key in keys}
    def would_cycle(source: str, target: str) -> bool:
        queue, seen = [target], set()
        while queue:
            current = queue.pop()
            if current == source:
                return True
            if current in seen:
                continue
            seen.add(current)
            queue.extend(adjacency.get(current, []))
        return False
    node_by_key = {node["key"]: node for node in clean_nodes}
    node_outputs = {"text": {"text"}, "image": {"image"}, "video": {"video"}, "music": {"audio"}, "voice": {"audio"}, "montage": {"video"}}
    node_inputs = {"text": {"task", "text"}, "image": {"text", "image"}, "video": {"text", "image", "video", "audio"}, "music": {"text", "lyrics"}, "voice": {"text"}, "montage": {"video", "audio"}}
    for item in raw_edges:
        if not isinstance(item, dict):
            raise ValueError("planner_edge_invalid")
        source, target = str(item.get("from") or ""), str(item.get("to") or "")
        output, input_name = str(item.get("output") or "text"), str(item.get("input") or "text")
        edge_key = (source, output, target, input_name)
        source_node, target_node = node_by_key.get(source), node_by_key.get(target)
        compatible = bool(
            source_node and target_node
            and output in node_outputs.get(source_node["type"], set())
            and input_name in node_inputs.get(target_node["type"], set())
            and (output == input_name or (output == "text" and input_name == "lyrics") or (output == "audio" and input_name == "audio"))
        )
        if source not in keys or target not in keys or source == target or output not in allowed_outputs or input_name not in allowed_inputs or not compatible:
            raise ValueError("planner_edge_incompatible")
        if edge_key in edge_keys:
            continue
        if would_cycle(source, target):
            raise ValueError("planner_edge_cycle")
        edge_keys.add(edge_key)
        clean_edges.append({"from": source, "output": output, "to": target, "input": input_name})
        adjacency[source].append(target)

    # Validate the director's graph as returned. Do not invent nodes, prompts
    # or edges here: that would make Python templates, rather than GPT, the
    # actual Grid brain.
    media_types = {"image", "video", "music", "voice"}
    for node in clean_nodes:
        if node["type"] not in media_types:
            continue
        text_edges = [
            edge for edge in clean_edges
            if edge["to"] == node["key"] and edge["output"] == "text" and edge["input"] in {"text", "lyrics"}
        ]
        if not text_edges and not str(node.get("prompt") or "").strip():
            raise ValueError(f"planner_{node['type']}_prompt_missing")
        for edge in text_edges:
            source_text = node_by_key.get(edge["from"])
            if not str((source_text or {}).get("output") or "").strip():
                raise ValueError("planner_text_output_missing")

    # Video productions use one independently editable finished prompt per
    # shot. Parallel image comparisons may intentionally share one prompt.
    video_nodes = [node for node in clean_nodes if node["type"] == "video"]
    if len(video_nodes) > 1:
        video_text_parents = []
        for node in video_nodes:
            parents = [edge["from"] for edge in clean_edges if edge["to"] == node["key"] and edge["output"] == "text"]
            if len(parents) != 1:
                raise ValueError("planner_video_text_parent_missing")
            video_text_parents.append(parents[0])
        if len(set(video_text_parents)) != len(video_text_parents):
            raise ValueError("planner_video_text_parent_shared")

    requested_duration = grid_requested_duration_seconds(task)
    if requested_duration and video_nodes:
        timeline_total = 0.0
        for index, node in enumerate(video_nodes):
            timeline = node.get("timeline") if isinstance(node.get("timeline"), dict) else {}
            duration = float(timeline.get("duration") or (node.get("settings") or {}).get("duration") or 0)
            if duration <= 0:
                raise ValueError("planner_video_timeline_missing")
            timeline["duration"] = duration
            timeline["order"] = int(timeline.get("order") or index + 1)
            node["timeline"] = timeline
            timeline_total += duration
        if abs(timeline_total - requested_duration) > 1:
            raise ValueError("planner_video_duration_mismatch")
    raw_references = plan.get("reference_requests") or []
    if not isinstance(raw_references, list) or len(raw_references) > 24:
        raise ValueError("planner_reference_limit")
    references = []
    reference_ids = set()
    for index, item in enumerate(raw_references):
        if not isinstance(item, dict):
            continue
        ref_id = re.sub(r"[^a-zA-Z0-9_-]", "", str(item.get("id") or f"reference_{index}"))[:64]
        if not ref_id or ref_id in reference_ids:
            continue
        reference_ids.add(ref_id)
        references.append({
            "id": ref_id,
            "kind": str(item.get("kind") or "object")[:30],
            "label": str(item.get("label") or "Reference")[:100],
            "reason": str(item.get("reason") or "")[:500],
            "required": False,
            "used_by": [key for key in (item.get("used_by") or []) if key in keys],
        })
    return {
        "action": "plan", "title": str(plan.get("title") or "")[:160],
        "summary": str(plan.get("summary") or "")[:2000],
        "reference_requests": references, "nodes": clean_nodes, "edges": clean_edges,
    }


def grid_planner_retryable_result(result: dict) -> bool:
    if not isinstance(result, dict):
        return True
    metadata = result.get("metadata") if isinstance(result.get("metadata"), dict) else {}
    status = int(metadata.get("_http_status") or 0)
    if status in {408, 409, 425, 429, 500, 502, 503, 504}:
        return True
    error = str(result.get("error") or result.get("message") or "").casefold()
    return any(marker in error for marker in ("timeout", "timed out", "temporarily", "rate limit", "overload", "connection", "try again"))


def grid_planner_generation_with_fallback(planner_payload: dict, planner_model: str, catalog: dict, task: str) -> dict:
    """Run the hidden GPT director, then one hidden GPT retry.

    No local/template plan is permitted: after both attempts fail the Task
    remains retryable and the real failure is shown instead of fabricating a
    graph that GPT did not design.
    """
    attempts = [
        (planner_model, GRID_PLAN_MAX_OUTPUT_TOKENS, GRID_PLANNER_POLL_SAFETY_LIMIT_SECONDS, "primary"),
        (GRID_PLANNER_FALLBACK_MODEL, GRID_PLAN_FALLBACK_MAX_OUTPUT_TOKENS, GRID_PLANNER_POLL_SAFETY_LIMIT_SECONDS, "fallback"),
    ]
    last_reason = "temporary_provider_failure"
    saw_temporary_failure = False
    for attempt_number, (model, output_cap, poll_timeout_seconds, attempt_name) in enumerate(attempts, 1):
        payload = dict(planner_payload)
        payload.update({
            "model": model,
            "output_token_cap": output_cap,
            "_provider_timeout_seconds": GRID_PLANNER_CREATE_TIMEOUT_SECONDS,
            "_openai_background": True,
            "_openai_poll_timeout_seconds": poll_timeout_seconds,
            "_reasoning_effort": GRID_PLANNER_REASONING_EFFORT,
            "_openai_idempotency_key": f"{planner_payload.get('job_id') or 'grid-plan'}:{attempt_name}:{model}",
        })
        started = time.monotonic()
        try:
            result = text_generation(payload)
        except requests.RequestException as exc:
            saw_temporary_failure = True
            last_reason = type(exc).__name__
            print("GRID_PLANNER_RETRY:", json.dumps({
                "attempt": attempt_number, "kind": attempt_name, "model": model,
                "create_timeout_seconds": GRID_PLANNER_CREATE_TIMEOUT_SECONDS,
                "poll_timeout_seconds": poll_timeout_seconds,
                "elapsed_ms": int((time.monotonic() - started) * 1000),
                "reason": last_reason,
            }))
            continue
        if result.get("ok"):
            raw = str(result.get("text") or "").strip()
            if raw.startswith("```"):
                raw = re.sub(r"^```(?:json)?\s*|\s*```$", "", raw, flags=re.I | re.S).strip()
            try:
                clean_grid_plan(json.loads(raw), str(catalog.get("text", {}).get("default") or "gpt-5.6"), catalog, task=task)
                result["planner_attempt"] = attempt_name
                result["planner_selected_model"] = model
                return result
            except (json.JSONDecodeError, ValueError) as exc:
                saw_temporary_failure = True
                last_reason = str(exc)[:120] or "invalid_planner_response"
                print("GRID_PLANNER_RETRY:", json.dumps({
                    "attempt": attempt_number, "kind": attempt_name, "model": model,
                    "elapsed_ms": int((time.monotonic() - started) * 1000), "reason": last_reason,
                }))
                continue
        if grid_planner_retryable_result(result):
            saw_temporary_failure = True
            last_reason = str(result.get("error") or "temporary_provider_failure")[:120]
            print("GRID_PLANNER_RETRY:", json.dumps({
                "attempt": attempt_number, "kind": attempt_name, "model": model,
                "elapsed_ms": int((time.monotonic() - started) * 1000), "reason": last_reason,
            }))
            continue
        # A real configuration/authentication/validation error must remain
        # visible unless it occurred only in the emergency fallback itself.
        if not saw_temporary_failure:
            return result
        last_reason = str(result.get("error") or last_reason)[:120]
        break

    print("GRID_PLANNER_UNAVAILABLE:", json.dumps({
        "primary_model": planner_model, "fallback_model": GRID_PLANNER_FALLBACK_MODEL,
        "reason": last_reason,
    }))
    return {
        "ok": False, "type": "text", "error": "planner_temporarily_unavailable",
        "message": "The Grid Director could not build a reliable plan. Please try again.",
        "retryable": True,
        "provider": "openai", "model": planner_model,
        "metadata": {"usage": {"input_tokens": 0, "output_tokens": 0}},
        "planner_attempt": "failed", "planner_selected_model": planner_model,
    }


def grid_planner_usage_credits(selected_model: str):
    def _credits(result):
        if not isinstance(result, dict):
            return 0
        return text_usage_credits(str(result.get("model") or selected_model), result.get("metadata"))
    return _credits


@app.post("/api/public/prostudio/grid/plan")
async def public_prostudio_grid_plan(request: Request):
    """Build a professional editable Grid plan. This call never starts media generation."""
    try:
        body = await request.json()
        telegram_id = int(getattr(request.state, "telegram_id", 0) or 0)
        if not telegram_id:
            raise HTTPException(status_code=401, detail="authentication_required")
        task = str((body or {}).get("task") or "").strip()
        if not task:
            return JSONResponse({"ok": False, "error": "task_required"}, status_code=400)
        # Task is a pure brief. The caller cannot downgrade, replace or
        # expose the director by submitting a model field from a saved or
        # modified client.
        planner_model = GRID_PLANNER_MODEL
        text_node_model = "gpt-5.6"
        context = (body or {}).get("context") if isinstance((body or {}).get("context"), dict) else {}
        catalog = grid_planner_catalog()
        planner_payload = {
            "prompt": grid_planner_prompt(task, catalog, context),
            "mode": "text", "category": "text", "model": planner_model, "provider": "sylvex-router",
            "text_options": {"tool": "text", "style": "professional", "format": "json", "language": "auto"},
            "history": [], "attachment": None, "telegram_id": telegram_id,
            "job_id": f"grid-plan:{uuid.uuid4()}", "output_token_cap": GRID_PLAN_MAX_OUTPUT_TOKENS,
            "_response_format": grid_plan_response_format(),
        }
        planner_input, planner_images = text_generation_price_input(planner_payload)
        primary_reservation = helper_text_reservation(planner_model, planner_input, GRID_PLAN_MAX_OUTPUT_TOKENS, planner_images)
        fallback_payload = {**planner_payload, "model": GRID_PLANNER_FALLBACK_MODEL, "output_token_cap": GRID_PLAN_FALLBACK_MAX_OUTPUT_TOKENS}
        fallback_input, fallback_images = text_generation_price_input(fallback_payload)
        fallback_reservation = helper_text_reservation(GRID_PLANNER_FALLBACK_MODEL, fallback_input, GRID_PLAN_FALLBACK_MAX_OUTPUT_TOKENS, fallback_images)
        # Preserve fail-closed pricing for the managed director. Reserve
        # whichever single successful attempt could cost
        # more; the user is never charged twice for a transport retry.
        reservation = max(primary_reservation, fallback_reservation) if primary_reservation > 0 else 0
        generated = await run_billed_helper(
            telegram_id,
            reservation,
            "grid_plan", lambda: asyncio.to_thread(grid_planner_generation_with_fallback, planner_payload, planner_model, catalog, task),
            client_request_id=str((body or {}).get("client_request_id") or ""),
            model=planner_model, usage_credits=grid_planner_usage_credits(planner_model),
        )
        if not generated.get("ok"):
            return JSONResponse(generated, status_code=502)
        raw = str(generated.get("text") or "").strip()
        if raw.startswith("```"):
            raw = re.sub(r"^```(?:json)?\s*|\s*```$", "", raw, flags=re.I | re.S).strip()
        clean = clean_grid_plan(json.loads(raw), text_node_model, catalog, task=task)
        return {
            "ok": True, **clean, "provider": generated.get("provider"),
            "planner_attempt": generated.get("planner_attempt") or "primary",
        }
    except SecurityError:
        raise
    except HTTPException:
        raise
    except (json.JSONDecodeError, ValueError) as exc:
        prostudio_error("GRID_PLANNER_INVALID_RESPONSE", exc)
        return JSONResponse({"ok": False, "error": "planner_invalid_response", "message": "The production plan was incomplete. Please refine the brief and try again."}, status_code=502)
    except Exception as exc:
        prostudio_error("GRID_PLANNER_FAILED", exc)
        return JSONResponse({"ok": False, "error": "planner_failed", "message": "Could not build the production chain."}, status_code=500)


HOME_ROUTE_MODES = ("image", "video", "music", "voice", "text", "grid", "tool")
HOME_ROUTE_MODEL = "gpt-4.1-mini"
HOME_ROUTE_MAX_OUTPUT_TOKENS = 300


def _home_route_choices(value, limit: int = 80) -> list:
    """Client-advertised model/tool ids, reduced to safe short identifiers."""
    if not isinstance(value, list):
        return []
    clean = []
    for item in value[:limit]:
        ident = re.sub(r"[^a-zA-Z0-9_.:\-]", "", str(item or ""))[:80]
        if ident and ident not in clean:
            clean.append(ident)
    return clean


HOME_ROUTE_SECTIONS = ("image", "video", "music", "voice", "text")
HOME_ROUTE_ATTACHMENT_KINDS = ("image", "video", "audio", "file")


def home_route_attachment_note(attachment, attachments) -> str:
    """One line per attached file (kind, name, type) for the classifier."""
    items = [attachment] if isinstance(attachment, dict) else []
    if isinstance(attachments, list):
        items = [item for item in attachments[:8] if isinstance(item, dict)] or items
    lines = []
    for item in items:
        kind = str(item.get("kind") or "").strip().lower()
        kind = kind if kind in HOME_ROUTE_ATTACHMENT_KINDS else "file"
        name = re.sub(r"[\r\n]+", " ", str(item.get("name") or "file"))[:120]
        mime = re.sub(r"[\r\n]+", " ", str(item.get("mime") or item.get("content_type") or ""))[:60]
        lines.append(f"Вложение ({kind}): {name} ({mime})")
    return "\n".join(lines)


def clean_home_route(route, message: str, models: dict, tools: list) -> dict:
    """Validate a router decision. Anything unclear falls back to Text and the
    user's original prompt is always passed through unchanged."""
    route = route if isinstance(route, dict) else {}
    mode = str(route.get("mode") or "").strip().lower()
    if mode not in HOME_ROUTE_MODES:
        mode = "text"
    tool = str(route.get("tool") or "").strip()
    if mode == "tool" and tool not in tools:
        mode, tool = "image", ""
    if mode != "tool":
        tool = ""
    model = str(route.get("model") or "").strip()
    if model not in (models.get(mode) or []):
        model = ""
    return {"ok": True, "ready": True, "mode": mode, "model": model, "tool": tool,
            "prompt": message, "reply": ""}


@app.post("/api/public/home-idea/route")
async def public_home_idea_route(request: Request):
    """Universal home router: classify the request and pick the destination
    (generator, exact model/tool or the full Text chat). Never launches a
    generation and never rewrites the user's prompt."""
    try:
        body = await request.json()
        message = str((body or {}).get("message") or "").strip()
        attachment = (body or {}).get("attachment") or None
        attachments = (body or {}).get("attachments") if isinstance((body or {}).get("attachments"), list) else []
        if not message and not attachment and not attachments:
            return JSONResponse({"ok": False, "error": "message_required"}, status_code=400)
        # The section the request was sent from (the home page's tab): a hint
        # for what the user means, never a destination by itself.
        section = str((body or {}).get("section") or "").strip().lower()
        section = section if section in HOME_ROUTE_SECTIONS else ""
        raw_models = (body or {}).get("models") if isinstance((body or {}).get("models"), dict) else {}
        models = {mode: _home_route_choices(raw_models.get(mode)) for mode in ("image", "video", "music", "voice", "text")}
        tools = _home_route_choices((body or {}).get("tools"))
        attachment_note = home_route_attachment_note(attachment, attachments)
        section_note = (
            f"Запрос отправлен из раздела «{section}». Если запрос не противоречит этому разделу, выбери его; "
            "text выбирай только для вопросов, обсуждений и написания текста."
        ) if section and section != "text" else ""
        catalog = "\n".join(f"{mode}: {', '.join(ids) or '-'}" for mode, ids in models.items())
        instruction = f"""
Ты — маршрутизатор SYLVEX. Определи, куда направить запрос пользователя. Ответь ТОЛЬКО JSON без markdown:
{{"mode":"image|video|music|voice|text|grid|tool","model":"","tool":""}}
Правила:
- image: пользователь просит создать, нарисовать, сгенерировать или отредактировать изображение/фото/картинку/логотип.
- video: просит создать или анимировать видео, ролик, клип.
- music: просит создать музыку, песню, трек, бит.
- voice: просит озвучить текст, сгенерировать речь/голос (TTS).
- tool: просит конкретный инструмент из списка инструментов ниже (например, удалить фон, апскейл); укажи его id в "tool".
- grid: только если пользователь прямо просит сетку/цепочку из нескольких генераций.
- text: вопрос, обсуждение, объяснение, план, перевод, написание текста или всё, что явно не просит медиа-генерацию.
- Если пользователь явно называет модель из списка моделей, укажи её id в "model" и соответствующий mode; иначе "model" оставь пустым.
- Вложения — это референсы пользователя (фото, видео, аудио): учитывай их тип вместе с текстом запроса.
- Если сомневаешься — {section if section and section != "text" else "text"}.
{section_note}
Модели:
{catalog}
Инструменты: {', '.join(tools) or '-'}
{attachment_note}
Запрос пользователя: {message[:4000]}
""".strip()
        route_payload = {
            "prompt": instruction, "mode": "text", "category": "text", "model": HOME_ROUTE_MODEL,
            "provider": "openai", "text_options": {"tool": "text", "format": "json", "style": "neutral"},
            "history": [], "attachment": None,
            "output_token_cap": HOME_ROUTE_MAX_OUTPUT_TOKENS,
        }
        route_input, route_images = await asyncio.to_thread(text_generation_price_input, route_payload)
        result = await run_billed_helper(
            int((body or {}).get("telegram_id") or 0),
            helper_text_reservation(HOME_ROUTE_MODEL, route_input, HOME_ROUTE_MAX_OUTPUT_TOKENS, route_images),
            "home_idea_route",
            lambda: asyncio.to_thread(text_generation, route_payload),
            client_request_id=str((body or {}).get("client_request_id") or ""),
            model=HOME_ROUTE_MODEL,
            usage_credits=text_generation_usage_credits(HOME_ROUTE_MODEL),
        )
        if not result.get("ok"):
            return JSONResponse(result, status_code=502)
        raw = str(result.get("text") or "").strip()
        if raw.startswith("```"):
            raw = re.sub(r"^```(?:json)?\s*|\s*```$", "", raw, flags=re.I | re.S).strip()
        try:
            route = json.loads(raw)
        except json.JSONDecodeError:
            route = {}
        return clean_home_route(route, message, models, tools)
    except SecurityError:
        raise
    except Exception as exc:
        prostudio_error("HOME_IDEA_ROUTE_FAILED", exc)
        return JSONResponse({"ok": False, "error": "idea_route_failed", "message": "SYLVEX временно не смог обработать запрос."}, status_code=500)


@app.post("/api/public/home-idea/realtime")
async def public_home_idea_realtime(request: Request):
    """Create a protected OpenAI Realtime WebRTC session; the standard API key stays on the server."""
    if "home_idea_realtime" in UNPRICED_HELPERS:
        return unpriced_helper_response("home_idea_realtime")
    if not OPENAI_API_KEY:
        return JSONResponse({"ok": False, "error": "openai_not_configured"}, status_code=503)
    sdp = (await request.body()).decode("utf-8", errors="ignore").strip()
    if not sdp:
        return JSONResponse({"ok": False, "error": "sdp_required"}, status_code=400)
    user_id = str(request.query_params.get("telegram_id") or "guest")
    safety_id = hashlib.sha256(("sylvex:" + user_id).encode()).hexdigest()
    session = {
        "type": "realtime", "model": os.getenv("OPENAI_REALTIME_MODEL", "gpt-realtime-2.1"),
        "instructions": "Ты SYLVEX AI. Общайся по-русски естественно и кратко. Помоги пользователю уточнить творческую идею и выбрать создание изображения, видео, музыки, озвучки, текста или сетку. Никогда не называй себя OpenAI или ChatGPT. Не запускай генерацию.",
        "audio": {"input": {"transcription": {"model": "gpt-4o-mini-transcribe"}}, "output": {"voice": "marin"}},
    }
    def create_call():
        return requests.post("https://api.openai.com/v1/realtime/calls",
            headers={"Authorization": f"Bearer {OPENAI_API_KEY}", "OpenAI-Safety-Identifier": safety_id},
            files={"sdp": (None, sdp), "session": (None, json.dumps(session))}, timeout=30)
    try:
        response = await asyncio.to_thread(create_call)
        return Response(content=response.content, status_code=response.status_code,
                        media_type=response.headers.get("content-type", "application/sdp"))
    except Exception as exc:
        prostudio_error("HOME_IDEA_REALTIME_FAILED", exc)
        return JSONResponse({"ok": False, "error": "realtime_unavailable"}, status_code=502)


@app.post("/api/public/prostudio/generate")
async def public_prostudio_generate(request: Request):
    payload = dict(await request.json())
    for internal_key in ("job_id", "generation_id", "load_test", "skip_telegram", "balance_charged", "cost_credits", "price_snapshot", "initData", "init_data", "initDataUnsafe", "_provider_timeout_seconds", "_response_format", "_openai_background", "_openai_poll_timeout_seconds", "_reasoning_effort", "_openai_idempotency_key",
                         "output_token_cap", TEXT_ATTACHMENT_BYTES_KEY):
        payload.pop(internal_key, None)
    resolved_grid_references = grid_references_service.resolve_grid_catalog_references(payload, WEBAPP_URL)
    if resolved_grid_references:
        prostudio_debug(
            "GRID_INTERNAL_REFERENCES_RESOLVED",
            project_id=str(payload.get("grid_project_id") or "")[:160],
            node_id=str(payload.get("grid_node_id") or "")[:180],
            count=resolved_grid_references,
        )
    normalize_grid_video_request(payload)
    telegram_id = _core_account_owner(request, payload)
    mode = (payload.get("mode") or payload.get("category") or "text").lower()
    category = (payload.get("category") or mode).lower()
    prompt = (payload.get("prompt") or "").strip()
    selected_model = (payload.get("model") or "").strip()
    selected_provider = (payload.get("provider") or "sylvex-router").strip().lower()
    image_options = payload.get("image_options") or {}
    if mode == "image" and is_edit_workspace_request(payload) and str(image_options.get("editWorkspaceMode") or "").lower() in {"camera", "lighting"}:
        # Cached clients may still submit former Qwen camera or Fal lighting models.
        # Store the actual route in new jobs as well as enforcing it at dispatch.
        selected_provider = payload["provider"] = "openai"
        selected_model = payload["model"] = "gpt_image_2_5_sunburst"
    elif mode == "image" and is_edit_workspace_sylvex_restore(payload):
        # Restored Edit sessions may still carry the former Topaz selection.
        # Persist the real route in the queued job as well as at dispatch.
        selected_provider = payload["provider"] = "openai"
        selected_model = payload["model"] = SYLVEX_RESTORE_MODEL_KEY
    elif mode == "image" and is_edit_workspace_request(payload) and str(image_options.get("editWorkspaceMode") or "edit").lower() == "edit":
        selected_model = edit_workspace_image_model(payload)
        if selected_model not in EDIT_WORKSPACE_IMAGE_MODEL_IDS:
            prostudio_debug("GENERATE_VALIDATION_REJECTED", status=422, code="unsupported_edit_model", mode=mode, model=selected_model, invalid_fields=["model"])
            return JSONResponse({
                "ok": False,
                "error": "unsupported_edit_model",
                "message": "The selected model is not available for Edit.",
            }, status_code=422)
        mapping = image_provider_mapping(selected_model)
        selected_provider = str(mapping.get("provider") or "").lower()
        payload["model"] = selected_model
        payload["provider"] = selected_provider
        image_options["editWorkspaceModel"] = selected_model
        image_options["modelId"] = selected_model
    video_options = payload.get("video_options") or {}
    voice_options = payload.get("voice_options") or {}
    reference_images = (
        _json_list(image_options.get("referenceImageUrls"))
        or _json_list(image_options.get("referenceImages"))
        or _json_list(image_options.get("characterReferences"))
        or _json_list(image_options.get("objectReferences"))
    )
    video_references = (
        video_options.get("reference_images")
        or video_options.get("referenceImageUrls")
        or []
    )
    video_template = video_options.get("video_template") if isinstance(video_options.get("video_template"), dict) else {}
    video_media = (
        video_options.get("start_image")
        or video_options.get("end_image")
        or video_options.get("input_video")
        or video_options.get("video_url")
        or video_options.get("image_url")
        or video_options.get("character_image")
        or video_template.get("reference_video")
        or video_template.get("video_url")
        or video_template.get("template_video_url")
        or video_template.get("preview_video")
    )

    print("PRO STUDIO BACKEND ROUTER:", {
        "mode": mode,
        "category": category,
        "provider": selected_provider,
        "model": selected_model,
        "has_image_options": bool(image_options),
        "has_video_options": bool(video_options),
    })

    generation_modes = {"image", "video", "music", "voice"}
    text_modes = {"text", "chat", "pro", "lite"}
    if mode not in generation_modes | text_modes:
        prostudio_debug("GENERATE_VALIDATION_REJECTED", status=422, code="unsupported_generation_mode", mode=mode, model=selected_model, invalid_fields=["mode"])
        return JSONResponse({"ok": False, "error": "unsupported_generation_mode"}, status_code=422)
    # Pro Studio is a subscription feature. This server-side check is the
    # enforcement point; hiding the button in the Mini App is only cosmetic.
    user_state = get_user_state(telegram_id) if telegram_id else {}
    if not telegram_id or user_state.get("subscription_status") != "active":
        return JSONResponse({
            "ok": False,
            "paywall": True,
            "subscription_required": True,
            "error": "prostudio_subscription_required",
            "message": "Pro Studio доступна после активации подписки.",
            "shop_url": SHOP_WEBAPP_URL,
        }, status_code=403)
    if mode == "image" and is_edit_workspace_request(payload):
        feature_error = validate_image_feature_request(payload)
        if feature_error:
            return JSONResponse(feature_error, status_code=400)
    if mode in text_modes:
        if text_media_attachment(payload):
            # No SYLVEX tariff for transcription or audio/video input tokens:
            # refused before any reservation or provider call.
            print("UNPRICED_HELPER_BLOCKED:", {"operation": "text_media_attachment"})
            prostudio_debug("GENERATE_VALIDATION_REJECTED", status=422, code="pricing_not_configured", mode=mode, model=selected_model, invalid_fields=["attachment"])
            return JSONResponse({"ok": False, "error": "pricing_not_configured",
                                 "message": "Аудио и видео во вложениях пока недоступны в Text."}, status_code=422)
        payload["output_token_cap"] = text_output_cap(payload)
        attachment = payload.get("attachment") if isinstance(payload.get("attachment"), dict) else {}
        attachment_mime = str(attachment.get("mime") or attachment.get("content_type") or "").lower()
        if attachment and not attachment_mime.startswith("image/"):
            # Measure the document text once so the reservation bounds what
            # text_generation() will actually send.
            try:
                document_text = await asyncio.to_thread(text_attachment_plain_text, attachment)
            except Exception as exc:
                prostudio_error("TEXT_ATTACHMENT_MEASURE_FAILED", exc, telegram_id=telegram_id)
            else:
                payload[TEXT_ATTACHMENT_BYTES_KEY] = len(str(document_text or "").encode("utf-8"))
    if video_editor_request(payload):
        # Editor actions return their media into the editor project; the
        # result is not also posted to the Telegram chat.
        payload["skip_telegram"] = True
    if mode == "video" and is_enhance_video_request(payload):
        enhance_error = await prepare_enhance_video_request(payload)
        if enhance_error:
            return JSONResponse(enhance_error, status_code=400)
        prompt = payload["prompt"]
        selected_model = payload["model"]
        selected_provider = "runway"
    if mode == "voice":
        dialogue_error = normalize_voice_dialogue_request(payload)
        if dialogue_error:
            return JSONResponse(dialogue_error, status_code=400)
        prompt = (payload.get("prompt") or "").strip()
        selected_model = (payload.get("model") or "").strip()
        selected_provider = (payload.get("provider") or selected_provider).strip().lower()
    cost_estimate = calculate_generation_price(payload)
    payload["price_snapshot"] = cost_estimate.get("price_snapshot") or {}
    if not cost_estimate.get("pricing_available", mode in {"image", "video"}):
        prostudio_debug("GENERATE_VALIDATION_REJECTED", status=422, code="pricing_not_configured", mode=mode, model=selected_model, invalid_fields=["model", f"{mode}_options"])
        return JSONResponse({
            "ok": False,
            "error": "pricing_not_configured",
            "message": "Для выбранной модели ещё нет подтверждённой цены. Запуск остановлен.",
        }, status_code=422)
    required_credits = int(cost_estimate.get("credits") or 0)
    if required_credits <= 0 and not edit_workspace_service.is_free_resize(payload):
        prostudio_debug("GENERATE_VALIDATION_REJECTED", status=422, code="pricing_not_configured", mode=mode, model=selected_model, invalid_fields=["model", f"{mode}_options"])
        return JSONResponse({"ok": False, "error": "pricing_not_configured", "message": "Не удалось определить стоимость генерации."}, status_code=422)
    try:
        # BUG-4 immediate mitigation: same blocking-call issue as
        # public_prostudio_active_job() above - see its comment. This
        # pre-check runs on every generation submission, so it blocked the
        # event loop just as often.
        active_job = await asyncio.to_thread(get_active_prostudio_job, telegram_id) if telegram_id else {}
    except Exception as exc:
        prostudio_error("ACTIVE_JOB_PRECHECK_FAILED", exc, telegram_id=telegram_id)
        return JSONResponse({
            "ok": False,
            "error": "active_job_lookup_failed",
            "message": "Не удалось проверить активную генерацию.",
        }, status_code=503)
    # Direct text requests remain available while a media task is running.
    # They do not use the worker queue and have independent, idempotent billing.
    if active_job and mode not in text_modes:
        return JSONResponse({
            "ok": False,
            "error": "active_generation_exists",
            "message": "У пользователя уже есть активная генерация.",
            "active_job_id": active_job.get("id") or "",
            "status": active_job.get("status") or "queued",
        }, status_code=409)
    if mode in generation_modes and is_internal_ui_model(selected_model):
        return invalid_generation_model_response(selected_model)

    voice_media = voice_options.get("attachment") or voice_options.get("uploads")
    if not prompt and not payload.get("attachment") and not voice_media and not reference_images and not video_references and not video_media:
        return JSONResponse({"ok": False, "error": "Prompt or attachment is required"}, status_code=400)

    if mode == "image":
        try:
            normalize_payload_image_seed(payload)
            image_options = payload.get("image_options") or {}
        except ValueError as exc:
            return JSONResponse(
                {"ok": False, "type": "image", "error": str(exc)},
                status_code=400,
            )
        feature_error = validate_image_feature_request(payload)
        if feature_error:
            return JSONResponse(feature_error, status_code=400)

        telegram_id = int(payload.get("telegram_id") or 0)
        cost_estimate = calculate_generation_price(payload)
        payload["price_snapshot"] = cost_estimate.get("price_snapshot") or payload.get("price_snapshot") or {}
        required_credits = int(cost_estimate.get("credits") or 0)
        if required_credits > 0:
            user_state = get_user_state(telegram_id) if telegram_id else {"balance": 0}
            balance = int(user_state.get("balance") or 0)
            if balance < required_credits:
                return JSONResponse({
                    "ok": False,
                    "paywall": True,
                    "insufficient_balance": True,
                    "error": "Недостаточно токенов для генерации",
                    "required_credits": required_credits,
                    "balance": balance,
                    "generation_cost": cost_estimate.get("generation_cost") or "",
                    "cost_usd": cost_estimate.get("cost_usd") or 0,
                    "shop_url": SHOP_WEBAPP_URL,
                }, status_code=402)

    if mode == "music":
        music_error = validate_music_reference_request(payload)
        if music_error:
            return JSONResponse(music_error, status_code=400)

    if mode == "video":
        feature_error = validate_video_feature_request(payload) or await validate_reference_video_media(payload)
        if feature_error:
            await asyncio.to_thread(log_video_reference_failure, "prostudio_generate", payload, None, feature_error.get("error"))
            return JSONResponse(feature_error, status_code=400)

        telegram_id = int(payload.get("telegram_id") or 0)
        cost_estimate = calculate_generation_price(payload)
        payload["price_snapshot"] = cost_estimate.get("price_snapshot") or payload.get("price_snapshot") or {}
        required_credits = int(cost_estimate.get("credits") or 0)
        if required_credits > 0:
            user_state = get_user_state(telegram_id) if telegram_id else {"balance": 0}
            balance = int(user_state.get("balance") or 0)
            if balance < required_credits:
                return JSONResponse({
                    "ok": False,
                    "paywall": True,
                    "insufficient_balance": True,
                    "error": "Недостаточно токенов для генерации",
                    "required_credits": required_credits,
                    "balance": balance,
                    "generation_cost": cost_estimate.get("generation_cost") or "",
                    "cost_usd": cost_estimate.get("cost_usd") or 0,
                    "shop_url": SHOP_WEBAPP_URL,
                }, status_code=402)

    if mode in generation_modes:
        telegram_id = int(payload.get("telegram_id") or 0)
        user_state = get_user_state(telegram_id) if telegram_id else {"balance": 0}
        balance = int(user_state.get("balance") or 0)
        if balance < required_credits:
            return JSONResponse({
                "ok": False,
                "paywall": True,
                "insufficient_balance": True,
                "error": "Недостаточно токенов для генерации",
                "required_credits": required_credits,
                "balance": balance,
                "generation_cost": cost_estimate.get("generation_cost") or "",
                "shop_url": SHOP_WEBAPP_URL,
            }, status_code=402)

    prostudio_debug(
        "GENERATE_ACCEPTED",
        mode=mode,
        category=category,
        provider=selected_provider,
        model=selected_model,
        telegram_id=int(payload.get("telegram_id") or 0),
        worker_enabled=PROSTUDIO_WORKER_ENABLED,
    )
    if mode in text_modes:
        text_timing_start = time.monotonic()
        text_received_at = time.time()
        prostudio_debug("TEXT_REQUEST_RECEIVED", telegram_id=telegram_id, model=selected_model, timestamp=round(text_timing_start, 6))
        request_key = str(payload.get("client_request_id") or "").strip()
        cache_key = f"{int(payload.get('telegram_id') or 0)}:{request_key}" if request_key else ""
        response_future = None
        owns_request = True
        if cache_key:
            with PROSTUDIO_TEXT_INFLIGHT_LOCK:
                cached = PROSTUDIO_TEXT_RESPONSE_CACHE.get(cache_key)
                response_future = PROSTUDIO_TEXT_INFLIGHT.get(cache_key)
                if cached is not None:
                    pass
                elif response_future is None:
                    response_future = asyncio.get_running_loop().create_future()
                    PROSTUDIO_TEXT_INFLIGHT[cache_key] = response_future
                else:
                    owns_request = False
            if cached is not None:
                return cached
            if not owns_request:
                # A transport retry must receive the first request's outcome,
                # never open a second provider call or balance reservation.
                return await asyncio.shield(response_future)

        def complete_text_request(response, cache_success: bool = False):
            if not cache_key or not owns_request:
                return response
            with PROSTUDIO_TEXT_INFLIGHT_LOCK:
                if cache_success:
                    if len(PROSTUDIO_TEXT_RESPONSE_CACHE) > 200:
                        PROSTUDIO_TEXT_RESPONSE_CACHE.clear()
                    PROSTUDIO_TEXT_RESPONSE_CACHE[cache_key] = response
                pending = PROSTUDIO_TEXT_INFLIGHT.pop(cache_key, None)
                if pending is not None and not pending.done():
                    pending.set_result(response)
            return response

        def fail_text_request(exc: Exception):
            if cache_key and owns_request:
                with PROSTUDIO_TEXT_INFLIGHT_LOCK:
                    pending = PROSTUDIO_TEXT_INFLIGHT.pop(cache_key, None)
                    if pending is not None and not pending.done():
                        pending.set_result(JSONResponse({"ok": False, "error": "text_generation_failed"}, status_code=503))

        if not selected_model or is_internal_ui_model(selected_model):
            payload["model"] = "gpt-5.5"
        prostudio_debug(
            "TEXT_VALIDATION_DONE", telegram_id=telegram_id,
            elapsed_ms=round((time.monotonic() - text_timing_start) * 1000),
        )
        try:
            generation_id = reserve_direct_text_generation(telegram_id, required_credits)
        except SecurityError as exc:
            return complete_text_request(JSONResponse({"ok": False, "paywall": exc.status == 402, "error": exc.code}, status_code=exc.status))
        except Exception as exc:
            fail_text_request(exc)
            raise
        provider_call_started_at = time.monotonic()
        text_sent_at = time.time()
        prostudio_debug("TEXT_PROVIDER_REQUEST_SENT", telegram_id=telegram_id, model=selected_model)
        try:
            with billing_scope(generation_id, required_credits):
                result = await asyncio.to_thread(text_generation, payload)
        except requests.Timeout as exc:
            release_direct_text_generation(generation_id)
            prostudio_error("TEXT_PROVIDER_TIMEOUT", exc, telegram_id=telegram_id, model=selected_model)
            return complete_text_request(JSONResponse({
                "ok": False,
                "error": "text_provider_timeout",
                "message": "The text model did not respond in time. Please retry the Grid node.",
                "retryable": True,
            }, status_code=504))
        except requests.RequestException as exc:
            release_direct_text_generation(generation_id)
            prostudio_error("TEXT_PROVIDER_REQUEST_FAILED", exc, telegram_id=telegram_id, model=selected_model)
            return complete_text_request(JSONResponse({
                "ok": False,
                "error": "text_provider_unavailable",
                "message": "The text provider is temporarily unavailable.",
                "retryable": True,
            }, status_code=502))
        except Exception as exc:
            release_direct_text_generation(generation_id)
            prostudio_error("TEXT_PROVIDER_FAILED", exc, telegram_id=telegram_id, model=selected_model)
            return complete_text_request(JSONResponse({
                "ok": False,
                "error": "text_generation_failed",
                "message": translate_provider_error(exc, provider=selected_provider, model=selected_model),
                "retryable": False,
            }, status_code=502))
        provider_done_at = time.monotonic()
        prostudio_debug(
            "TEXT_PROVIDER_RESPONSE_RECEIVED", telegram_id=telegram_id, ok=bool(result.get("ok")),
            provider_elapsed_ms=round((provider_done_at - provider_call_started_at) * 1000),
        )
        if not result.get("ok"):
            release_direct_text_generation(generation_id)
            return complete_text_request(JSONResponse(result, status_code=502))
        # Settle on the provider-reported usage; the rest of the reservation
        # is returned. Unknown usage settles at the reserved upper bound.
        snapshot = payload.get("price_snapshot") if isinstance(payload.get("price_snapshot"), dict) else {}
        project_fee = int(snapshot.get("sylvex_project_fee_credits") or snapshot.get("additions_credits") or 0)
        provider_reservation = max(0, required_credits - project_fee)
        provider_charge = settled_helper_credits(
            provider_reservation,
            text_generation_usage_credits(normalize_text_model(payload.get("model") or "gpt-5.5"))(result),
            "text",
        )
        charged_credits = min(required_credits, provider_charge + project_fee)
        settle_payload = dict(payload)
        settle_payload["price_snapshot"] = dict(
            snapshot,
            final_credits=charged_credits,
            reserved_credits=required_credits,
            provider_and_model_credits=provider_charge,
            sylvex_project_fee_credits=project_fee,
        )
        result["cost_credits"] = charged_credits
        result["reserved_credits"] = required_credits
        result["generation_cost"] = f"{charged_credits} ⚡"
        billing = charge_generation_balance(telegram_id, generation_id, result, settle_payload)
        if not billing.get("charged") and not billing.get("already_charged"):
            release_direct_text_generation(generation_id)
            return complete_text_request(JSONResponse({"ok": False, "error": "billing_failed"}, status_code=503))
        prostudio_debug(
            "TEXT_RESULT_PERSISTED", telegram_id=telegram_id,
            elapsed_ms_since_provider_response=round((time.monotonic() - provider_done_at) * 1000),
        )
        # History/conversation save enriches an already-successful, already-
        # billed response. Its failure must never turn a successful
        # generation into an error response for the user.
        try:
            result["conversation_id"] = await asyncio.to_thread(save_prostudio_message, payload, result)
        except Exception as exc:
            prostudio_error("TEXT_HISTORY_SAVE_FAILED", exc, telegram_id=telegram_id)
            result.setdefault("conversation_id", "")
        prostudio_debug(
            "TEXT_CLIENT_VISIBLE_COMPLETION", telegram_id=telegram_id,
            total_elapsed_ms=round((time.monotonic() - text_timing_start) * 1000),
        )
        # The direct text request has no job row: its confirmed stages travel
        # with the answer (see prostudio_job_progress for job-backed modes).
        text_ready_at = time.time()
        result["progress"] = {
            "stages": {"received": text_received_at, "sent": text_sent_at, "ready": text_ready_at},
            "server_time": text_ready_at,
        }
        return complete_text_request(result, cache_success=True)

    # Worker owns Telegram delivery. Persist this flag in request_json before
    # the job is inserted so provider adapters cannot send the result early.
    if mode in generation_modes:
        payload["skip_telegram"] = True
    try:
        job_id = create_prostudio_generation_job(payload) if mode in generation_modes else ""
    except SecurityError as exc:
        return JSONResponse({"ok": False, "error": exc.code}, status_code=exc.status)
    except ActiveProstudioJobError as exc:
        return JSONResponse({
            "ok": False,
            "error": "active_generation_exists",
            "message": "У пользователя уже есть активная генерация.",
            "active_job_id": exc.job_id,
            "status": exc.status,
        }, status_code=409)
    except Exception:
        return JSONResponse({
            "ok": False,
            "error": "generation_job_create_failed",
            "message": "Не удалось создать задачу генерации.",
        }, status_code=500)
    if job_id:
        payload["job_id"] = job_id
        payload["generation_id"] = job_id
        prostudio_debug("GENERATE_JOB_CREATED", job_id=job_id, mode=mode, worker_enabled=PROSTUDIO_WORKER_ENABLED)
    if job_id:
        log_user_event(
            int(payload.get("telegram_id") or 0),
            "miniapp",
            "generation",
            "generation_queued",
            {"job_id": job_id, "mode": mode, "model": selected_model, "provider": selected_provider},
        )

    prostudio_debug("GENERATE_QUEUED_FOR_WORKER", job_id=job_id)

    return {
        "ok": True,
        "job_id": job_id,
        "generation_id": job_id,
        "status": "queued"
    }


def resolve_prostudio_provider_for_slot(payload: dict, mode: str, selected_model: str, selected_provider: str) -> str:
    """Resolve the real provider before any external generation request."""
    if mode == "image" and is_edit_workspace_request(payload):
        edit_mode = str((payload.get("image_options") or {}).get("editWorkspaceMode") or "edit").lower()
        if edit_mode == "upscale":
            return "OPENAI" if is_edit_workspace_sylvex_restore(payload) else "TOPAZ"
        if edit_mode == "edit":
            mapping = image_provider_mapping(edit_workspace_image_model(payload))
            return normalize_provider(mapping.get("provider") or selected_provider)
        return "OPENAI"
    candidate = selected_provider
    if mode == "image":
        if is_seedream_request(payload):
            candidate = "byteplus"
        else:
            mapping = image_provider_mapping(selected_model) if selected_model else {}
            candidate = mapping.get("provider") or candidate
    elif mode in {"text", "chat", "pro", "lite"}:
        config = TEXT_MODEL_VARIANTS.get(selected_model) or TEXT_MODEL_VARIANTS.get("gpt-5.5") or {}
        candidate = config.get("provider") or candidate

    normalized = normalize_provider(candidate)
    if normalized and normalized not in {"SYLVEX_ROUTER", "AUTO"}:
        return normalized

    # Last-resort model inference covers old queued payloads which predate the
    # normalized provider field. It never changes the provider payload itself.
    haystack = f"{selected_provider} {selected_model}".lower()
    model_hints = (
        ("seedream", "BYTEPLUS"), ("byteplus", "BYTEPLUS"),
        ("gemini", "GEMINI"), ("imagen", "GEMINI"), ("nano_banana", "GEMINI"), ("lyria", "GEMINI"),
        ("gpt", "OPENAI"), ("openai", "OPENAI"), ("qwen", "QWEN"),
        ("grok", "GROK"), ("xai", "GROK"), ("kling", "KLING"),
        ("runway", "RUNWAY"), ("eleven", "ELEVENLABS"), ("heygen", "HEYGEN"),
        ("hedra", "HEDRA"), ("higgsfield", "HIGGSFIELD"), ("luma", "LUMA"),
        ("flux", "FLUX"), ("ideogram", "IDEOGRAM"), ("recraft", "RECRAFT"),
        ("fashn", "FASHN"), ("suno", "SUNO"), ("udio", "SUNO"),
    )
    for hint, provider in model_hints:
        if hint in haystack:
            return provider
    raise RuntimeError(
        f"Cannot apply global provider limit: unresolved provider "
        f"for mode={mode}, model={selected_model}, provider={selected_provider}"
    )


async def dispatch_prostudio_provider_request(
    job_id: str,
    payload: dict,
    mode: str,
    selected_model: str,
    selected_provider: str,
    text_modes: set,
) -> dict:
    """Perform one initial provider submission/generation attempt."""
    require_billing_scope("dispatch_prostudio_provider_request")
    result = None
    if mode == "image" and is_edit_workspace_request(payload):
        edit_mode = str((payload.get("image_options") or {}).get("editWorkspaceMode") or "edit")
        edit_mapping = image_provider_mapping(edit_workspace_image_model(payload)) if edit_mode == "edit" else {}
        edit_provider = "openai" if is_edit_workspace_sylvex_restore(payload) else "topaz" if edit_mode == "upscale" else edit_mapping.get("provider") or "openai"
        prostudio_debug("JOB_PROVIDER_DISPATCH", job_id=job_id, mode=mode, provider=edit_provider, model=selected_model, route="generate_edit_workspace_image", edit_mode=edit_mode)
        result = await run_provider_coroutine_off_loop(lambda: generate_edit_workspace_image(payload))
    elif mode == "image" and is_watermark_removal_request(payload):
        prostudio_debug("JOB_PROVIDER_DISPATCH", job_id=job_id, mode=mode, provider="openai", model=selected_model, route="generate_watermark_removal_image")
        result = await run_provider_coroutine_off_loop(lambda: generate_watermark_removal_image(payload))
    elif mode == "image" and is_replace_object_request(payload):
        prostudio_debug("JOB_PROVIDER_DISPATCH", job_id=job_id, mode=mode, provider="openai", model=selected_model, route="generate_replace_object_image")
        result = await run_provider_coroutine_off_loop(lambda: generate_replace_object_image(payload))
    elif mode == "image" and is_remove_object_request(payload):
        prostudio_debug("JOB_PROVIDER_DISPATCH", job_id=job_id, mode=mode, provider="openai", model=selected_model, route="generate_remove_object_image")
        # Isolated Quick Tool flow - never falls through to the normal
        # Seedream/image_generation dispatch below, which would read
        # image_options.characterReferences/objectReferences/style.
        result = await run_provider_coroutine_off_loop(lambda: generate_remove_object_image(payload))
    elif mode == "image" and is_try_on_request(payload):
        prostudio_debug("JOB_PROVIDER_DISPATCH", job_id=job_id, mode=mode, provider="fashn", model=selected_model, route="generate_try_on_image")
        # Isolated Quick Tool flow - never falls through to the normal
        # Seedream/image_generation dispatch below, which would read
        # image_options.characterReferences/objectReferences/style.
        result = await run_provider_coroutine_off_loop(lambda: generate_try_on_image(payload))
    elif mode == "image" and is_remove_bg_request(payload):
        prostudio_debug("JOB_PROVIDER_DISPATCH", job_id=job_id, mode=mode, provider="ideogram", model=selected_model, route="generate_remove_bg_image")
        # Isolated Quick Tool flow - never falls through to the normal
        # Seedream/image_generation dispatch below, which would read
        # image_options.characterReferences/objectReferences/style.
        result = await run_provider_coroutine_off_loop(lambda: generate_remove_bg_image(payload))
    elif mode == "image" and is_replace_character_request(payload):
        prostudio_debug("JOB_PROVIDER_DISPATCH", job_id=job_id, mode=mode, provider="flux", model=selected_model, route="generate_character_replace_image")
        # Isolated Quick Tool flow - never falls through to the normal
        # Seedream/image_generation dispatch below, which would read
        # image_options.characterReferences/objectReferences/style.
        result = await run_provider_coroutine_off_loop(lambda: generate_character_replace_image(payload))
    elif mode == "image" and is_enhance_photo_request(payload):
        sylvex_restore = is_sylvex_restore_request(payload)
        enhance_provider = "openai" if sylvex_restore else "topaz"
        enhance_route = "generate_sylvex_restore_image" if sylvex_restore else "generate_enhance_photo_image"
        prostudio_debug("JOB_PROVIDER_DISPATCH", job_id=job_id, mode=mode, provider=enhance_provider, model=selected_model, route=enhance_route)
        # Isolated Quick Tool flow - never falls through to the normal
        # Seedream/image_generation dispatch below, which would read
        # image_options.characterReferences/objectReferences/style.
        if sylvex_restore:
            result = await run_provider_coroutine_off_loop(lambda: generate_sylvex_restore_image(payload))
        else:
            result = await run_provider_coroutine_off_loop(lambda: generate_enhance_photo_image(payload))
    elif mode == "image" and is_seedream_request(payload):
        prostudio_debug("JOB_PROVIDER_DISPATCH", job_id=job_id, mode=mode, provider="bytedance", model=selected_model, route="generateBytePlusSeedreamImage")
        # Seedream's image adapter makes blocking requests.post calls; keep them off the shared event loop.
        result = await run_provider_coroutine_off_loop(lambda: generateBytePlusSeedreamImage(payload))
    elif mode == "image":
        prostudio_debug("JOB_PROVIDER_DISPATCH", job_id=job_id, mode=mode, provider=selected_provider, model=selected_model, route="image_generation")
        # image_generation() calls synchronous per-provider adapters (OpenAI, Flux,
        # Recraft, Gemini, Qwen, Grok, Ideogram) that block on requests.post; keep
        # them off the shared event loop, same as video_generation below.
        result = await run_provider_coroutine_off_loop(lambda: image_generation(payload))
    elif mode == "video" and is_enhance_video_request(payload):
        prostudio_debug("JOB_PROVIDER_DISPATCH", job_id=job_id, mode=mode, provider="runway", model=selected_model, route="generate_enhance_video")
        result = await run_provider_coroutine_off_loop(lambda: generate_enhance_video(payload))
    elif mode == "video" and is_animate_photo_request(payload):
        prostudio_debug("JOB_PROVIDER_DISPATCH", job_id=job_id, mode=mode, provider="runway", model=selected_model, route="generate_animate_photo_video")
        # Isolated Quick Tool flow - never falls through to the normal
        # video_generation dispatch below, which would read
        # video_options.characterReferences/objectReferences/style.
        result = await run_provider_coroutine_off_loop(lambda: generate_animate_photo_video(payload))
    elif mode == "video":
        prostudio_debug("JOB_PROVIDER_DISPATCH", job_id=job_id, mode=mode, provider=selected_provider, model=selected_model, route="video_generation")
        result = await run_provider_coroutine_off_loop(lambda: video_generation(payload))
    elif mode == "music":
        prostudio_debug("JOB_PROVIDER_DISPATCH", job_id=job_id, mode=mode, provider=selected_provider, model=selected_model, route="audio_generation")
        result = await audio_generation(payload)
    elif mode == "voice":
        if is_voice_video_voiceover_request(payload):
            input_video = voice_uploaded_video_url(payload)
            if not input_video:
                result = {"ok": False, "type": "video", "error": "Для режима «Озвучить видео» нужно загрузить видео"}
            else:
                voice_payload = json.loads(json.dumps(payload))
                voice_payload["skip_telegram"] = True
                voice_options = voice_payload.setdefault("voice_options", {})
                voice_options["elevenlabs_tool"] = "text_to_speech"
                voice_options["runway_tool"] = "text_to_speech"
                voice_options["upload_purpose"] = "voiceover"
                voice_options["uploadPurpose"] = "voiceover"
                voice_options["uploads"] = []
                voice_options["attachment"] = None
                prostudio_debug("JOB_PROVIDER_DISPATCH", job_id=job_id, mode=mode, provider=selected_provider, model=selected_model, route="voice_video_voiceover_tts")
                audio_result = await audio_generation(voice_payload)
                if not isinstance(audio_result, dict) or not audio_result.get("ok"):
                    result = audio_result if isinstance(audio_result, dict) else {"ok": False, "type": "voice", "error": "Не удалось создать озвучку для видео"}
                else:
                    prostudio_debug("JOB_PROVIDER_DISPATCH", job_id=job_id, mode=mode, provider="local-ffmpeg", model=selected_model, route="voice_video_voiceover_mux")
                    result = build_voice_video_voiceover_result(payload, audio_result, input_video)
            if isinstance(result, dict):
                result["voice_video_voiceover"] = True
        else:
            prostudio_debug("JOB_PROVIDER_DISPATCH", job_id=job_id, mode=mode, provider=selected_provider, model=selected_model, route="voice_generation")
            result = await audio_generation(payload)
    elif mode in text_modes:
        if not selected_model or is_internal_ui_model(selected_model):
            payload["model"] = "gpt-5.5"
        result = await asyncio.to_thread(text_generation, payload)
    else:
        result = {"ok": False, "error": "Unknown generation mode", "mode": mode}

    if mode == "voice" and isinstance(result, dict) and result.get("ok"):
        actual_voice_cost = voice_provider_usage_cost_usd(payload, result)
        if actual_voice_cost is not None:
            result["provider_cost_usd_actual"] = actual_voice_cost
    return result


def _log_circuit_transition(stage: str, provider: str, job_id: str, attempt: int, status_code, delay: float, outcome: dict):
    prostudio_debug(
        stage,
        provider=provider,
        job_id=job_id,
        attempt=attempt,
        status_code=status_code or "",
        delay=round(float(delay or 0), 3),
        circuit_state=outcome.get("state") or "CLOSED",
        failure_count=int(outcome.get("failure_count") or 0),
        worker_id=WORKER_ID,
    )


async def provider_call_with_retry(job_id: str, provider: str, operation) -> dict:
    """Run one logical provider operation with bounded transient retries."""
    async def record_outcome(transient: bool):
        return await asyncio.to_thread(
            circuit_record_outcome, DATABASE_URL, provider, job_id, transient
        )

    return await run_with_provider_retry(
        provider=provider,
        job_id=job_id,
        operation=operation,
        record_outcome=record_outcome,
        log=prostudio_debug,
        worker_id=WORKER_ID,
    )


def verify_job_reservation(job_id: str, credits: int) -> None:
    """The job's own reservation must still be held before any dispatch."""
    if not DATABASE_URL:
        raise SecurityError("billing_unavailable", 503)
    conn = db_connect(DATABASE_URL)
    cursor = conn.cursor()
    try:
        assert_reserved(cursor, job_id, credits)
    finally:
        cursor.close()
        conn.close()


async def run_prostudio_provider_request(
    job_id: str,
    payload: dict,
    mode: str,
    selected_model: str,
    selected_provider: str,
    text_modes: set,
    provider: str,
) -> tuple[dict, str]:
    """Billing gate for every queued job: a known SYLVEX price, the job's own
    held reservation, and one billing scope for all of its provider calls
    (retries and polling included). Settlement/release happen in the worker
    via charge_generation_balance()/update_prostudio_generation_job()."""
    snapshot = payload.get("price_snapshot") if isinstance(payload.get("price_snapshot"), dict) else {}
    credits = int(snapshot.get("final_credits") or 0)
    free = mode == "image" and edit_workspace_service.is_free_resize(payload)
    try:
        if not free:
            if credits <= 0:
                raise SecurityError("pricing_not_configured", 402)
            await asyncio.to_thread(verify_job_reservation, job_id, credits)
        with billing_scope(job_id, credits, free=free), generation_stages.reporting(
            lambda stage: record_prostudio_job_stage(job_id, stage)
        ):
            result, status = await _run_prostudio_provider_request_billed(
                job_id, payload, mode, selected_model, selected_provider, text_modes, provider,
            )
        if mode == "video" and status == "failed":
            try:
                await asyncio.to_thread(log_video_reference_failure, "prostudio_job", payload, result)
            except Exception as exc:
                print("VIDEO_REFERENCE_LOG_FAILED:", type(exc).__name__)
        return result, status
    except SecurityError as exc:
        prostudio_debug("JOB_BILLING_BLOCKED", job_id=job_id, mode=mode, reason=exc.code, credits=credits)
        return {"ok": False, "type": mode, "error": "Генерация недоступна: стоимость не подтверждена.", "raw_error": exc.code}, "failed"


async def _run_prostudio_provider_request_billed(
    job_id: str,
    payload: dict,
    mode: str,
    selected_model: str,
    selected_provider: str,
    text_modes: set,
    provider: str,
) -> tuple[dict, str]:
    """Submit and poll a provider with retry.

    A concurrency slot is held only while a real dispatch attempt is in
    flight: retrying after a transient failure sleeps for backoff with no
    slot held, since nothing is actually running at the provider during that
    wait. Once the provider accepts an async job, one slot is held
    continuously through the poll loop - that job is genuinely occupying the
    account's real capacity at the provider regardless of our poll cadence.
    """
    async def dispatch_attempt():
        async with provider_slot(
            DATABASE_URL, provider, job_id, prostudio_debug, wait_for_slot=False,
        ):
            generation_stages.report("sent")
            return await dispatch_prostudio_provider_request(
                job_id, payload, mode, selected_model, selected_provider, text_modes
            )

    if mode == "image" and edit_workspace_service.is_free_resize(payload):
        # Pixel resizing is local work; it needs neither an AI lease nor retry.
        result = await dispatch_prostudio_provider_request(job_id, payload, mode, selected_model, selected_provider, text_modes)
    else:
        result = await provider_call_with_retry(job_id, provider, dispatch_attempt)
    if not isinstance(result, dict) or not result.get("ok"):
        return result, "failed"

    final_status = normalize_generation_status(result, mode)
    result["job_id"] = job_id
    result["generation_id"] = job_id
    result["status"] = final_status
    prostudio_debug("JOB_STATUS_NORMALIZED", job_id=job_id, mode=mode, final_status=final_status)

    if final_status == "provider_processing":
        generation_stages.report("accepted")
        update_prostudio_generation_job(job_id, "provider_processing", result=result)
        log_user_event(
            int(payload.get("telegram_id") or 0), "worker", "generation",
            "generation_provider_processing",
            {"job_id": job_id, "mode": mode, "task_id": result.get("task_id") or result.get("workId"), "poll_url": result.get("poll_url")},
        )
        # A dispatch failure here would mean abandoning an already-accepted
        # provider job, so wait for the slot rather than deferring the job.
        async with provider_slot(
            DATABASE_URL, provider, job_id, prostudio_debug, wait_for_slot=True,
        ):
            while True:
                await asyncio.sleep(5)
                # No heartbeat write here: _prostudio_job_heartbeat_loop
                # already heartbeats this job_id independently every ~60s
                # for as long as this worker slot is occupied (see
                # _run_prostudio_generation_pool). A second heartbeat call
                # tied to this 5s poll cadence would be pure duplicate DB
                # traffic - and this one wasn't even off-loop, unlike the
                # background loop's asyncio.to_thread-wrapped version.
                poll = await provider_call_with_retry(
                    job_id,
                    provider,
                    lambda: run_provider_coroutine_off_loop(lambda: poll_video_generation(result)),
                )
                if not poll.get("ok"):
                    return poll, "failed"
                status = poll.get("status")
                if status == "completed":
                    return poll, "completed"
                if status == "failed":
                    return poll, "failed"

    return result, final_status


# New async function for background job processing
# =====================================================
# ФОНОВАЯ ЗАДАЧА: process_prostudio_generation
# Обрабатывает job после нажатия пользователем кнопки генерации: запускает провайдера, ждёт результат и сохраняет итог.
# =====================================================
async def process_prostudio_generation(job_id: str, payload: dict):
    pipeline_started_at = time.monotonic()
    prostudio_debug(
        "JOB_PROCESS_ENTER",
        job_id=job_id,
        payload_job_id=payload.get("job_id") or "",
        mode=payload.get("mode") or payload.get("category") or "",
        model=payload.get("model") or "",
        provider=payload.get("provider") or "",
    )
    try:
        payload["job_id"] = job_id
        payload["generation_id"] = job_id
        mode = (payload.get("mode") or payload.get("category") or "text").lower()
        category = (payload.get("category") or mode).lower()
        prompt = (payload.get("prompt") or "").strip()
        selected_model = (payload.get("model") or "").strip()
        selected_provider = (payload.get("provider") or "sylvex-router").strip().lower()
        if payload.get("load_test") and not PROSTUDIO_MOCK_GENERATION:
            # A load-test job must never fall through to a real provider, even
            # if the CLI and worker were accidentally configured differently.
            update_prostudio_generation_job(
                job_id,
                "failed",
                error={
                    "ok": False,
                    "mock": True,
                    "error": "PROSTUDIO_MOCK_GENERATION is disabled on worker",
                },
            )
            prostudio_debug(
                "MOCK_GENERATION_REJECTED",
                job_id=job_id,
                telegram_id=int(payload.get("telegram_id") or 0),
                reason="mock_generation_disabled",
            )
            return
        if PROSTUDIO_MOCK_GENERATION:
            mock_duration_seconds = random.randint(5, 15)
            prostudio_debug(
                "MOCK_GENERATION_STARTED",
                job_id=job_id,
                telegram_id=int(payload.get("telegram_id") or 0),
                mode=mode,
                model=selected_model,
                duration_seconds=mock_duration_seconds,
                mock=True,
            )
            await asyncio.sleep(mock_duration_seconds)
            mock_result = {
                "ok": True,
                "mock": True,
                "type": mode,
                "status": "completed",
                "job_id": job_id,
                "generation_id": job_id,
                "provider": "mock",
                "model": selected_model,
                "duration_seconds": mock_duration_seconds,
                "balance_charged": False,
                "sent_to_telegram": False,
            }
            update_prostudio_generation_job(job_id, "completed", result=mock_result)
            prostudio_debug(
                "MOCK_GENERATION_COMPLETED",
                job_id=job_id,
                telegram_id=int(payload.get("telegram_id") or 0),
                mode=mode,
                model=selected_model,
                duration_seconds=mock_duration_seconds,
                mock=True,
            )
            return
        prompt_report = optimize_prompt_for_model(
            prompt,
            model=selected_model,
            provider=selected_provider,
            mode=mode,
        )
        prostudio_debug(
            "PROMPT_OPTIMIZER",
            job_id=job_id,
            mode=mode,
            model=selected_model,
            provider=selected_provider,
            original_length=prompt_report.get("original_length"),
            model_limit=prompt_report.get("limit"),
            optimized=prompt_report.get("optimized"),
            new_length=prompt_report.get("optimized_length"),
            failed_reason=prompt_report.get("failed_reason") or "",
        )
        if prompt and not prompt_report.get("ok"):
            provider_name = "Kling" if "kling" in f"{selected_provider} {selected_model}".lower() else "выбранной модели"
            error_result = {
                "ok": False,
                "type": mode,
                "provider": selected_provider,
                "model": selected_model,
                "error": (
                    f"Ваше описание слишком большое для {provider_name}.\n\n"
                    f"Максимальный размер описания для {provider_name} — {prompt_report.get('limit')} символов.\n\n"
                    "Попробуйте сделать описание немного короче или выберите другую модель."
                ),
                "raw_error": "Prompt optimization failed to reach limit",
                "prompt_limit": prompt_report.get("limit"),
                "prompt_length": prompt_report.get("original_length"),
                "optimized_length": prompt_report.get("optimized_length"),
            }
            if update_prostudio_generation_job(job_id, "failed", error=error_result):
                await notify_telegram_generation_failed(int(payload.get("telegram_id") or 0), mode)
            log_prostudio_error(payload, error_result, job_id=job_id)
            return
        if prompt_report.get("optimized"):
            prompt = prompt_report.get("prompt") or prompt
            payload["prompt"] = prompt
            payload["prompt_optimization"] = prompt_report
        image_options = payload.get("image_options") or {}
        video_options = payload.get("video_options") or {}
        reference_images = (
            _json_list(image_options.get("referenceImageUrls"))
            or _json_list(image_options.get("referenceImages"))
            or _json_list(image_options.get("characterReferences"))
            or _json_list(image_options.get("objectReferences"))
        )
        video_references = (
            video_options.get("reference_images")
            or video_options.get("referenceImageUrls")
            or []
        )
        video_template = video_options.get("video_template") if isinstance(video_options.get("video_template"), dict) else {}
        video_media = (
            video_options.get("start_image")
            or video_options.get("end_image")
            or video_options.get("input_video")
            or video_options.get("video_url")
            or video_options.get("image_url")
            or video_options.get("character_image")
            or video_template.get("reference_video")
            or video_template.get("video_url")
            or video_template.get("template_video_url")
            or video_template.get("preview_video")
        )
        generation_modes = {"image", "video", "music", "voice"}
        text_modes = {"text", "chat", "pro", "lite"}
        if mode == "image":
            try:
                normalize_payload_image_seed(payload)
                image_options = payload.get("image_options") or {}
            except ValueError as exc:
                result = {"ok": False, "type": "image", "error": str(exc)}
                if job_id:
                    if update_prostudio_generation_job(job_id, "failed", error=result):
                        await notify_telegram_generation_failed(int(payload.get("telegram_id") or 0), mode)
                    log_prostudio_error(payload, result, job_id=job_id)
                return
        heartbeat_prostudio_generation_job(job_id)
        prostudio_debug(
            "JOB_PROCESS_STARTED",
            job_id=job_id,
            mode=mode,
            category=category,
            model=selected_model,
            provider=selected_provider,
            has_prompt=bool(prompt),
            has_image_refs=bool(reference_images),
            has_video_refs=bool(video_references),
            has_video_media=bool(video_media),
        )
        provider_for_slot = resolve_prostudio_provider_for_slot(
            payload, mode, selected_model, selected_provider
        )
        local_edit = mode == "image" and edit_workspace_service.is_free_resize(payload)
        circuit = {"allowed": True} if local_edit else await asyncio.to_thread(
            circuit_before_request,
            DATABASE_URL,
            provider_for_slot,
            job_id,
            WORKER_ID,
        )
        if circuit.get("transition") == "HALF_OPEN":
            _log_circuit_transition(
                "PROVIDER_CIRCUIT_HALF_OPEN", provider_for_slot, job_id, 0,
                None, 0, circuit,
            )
        if not circuit.get("allowed"):
            _log_circuit_transition(
                "PROVIDER_CIRCUIT_BLOCKED", provider_for_slot, job_id, 0,
                None, circuit.get("wait_seconds") or 1, circuit,
            )
            await asyncio.to_thread(
                defer_prostudio_job_for_provider,
                job_id,
                circuit.get("wait_seconds") or 1,
            )
            return
        try:
            try:
                # run_prostudio_provider_request owns its own provider-slot
                # lifecycle: one slot per real dispatch attempt (so a failed
                # attempt's retry backoff doesn't hold capacity nothing is
                # using), then one continuously-held slot for as long as the
                # provider's own async job is actually processing.
                log_user_event(
                    int(payload.get("telegram_id") or 0), "worker", "generation",
                    "generation_started",
                    {"job_id": job_id, "mode": mode, "model": selected_model, "provider": selected_provider},
                )
                result, final_status = await run_prostudio_provider_request(
                    job_id, payload, mode, selected_model, selected_provider,
                    text_modes, provider_for_slot,
                )
            except ProviderSlotUnavailable:
                await asyncio.to_thread(defer_prostudio_job_for_provider, job_id)
                return
        finally:
            if not local_edit:
                await asyncio.shield(
                    asyncio.to_thread(circuit_release_probe, DATABASE_URL, provider_for_slot, job_id)
                )

        prostudio_debug(
            "JOB_PROVIDER_RESULT",
            job_id=job_id,
            mode=mode,
            ok=bool(result.get("ok")) if isinstance(result, dict) else False,
            status=(result or {}).get("status") if isinstance(result, dict) else "",
            result_keys=sorted((result or {}).keys()) if isinstance(result, dict) else [],
            image_url=(result or {}).get("image_url") if isinstance(result, dict) else "",
            thumbnail_url=(result or {}).get("thumbnail_url") if isinstance(result, dict) else "",
            images_count=len(_json_list((result or {}).get("images"))) if isinstance(result, dict) else 0,
        )
        if not isinstance(result, dict):
            result = {"ok": False, "error": "Provider returned empty result", "type": mode}
        if not result.get("ok"):
            if job_id:
                if update_prostudio_generation_job(job_id, "failed", error=result):
                    await notify_telegram_generation_failed(int(payload.get("telegram_id") or 0), mode)
                log_prostudio_error(payload, result, job_id=job_id)
                prostudio_debug("JOB_PROCESS_FAILED_PROVIDER_RESULT", job_id=job_id, error=(result or {}).get("error") or "")
            return

        if final_status != "completed":
            error_result = {
                "ok": False,
                "error": "Provider returned no completed result",
                "status": final_status,
                "result": result,
            }
            if update_prostudio_generation_job(job_id, "failed", error=error_result):
                await notify_telegram_generation_failed(int(payload.get("telegram_id") or 0), mode)
            log_prostudio_error(payload, error_result, job_id=job_id)
            prostudio_debug("JOB_PROCESS_FAILED_NOT_COMPLETED", job_id=job_id, final_status=final_status)
            return

        if not generation_has_completed_result(result, mode):
            pending_result = dict(result or {})
            pending_result["status"] = "provider_processing"
            update_prostudio_generation_job(job_id, "provider_processing", result=pending_result)
            prostudio_debug("JOB_COMPLETED_WITHOUT_RESULT_HELD", job_id=job_id, mode=mode)
            return

        # Non-negotiable rule: the provider's own response is the critical
        # user-facing result. R2 persistence, thumbnails, history, and
        # Telegram delivery are side effects and must never delay or
        # invalidate an already-successful provider result. The provider's
        # own (possibly temporary/ephemeral) URLs are used immediately;
        # durable R2 persistence happens afterward in the background and can
        # only upgrade those URLs later, never flip generation_status.
        provider_ready_at = time.monotonic()
        prostudio_debug(
            "JOB_PROVIDER_RESULT_READY",
            job_id=job_id,
            mode=mode,
            timestamp=round(provider_ready_at, 6),
        )
        
        telegram_id = int(payload.get("telegram_id") or 0)
        # Settle authoritative provider-reported cost when available (xAI
        # exact USD ticks / Runway realized credits). The held reservation is
        # still the hard ceiling, and the independent SYLVEX asset fee stays
        # attached. Providers without exact cost retain their audited frozen
        # estimator rather than falling back to a generic formula.
        snapshot = settle_media_price_snapshot(payload, result)
        payload = dict(payload)
        payload["price_snapshot"] = snapshot
        result["cost_credits"] = int(snapshot.get("final_credits") or 0)
        result["generation_cost"] = f"{result['cost_credits']} ⚡" if result["cost_credits"] else ""
        print("PROSTUDIO RESULT BEFORE CHARGE:", {
            "job_id": job_id,
            "mode": mode,
            "ok": result.get("ok"),
            "status": result.get("status"),
            "image_url": result.get("image_url"),
            "images": _json_list(result.get("images")),
            "thumbnail_url": result.get("thumbnail_url"),
            "thumbnails": _json_list(result.get("thumbnails")),
            "provider": result.get("provider"),
            "model": result.get("model"),
            "provider_model": result.get("provider_model"),
            "cost": result.get("cost"),
            "cost_credits": result.get("cost_credits"),
            "generation_cost": result.get("generation_cost"),
        })
        charge = charge_generation_balance(telegram_id, job_id or result.get("generation_id") or str(uuid4()), result, payload)
        if charge.get("error") or charge.get("insufficient_balance"):
            raise RuntimeError(charge.get("error") or "Insufficient balance while finalizing generation")
        result["balance_charged"] = bool(charge.get("charged") or charge.get("already_charged"))
        result["balance_after"] = charge.get("balance_after")
        result["charge_id"] = job_id or result.get("generation_id") or ""
        print("PROSTUDIO CHARGE RESULT:", {
            "job_id": job_id,
            "telegram_id": telegram_id,
            "charge": charge,
            "balance_charged": result.get("balance_charged"),
            "balance_after": result.get("balance_after"),
        })
        charge_done_at = time.monotonic()
        prostudio_debug(
            "JOB_CHARGE_DONE",
            job_id=job_id,
            timestamp=round(charge_done_at, 6),
            elapsed_ms_since_provider_ready=round((charge_done_at - provider_ready_at) * 1000),
        )

        # This is the only result Mini App needs to stop polling. It carries
        # the provider's own (possibly temporary) URLs immediately - durable
        # R2 persistence is a background side effect, never a precondition
        # for showing the user their already-successful result.
        completed_result = build_completed_job_result(result, mode)
        completed_result["storage_status"] = "pending"
        if not update_prostudio_generation_job(job_id, "completed", result=completed_result):
            raise RuntimeError("Failed to commit completed Pro Studio job")
        completed_committed_at = time.monotonic()
        prostudio_debug(
            "JOB_COMPLETED_COMMITTED",
            job_id=job_id,
            timestamp=round(completed_committed_at, 6),
            elapsed_ms_since_provider_ready=round((completed_committed_at - provider_ready_at) * 1000),
        )
        prostudio_debug(
            "JOB_PROCESS_COMPLETED", job_id=job_id, conversation_id="", status="completed",
            # End-to-end time from this worker picking up the job to the
            # completed status being committed (client-visible on its next
            # poll) - the number to compare against the provider's own
            # documented generation time to see whether SYLVEX or the
            # provider dominates total latency for this job.
            total_pipeline_ms=round((time.monotonic() - pipeline_started_at) * 1000),
        )
        # The completion transaction already recorded the media outbox. Existing
        # workers claim it independently, including after a process restart.

        # History enriches an already completed job and is intentionally not
        # allowed to roll its terminal status back on failure.
        try:
            prostudio_debug("JOB_SAVE_GENERATION_START", job_id=job_id, telegram_id=telegram_id, mode=mode)
            save_generation(telegram_id, mode, prompt or "[attachment]")
            prostudio_debug("JOB_METADATA_BUILD_START", job_id=job_id)
            metadata = build_prostudio_metadata(payload, result)
            if metadata:
                result["metadata"] = metadata
            prostudio_debug(
                "JOB_MESSAGE_SAVE_START",
                job_id=job_id,
                image_url=result.get("image_url") or "",
                thumbnail_url=result.get("thumbnail_url") or "",
                images_count=len(_json_list(result.get("images"))),
                thumbs_count=len(_json_list(result.get("thumbnails"))),
            )
            result["conversation_id"] = await asyncio.to_thread(save_prostudio_message, payload, result)
            prostudio_debug("JOB_MESSAGE_SAVE_DONE", job_id=job_id, conversation_id=result["conversation_id"])
            # "Generated with this Character" - only when a Character was
            # actively selected/committed on THIS request (metadata.characterId
            # comes straight from this request's own image options, never
            # from some separately-tracked "currently selected" state),
            # covering every surface that reaches this single completion
            # path: the Pro Studio result, the Telegram delivery below, a
            # plain Image-mode result, and a job the client only discovers
            # via polling after a disconnect. Character History is images
            # only - a video/music/voice job is never recorded here, even
            # if it happened to carry a characterId. Every generated image
            # URL from this completed result is recorded, not just the
            # first - a 4-image job must produce 4 History rows.
            # record_character_generation_history itself verifies the
            # Character is a custom one actually owned by this user before
            # writing anything.
            if mode == "image" and metadata and metadata.get("characterId"):
                character_media_urls = metadata.get("result_images") or (
                    [metadata.get("result_url")] if metadata.get("result_url") else []
                )
                await asyncio.to_thread(
                    record_character_generation_history,
                    str(metadata.get("characterId")),
                    telegram_id,
                    job_id,
                    character_media_urls,
                    metadata.get("prompt") or "",
                    metadata.get("model") or "",
                )
            update_prostudio_generation_job(
                job_id, "completed", result=result, conversation_id=result["conversation_id"]
            )
            log_user_event(
                telegram_id,
                "backend",
                "generation",
                "generation_completed",
                {"job_id": job_id, "mode": mode, "conversation_id": result["conversation_id"]},
            )
            history_done_at = time.monotonic()
            prostudio_debug(
                "JOB_HISTORY_DONE",
                job_id=job_id,
                success=True,
                timestamp=round(history_done_at, 6),
                elapsed_ms_since_provider_ready=round((history_done_at - provider_ready_at) * 1000),
            )
        except Exception as history_exc:
            prostudio_error("JOB_POST_COMPLETION_HISTORY_FAILED", history_exc, job_id=job_id)
            history_done_at = time.monotonic()
            prostudio_debug(
                "JOB_HISTORY_DONE",
                job_id=job_id,
                success=False,
                timestamp=round(history_done_at, 6),
                elapsed_ms_since_provider_ready=round((history_done_at - provider_ready_at) * 1000),
            )

        # Telegram is another post-completion side effect and cannot alter the
        # terminal PostgreSQL status.
        telegram_sent = await sync_completed_generation_to_telegram(telegram_id, mode, payload, result)
        telegram_done_at = time.monotonic()
        prostudio_debug(
            "JOB_TELEGRAM_SENT",
            job_id=job_id,
            telegram_id=telegram_id,
            sent=bool(telegram_sent),
            timestamp=round(telegram_done_at, 6),
            elapsed_ms_since_provider_ready=round((telegram_done_at - provider_ready_at) * 1000),
        )
    except Exception as exc:
        prostudio_error("JOB_PROCESS_EXCEPTION", exc, job_id=job_id)
        error_result = {"ok": False, "error": str(exc), "traceback": traceback.format_exc()}
        if job_id:
            if update_prostudio_generation_job(job_id, "failed", error=error_result):
                await notify_telegram_generation_failed(
                    int(payload.get("telegram_id") or 0),
                    str(payload.get("mode") or payload.get("category") or "").lower(),
                )
            log_prostudio_error(payload, error_result, job_id=job_id)

def _schedule_local_prostudio_queue_signal(*, delay: float = 0.0, listener_healthy: Optional[bool] = None, all_waiters: bool = False) -> bool:
    """Thread-safe bridge from PostgreSQL LISTEN (or a defer timer) to asyncio."""
    with _PROSTUDIO_QUEUE_RUNTIME_LOCK:
        loop = _PROSTUDIO_QUEUE_RUNTIME_LOOP
        signal = _PROSTUDIO_QUEUE_RUNTIME_SIGNAL
    if loop is None or signal is None or loop.is_closed():
        return False

    def dispatch():
        def create_notification_task():
            asyncio.create_task(
                signal.notify(listener_healthy=listener_healthy, all_waiters=all_waiters),
                name="prostudio-queue-notification",
            )

        if delay > 0:
            loop.call_later(float(delay), create_notification_task)
        else:
            create_notification_task()

    try:
        loop.call_soon_threadsafe(dispatch)
        return True
    except RuntimeError:
        return False


def _listen_for_prostudio_queue_notifications(stop_event: threading.Event):
    """One dedicated LISTEN connection per worker service, never per slot."""
    reconnect_delay = 0.5
    while not stop_event.is_set():
        conn = None
        cursor = None
        try:
            conn = psycopg2.connect(
                DATABASE_URL,
                connect_timeout=10,
                application_name="sylvex-prostudio-queue-listener",
            )
            conn.set_session(autocommit=True)
            cursor = conn.cursor()
            cursor.execute(f"LISTEN {PROSTUDIO_QUEUE_CHANNEL}")
            reconnect_delay = 0.5
            _schedule_local_prostudio_queue_signal(listener_healthy=True)
            prostudio_debug("WORKER_QUEUE_LISTENER_READY")
            while not stop_event.is_set():
                ready, _, _ = select.select([conn], [], [], 1.0)
                if not ready:
                    continue
                conn.poll()
                notification_count = 0
                while conn.notifies:
                    conn.notifies.pop(0)
                    notification_count += 1
                for _ in range(notification_count):
                    _schedule_local_prostudio_queue_signal(listener_healthy=True)
        except Exception as exc:
            _schedule_local_prostudio_queue_signal(listener_healthy=False, all_waiters=True)
            prostudio_error("WORKER_QUEUE_LISTENER_RECONNECT", exc)
            if stop_event.wait(reconnect_delay):
                break
            reconnect_delay = min(10.0, reconnect_delay * 2.0)
        finally:
            if cursor is not None:
                try:
                    cursor.close()
                except Exception:
                    pass
            if conn is not None:
                try:
                    conn.close()
                except Exception:
                    pass
    _schedule_local_prostudio_queue_signal(listener_healthy=False, all_waiters=True)


async def _wait_for_prostudio_worker_stop(stop_event: asyncio.Event, timeout: float) -> bool:
    if stop_event.is_set():
        return True
    try:
        await asyncio.wait_for(stop_event.wait(), timeout=max(0.05, float(timeout)))
    except asyncio.TimeoutError:
        return stop_event.is_set()
    return True


async def _prostudio_job_heartbeat_loop(job_id: str, finished_event: asyncio.Event):
    # A bounded companion coroutine is created only for an occupied pool slot.
    # It prevents a healthy long-running provider call from being recovered as stale.
    heartbeat_interval = max(5.0, min(60.0, PROSTUDIO_STALE_PROCESSING_MINUTES * 20.0))
    while not finished_event.is_set():
        try:
            await asyncio.wait_for(finished_event.wait(), timeout=heartbeat_interval)
            return
        except asyncio.TimeoutError:
            await asyncio.to_thread(heartbeat_prostudio_generation_job, job_id)


async def run_prostudio_generation_with_timeout(job_id: str, payload: dict):
    """Bound a claimed job's full provider lifecycle and commit a terminal timeout."""
    try:
        await asyncio.wait_for(
            process_prostudio_generation(job_id, payload),
            timeout=PROSTUDIO_MAX_JOB_RUNTIME_SECONDS,
        )
    except asyncio.TimeoutError:
        error = {
            "ok": False,
            "error_code": "generation_timeout",
            "error": "Generation exceeded the Pro Studio hard runtime limit",
        }
        prostudio_debug(
            "JOB_PROVIDER_TIMEOUT",
            job_id=job_id,
            timeout_seconds=PROSTUDIO_MAX_JOB_RUNTIME_SECONDS,
        )
        if update_prostudio_generation_job(job_id, "failed", error=error):
            await notify_telegram_generation_failed(
                int(payload.get("telegram_id") or 0),
                str(payload.get("mode") or payload.get("category") or "").lower(),
            )
        log_prostudio_error(payload, error, job_id=job_id)


async def _run_prostudio_generation_pool(
    stop_event: asyncio.Event,
    concurrency: Optional[int] = None,
):
    pool_size = _bounded_prostudio_worker_concurrency(
        PROSTUDIO_WORKER_CONCURRENCY if concurrency is None else concurrency
    )
    active_job_ids = set()
    active_lock = asyncio.Lock()
    queue_signal = ProstudioQueueSignal()
    queue_listener_stop = threading.Event()
    queue_listener = threading.Thread(
        target=_listen_for_prostudio_queue_notifications,
        args=(queue_listener_stop,),
        name="prostudio-queue-listener",
        daemon=True,
    )
    loop = asyncio.get_running_loop()
    global _PROSTUDIO_QUEUE_RUNTIME_LOOP, _PROSTUDIO_QUEUE_RUNTIME_SIGNAL
    with _PROSTUDIO_QUEUE_RUNTIME_LOCK:
        _PROSTUDIO_QUEUE_RUNTIME_LOOP = loop
        _PROSTUDIO_QUEUE_RUNTIME_SIGNAL = queue_signal
    queue_listener.start()

    async def pool_counts():
        async with active_lock:
            active_count = len(active_job_ids)
        return active_count, max(0, pool_size - active_count)

    async def log_pool_status(job_id: str = ""):
        active_count, free_slots = await pool_counts()
        prostudio_debug(
            "WORKER_POOL_STATUS",
            concurrency=pool_size,
            active_tasks=active_count,
            free_slots=free_slots,
            job_id=job_id or "",
        )

    async def worker_slot(slot_id: int):
        seen_queue_generation = queue_signal.generation
        while not stop_event.is_set():
            claimed = None
            try:
                claimed = await asyncio.to_thread(claim_next_prostudio_generation_job)
            except Exception as exc:
                prostudio_error("WORKER_CLAIM_FAILED", exc, slot_id=slot_id)

            if stop_event.is_set():
                # A claim that completed concurrently with shutdown is already
                # marked processing. Process it instead of abandoning it.
                if not claimed:
                    return
            if not claimed or not claimed.get("id") or not claimed.get("payload"):
                wait_seconds = (
                    PROSTUDIO_WORKER_FALLBACK_INTERVAL
                    if queue_signal.listener_healthy
                    else PROSTUDIO_WORKER_INTERVAL
                )
                seen_queue_generation = await queue_signal.wait(
                    seen_queue_generation,
                    wait_seconds,
                )
                if stop_event.is_set():
                    return
                continue

            job_id = str(claimed["id"])
            async with active_lock:
                duplicate = job_id in active_job_ids
                if not duplicate:
                    active_job_ids.add(job_id)
                active_count = len(active_job_ids)
            if duplicate:
                prostudio_error(
                    "WORKER_DUPLICATE_JOB_BLOCKED",
                    job_id=job_id,
                    slot_id=slot_id,
                    concurrency=pool_size,
                    active_tasks=active_count,
                    free_slots=max(0, pool_size - active_count),
                )
                continue

            finished_event = asyncio.Event()
            heartbeat_task = asyncio.create_task(
                _prostudio_job_heartbeat_loop(job_id, finished_event),
                name=f"prostudio-heartbeat-{job_id}",
            )
            prostudio_debug(
                "WORKER_TASK_STARTED",
                concurrency=pool_size,
                active_tasks=active_count,
                free_slots=max(0, pool_size - active_count),
                job_id=job_id,
                slot_id=slot_id,
                attempts=claimed.get("attempts"),
                # Time between the client's submit and this worker picking the
                # job up - isolates SYLVEX-side queueing latency from whatever
                # happens next at the provider.
                queue_wait_ms=claimed.get("queue_wait_ms"),
            )
            try:
                await run_prostudio_generation_with_timeout(job_id, claimed["payload"])
            except Exception as exc:
                # process_prostudio_generation already isolates provider errors,
                # but keep the pool healthy if an unexpected exception escapes.
                prostudio_error("WORKER_TASK_EXCEPTION", exc, job_id=job_id, slot_id=slot_id)
                update_prostudio_generation_job(
                    job_id,
                    "failed",
                    error={"ok": False, "error": str(exc)},
                )
            finally:
                finished_event.set()
                await asyncio.gather(heartbeat_task, return_exceptions=True)
                async with active_lock:
                    active_job_ids.discard(job_id)
                    active_count = len(active_job_ids)
                prostudio_debug(
                    "WORKER_TASK_FINISHED",
                    concurrency=pool_size,
                    active_tasks=active_count,
                    free_slots=max(0, pool_size - active_count),
                    job_id=job_id,
                    slot_id=slot_id,
                )

    # Recover abandoned work before accepting new jobs. Heartbeats protect all
    # subsequently active pool jobs during periodic recovery passes.
    await asyncio.to_thread(requeue_stale_prostudio_jobs)
    slots = [
        asyncio.create_task(worker_slot(index + 1), name=f"prostudio-worker-slot-{index + 1}")
        for index in range(pool_size)
    ]
    prostudio_debug(
        "WORKER_POOL_STARTED",
        concurrency=pool_size,
        active_tasks=0,
        free_slots=pool_size,
        job_id="",
    )
    status_interval = max(15.0, PROSTUDIO_WORKER_INTERVAL * 10.0)
    try:
        while not stop_event.is_set():
            if await _wait_for_prostudio_worker_stop(stop_event, status_interval):
                break
            await asyncio.to_thread(requeue_stale_prostudio_jobs)
            await log_pool_status()
    finally:
        # Slots are never cancelled here: they stop claiming immediately and
        # finish any job they already own before the pool returns.
        stop_event.set()
        await queue_signal.notify(all_waiters=True)
        await asyncio.gather(*slots, return_exceptions=True)
        queue_listener_stop.set()
        await asyncio.to_thread(queue_listener.join, 3.0)
        with _PROSTUDIO_QUEUE_RUNTIME_LOCK:
            if _PROSTUDIO_QUEUE_RUNTIME_SIGNAL is queue_signal:
                _PROSTUDIO_QUEUE_RUNTIME_SIGNAL = None
                _PROSTUDIO_QUEUE_RUNTIME_LOOP = None
        await log_pool_status()


# =====================================================
# ФОНОВАЯ ЗАДАЧА: prostudio_generation_worker_loop
# Обрабатывает job после нажатия пользователем кнопки генерации: запускает провайдера, ждёт результат и сохраняет итог.
# =====================================================
async def prostudio_generation_worker_loop():
    if not PROSTUDIO_WORKER_ENABLED:
        print("PROSTUDIO WORKER DISABLED")
        return
    print("PROSTUDIO WORKER STARTED")
    stop_event = asyncio.Event()
    try:
        await _run_prostudio_generation_pool(stop_event, PROSTUDIO_WORKER_CONCURRENCY)
    except asyncio.CancelledError:
        # Cancellation is treated as a graceful stop request. The pool's
        # cleanup waits for jobs already claimed, while no new jobs are read.
        stop_event.set()
        prostudio_debug(
            "WORKER_POOL_STOPPING",
            concurrency=PROSTUDIO_WORKER_CONCURRENCY,
        )
        raise


def process_subscription_reminders() -> dict:
    if not DATABASE_URL or not BOT_TOKEN:
        return {"checked": 0, "sent": 0}
    ensure_payment_tables()
    ensure_stripe_tables()
    ensure_shop_orders()
    conn = db_connect(DATABASE_URL)
    cursor = conn.cursor()
    try:
        cursor.execute("""
            UPDATE subscriptions
            SET status = 'expired'
            WHERE status = 'active'
              AND expires_at IS NOT NULL
              AND expires_at::timestamp <= NOW()
        """)
        cursor.execute("""
            SELECT s.id, s.telegram_id, s.subscription_type, s.expires_at::timestamp,
                   EXTRACT(EPOCH FROM (s.expires_at::timestamp - NOW()))
            FROM subscriptions s
            WHERE s.status = 'active'
              AND s.expires_at::timestamp > NOW()
              AND s.expires_at::timestamp <= NOW() + INTERVAL '8 days'
              -- A Stripe plan that renews automatically needs no reminder.
              AND NOT """ + stripe_billing.renews_automatically_sql(
                  "s", stripe_billing.key_livemode(STRIPE_SECRET_KEY) if STRIPE_SECRET_KEY else True) + """
              -- Neither does a Telegram Stars subscription that renews automatically.
              AND NOT EXISTS (
                  SELECT 1 FROM subscription_agreements agreement
                  WHERE agreement.id = s.agreement_id AND agreement.renewal_status = 'auto'
              )
              AND NOT EXISTS (
                  SELECT 1
                  FROM subscriptions newer
                  WHERE newer.telegram_id = s.telegram_id
                    AND newer.status = 'active'
                    AND newer.expires_at::timestamp > s.expires_at::timestamp
              )
            ORDER BY s.expires_at ASC
        """)
        subscriptions = cursor.fetchall()
        conn.commit()
    finally:
        cursor.close()
        conn.close()

    checked = 0
    sent = 0
    for subscription_id, telegram_id, plan, expires_at, remaining_seconds in subscriptions:
        checked += 1
        seconds = max(0, float(remaining_seconds or 0))
        days_before = int((seconds + 86399) // 86400)
        if days_before not in {7, 5, 2, 1}:
            continue

        claim_conn = db_connect(DATABASE_URL)
        claim_cursor = claim_conn.cursor()
        try:
            claim_cursor.execute("""
                INSERT INTO subscription_reminders
                    (subscription_id, telegram_id, days_before, status)
                VALUES (%s, %s, %s, 'sending')
                ON CONFLICT (subscription_id, days_before) DO NOTHING
                RETURNING id
            """, (subscription_id, telegram_id, days_before))
            claimed = claim_cursor.fetchone()
            claim_conn.commit()
        finally:
            claim_cursor.close()
            claim_conn.close()
        if not claimed:
            continue

        day_word = "день" if days_before == 1 else ("дня" if days_before in {2, 3, 4} else "дней")
        plan_label = shop_catalog.plan_label(plan)
        text = (
            f"⏳ <b>Подписка {html.escape(shop_catalog.plan_product_name(plan))} скоро закончится</b>\n\n"
            f"До окончания осталось: <b>{days_before} {day_word}</b>\n"
            f"Текущий план: <b>{plan_label}</b>\n"
            f"Дата окончания: <b>{expires_at.strftime('%d.%m.%Y %H:%M')}</b>\n\n"
            "Продлите подписку заранее, чтобы сохранить непрерывный доступ к генерациям."
        )
        try:
            response = requests.post(
                f"https://api.telegram.org/bot{BOT_TOKEN}/sendMessage",
                json={
                    "chat_id": int(telegram_id),
                    "text": text,
                    "parse_mode": "HTML",
                    "disable_web_page_preview": True,
                    "reply_markup": {
                        "inline_keyboard": [[{
                            "text": "Продлить подписку",
                            "web_app": {"url": WEBAPP_URL.rstrip("/") + "/webapp/index.html?view=shop"},
                        }]]
                    },
                },
                timeout=20,
            )
            result = response.json() if response.content else {}
            if response.status_code >= 400 or not result.get("ok"):
                raise RuntimeError(f"Telegram sendMessage failed: {response.status_code} {result}")
            update_conn = db_connect(DATABASE_URL)
            update_cursor = update_conn.cursor()
            try:
                update_cursor.execute("""
                    UPDATE subscription_reminders
                    SET status = 'sent', sent_at = NOW()
                    WHERE id = %s
                """, (claimed[0],))
                update_conn.commit()
            finally:
                update_cursor.close()
                update_conn.close()
            sent += 1
        except Exception as exc:
            prostudio_error(
                "SUBSCRIPTION_REMINDER_FAILED",
                exc,
                telegram_id=telegram_id,
                subscription_id=subscription_id,
                days_before=days_before,
            )
            retry_conn = db_connect(DATABASE_URL)
            retry_cursor = retry_conn.cursor()
            try:
                retry_cursor.execute("DELETE FROM subscription_reminders WHERE id = %s", (claimed[0],))
                retry_conn.commit()
            finally:
                retry_cursor.close()
                retry_conn.close()
    return {"checked": checked, "sent": sent}


# ---------------------------------------------------------------------------
# Subscription administration notifications and the expiry sweep.
#
# Payment code queues events in shop_orders' subscription_events outbox inside
# the payment transaction (webapp webhook and polling bot alike); this worker
# delivers them to the administration chat with retries, so a notification
# failure never affects a payment. Messages carry identifiers only: SYLVEX ID,
# Telegram ID, plan, amount, status, time and the Telegram charge reference -
# never tokens, secrets, names or usernames.
# ---------------------------------------------------------------------------
SUBSCRIPTION_ADMIN_CHAT_ID = int(os.getenv("SUBSCRIPTION_ADMIN_CHAT_ID", str(PROSTUDIO_ADMIN_ID)) or PROSTUDIO_ADMIN_ID)
SUBSCRIPTION_EVENTS_WORKER_ENABLED = os.getenv("SUBSCRIPTION_EVENTS_WORKER_ENABLED", "1") == "1"
SUBSCRIPTION_EVENTS_INTERVAL_SECONDS = int(os.getenv("SUBSCRIPTION_EVENTS_INTERVAL_SECONDS", "30") or 30)
SUBSCRIPTION_SWEEP_INTERVAL_SECONDS = int(os.getenv("SUBSCRIPTION_SWEEP_INTERVAL_SECONDS", "600") or 600)

SUBSCRIPTION_EVENT_TITLES = {
    "subscription_purchased": "🟢 Новая подписка",
    "subscription_renewed": "🔁 Подписка продлена",
    "renewal_canceled": "⏹ Автопродление отменено через SYLVEX",
    "renewal_reactivated": "▶️ Автопродление возобновлено",
    "subscription_expired": "⌛ Подписка закончилась",
    "primary_changed": "🔀 Сменился основной тариф",
    "payment_error": "⚠️ Ошибка обработки платежа",
    "payment_attention": "⚠️ Платёж требует внимания",
    "management_error": "⚠️ Ошибка управления подпиской",
}


def sylvex_account_id_for(telegram_id):
    if not telegram_id or not DATABASE_URL:
        return None
    try:
        conn = db_connect(DATABASE_URL)
        try:
            with conn.cursor() as cur:
                cur.execute("SELECT to_regclass('public.sylvex_accounts')")
                if not cur.fetchone()[0]:
                    return None
                cur.execute("SELECT account_id FROM sylvex_accounts WHERE active_telegram_id = %s LIMIT 1", (int(telegram_id),))
                row = cur.fetchone()
                return int(row[0]) if row else None
        finally:
            conn.close()
    except Exception:
        return None


def format_subscription_event(event: dict, sylvex_id=None) -> str:
    lines = [SUBSCRIPTION_EVENT_TITLES.get(event["event_type"], event["event_type"])]
    lines.append(f"SYLVEX ID: {sylvex_id if sylvex_id else '—'}")
    lines.append(f"Telegram ID: {event['telegram_id'] or '—'}")
    if event.get("plan_key"):
        lines.append(f"Тариф: {shop_catalog.plan_product_name(event['plan_key'])} · {shop_catalog.plan_label(event['plan_key'])}")
    if event.get("amount") is not None:
        lines.append(f"Сумма: {event['amount']} {event.get('currency') or ''}".rstrip())
    if event.get("status"):
        lines.append(f"Статус: {event['status']}")
    created = event.get("created_at")
    lines.append(f"Время: {created.strftime('%Y-%m-%d %H:%M:%S') if created else '—'}")
    if event.get("reference"):
        lines.append(f"Транзакция: {event['reference']}")
    if event.get("details"):
        lines.append(f"Детали: {event['details']}")
    return "\n".join(lines)


def deliver_subscription_events(limit: int = 20) -> dict:
    ensure_shop_orders()
    sent = failed = 0
    for event in shop_orders.claim_events(shop_db, limit):
        ok, error = telegram_bot_api("sendMessage", {
            "chat_id": SUBSCRIPTION_ADMIN_CHAT_ID,
            "text": format_subscription_event(event, sylvex_account_id_for(event.get("telegram_id"))),
            "disable_web_page_preview": True,
        })
        if ok:
            shop_orders.mark_event_sent(shop_db, event["id"])
            sent += 1
        else:
            shop_orders.mark_event_failed(shop_db, event["id"], error)
            failed += 1
    return {"sent": sent, "failed": failed}


def run_subscription_sweep() -> dict:
    """Record ended subscriptions (and fall back to still-valid plans), then
    retry stopping replaced renewals Telegram has not confirmed yet."""
    ensure_shop_orders()
    result = shop_orders.sweep_subscriptions(shop_db)
    if result["stop_pending"]:
        result["stopped"] = shop_orders.stop_renewals(shop_db, result["stop_pending"], telegram_bot_api)
    return result


async def subscription_events_worker_loop():
    print("SUBSCRIPTION EVENTS WORKER STARTED")
    last_sweep = 0.0
    while True:
        try:
            if time.monotonic() - last_sweep >= SUBSCRIPTION_SWEEP_INTERVAL_SECONDS:
                last_sweep = time.monotonic()
                swept = await asyncio.to_thread(run_subscription_sweep)
                if swept.get("expired") or swept.get("stop_pending"):
                    prostudio_debug("SUBSCRIPTION_SWEEP", expired=swept.get("expired"),
                                    stop_pending=len(swept.get("stop_pending") or []))
            delivered = await asyncio.to_thread(deliver_subscription_events)
            if delivered["sent"] or delivered["failed"]:
                prostudio_debug("SUBSCRIPTION_EVENTS_DELIVERED", **delivered)
        except Exception as exc:
            prostudio_error("SUBSCRIPTION_EVENTS_WORKER_FAILED", exc)
        await asyncio.sleep(max(5, SUBSCRIPTION_EVENTS_INTERVAL_SECONDS))


async def payment_recovery_worker_loop():
    """Always on (independent of notifications): replay confirmed Telegram
    Stars payments that are stored but unprocessed - after an outage, crash or
    restart - and reconcile with Telegram's Star transaction history."""
    print("PAYMENT RECOVERY WORKER STARTED")
    last_reconcile = 0.0
    while True:
        try:
            replayed = await asyncio.to_thread(replay_star_payments)
            if replayed.get("spooled") or replayed.get("processed") or replayed.get("rejected") or replayed.get("error"):
                prostudio_debug("STARS_PAYMENTS_REPLAYED", **replayed)
            if time.monotonic() - last_reconcile >= PAYMENT_RECONCILE_INTERVAL_SECONDS:
                reconciled = await asyncio.to_thread(reconcile_star_payments)
                last_reconcile = time.monotonic()
                if reconciled.get("ingested"):
                    prostudio_debug("STARS_PAYMENTS_RECONCILED", **reconciled)
        except Exception as exc:
            prostudio_error("STARS_PAYMENT_RECOVERY_FAILED", exc)
        await asyncio.sleep(max(5, PAYMENT_REPLAY_INTERVAL_SECONDS))


async def subscription_reminder_worker_loop():
    if not SUBSCRIPTION_REMINDER_WORKER_ENABLED:
        print("SUBSCRIPTION REMINDER WORKER DISABLED")
        return
    print("SUBSCRIPTION REMINDER WORKER STARTED")
    while True:
        try:
            result = await asyncio.to_thread(process_subscription_reminders)
            if result.get("sent"):
                prostudio_debug("SUBSCRIPTION_REMINDERS_SENT", **result)
        except Exception as exc:
            prostudio_error("SUBSCRIPTION_REMINDER_WORKER_FAILED", exc)
        await asyncio.sleep(max(300, SUBSCRIPTION_REMINDER_INTERVAL_SECONDS))

# =====================================================
# API ENDPOINT: start_prostudio_generation_worker
# Принимает HTTP-запрос от Mini App или Telegram Bot.
# Маршрут FastAPI: @app.on_event("startup")
# Проверяет входные данные, работает с базой/провайдерами и возвращает JSON-ответ фронтенду.
# =====================================================
@app.on_event("startup")
# =====================================================
# ФОНОВАЯ ЗАДАЧА: start_prostudio_generation_worker
# Обрабатывает job после нажатия пользователем кнопки генерации: запускает провайдера, ждёт результат и сохраняет итог.
# =====================================================
async def start_prostudio_generation_worker():
    from services.runtime_checks import validate_runtime
    validate_runtime()
    app.state.background_tasks = []
    if DATABASE_URL:
        await asyncio.to_thread(start_db_pool, DATABASE_URL)
        await asyncio.to_thread(ensure_limit_table, DATABASE_URL)
        # Proactively create the hot-path indexes added for the
        # session/me and gallery latency fix, instead of waiting for each
        # table's own (unrelated) first caller to lazily create them -
        # otherwise the first get_user_state()/get_account_summary() calls
        # after a deploy would still hit the old full-scan behavior until
        # some other endpoint happened to run first.
        await asyncio.to_thread(ensure_payment_tables)
        await asyncio.to_thread(ensure_user_events_table)
        await asyncio.to_thread(ensure_generations_index)
        await asyncio.to_thread(account_identity_service.ensure_account_tables, DATABASE_URL)
        try:
            # Payment inbox and order tables before the first payment arrives.
            await asyncio.to_thread(ensure_shop_orders)
        except Exception as exc:
            prostudio_error("SHOP_ORDER_TABLES_STARTUP_FAILED", exc)
        db_pool_status()
    if PROSTUDIO_WORKER_ENABLED:
        app.state.background_tasks.append(asyncio.create_task(prostudio_generation_worker_loop()))
        if DATABASE_URL:
            app.state.background_tasks.append(asyncio.create_task(prostudio_media_storage_worker_loop()))
    if SUBSCRIPTION_REMINDER_WORKER_ENABLED and DATABASE_URL and BOT_TOKEN:
        app.state.background_tasks.append(asyncio.create_task(subscription_reminder_worker_loop()))
    if SUBSCRIPTION_EVENTS_WORKER_ENABLED and DATABASE_URL and BOT_TOKEN:
        app.state.background_tasks.append(asyncio.create_task(subscription_events_worker_loop()))
    if (DATABASE_URL or PAYMENT_SPOOL.enabled) and BOT_TOKEN:
        app.state.background_tasks.append(asyncio.create_task(payment_recovery_worker_loop()))
    if STRIPE_SECRET_KEY and not stripe_key_allowed():
        print("STRIPE DISABLED: a live key is configured but STRIPE_TEST_MODE_ONLY=1")
    if stripe_enabled():
        # Create or reuse the Stripe products/prices without blocking startup.
        app.state.background_tasks.append(asyncio.create_task(asyncio.to_thread(sync_stripe_catalog_in_background)))


@app.on_event("shutdown")
async def close_postgresql_pool():
    tasks = getattr(app.state, "background_tasks", [])
    for task in tasks:
        task.cancel()
    if tasks:
        await asyncio.gather(*tasks, return_exceptions=True)
    await asyncio.to_thread(close_db_pool)

# =====================================================
# API ENDPOINT: public_prostudio_transcribe
# Принимает HTTP-запрос от Mini App или Telegram Bot.
# Маршрут FastAPI: @app.post("/api/public/prostudio/transcribe")
# Проверяет входные данные, работает с базой/провайдерами и возвращает JSON-ответ фронтенду.
# =====================================================
@app.post("/api/public/prostudio/transcribe")
async def public_prostudio_transcribe(request: Request):
    if "transcribe" in UNPRICED_HELPERS:
        return unpriced_helper_response("transcribe")
    form = await request.form()
    file = form.get("file")
    if not file or not hasattr(file, "read"):
        return JSONResponse({"ok": False, "error": "File is required"}, status_code=400)

    content = await read_upload(file, 25 * 1024 * 1024)
    if not content:
        return JSONResponse({"ok": False, "error": "Empty file"}, status_code=400)
    if len(content) > 25 * 1024 * 1024:
        return JSONResponse(
            {"ok": False, "error": "Запись превышает допустимый размер 25 МБ"},
            status_code=413,
        )
    filename = getattr(file, "filename", None) or "voice.webm"
    content_type = getattr(file, "content_type", None) or "audio/webm"
    # Provider calls are synchronous; keep them off FastAPI's event loop so a
    # long transcription cannot freeze the Mini App's other API requests.
    ok, text = await asyncio.to_thread(
        openai_transcribe_bytes,
        content,
        filename,
        content_type,
    )
    if not ok:
        openai_error = text
        ok, text = await asyncio.to_thread(gemini_transcribe_bytes, content, content_type)
        if not ok:
            print("PROSTUDIO ERROR TRANSCRIBE_FAILED:", {
                "filename": filename,
                "content_type": content_type,
                "bytes": len(content),
                "openai_error": openai_error,
                "gemini_error": text,
            })
            return JSONResponse(
                {"ok": False, "error": "Сервис распознавания речи временно недоступен. Попробуйте ещё раз позже."},
                status_code=503,
            )
        print("PROSTUDIO TRANSCRIBE FALLBACK:", {
            "provider": "gemini",
            "filename": filename,
            "bytes": len(content),
            "openai_error": openai_error,
        })
    return {"ok": True, "text": text}


def voice_dialogue_script_instruction(brief: str) -> str:
    tags = ", ".join(f"[{tag}]" for tag in ELEVENLABS_V3_AUDIO_TAGS)
    return (
        "Write a short spoken dialogue for an AI voice studio from this brief:\n"
        f"{brief}\n\n"
        "Rules:\n"
        "- One line per turn, formatted exactly as `Name: text`. Each line becomes one voiced block.\n"
        "- Use the language of the brief. Keep it natural to speak aloud.\n"
        f"- Where it helps the delivery, put an emotion tag right before the words it colours. Use only these tags: {tags}.\n"
        "- Several tags inside one turn are fine. Never invent other bracketed tags or stage directions.\n"
        "- At most 20 turns and 1800 characters in total.\n"
        "- Return only the dialogue lines, without a title, notes or Markdown."
    )


_DIALOGUE_LINE_RE = re.compile(r"^\s*(?:[-*•]\s*)?\**([^:\n\[\]]{1,40}?)\**\s*:\s*(.+)$")
_DIALOGUE_TAG_RE = re.compile(r"\[([^\[\]\n]{1,40})\]")


def parse_voice_dialogue_script(text: str) -> list:
    """Split an AI-written `Name: text` script into ordered blocks. Only the
    supported Eleven v3 tags survive; voices are never assigned here."""
    allowed = set(ELEVENLABS_V3_AUDIO_TAGS)

    def clean(value: str) -> str:
        value = _DIALOGUE_TAG_RE.sub(lambda m: f"[{m.group(1).strip().lower()}]" if m.group(1).strip().lower() in allowed else "", value)
        return re.sub(r"[ \t]{2,}", " ", value).strip()

    blocks = []
    for raw_line in str(text or "").splitlines():
        line = raw_line.strip().strip("`")
        if not line:
            continue
        match = _DIALOGUE_LINE_RE.match(line)
        if match:
            body = clean(match.group(2))
            if body:
                blocks.append({"speaker": match.group(1).strip()[:40], "text": body})
        elif blocks:
            body = clean(line)
            if body:
                blocks[-1]["text"] = (blocks[-1]["text"] + " " + body).strip()
    total = 0
    kept = []
    for block in blocks[:40]:
        block["text"] = block["text"][:2000]
        if total + len(block["text"]) > 2000:
            break
        total += len(block["text"])
        kept.append(block)
    return kept


@app.post("/api/public/prostudio/voice/text-tool")
async def public_prostudio_voice_text_tool(request: Request):
    """Small editor actions for Voice Studio; never starts audio generation."""
    payload = await request.json()
    action = str(payload.get("action") or "").strip().lower()
    text = str(payload.get("text") or "").strip()
    brief = str(payload.get("brief") or "").strip()
    format_name = str(payload.get("format") or "script").strip()
    source_language = str(payload.get("source_language") or "auto").strip()
    target_language = str(payload.get("target_language") or "en").strip()
    if action not in {"create", "improve", "translate", "dialogue"}:
        return JSONResponse({"ok": False, "error": "Unsupported text action"}, status_code=400)
    if action in {"create", "dialogue"} and not brief:
        return JSONResponse({"ok": False, "error": "Описание текста обязательно"}, status_code=400)
    if action not in {"create", "dialogue"} and not text:
        return JSONResponse({"ok": False, "error": "Текст обязателен"}, status_code=400)
    if len(text) + len(brief) > 60000:
        return JSONResponse({"ok": False, "error": "Текст слишком длинный"}, status_code=413)

    language_names = {
        "en": "English", "de": "German", "fr": "French", "ru": "Russian",
        "es": "Spanish", "it": "Italian", "tr": "Turkish",
    }
    if action == "dialogue":
        instruction = voice_dialogue_script_instruction(brief)
    elif action == "create":
        instruction = (
            f"Create a {format_name} voice-over script from this brief:\n{brief}\n\n"
            "Write polished, natural spoken text. Return only the finished script, without headings, notes or Markdown."
        )
    elif action == "translate":
        source_hint = "Detect the source language automatically" if source_language == "auto" else f"The source language is {language_names.get(source_language, source_language)}"
        instruction = (
            f"{source_hint}. Translate the following voice-over text into {language_names.get(target_language, target_language)}. "
            "Preserve speaker labels, pauses, emotion markers, meaning and natural spoken rhythm. "
            f"Return only the translation.\n\n{text}"
        )
    else:
        instruction = (
            "Improve the following text for professional voice-over. Correct grammar, make it natural to speak, "
            "preserve its meaning, language, speaker labels and markup. Return only the improved text.\n\n" + text
        )

    messages = [
        {"role": "system", "content": "You are the SYLVEX Voice Studio script editor. Follow the requested operation precisely."},
        {"role": "user", "content": instruction},
    ]
    provider_errors = {}
    openai_model = env_value("OPENAI_VOICE_TEXT_MODEL", default="gpt-5-mini")
    gemini_model = env_value("GEMINI_VOICE_TEXT_MODEL", default="gemini-2.5-flash")
    price_text = instruction + messages[0]["content"]
    # The edited script is about as long as the input; the cap keeps the
    # reservation an upper bound (reasoning/thinking tokens included).
    output_cap = min(16000, max(2048, len(instruction) * 2))
    # Reserved for whichever model may answer (OpenAI first, Gemini
    # fallback; both may run), settled on the usage they report. A model
    # without a rate is never called.
    openai_credits = helper_text_reservation(openai_model, price_text, output_cap) if OPENAI_API_KEY else 0
    gemini_credits = helper_text_reservation(gemini_model, price_text, output_cap)

    async def run_text_tool():
        result_text = ""
        used_credits = 0
        usage_known = True
        if openai_credits:
            ok, result_text, data = await asyncio.to_thread(
                openai_compatible_text_request,
                "openai",
                OPENAI_API_BASE,
                OPENAI_API_KEY,
                openai_model,
                messages,
                {"max_completion_tokens": output_cap},
            )
            usage = text_usage_credits(openai_model, data)
            used_credits += usage or 0
            usage_known = usage_known and (usage is not None or not ok)
            if not ok:
                provider_errors["openai"] = result_text
                result_text = ""
        if not result_text and gemini_credits:
            ok, result_text, data = await asyncio.to_thread(gemini_text_request, gemini_model, messages, output_cap)
            usage = text_usage_credits(gemini_model, data)
            used_credits += usage or 0
            usage_known = usage_known and (usage is not None or not ok)
            if not ok:
                provider_errors["gemini"] = result_text
                result_text = ""
        return {"ok": bool(result_text), "text": result_text, "usage_credits": used_credits if usage_known else None}

    tool_result = await run_billed_helper(
        int(payload.get("telegram_id") or 0),
        openai_credits + gemini_credits,
        "voice_text_tool",
        run_text_tool,
        client_request_id=str(payload.get("client_request_id") or ""),
        model=openai_model if openai_credits else gemini_model,
        usage_credits=lambda result: result.get("usage_credits") if isinstance(result, dict) else None,
    )
    result_text = tool_result.get("text") or ""
    if not result_text:
        print("PROSTUDIO ERROR VOICE_TEXT_TOOL_FAILED:", {
            "action": action,
            "text_length": len(text),
            "brief_length": len(brief),
            "providers": provider_errors,
        })
        return JSONResponse(
            {"ok": False, "error": "AI-редактор временно недоступен. Попробуйте немного позже."},
            status_code=503,
        )
    if action == "dialogue":
        blocks = parse_voice_dialogue_script(result_text)
        if not blocks:
            return JSONResponse({"ok": False, "error": "AI не смог разбить диалог на реплики. Попробуйте описать иначе."}, status_code=422)
        return {"ok": True, "text": result_text.strip(), "action": action, "blocks": blocks}
    return {"ok": True, "text": result_text.strip(), "action": action}

# =====================================================
# API ENDPOINT: public_prostudio_elevenlabs_voice_clone
# Принимает запись микрофона из Mini App и создаёт новый голос ElevenLabs.
# Возвращает voice_id, чтобы пользователь мог сразу выбрать созданный голос в разделе «Озвучка».
# =====================================================
@app.post("/api/public/prostudio/elevenlabs/voice-clone")
async def public_prostudio_elevenlabs_voice_clone(request: Request):
    if "voice_clone" in UNPRICED_HELPERS:
        return unpriced_helper_response("voice_clone")
    form = await request.form()
    file = form.get("file")
    if not file or not hasattr(file, "read"):
        return JSONResponse({"ok": False, "error": "File is required"}, status_code=400)

    content = await read_upload(file, 25 * 1024 * 1024)
    if not content:
        return JSONResponse({"ok": False, "error": "Empty file"}, status_code=400)

    telegram_id = request.state.telegram_id
    claimed_id = form.get("telegram_id")
    if claimed_id and str(claimed_id) != str(telegram_id):
        raise HTTPException(status_code=403, detail="user_mismatch")
    try:
        clone_settings = json.loads(str(form.get("settings") or "{}"))
    except Exception:
        clone_settings = {}
    result = await elevenlabs_clone_voice_from_audio(
        file_content=content,
        filename=getattr(file, "filename", None) or "sylvex-voice.webm",
        content_type=getattr(file, "content_type", None) or "audio/webm",
        name=str(form.get("name") or "SYLVEX Voice"),
        description=str(form.get("description") or "Created in SYLVEX Mini App"),
        telegram_id=telegram_id,
        gender=str(form.get("gender") or clone_settings.get("gender") or "neutral"),
        emotion=str(form.get("emotion") or clone_settings.get("emotion") or "neutral"),
        settings=clone_settings if isinstance(clone_settings, dict) else {},
    )
    if not result.get("ok"):
        return JSONResponse(result, status_code=502)
    return result

# =====================================================
# API ENDPOINT: get_cabinet
# Принимает HTTP-запрос от Mini App или Telegram Bot.
# Маршрут FastAPI: @app.get("/api/cabinet/{telegram_id}")
# Проверяет входные данные, работает с базой/провайдерами и возвращает JSON-ответ фронтенду.
# =====================================================
@app.get("/api/cabinet/{telegram_id}")
async def get_cabinet(telegram_id: int):

    def _sync():
        conn = db_connect(DATABASE_URL)
        cursor = conn.cursor()

        cursor.execute("""
        SELECT
            telegram_id,
            username,
            first_name,
            balance,
            subscription,
            total_generations,
            created_at
        FROM users
        WHERE telegram_id = %s
        """, (telegram_id,))

        user = cursor.fetchone()

        cursor.execute("""
        SELECT
            generation_type,
            prompt,
            status,
            created_at
        FROM generations
        WHERE telegram_id = %s
        ORDER BY id DESC
        LIMIT 10
        """, (telegram_id,))

        generations = cursor.fetchall()

        cursor.close()
        conn.close()
        return user, generations

    user, generations = await asyncio.to_thread(_sync)

    if not user:
        return JSONResponse(
            {
                "success": False
            }
        )

    return {
        "success": True,
        "user": {
            "telegram_id": user[0],
            "username": user[1],
            "first_name": user[2],
            "balance": user[3],
            "subscription": user[4],
            "total_generations": user[5],
            "created_at": user[6]
        },
        "generations": [
            {
                "generation_type": row[0],
                "prompt": row[1],
                "status": row[2],
                "created_at": row[3]
            }
            for row in generations
        ]
    }


@app.get("/health/live")
async def health_live():
    return {"ok": True}

@app.get("/health/ready")
async def health_ready():
    if not DATABASE_URL:
        return JSONResponse({"ok": False}, status_code=503)
    def probe():
        conn = db_connect(DATABASE_URL)
        try:
            with conn.cursor() as cursor:
                cursor.execute("SELECT 1")
                return cursor.fetchone()[0] == 1
        finally:
            conn.close()
    try:
        if await asyncio.to_thread(probe):
            return {"ok": True}
    except Exception:
        pass
    return JSONResponse({"ok": False}, status_code=503)


